window.CHAPTERS = [{"id":"ch01","num":1,"title":"細胞","en":"The Cell","group":"基礎","tagline":"細胞膜、胞器與物質運輸","intro":"細胞是身體最小的功能單位，由細胞質膜包圍，內含胞器與細胞溶質。考試主線是膜：磷脂雙層怎樣選擇性通透、主動與被動運輸怎樣分辨，以及黏膜、漿膜、滑膜三種膜的位置與功能。","memoryHook":"親水頭向外、疏水尾向內；黏膜濕、漿膜滑、滑膜顧關節。","sections":[{"title":"細胞的基本組成","points":["人體由受精卵（zygote）發育而來，經歷細胞分裂與分化；所有細胞都帶有與受精卵相同的基因構造。","細胞由細胞質膜（plasma membrane）包圍，內部是細胞溶質（cytosol），多種細胞器（organelles）懸浮其中，各有高度特化的功能。","課文列出的胞器包括細胞核、線粒體、核糖小體、內膜漿網、高爾基體、溶酶體和細胞骨架。","細胞太小，肉眼看不到；組織薄片要染色後在顯微鏡下放大觀察。"]},{"title":"細胞質膜：液體鑲嵌模型","points":["細胞膜由雙層磷脂構成，蛋白質分子嵌入其中；部分蛋白質完全穿過膜，形成通道讓電解質和非脂溶性物質通過。","磷脂頭部帶電、親水，排在膜的外側表面；尾部不帶電、疏水，組成中間的排水層。","這種排列決定物質能否穿越：水溶性物質不能隨便穿過脂肪層，脂溶性物質則可穿過膜的中央層。","膜蛋白可作為荷爾蒙和化學信差的特異性受體、酵素，或參與跨膜運輸。","膜蛋白外部的分支碳水化合物給細胞免疫學上的身份，是細胞識別與免疫標記的基礎。"],"table":{"headers":["成分","排列／角色"],"rows":[["磷脂雙層","親水頭向外、疏水尾向內，形成膜的基礎屏障"],["嵌入蛋白","部分貫穿膜形成通道；可作受體、酵素或運輸工具"],["碳水化合物鏈","附在膜蛋白外部，給細胞免疫學身份"]]}},{"title":"物質進出細胞","points":["被動運輸由高濃度往低濃度移動，不需要能量；主動運輸逆濃度梯度，需要能量。","課文列出多種方式：滲透作用、被動擴散、促進擴散、主動運輸、胞吞作用和胞吐作用。","葡萄糖不能自由穿過膜，需要荷爾蒙（胰島素）促進它進入細胞；這是糖尿病會影響細胞燃料供應的原因。","鈉和鉀是細胞質的重要成分，要靠耗能的泵維持理想濃度；鈉泵為磷脂層中的蛋白質分子提供能量。"],"table":{"headers":["情況","結果"],"rows":[["脂溶性物質","可穿過膜的中央脂肪層"],["水溶性物質","不能自由穿過脂肪層，需膜蛋白通道或載體"],["順濃度梯度","被動運輸，不需能量"],["逆濃度梯度","主動運輸，需能量"]]}},{"title":"體內的三種膜","points":["黏膜（mucous membrane）是消化道、呼吸道和泌尿生殖道的潮濕內層，表面由上皮細胞構成，分泌黏液。","杯狀細胞（goblet cells）裝滿黏液時外形像高腳杯；黏液保護黏膜免受乾燥、機械性和化學損害。","漿膜（serous membrane）由單層鱗狀上皮加雙層疏鬆結締組織構成，分腔壁層和內臟層，兩層之間有漿液。","漿膜見於胸膜、心包膜和腹膜；漿液讓器官在體腔內滑動，減少摩擦。","滑膜（synovial membrane）內襯可活動的關節腔並包圍腱；它不是上皮膜，由細隙狀結締組織和彈性纖維構成，分泌滑液潤滑和滋養關節。"],"table":{"headers":["膜","位置","分泌／作用"],"rows":[["黏膜","消化道、呼吸道、泌尿生殖道","黏液：保護、濕潤、捕捉微粒"],["漿膜","胸膜、心包膜、腹膜","漿液：減少器官滑動時的摩擦"],["滑膜","可動關節腔、腱周圍","滑液：潤滑、滋養關節"]]}},{"title":"腺體與健康膜的維護","points":["外分泌腺（exocrine glands）經管道把分泌物排到上皮表面；內分泌腺（endocrine glands）無管，把荷爾蒙排入血液和淋巴。","腸漏綜合症（leaky gut syndrome）指腸壁完整的膜讓本應被阻擋的物質通過。","課文列出的誘因包括寄生蟲、病毒或細菌感染、過量乙醇，以及非類固醇抗發炎藥（NSAIDs）。","後果可以是粉刺、牛皮癬、腸易激綜合症和慢性疲勞症等。","課文提到蘆薈、多不飽和脂肪酸、抗氧化劑和麩氨基硫過氧化酵素等營養補充研究方向；使用 PUFA 時要合併抗氧化劑，否則可能傷害膜。"]}],"terms":[{"zh":"細胞質膜","en":"Plasma membrane","def":"包圍細胞的雙層磷脂膜，控制物質進出並維持細胞邊界。"},{"zh":"細胞溶質","en":"Cytosol","def":"細胞內懸浮胞器的液體部分。"},{"zh":"細胞器","en":"Organelle","def":"細胞內具有特定功能的小型構造，例如線粒體和溶酶體。"},{"zh":"磷脂","en":"Phospholipid","def":"細胞膜的主要成分；頭部親水、尾部疏水，形成雙層。"},{"zh":"選擇性通透","en":"Selective permeability","def":"膜只讓某些物質通過的特性，是維持細胞內外環境的基礎。"},{"zh":"杯狀細胞","en":"Goblet cell","def":"黏膜上皮中分泌黏液的細胞，裝滿黏液時呈高腳杯狀。"},{"zh":"黏膜","en":"Mucous membrane","def":"消化道、呼吸道和泌尿生殖道的潮濕內層，分泌黏液保護。"},{"zh":"漿膜","en":"Serous membrane","def":"由單層鱗狀上皮和結締組織構成，分泌漿液以減少器官摩擦。"},{"zh":"滑膜","en":"Synovial membrane","def":"內襯可動關節腔的膜，分泌滑液潤滑和滋養關節。"},{"zh":"外分泌腺","en":"Exocrine gland","def":"經管道把分泌物排到上皮表面的腺體。"},{"zh":"內分泌腺","en":"Endocrine gland","def":"無管腺，把荷爾蒙直接排入血液和淋巴。"}],"examTips":["磷脂頭部親水、尾部疏水：頭朝外、尾朝內，別把方向倒轉。","主動運輸是「低→高」、要能量；被動是「高→低」、不用能量。","漿膜只有三處：胸膜、心包膜、腹膜；滑膜不屬於上皮膜。","杯狀細胞在黏膜，不在漿膜；黏液的作用是保護和捕捉微粒。","葡萄糖入細胞需要胰島素；鈉鉀泵耗能，這是膜運輸考題的常見陷阱。","腸漏是「屏障失效」，不是腸壁變厚；NSAIDs、酒精和感染都是課文列出的誘因。"],"remedies":[{"name":"Natrum muriaticum（氯化鈉）","note":"課文指其含鈉，對細胞膜有親和力；鈉鉀泵維持膜兩側濃度需要能量。"},{"name":"Kali muriaticum（氯化鉀）","note":"課文與 Natrum muriaticum 並列，指含鉀並對細胞膜有親和力。"}],"atlas":[4,5,6,7,15],"questions":[{"id":"q0101","ch":1,"level":1,"type":"single","style":"concept","q":"細胞質膜的雙層磷脂中，親水頭部和疏水尾部怎樣排列？","options":["親水頭向外、疏水尾向內","親水頭向內、疏水尾向外","頭尾隨機分布，沒有方向性","親水頭與疏水尾都朝外"],"answer":[0],"explain":"磷脂頭部帶電、親水，所以朝向膜兩側的水性環境；尾部不帶電、疏水，藏在雙層中間形成排水層。把親水頭與疏水尾方向倒轉，是最常見的錯誤；其他選項忽略了磷脂兩端性質完全不同。","source":"第一章 細胞質膜的功能","chId":"ch01"},{"id":"q0102","ch":1,"level":1,"type":"single","style":"concept","q":"下列哪一項不是課文列出的細胞器（organelle）？","options":["溶酶體","杯狀細胞","線粒體","核糖小體"],"answer":[1],"explain":"杯狀細胞是黏膜上皮中分泌黏液的細胞，屬於細胞類型，不是細胞內的胞器。線粒體、核糖小體和溶酶體都在課文列出的胞器名單內。題目考的是「胞器」與「特化細胞」的分類，不要見到顯微構造就當成胞器。","source":"第一章 細胞結構和功能","chId":"ch01"},{"id":"q0103","ch":1,"level":1,"type":"single","style":"concept","q":"哪一種膜內襯可活動的關節腔，並分泌滑液？","options":["黏膜","皮膚膜","滑膜","漿膜"],"answer":[2],"explain":"滑膜內襯可動關節腔並包圍腱，分泌清澈黏滑的滑液，作用是潤滑和滋養關節。黏膜見於消化道、呼吸道和泌尿生殖道；漿膜見於胸膜、心包膜和腹膜；皮膚膜是身體外表面的保護層。","source":"第一章 1.3 滑膜","chId":"ch01"},{"id":"q0104","ch":1,"level":1,"type":"single","style":"concept","q":"杯狀細胞（goblet cell）的主要分泌物是什麼？","options":["滑液","膽汁","漿液","黏液"],"answer":[3],"explain":"杯狀細胞在黏膜上皮中製造黏液；黏液積聚時細胞脹大，外形像高腳杯。漿液由漿膜分泌，滑液由滑膜分泌，膽汁由肝臟製造，三者都不是杯狀細胞的產物，不要把它們混成同一種分泌。","source":"第一章 1.3 黏膜","chId":"ch01"},{"id":"q0105","ch":1,"level":2,"type":"single","style":"concept","q":"下列哪一項不屬於漿膜（serous membrane）？","options":["滑膜","胸膜","心包膜","腹膜"],"answer":[0],"explain":"課文明確指出漿膜只見於三處：胸膜、心包膜和腹膜。滑膜雖然也分泌液體，但它內襯關節腔，而且不是上皮膜，由細隙狀結締組織和彈性纖維構成，因此不能混入漿膜；「會分泌液體」不是漿膜的判準。","source":"第一章 1.3 漿液膜、滑膜","chId":"ch01"},{"id":"q0106","ch":1,"level":2,"type":"single","style":"concept","q":"主動運輸與被動運輸最關鍵的分別是甚麼？","options":["主動運輸由高濃度往低濃度，被動相反","主動運輸逆濃度梯度並需要能量","主動運輸不需要膜蛋白，被動需要","主動運輸只運送水，被動只運送氣體"],"answer":[1],"explain":"課文定義主動運輸是物質由低濃度往高濃度、逆濃度梯度移動，需要能量；被動運輸則順濃度梯度，不需能量。把主動與被動的方向說反，是常見錯誤；也有選項把運輸方式與物質種類錯誤配對，或忽略膜蛋白參與多種運輸。","source":"第一章 細胞質膜的功能","chId":"ch01"},{"id":"q0107","ch":1,"level":2,"type":"multi","style":"concept","q":"根據課文，膜蛋白質可以有以下哪些功能？","options":["製造黏液","作為酵素","參與物質穿越細胞膜的運輸","合成磷脂","作為荷爾蒙和化學信差的特異性受體"],"answer":[1,2,4],"explain":"課文列出膜蛋白可作特異性感受器、酵素，以及參與跨膜運輸；附在膜蛋白外部的碳水化合物則給細胞免疫學身份。黏液由杯狀細胞製造，磷脂是膜的成分而非膜蛋白的產物，所以「製造黏液」和「合成磷脂」都是把其他構造的功能借用過來。","source":"第一章 膜蛋白質的一些功能","chId":"ch01"},{"id":"q0108","ch":1,"level":2,"type":"single","style":"concept","q":"下列哪一項不是課文列出的腸漏綜合症誘因？","options":["病毒或細菌感染","寄生蟲侵擾","長期高纖飲食","過量攝取乙醇"],"answer":[2],"explain":"課文列出的誘因包括寄生蟲、病毒和細菌感染、過量乙醇，以及非類固醇抗發炎藥；高纖飲食不在其列。腸漏的關鍵是腸壁屏障失效，讓本應被阻擋的物質通過，而不是由纖維攝取量直接造成。","source":"第一章 1.4 維持健康的膜","chId":"ch01"},{"id":"q0109","ch":1,"level":3,"type":"single","style":"case","q":"一名長期吸煙者的呼吸道上皮杯狀細胞分泌黏液的功能受損。最直接受影響的防禦是甚麼？","options":["腎臟的鈉鉀泵失去能量","關節滑液的黏度下降","肺泡的氣體交換面積增加","吸入的外來微粒較難被黏住並排出"],"answer":[3],"explain":"課文指呼吸道黏膜的黏液能阻止吸入的外來微粒，防止它們進入肺泡；杯狀細胞分泌不足，最直接就是黏附與清除微粒的能力下降。腎臟鈉鉀泵、關節滑液和肺泡氣體交換面積都不是杯狀細胞黏液的直接防禦，與呼吸道黏膜無直接關係。","source":"第一章 1.3 黏膜","chId":"ch01"},{"id":"q0110","ch":1,"level":3,"type":"multi","style":"concept","q":"關於體內三種膜，下列哪些敘述正確？","options":["滑膜是一種上皮膜","滑液有潤滑和滋養關節的作用","黏膜見於消化道、呼吸道和泌尿生殖道","漿膜由單層鱗狀上皮和疏鬆結締組織構成"],"answer":[1,2,3],"explain":"正確項包括：滑液潤滑並滋養關節、黏膜見於消化道／呼吸道／泌尿生殖道、漿膜由單層鱗狀上皮和疏鬆結締組織構成。滑膜不是上皮膜，而是由細隙狀結締組織層和彈性纖維構成，所以「滑膜是一種上皮膜」是陷阱。","source":"第一章 1.3 上皮膜、滑膜","chId":"ch01"},{"id":"q0111","ch":1,"level":3,"type":"single","style":"case","q":"一名病人長期服用非類固醇抗發炎藥並每日飲酒，出現腹痛和腹瀉。按課文，最可能受損的是哪一層？","options":["消化道黏膜","胸膜","關節滑膜","心包膜"],"answer":[0],"explain":"課文把 NSAIDs 和過量乙醇列為腸漏綜合症的誘因，而腸漏是腸壁黏膜屏障失效，讓本應被阻擋的物質通過。心包膜和胸膜屬漿膜，與口服藥物和酒精的直接接觸無關；滑膜在關節，也不是消化道的第一線。","source":"第一章 1.4 維持健康的膜","chId":"ch01"}]},{"id":"ch02","num":2,"title":"皮膚","en":"The Skin","group":"基礎","tagline":"表皮、真皮、體溫調節與傷口癒合","intro":"皮膚是人體最大的器官，也是第一道防線。考試主線是分層：表皮靠角質化屏障保護，真皮藏血管、神經和附屬物；再串連體溫調節的四種散熱方式，以及一級與二級傷口癒合的差別。","memoryHook":"表皮無血管、真皮有神經；汗腺散熱、角質防水。","sections":[{"title":"皮膚的整體結構與功能","points":["皮膚是人體最大的器官，成年人表面積約 1.5–2 平方米；分表皮（epidermis）和真皮（dermis），下方有皮下脂肪（subcutaneous fat）。","一枚 2 英鎊硬幣大小的皮膚已有超過 300 萬個細胞、1 米血管、80 個汗腺和至少 35 個神經末梢。","皮膚的功能包括保護、調節體溫、排泄、感覺和痛觸覺；它阻擋紫外線、汙物和微生物，也防止水分過量流失或浸入。","表皮是最根本的屏障；真皮較疏鬆，藏有血管、淋巴管、神經末梢和皮膚附屬物。"],"table":{"headers":["層","主要特徵"],"rows":[["表皮","複層角質鱗狀上皮；無血管、無神經末梢；最厚在手掌和腳底"],["真皮","結締組織、膠原和彈性纖維；有血管、淋巴管、神經末梢及附屬物"],["皮下脂肪","位於皮膚和底層結構之間的一層脂肪"]]}},{"title":"表皮：角質化屏障","points":["表皮由複層角質鱗狀上皮構成，從最深處的生發層延伸到表面的角質層。","表面細胞扁平、薄、無核、無生命，被角質蛋白（keratin）取代，並不斷被磨掉，由生發層細胞補充。","表皮完全更新大約需要一個月；手掌和腳底的表皮最厚。","表皮沒有血管或神經末梢，靠真皮乳突滲出的間質液取得氧氣和營養。","黑色素細胞（melanocytes）在生發層把酪氨酸製成黑色素，保護皮膚免受紫外線；黑色素細胞數量相當固定，膚色深淺取決於分泌量。","蘭格罕氏細胞（Langerhans cells）吞噬入侵抗原，經淋巴組織把資料交給 T 淋巴細胞。"],"table":{"headers":["表皮細胞／構造","角色"],"rows":[["角質細胞","被角質蛋白取代，形成防水、耐磨的角質層"],["黑色素細胞","製造黑色素，吸收紫外線，決定膚色深淺"],["蘭格罕氏細胞","吞噬抗原，啟動特異性免疫反應"],["乳突","真皮向表皮的凸出物，形成指紋脊"]]}},{"title":"真皮與附屬物","points":["真皮由膠原纖維和彈性纖維交織而成；彈性纖維過度伸展破裂會形成妊娠紋，膠原隨年齡下降會產生皺紋。","真皮內有血管、淋巴管、感覺神經末梢、汗腺及管道、毛髮、豎毛肌和皮脂腺。","感覺接受器：麥氏小體（Meissner's corpuscle）感受輕壓，巴氏小體（Pacinian corpuscle）感受重壓，自由神經末梢感受疼痛。","汗腺受交感神經刺激，對體溫升高和恐懼有反應；最重要功能是調節體溫，汗液蒸發帶走體熱。","皮脂腺分泌皮脂（sebum）進入毛囊，潤滑毛髮、防水、殺菌和防黴；手掌和腳底沒有皮脂腺。"],"table":{"headers":["附屬物","位置／特點","功能"],"rows":[["汗腺","手掌、腳底、腋窩、鼠蹊最多","分泌汗液，蒸發散熱，調節體溫"],["皮脂腺","除手掌、腳底外全身；頭面腋窩鼠蹊最多","皮脂潤滑毛髮、防水、抗菌防黴"],["毛髮與豎毛肌","毛囊在真皮或皮下組織","豎毛肌收縮造成雞皮，困住空氣保溫"],["指甲","甲根、甲床、甲板、弧影","保護指趾尖端；手指甲生長較腳趾甲快"]]}},{"title":"體溫調節","points":["正常體溫約 36.8°C，健康情況下波動約 0.5–0.75°C；傍晚、運動和排卵後會稍高。","產熱主要來自肌肉收縮、肝臟代謝和消化器官蠕動；低溫時顫抖會收縮骨骼肌產熱。","散熱主要經皮膚，方式有蒸發、放射、傳導和對流；只有經皮膚的散熱可以調節。","下視丘的溫度調節中樞根據血液溫度調節；體溫升高時經自主神經刺激汗腺，皮膚血管擴張。","延髓的血管舒縮中樞控制小動脈直徑；體溫下降時血管收縮，減少體表血流以保存熱能。","發燒時熱原作用於下視丘，透過前列腺素把溫器設定得更高；退燒時大量流汗和血管舒張。"],"table":{"headers":["散熱方式","機制"],"rows":[["蒸發","汗液變成水蒸氣時帶走熱能"],["放射","身體未被遮蔽部分把熱散射出去"],["傳導","接觸皮膚的衣物或物體帶走熱"],["對流","皮膚附近空氣受熱上升，冷空氣補上形成氣流"]]}},{"title":"傷口癒合","points":["傷口癒合受全身因素（營養、整體健康、感染、免疫力、血液供應、糖尿病、癌症）和局部因素（血供、遠離污染）影響。","一級癒合：傷口邊緣緊密對合，常見於縫線、膠帶或釘子閉合；階段為發炎、增殖、成熟，互相重疊。","發炎期血凝塊填滿裂口，噬菌細胞清除殘骸，纖維組織母細胞分泌膠原；增殖期上皮細胞跨越傷口，凝塊變成痂，約 3–10 天分離。","二級癒合：大量組織損傷或邊緣無法並置（如靜脈曲張性潰瘍、褥瘡），肉芽組織由傷口底部長起，收縮較大、疤痕較多、需時較長。","疤痕組織光滑，不含汗腺、毛囊或皮脂腺；接觸抑制（contact inhibition）使細胞不過度生長，癌細胞則失去這種抑制。"],"table":{"headers":["比較","一級癒合","二級癒合"],"rows":[["傷口閉合","邊緣緊密對合，直接癒合","傷口開放，靠肉芽組織和表皮新生"],["增殖重點","主要是上皮細胞增殖","主要是肉芽組織形成"],["收縮","很少","較大，以縮小傷口"],["疤痕／時間","疤痕較少、時間較短","疤痕較多、時間較長"]]}}],"terms":[{"zh":"表皮","en":"Epidermis","def":"皮膚最外層，由複層角質鱗狀上皮構成，無血管和神經末梢。"},{"zh":"真皮","en":"Dermis","def":"表皮下的結締組織層，含膠原、彈性纖維、血管、神經和附屬物。"},{"zh":"角質蛋白","en":"Keratin","def":"表皮細胞產生的纖維蛋白，形成耐磨、防水的角質層。"},{"zh":"黑色素細胞","en":"Melanocyte","def":"生發層中製造黑色素的細胞，保護皮膚免受紫外線傷害。"},{"zh":"生發層","en":"Germinative layer","def":"表皮最深層，細胞迅速分裂以補充表面被磨掉的細胞。"},{"zh":"角質層","en":"Stratum corneum","def":"表皮最表面的一層，由扁平、無核、充滿角質的死細胞組成。"},{"zh":"皮下脂肪","en":"Subcutaneous fat","def":"皮膚與底層結構之間的一層脂肪組織。"},{"zh":"豎毛肌","en":"Arrector pili muscle","def":"附著毛囊的平滑肌，收縮使毛髮豎立並造成雞皮。"},{"zh":"皮脂腺","en":"Sebaceous gland","def":"分泌皮脂進入毛囊的腺體，潤滑毛髮並提供防水、抗菌作用。"},{"zh":"汗腺","en":"Sweat gland","def":"受交感神經刺激的腺體，分泌汗液以蒸發散熱、調節體溫。"},{"zh":"蘭格罕氏細胞","en":"Langerhans cell","def":"表皮中的免疫細胞，吞噬抗原並把資料交給 T 淋巴細胞。"},{"zh":"接觸抑制","en":"Contact inhibition","def":"正常細胞互相接觸便停止生長的現象；癌細胞會失去這種抑制。"}],"examTips":["表皮沒有血管和神經末梢，營養來自真皮乳突的間質液；不要說表皮靠血管供養。","膚色深淺取決於黑色素「分泌量」，不是黑色素細胞數目；日曬促進合成。","麥氏小體＝輕壓，巴氏小體＝重壓，自由神經末梢＝痛。","汗腺由交感神經刺激；體溫每升 0.25–0.5°C 便開始出汗。","一級癒合疤痕少、時間短；二級癒合收縮大、疤痕多，別倒轉。","低體溫定義是核心溫度低於 35°C；低於 32°C 補償機制通常失效。"],"remedies":[{"name":"Arnica（山金車）","note":"課文把 Arnica 列為急救藥箱中的治創傷療劑（vulnerary）之一；本章的傷口癒合分期是理解創傷用藥場合的基礎。"},{"name":"Calendula（金盞花）","note":"課文與 Arnica 等並列為治創傷療劑，見於順勢療法急救藥箱；本章只交代其分類，沒有逐一列出適應症。"},{"name":"Ledum（杜香）","note":"同屬課文列出的治創傷療劑群；考試重點是認得它與 Arnica、Calendula 同類，而非背個別劑量。"}],"atlas":[10,11,12,13,14],"questions":[{"id":"q0201","ch":2,"level":1,"type":"single","style":"concept","q":"成年人皮膚的表面積大約是多少？","options":["0.5–1 平方米","1.5–2 平方米","5–6 平方米","3–4 平方米"],"answer":[1],"explain":"課文指成年人皮膚表面積平均約 20,000 cm²，即大約 1.5–2 平方米。這個數字要與「2 英鎊硬幣大小的皮膚有超過 300 萬個細胞」分開記：前者是全身面積，後者是一小片皮膚的細胞數。","source":"第二章 2.1 皮膚的結構","chId":"ch02"},{"id":"q0202","ch":2,"level":1,"type":"single","style":"concept","q":"表皮最厚的位置在哪裡？","options":["背部","腹部","手掌和腳底","面部"],"answer":[2],"explain":"課文指表皮在身體不同部位有不同厚度，手掌和腳底最厚，這是經常受壓和摩擦的部位。背部、腹部和面部的表皮都較薄；題目常用「經常受壓」作提示，手掌和腳底正符合，不要只看面積大小。","source":"第二章 2.1.1 表皮","chId":"ch02"},{"id":"q0203","ch":2,"level":1,"type":"single","style":"concept","q":"下列哪一項不是表皮的特徵？","options":["由複層角質鱗狀上皮構成","靠真皮間質液取得營養","最外層是角質層","含豐富血管"],"answer":[3],"explain":"表皮沒有血管，營養和氧氣來自由真皮乳突滲出的間質液；它由複層角質鱗狀上皮構成，最表面是角質層。把真皮的特徵套到表皮，是最常見的混淆；表皮也無神經末梢，感覺由真皮接受器負責。","source":"第二章 2.1.1 表皮","chId":"ch02"},{"id":"q0204","ch":2,"level":1,"type":"single","style":"concept","q":"麥氏小體（Meissner's corpuscle）主要感受哪種刺激？","options":["輕壓","溫度","重壓","疼痛"],"answer":[0],"explain":"課文的感覺接受器表列明：麥氏小體感受輕壓，巴氏小體感受重壓，自由神經末梢感受疼痛。重壓是巴氏小體的功能，疼痛是自由神經末梢，兩者最易與麥氏小體混淆；溫度由另一類接受器負責，不是本表三項。","source":"第二章 表 2.1 皮膚中的感覺接受器","chId":"ch02"},{"id":"q0205","ch":2,"level":2,"type":"single","style":"concept","q":"兩個膚色不同的人，黑色素細胞數量與膚色的關係，哪項正確？","options":["黑色素由角質層製造","黑色素細胞數量相近，膚色差異主要來自黑色素分泌量","膚色較深者的黑色素細胞數目一定較多","日曬會減少黑色素合成"],"answer":[1],"explain":"課文指黑色素細胞的數量相當固定，膚色差別取決於黑色素被分泌的數量；接觸陽光會促進黑色素合成。把「細胞數目」和「分泌量」混淆、說黑色素由角質層製造、或說日曬會減少合成，都與課文相反。","source":"第二章 2.1.1 皮膚顏色","chId":"ch02"},{"id":"q0206","ch":2,"level":2,"type":"single","style":"concept","q":"汗腺主要受哪種神經刺激？","options":["沒有神經支配","副交感神經","交感神經","體感神經"],"answer":[2],"explain":"課文明言汗腺受交感神經刺激，並對體溫升高和恐懼有反應；下視丘的溫度調節中樞再透過自主神經調控。副交感神經主要與消化分泌和蠕動有關，不要把所有腺體都歸給副交感；「汗腺由交感支配」是本章必記點。","source":"第二章 2.1.2 汗腺","chId":"ch02"},{"id":"q0207","ch":2,"level":2,"type":"multi","style":"concept","q":"真皮內含有下列哪些結構？","options":["汗腺及管道","骨髓","角質層","血管","感覺神經末梢"],"answer":[0,3,4],"explain":"真皮內有血管、淋巴管、汗腺及管道、感覺神經末梢、毛髮、豎毛肌和皮脂腺。角質層屬表皮最表面，骨髓在骨骼的骨髓腔，兩者都不在真皮；這題考的是分層，不是把所有皮膚構造混在一起。","source":"第二章 2.1.2 真皮","chId":"ch02"},{"id":"q0208","ch":2,"level":2,"type":"single","style":"concept","q":"一級與二級癒合的比較，哪項正確？","options":["一級癒合的疤痕較多","一級癒合靠肉芽組織從底部長起","二級癒合所需時間較短","二級癒合收縮較大、疤痕較多"],"answer":[3],"explain":"課文比較表列明：二級癒合收縮較大以縮小傷口、疤痕較多、需時較長；一級癒合則疤痕較少、時間較短。把一級說成疤痕較多或靠肉芽由底部長起，或把二級說成時間較短，都是把兩者特徵倒轉。","source":"第二章 2.4 傷口癒合","chId":"ch02"},{"id":"q0209","ch":2,"level":3,"type":"single","style":"case","q":"一名病人小腿有靜脈曲張性潰瘍，傷口開放、邊緣無法對合。最可能採用的癒合方式及其特徵是？","options":["二級癒合，肉芽組織由底部生長並收縮","一級癒合，疤痕較多且收縮較大","二級癒合，主要靠上皮細胞增殖且沒有收縮","一級癒合，上皮細胞直接跨越傷口"],"answer":[0],"explain":"課文把靜脈曲張性潰瘍和褥瘡列為二級癒合的例子：傷口開放，肉芽組織由凹洞底部生長，纖維組織造成較大的收縮以縮小傷口。把二級癒合說成主要靠上皮增殖而沒有收縮，或把一級癒合說成上皮直接跨越傷口，都不符合課文。","source":"第二章 2.4 二級癒合","chId":"ch02"},{"id":"q0210","ch":2,"level":3,"type":"multi","style":"concept","q":"下列哪些會延緩傷口癒合？","options":["傷口感染","局部血液供應不足","糖尿病","營養狀態良好","年輕"],"answer":[0,1,2],"explain":"課文把感染、免疫力受損、血液供應和全身狀態不良（例如糖尿病和癌症）列為降低癒合速度的因素；局部血供良好才有利修復。營養良好和年輕並非延緩因素，反而是較有利的條件。","source":"第二章 2.4.1 傷口癒合需具備的條件","chId":"ch02"},{"id":"q0211","ch":2,"level":3,"type":"single","style":"case","q":"工人在酷熱環境大量流汗，只補充清水。按課文，最可能出現哪種電解質問題？","options":["血鉀過高","血鈉過低","血鈣過高","血糖過低"],"answer":[1],"explain":"課文在排泄作用一節指出，汗液含氯化鈉，過度流汗而只補清水會稀釋體液，可能導致血鈉水準異常低；要適度增加水分和鹽的攝取。血鉀過高、血鈣過高和血糖過低都不是課文與流汗直接連結的電解質變化。","source":"第二章 排泄作用","chId":"ch02"}]},{"id":"ch03","num":3,"title":"消化系統","en":"The Digestive System","group":"內臟","tagline":"四層腸壁、消化腺與營養素吸收","intro":"消化系統由口腔到肛門是一條結構大致相同的長管，壁分四層，靠蠕動和括約肌推進。考試主線是「哪一層做甚麼」、腹膜與腹腔九區的位置，以及三大營養素在哪裡被哪種酵素分解、經哪條路吸收。","memoryHook":"黏膜在內、漿膜在外；歐氏管肌肉、麥氏管黏膜下。","sections":[{"title":"消化道壁的四層","points":["由食道以下，消化道壁基本分四層：黏膜（mucosa）、黏膜下層（submucosa）、肌肉層（muscularis）、漿膜（serosa）或動脈外膜（adventitia）。","黏膜是最內層，由柱狀上皮、黏膜固有層和黏膜肌層構成，功能是保護、分泌和吸收。","黏膜下層由疏鬆結締組織、膠原和彈性纖維構成，內有血管叢、淋巴管和黏膜下神經叢（麥氏神經叢）。","肌肉層一般由內環、外縱兩層平滑肌構成；兩層之間有腸肌叢（歐氏神經叢），協調蠕動。","漿膜或動脈外膜是最外層；腹部器官由腹膜覆蓋，胸廓內則是疏鬆纖維組織。"],"table":{"headers":["層（由內到外）","主要成分","功能"],"rows":[["黏膜","柱狀上皮、黏膜固有層、黏膜肌層","保護、分泌消化液、吸收"],["黏膜下層","疏鬆結締組織、血管、淋巴管、麥氏神經叢","供應黏膜、運送養分、調控分泌"],["肌肉層","內環、外縱平滑肌；歐氏神經叢","蠕動、混合食物、括約肌控制"],["漿膜／動脈外膜","腹膜或疏鬆纖維組織","包覆器官、減少摩擦"]]}},{"title":"腹膜與腹腔分區","points":["腹膜是體內最大的漿液膜，在腹腔形成密閉囊，內含少量漿液，有豐富血液和淋巴供應及淋巴結。","腹膜分腔壁層和內臟層；兩層之間的漿液減少摩擦，腹膜腔只是一個潛在腔。","胃和腸幾乎完全被腹膜包圍，由腸系膜懸吊於後腹壁；大網膜像圍裙懸在腹部器官前方，儲存脂肪。","胰臟、脾臟、腎臟和腎上腺只有前方表面被腹膜覆蓋，屬腹膜腔後器官。","腹部九區中，右季肋部是肝臟和膽囊，上腹部是胃和胰臟，右髂骨窩是盲腸和闌尾。"],"table":{"headers":["腹部區域","主要器官"],"rows":[["右季肋部","肝臟、膽囊"],["上腹部","胃、胰臟，可能有橫結腸"],["左季肋部","脾臟"],["右髂骨窩","盲腸、闌尾"],["左髂骨窩","降結腸"]]}},{"title":"消化道各部分","points":["口腔把食物切碎、變軟和揉成團；咽頭分鼻咽、口咽和喉咽，食物經咽頭入食道。","食道約 25 cm 長、2 cm 闊，進入胃前在橫隔膜處有一個急彎，可預防胃內容物反流；該處薄弱可形成裂孔性疝氣。","胃是 J 形器官，暫時儲存食物，胃蛋白酶把蛋白質分解為多勝肽，三層平滑肌把內容物攪成乳糜。","胃分泌鹽酸作非特異防禦，酸性環境溶解鐵鹽以便吸收，並分泌內在因子供迴腸末端吸收維生素 B12。","小腸約 5 公尺，分十二指腸、空腸、迴腸；絨毛和單細胞厚的壁增加吸收表面積，並分泌 CCK 和胰泌素。","大腸約 1.5 公尺，主要再吸收水分、讓腸道菌居住、形成糞便；維生素 K 由結腸細菌合成並在此吸收。"],"table":{"headers":["器官","主要功能"],"rows":[["胃","儲存、胃蛋白酶分解蛋白質、鹽酸防禦、分泌內在因子"],["小腸","化學消化、吸收營養素、分泌 CCK 和胰泌素"],["大腸","再吸收水分、腸道菌、合成維生素 K、形成糞便"],["直腸","暫存糞便，觸發排便反射"]]}},{"title":"附屬腺體：肝、膽、胰","points":["肝臟製造膽汁，每天約 500 mL；膽汁含膽鹽、膽色素、膽固醇、黏液、礦物鹽和水。","膽鹽的作用是乳化脂肪，把脂肪散成薄層，方便脂肪酶作用；膽汁本身不含分解脂肪的酵素。","膽汁儲存在膽囊，經膽管釋放入十二指腸；用過的膽鹽在迴腸末端回收。","胰臟位於十二指腸彎曲處，分泌含蛋白酶、澱粉酶和脂肪酶的胰液，經胰臟導管進入十二指腸。"],"table":{"headers":["腺體","分泌","主要作用"],"rows":[["肝臟","膽汁","乳化脂肪，幫助脂肪消化"],["膽囊","儲存膽汁","進食時把膽汁釋放入十二指腸"],["胰臟","胰液（多種消化酶）","分解蛋白質、碳水化合物和脂肪"]]}},{"title":"營養素的消化與吸收","points":["碳水化合物由唾液澱粉酶開始分解為雙醣；胃酸令唾液澱粉酶停止，胰澱粉酶接手，腸細胞的蔗糖酶、麥芽糖酶和乳糖酶把雙醣變成單醣。","蛋白質由胃蛋白酶分解為多勝肽；胰蛋白酶和胰凝乳蛋白酶把多勝肽切成二、三胜肽，腸細胞的胜肽酶再切成氨基酸。","脂肪靠膽鹽乳化，胰脂肪酶把脂肪分解為脂肪酸和甘油。","單醣和氨基酸進入絨毛的毛細血管；脂肪酸和甘油進入絨毛的乳糜管。","水分大部分在小腸吸收，其餘在大腸；水溶性維生素入毛細血管，脂溶性維生素入乳糜管。"],"table":{"headers":["營養素","吸收途徑"],"rows":[["單醣、氨基酸","絨毛的毛細血管"],["脂肪酸、甘油","絨毛的乳糜管"],["水溶性維生素","毛細血管"],["脂溶性維生素","乳糜管"]]}}],"terms":[{"zh":"消化道","en":"Alimentary canal","def":"由口腔到肛門的連續管道，負責消化食物和吸收營養素。"},{"zh":"黏膜","en":"Mucosa","def":"消化道最內層，由上皮、黏膜固有層和黏膜肌層構成。"},{"zh":"黏膜下層","en":"Submucosa","def":"黏膜與肌肉層之間的結締組織層，含血管、淋巴管和麥氏神經叢。"},{"zh":"肌肉層","en":"Muscularis","def":"消化道壁的平滑肌層，內環外縱，負責蠕動和混合食物。"},{"zh":"腹膜","en":"Peritoneum","def":"體內最大的漿液膜，分腔壁層和內臟層，包覆腹腔器官。"},{"zh":"腸系膜","en":"Mesentery","def":"雙層腹膜皺褶，把胃和腸懸吊於後腹壁。"},{"zh":"大網膜","en":"Greater omentum","def":"像圍裙懸在腹部器官前方的腹膜皺褶，可儲存脂肪。"},{"zh":"蠕動","en":"Peristalsis","def":"消化道平滑肌的波動式收縮，把內容物向前推進。"},{"zh":"括約肌","en":"Sphincter","def":"增厚的環狀肌環，控制內容物前進並防止反流。"},{"zh":"絨毛","en":"Villus","def":"小腸表面的細小突出物，增加吸收表面積。"},{"zh":"乳糜管","en":"Lacteal","def":"絨毛內的淋巴管，吸收脂肪酸和甘油。"},{"zh":"內在因子","en":"Intrinsic factor","def":"胃分泌的物質，是迴腸末端吸收維生素 B12 所必需。"}],"examTips":["四層由內到外：黏膜→黏膜下層→肌肉層→漿膜；歐氏神經叢在肌肉層，麥氏神經叢在黏膜下層。","副交感（迷走神經）增加蠕動和分泌；交感則抑制。","膽汁乳化脂肪，不是分解脂肪；分解靠胰脂肪酶。","鐵的吸收需要胃酸；維生素 B12 需要胃的內在因子，並在迴腸末端吸收。","大腸主要吸水，不是主要吸收營養素；維生素 K 由結腸細菌合成。","腹膜腔後器官：胰、脾、腎、腎上腺；胃和腸幾乎完全被腹膜包圍。"],"remedies":[],"atlas":[17,18,19,20],"questions":[{"id":"q0301","ch":3,"level":1,"type":"single","style":"concept","q":"消化道壁由內到外的四層次序是？","options":["漿膜→肌肉層→黏膜下層→黏膜","黏膜→肌肉層→黏膜下層→漿膜","黏膜→黏膜下層→肌肉層→漿膜","黏膜下層→黏膜→肌肉層→漿膜"],"answer":[2],"explain":"課文由內到外描述四層：黏膜→黏膜下層→肌肉層→漿膜（或動脈外膜）。把黏膜下層和肌肉層倒轉、由外到內排列、或把黏膜下層放到最內，都是常見的次序錯配。","source":"第三章 3.1.1 消化道的基礎結構","chId":"ch03"},{"id":"q0302","ch":3,"level":1,"type":"single","style":"concept","q":"右髂骨窩主要對應哪組器官？","options":["肝臟和膽囊","脾臟","胃和胰臟","盲腸和闌尾"],"answer":[3],"explain":"課文的腹部器官位置表列明：右髂骨窩是盲腸和闌尾，右季肋部是肝臟和膽囊，左季肋部是脾臟，上腹部是胃和胰臟。這題考九區定位，左右以人體為準，不要以觀察者方向混淆；右下腹不等於右上腹。","source":"第三章 3.2 腹部內各器官的位置","chId":"ch03"},{"id":"q0303","ch":3,"level":1,"type":"single","style":"concept","q":"膽汁由哪個器官製造？","options":["肝臟","胰臟","膽囊","胃"],"answer":[0],"explain":"膽汁由肝臟製造，每天約 500 mL，儲存在膽囊，進食時經膽管釋放入十二指腸。膽囊只是儲存和釋放，不是製造；胰臟分泌胰液，胃分泌胃液，三者的產物不要混淆，尤其膽囊與肝臟的分工最常考。","source":"第三章 3.3.1 肝臟和膽囊","chId":"ch03"},{"id":"q0304","ch":3,"level":1,"type":"single","style":"concept","q":"胃蛋白酶（pepsin）把蛋白質分解成甚麼？","options":["單醣","多勝肽","脂肪酸和甘油","氨基酸"],"answer":[1],"explain":"課文指胃蛋白酶把蛋白質轉化為多勝肽；氨基酸要再靠胰蛋白酶、胰凝乳蛋白酶和腸細胞的胜肽酶逐步分解。脂肪酸和甘油是脂肪分解產物，單醣是碳水化合物分解產物；把「多勝肽」誤當成最終產物氨基酸，是常見陷阱。","source":"第三章 胃部的功能","chId":"ch03"},{"id":"q0305","ch":3,"level":2,"type":"single","style":"concept","q":"歐氏神經叢（Auerbach's plexus）位於何處？","options":["黏膜上皮之下","黏膜下層","肌肉層的內環肌與外縱肌之間","漿膜之外"],"answer":[2],"explain":"課文指腸肌叢（歐氏神經叢）位於肌肉層的內環肌和外縱肌之間，供應鄰近平滑肌和血管；黏膜下層的神經叢則是麥氏神經叢。把歐氏叢放在黏膜上皮之下、黏膜下層或漿膜之外，都不符合課文。","source":"第三章 3.1.1 肌肉層、黏膜下層","chId":"ch03"},{"id":"q0306","ch":3,"level":2,"type":"single","style":"concept","q":"副交感神經受刺激時，消化道會出現甚麼反應？","options":["蠕動減少、分泌減少","只增加分泌，蠕動不變","括約肌全部放鬆且沒有蠕動","蠕動增加、腺體分泌增加"],"answer":[3],"explain":"課文指副交感神經透過活躍腸肌神經叢增加肌肉活動（尤其蠕動），並透過活躍黏膜下神經叢增加腺體分泌，所以蠕動和分泌會同時增加。說蠕動減少、只增加分泌、或括約肌全部放鬆而沒有蠕動，都是把交感效應或兩個神經叢的作用錯誤拆開。","source":"第三章 3.1.1 神經分佈","chId":"ch03"},{"id":"q0307","ch":3,"level":2,"type":"multi","style":"concept","q":"胃的功能包括下列哪些？","options":["分泌內在因子","製造膽汁","吸收大部分水分","暫時儲存食物","分泌鹽酸作非特異防禦"],"answer":[0,3,4],"explain":"課文列出的胃功能包括暫時儲存食物、分泌內在因子供 B12 吸收、以鹽酸作非特異防禦，以及分泌胃蛋白酶和胃泌素等。製造膽汁的是肝臟，大部分水分在小腸吸收，所以這兩項不屬於胃。","source":"第三章 胃部的功能","chId":"ch03"},{"id":"q0308","ch":3,"level":2,"type":"single","style":"concept","q":"膽汁在脂肪消化中的主要作用是甚麼？","options":["乳化脂肪","中和胃酸","把脂肪分解為脂肪酸和甘油","把蛋白質分解為多勝肽"],"answer":[0],"explain":"膽鹽把脂肪乳化成薄層，增加脂肪酶作用的表面積，但膽汁本身不含分解脂肪的酵素；真正把脂肪切成脂肪酸和甘油的是胰脂肪酶。中和胃酸、分解蛋白質或直接分解脂肪都不是膽汁的主要作用。","source":"第三章 3.3.1 肝臟和膽囊、表 3.2","chId":"ch03"},{"id":"q0309","ch":3,"level":3,"type":"single","style":"case","q":"一名病人胃部切除後出現維生素 B12 吸收不良。最可能缺少甚麼？","options":["胃蛋白酶","內在因子","胰澱粉酶","膽鹽"],"answer":[1],"explain":"課文指胃分泌內在因子，而內在因子是迴腸末端吸收維生素 B12 所必需；胃部切除最直接就是失去這個來源。膽鹽與脂肪乳化有關，胰澱粉酶分解澱粉，胃蛋白酶分解蛋白質，都不直接負責 B12 吸收。","source":"第三章 胃部的功能、表 3.2","chId":"ch03"},{"id":"q0310","ch":3,"level":3,"type":"multi","style":"concept","q":"小腸適合吸收的結構特徵包括哪些？","options":["絨毛內毛細血管壁只有一個細胞厚","絨毛壁只有一個細胞厚","絨毛增加表面積","有大量破骨細胞","表面由多層角質鱗狀上皮覆蓋"],"answer":[0,1,2],"explain":"課文指小腸表面有絨毛，絨毛壁只有一個細胞厚，與它接觸的毛細血管壁也只有一個細胞厚，以促進營養物質通過。破骨細胞屬骨骼；多層角質鱗狀上皮是皮膚表皮的特徵，不是小腸吸收面。","source":"第三章 3.3.1 小腸","chId":"ch03"},{"id":"q0311","ch":3,"level":3,"type":"single","style":"case","q":"膽結石阻塞膽管後，脂肪消化最先受影響的是哪一步？","options":["蛋白質分解為多勝肽","維生素 B12 吸收","脂肪乳化不足","澱粉分解為雙醣"],"answer":[2],"explain":"膽汁經膽管進入十二指腸，膽鹽負責乳化脂肪；膽管阻塞會令膽汁不能到達小腸，脂肪無法散成薄層，脂肪酶效率下降。蛋白質和澱粉的消化主要靠胃蛋白酶和胰澱粉酶，B12 吸收則靠內在因子和迴腸末端。","source":"第三章 3.3.1 肝臟和膽囊","chId":"ch03"}]},{"id":"ch04","num":4,"title":"骨骼","en":"Bones","group":"運動","tagline":"206 塊骨、骨骼結構與骨折修復","intro":"骨骼提供支撐、保護和肌肉附著，也是鈣的倉庫。考試主線是分區與數目（中軸／附肢、頸胸腰）、長骨與骨膜的構造、造骨與蝕骨細胞的平衡，以及骨折由血腫到骨痂重建的五個階段。","memoryHook":"頸七胸十二腰五；血腫、骨痂、重建——骨折五步記。","sections":[{"title":"骨架的分區與功能","points":["成人有 206 塊骨；最大是股骨，最細小是耳內的鐙骨。","骨架分中軸骨骼和附肢骨骼。中軸包括頭骨、脊柱、胸骨和肋骨；附肢包括肩帶、上肢、骨盆帶和下肢。","骨架構成體腔和小窩保護器官，組成關節，並給肌肉附著。","附肢骨骼的兩大功能是隨意活動和保護沿四肢縱向分佈的血管與神經。"],"table":{"headers":["分區","組成","主要功能"],"rows":[["中軸骨骼","頭骨、脊柱、胸骨、肋骨","保護腦、脊髓和胸腔器官，支撐身體"],["附肢骨骼","肩帶、上肢、骨盆帶、下肢","活動、移動、負重"]]}},{"title":"頭骨、脊柱與胸廓","points":["頭骨分顱骨和面骨；唯一可活動的頭骨是下頜骨，咀嚼由嚼肌帶動下頜骨。","顱骨保護腦，眼窩保護眼睛，顳骨保護耳，部分頭骨內的竇產生共鳴。","脊柱由 24 塊可動脊椎骨加上薦骨和尾骨構成：7 頸、12 胸、5 腰、1 薦骨（5 塊融合）、1 尾骨（4 塊融合）。","每個脊椎骨有椎孔，連成椎管保護脊髓；相鄰脊椎骨形成椎間孔，讓脊髓神經穿出。","胸廓由 12 塊胸椎、12 對肋骨和 1 塊胸骨組成，保護心、肺和大血管，並連接呼吸肌。"],"table":{"headers":["脊柱分區","數目"],"rows":[["頸椎","7"],["胸椎","12"],["腰椎","5"],["薦骨","1（由 5 塊薦椎融合）"],["尾骨","1（由 4 塊尾椎融合）"]]}},{"title":"骨骼的構造與微觀結構","points":["長骨有骨幹（diaphysis）和兩個骨骺（epiphysis）；骨幹是緻密質骨加中央骨髓腔（含黃骨髓），骨骺外層緻密、內層疏鬆。","骨膜（periosteum）分兩層：外層纖維層保護骨骼，內層含造骨細胞和蝕骨細胞，負責生長、修復和重建。","骨膜覆蓋骨骼，但關節面由透明軟骨代替；骨骺軟骨分隔骨幹與骨骺，成年後骨化。","骨質約 65% 是鈣鹽（主要是磷酸鈣），約三分之一是有機的骨基質（主要為膠原），細胞少於 2%。","造骨細胞形成骨骼並分泌膠原，成熟後成為骨細胞；蝕骨細胞負責骨再吸收，兩者平衡維持骨骼結構。"],"table":{"headers":["細胞／結構","功能"],"rows":[["造骨細胞（osteoblast）","形成新骨、分泌膠原和骨基質"],["骨細胞（osteocyte）","成熟的骨細胞，監控和維持骨骼組織"],["蝕骨細胞（osteoclast）","再吸收骨骼，維持形狀，清除多餘骨痂"],["骨單位（osteon）","緻密骨的管狀單位，中央管含血管和神經"]]}},{"title":"骨骼生長的荷爾蒙調節","points":["生長激素和甲狀腺素在嬰兒期和兒童期對骨架發育尤其重要，分泌過多或不足都會造成異常。","睾丸酮和雌激素推動青春期生長，之後促使骨骺板閉合，縱向生長停止；骨骼仍可終生長厚。","雌激素在青春期令女性骨盆變寬，成年後維持骨質；更年期雌激素下降會增加骨質疏鬆和骨折風險。","降鈣素增加鈣進入骨骼；副甲狀腺素減少鈣進入骨骼，從而調節血鈣。"],"table":{"headers":["荷爾蒙","對骨骼的主要作用"],"rows":[["生長激素","促進骨骼生長，兒童期尤其重要"],["甲狀腺素（T3／T4）","調節骨骼發育"],["雌激素","維持骨質；缺乏時易骨質疏鬆"],["降鈣素","增加鈣進入骨骼"],["副甲狀腺素","減少鈣進入骨骼，提升血鈣"]]}},{"title":"骨折修復","points":["骨折分三類：簡單（骨端不穿破皮膚）、複雜（骨端刺穿皮膚）、病理（疾病削弱骨骼造成）。","癒合五階段：血腫形成→炎症與肉芽組織（約 5 天）→骨痂形成→骨痂成熟→骨骼重建。","炎症期巨噬細胞在無血供下吞噬血腫和碎片；纖維組織母細胞、肉芽組織和新毛細血管進場。","造骨細胞分泌海綿質骨和軟骨形成骨痂；數星期後軟骨由新骨代替，骨髓腔逐漸重開。","修補部位通常比原來更厚更強，所以再次骨折多發生在其他位置。","延緩癒合的因素包括死骨碎片、血供不足、骨端排列不當、持續活動、感染、全身疾病、營養不良、類固醇和老化。"],"table":{"headers":["階段","主要事件","時間"],"rows":[["1 血腫","骨折末端之間形成血腫","立即"],["2 炎症／肉芽","巨噬細胞清除血腫和碎片","約 5 天"],["3 骨痂","造骨細胞分泌海綿骨和軟骨","數星期"],["4 成熟","軟骨逐步由新骨取代","數星期至數月"],["5 重建","骨髓腔重開，成熟緻密骨取代骨痂","數月"]]}}],"terms":[{"zh":"解剖位置","en":"Anatomical position","def":"人體直立、雙臂垂於兩側、手掌向前的標準描述姿勢。"},{"zh":"中軸骨骼","en":"Axial skeleton","def":"身體中軸線上的骨骼，包括頭骨、脊柱、胸骨和肋骨。"},{"zh":"附肢骨骼","en":"Appendicular skeleton","def":"附著於中軸骨骼的肢體骨骼，包括肩帶、上肢、骨盆帶和下肢。"},{"zh":"骨膜","en":"Periosteum","def":"覆蓋骨骼表面的有血管膜；內層含造骨細胞和蝕骨細胞。"},{"zh":"骨幹","en":"Diaphysis","def":"長骨的中段，由緻密質骨和中央骨髓腔構成。"},{"zh":"骨骺","en":"Epiphysis","def":"長骨的兩端，外層緻密骨、內層疏鬆骨。"},{"zh":"造骨細胞","en":"Osteoblast","def":"形成新骨、分泌膠原和骨基質的細胞，成熟後成為骨細胞。"},{"zh":"骨細胞","en":"Osteocyte","def":"成熟的骨骼細胞，負責監控和維持骨骼組織。"},{"zh":"蝕骨細胞","en":"Osteoclast","def":"在骨骼表面進行再吸收，維持骨骼形狀並清除多餘骨痂。"},{"zh":"骨痂","en":"Callus","def":"骨折後由新骨和軟骨形成的暫時性接合組織。"},{"zh":"骨單位","en":"Osteon","def":"緻密骨的管狀單位，中央管周圍排列骨板，又稱哈氏系統。"},{"zh":"骨質疏鬆","en":"Osteoporosis","def":"骨質減少、骨骼變脆的情況；雌激素下降是重要相關因素。"}],"examTips":["206 塊；股骨最大，鐙骨最小。","脊柱：頸 7、胸 12、腰 5；24 塊可動，薦骨和尾骨由融合骨組成。","造骨細胞製造骨，蝕骨細胞吸收骨；骨細胞是成熟後被困在骨質內的造骨細胞。","降鈣素→鈣入骨；副甲狀腺素→鈣出骨，別倒轉。","骨折癒合五階段：血腫→炎症／肉芽（約 5 天）→骨痂→成熟→重建。","血供不足、持續活動、骨端排列不當都會延緩癒合；股骨頸、舟狀骨和脛骨骨幹是高危部位。"],"remedies":[{"name":"Calcarea fluorica（氟化鈣）","note":"課文列為對骨骼、關節和肌肉骨骼系統有親和力，常用於外生骨贅、骨刺和關節炎；關節痛遇熱和動作會減輕。"},{"name":"Calcarea phosphorica（磷酸鈣）","note":"親和力在骨骼、骨縫、骨膜和軟骨；課文用於成長痛、骨折癒合不良、佝僂病和軟骨病，兒童骨骼發育遲緩亦相關。"},{"name":"Symphytum（紫草）","note":"親和力在軟骨、骨膜和扁平骨；課文用於骨折、骨膜損傷、鈍器傷後疼痛和骨不連合，眼部鈍傷也是重點。"}],"atlas":[],"questions":[{"id":"q0401","ch":4,"level":1,"type":"single","style":"concept","q":"成年人體內共有多少塊骨？","options":["106 塊","156 塊","306 塊","206 塊"],"answer":[3],"explain":"課文明確指人體內有 206 塊不同的骨骼。這個數字要與脊柱的 24 塊可動脊椎骨分開：24 只是脊柱的一部分，加上薦骨、尾骨和四肢、頭骨等才是全身 206 塊。","source":"第四章 4.2 骨骼","chId":"ch04"},{"id":"q0402","ch":4,"level":1,"type":"single","style":"concept","q":"人體最大的骨與最細小的骨，正確配對是？","options":["股骨與鐙骨","脛骨與腕骨","髖骨與趾骨","肱骨與指骨"],"answer":[0],"explain":"課文指人體內最大的骨骼是股骨，最細小的是耳內小骨之一的鐙骨。肱骨、脛骨和髖骨都比股骨小；指骨、腕骨和趾骨也不是最細小的骨。兩個極端都在課文點名，其他選項只是隨意配對。","source":"第四章 4.2 骨骼","chId":"ch04"},{"id":"q0403","ch":4,"level":1,"type":"single","style":"concept","q":"造骨細胞（osteoblast）的主要功能是甚麼？","options":["成熟後監控骨骼組織","形成新骨並分泌膠原","製造軟骨","再吸收骨骼"],"answer":[1],"explain":"課文指造骨細胞負責形成骨骼，分泌膠原和骨骼組織其他成分；它們成熟後被困於新骨內，成為骨細胞。再吸收是蝕骨細胞的工作，製造軟骨的是軟骨細胞，兩者不要與造骨細胞混淆。","source":"第四章 4.3.2 骨骼細胞","chId":"ch04"},{"id":"q0404","ch":4,"level":1,"type":"single","style":"concept","q":"長骨的骨髓腔內主要含哪種骨髓？","options":["紅骨髓","骨膜","黃骨髓","透明軟骨"],"answer":[2],"explain":"課文指長骨骨幹由緻密質骨和中央骨髓腔構成，骨髓腔內含多脂肪的黃骨髓；紅骨髓主要見於短骨、不規則骨、扁骨和種子骨的疏鬆質骨內。骨膜和透明軟骨是骨骼的其他構造，不是骨髓腔的內容物。","source":"第四章 4.3.1 長骨的一般結構","chId":"ch04"},{"id":"q0405","ch":4,"level":2,"type":"single","style":"concept","q":"脊柱的頸椎、胸椎和腰椎數目，正確的是？","options":["7、5、12","12、7、5","5、12、7","7、12、5"],"answer":[3],"explain":"課文列明 7 塊頸椎、12 塊胸椎、5 塊腰椎，另有 1 塊薦骨（5 塊融合）和 1 塊尾骨（4 塊融合）。把頸和腰倒轉、腰和胸倒轉、或頸和胸倒轉，都是常見的數字錯配。","source":"第四章 4.2.2 脊柱","chId":"ch04"},{"id":"q0406","ch":4,"level":2,"type":"single","style":"concept","q":"降鈣素（calcitonin）對骨骼與血鈣的作用是甚麼？","options":["增加鈣進入骨骼","促進蝕骨細胞再吸收","減少鈣進入骨骼","抑制造骨細胞形成骨"],"answer":[0],"explain":"課文指降鈣素增加鈣攝入骨骼，副甲狀腺素則促進骨釋放鈣、減少鈣進入骨骼，提升血鈣。促進蝕骨細胞再吸收、減少鈣進入骨骼或抑制造骨細胞，方向都與降鈣素相反。","source":"第四章 4.4.1 骨骼生長的荷爾蒙調節","chId":"ch04"},{"id":"q0407","ch":4,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於中軸骨骼（axial skeleton）？","options":["肋骨","脊柱","頭骨","肩胛骨","鎖骨"],"answer":[0,1,2],"explain":"課文指中軸骨架由頭骨、脊柱、胸骨和肋骨構成；鎖骨和肩胛骨屬肩帶，是附肢骨骼的一部分。這題的陷阱是把「位於軀幹附近」的肩帶骨誤當成中軸骨，位置接近不等於同一分區。","source":"第四章 4.2.2 中軸骨骼、4.2.3 附肢骨架","chId":"ch04"},{"id":"q0408","ch":4,"level":2,"type":"single","style":"concept","q":"骨折癒合的階段次序，正確的是？","options":["骨痂→血腫→炎症／肉芽→成熟→重建","血腫→炎症／肉芽→骨痂→成熟→重建","血腫→骨痂→炎症／肉芽→重建→成熟","炎症／肉芽→血腫→骨痂→重建→成熟"],"answer":[1],"explain":"課文列明五階段：血腫→炎症／肉芽→骨痂→成熟→重建。把血腫放到骨痂之後、把炎症與血腫倒轉、或把成熟與重建倒轉，都會打亂次序。","source":"第四章 4.5.1 骨骼的癒合","chId":"ch04"},{"id":"q0409","ch":4,"level":3,"type":"single","style":"case","q":"一名長者股骨頸骨折，骨折部位血液供應不足。最可能出現哪種後果？","options":["骨痂形成過多，骨骼特別堅硬","骨折在數天內完全癒合","軟骨性接合，修復部位較軟弱","骨折只形成血腫，沒有炎症期"],"answer":[2],"explain":"課文指血液供應不足會減少造骨細胞、增加軟骨細胞，可能導致骨折的軟骨性接合，修復部位較軟弱；股骨頸正是課文列出的高危部位。說骨痂過多、數天內完全癒合、或沒有炎症期，都與血供不足的結果相反。","source":"第四章 4.5.2 延緩骨折癒合的因素","chId":"ch04"},{"id":"q0410","ch":4,"level":3,"type":"multi","style":"concept","q":"下列哪些是課文列出的延緩骨折癒合因素？","options":["血液供應不足","年輕","骨端持續移動","骨端排列良好","死骨碎片或軟組織碎片"],"answer":[0,2,4],"explain":"課文列出的因素包括死骨和軟組織碎片、血供不足、骨端排列不當、骨端持續移動，以及感染、全身疾病、營養不良、類固醇和老化。骨端排列良好有利癒合；年輕也不是延緩因素。","source":"第四章 4.5.2 延緩骨折癒合的因素","chId":"ch04"},{"id":"q0411","ch":4,"level":3,"type":"single","style":"remedy","q":"一名病人跌倒後脛骨骨膜壓痛，骨折已接合但局部仍有刺痛，觸摸和動作時加重。課文中最對應的療劑是？","options":["Calcarea phosphorica","Calcarea fluorica","Bryonia","Symphytum"],"answer":[3],"explain":"Symphytum 的親和力在軟骨、骨膜和扁平骨，課文用於骨折、骨膜損傷、鈍器傷後疼痛和骨不連合；傷口癒合後仍留骨膜痛正是其重點。Calcarea fluorica 偏向外生骨贅和骨刺，Calcarea phosphorica 偏向成長痛和癒合不良，Bryonia 偏向滑液膜和漿膜。","source":"第四章 表八、紫草（Symphytum）","chId":"ch04"}]},{"id":"ch05","num":5,"title":"關節","en":"Joints","group":"運動","tagline":"三類關節、滑液關節結構與動作","intro":"關節是兩塊或以上骨骼相接的地方，活動度由纖維、軟骨到滑液關節依次增加。考試主線是滑液關節的共同結構（軟骨、滑囊韌帶、滑液膜、滑液）、六種關節類型與例子，以及穩定度與活動度的取捨。","memoryHook":"纖維不動、軟骨微動、滑液自由；肩最不穩、膝最大。","sections":[{"title":"三類關節","points":["關節是兩塊或以上骨骼交接的地方，讓骨骼互相連接並產生活動。","纖維關節（fibrous joints）以堅韌纖維組織連接，通常不可活動，例如頭骨骨縫。","軟骨關節（cartilaginous joints）以纖維軟骨墊分隔，可輕微活動，例如椎間盤和恥骨聯合。","滑液關節（synovial joints）在骨骼之間有充滿滑液的空間，可自由活動，例如肩、膝、髖。","牙齒以牙周韌帶固定於下頜骨；脛骨和腓骨之間的骨間膜屬纖維關節，容許有限度動作並穩定骨骼。"],"table":{"headers":["關節類型","活動度","例子"],"rows":[["纖維關節","不可活動（骨間膜有限度）","頭骨骨縫、牙齒與下頜骨、脛腓骨間膜"],["軟骨關節","可輕微活動","椎間盤、恥骨聯合、兒童骨骺板"],["滑液關節","可自由活動","肩、膝、髖、肘"]]}},{"title":"滑液關節的共同結構","points":["關節軟骨（articular cartilage）通常是透明軟骨，覆蓋骨骼相接處，提供平滑表面、吸收壓力並支撐體重。","關節軟骨沒有血液供應，營養來自滑液；年輕時可達 7 mm 厚，隨年齡變薄，緩衝能力下降。","滑囊韌帶（capsular ligament）是包圍關節的纖維袖狀物，既要夠鬆讓關節活動，又要夠強保護關節。","滑液膜（synovial membrane）由上皮細胞組成，內襯滑囊、覆蓋沒有軟骨的骨面和不負重的囊內結構。","滑液（synovial fluid）黏稠，含噬菌細胞，能潤滑、供養關節內結構、維持穩定並防止骨骼末端分開。","黏液囊（bursae）像軟墊，減少骨骼與韌帶、肌腱或皮膚之間的摩擦；半月軟骨和脂肪墊屬囊內結構。"],"table":{"headers":["結構","主要功能"],"rows":[["關節軟骨","平滑表面、吸收壓力、支撐體重；無血管，營養來自滑液"],["滑囊韌帶","包圍並連接骨骼，保護關節又不限制活動"],["滑液膜","內襯滑囊，分泌滑液，覆蓋部分囊內結構"],["滑液","潤滑、營養、含噬菌細胞、維持關節穩定"],["黏液囊","軟墊，減少骨骼與肌腱、韌帶或皮膚的摩擦"]]}},{"title":"滑液關節的類型","points":["球窩關節（ball and socket）由球狀頭進入杯狀窩，活動範圍最大，例如肩和髖。","屈戌關節（hinge）像門鉸，只容許屈曲和伸展，例如肘、膝、踝和指骨間關節。","滑動關節（gliding）關節面扁平或輕微彎曲，活動性最小，例如腕骨間、跗骨間和脊椎關節突。","車軸關節（pivot）讓骨骼在環形韌帶內旋轉，例如寰椎與樞椎、近側和遠側橈尺關節。","髁狀關節（condyloid）是髁狀突進入杯形凹陷，可屈伸、外展、內收和環繞，例如下頜、掌指和蹠趾關節。","鞍狀關節（saddle）像人坐在馬鞍上，最重要是拇指基部，能作對向動作，靈活性比髁狀關節更高。"],"table":{"headers":["類型","動作範圍","例子"],"rows":[["球窩","最大：屈伸、內收外展、旋轉、環繞","肩、髖"],["屈戌","只屈曲和伸展","肘、膝、踝、指骨間"],["滑動","最小，只滑動","腕骨間、跗骨間、脊椎關節突"],["車軸","旋轉","寰樞關節、近側及遠側橈尺關節"],["髁狀","屈伸、內收外展、環繞","下頜、掌指、蹠趾"],["鞍狀","屈伸、內收外展、環繞、對向","拇指基部（大多角骨與第一掌骨）"]]}},{"title":"主要肢體關節","points":["肩關節是人體活動性最大、也最不穩定的關節，由關節盂和肱骨頭構成，盂唇加深關節盂。","肘關節是屈戌關節，由肱骨滑車和小頭與尺骨、橈骨構成，非常穩定，只能屈曲和伸展。","髖關節是球窩關節，由髖臼和股骨頭構成，負荷體重，靠髂股、恥股、坐骨股韌帶和股骨頭韌帶穩定。","膝關節是最大最複雜的關節，由股骨髁、脛骨髁和膝蓋骨後面構成；十字韌帶在囊內，半月軟骨因支撐體重而不被滑液膜覆蓋。","踝關節是屈戌關節，由脛骨、腓骨和距骨構成；內翻和外翻發生在跗骨之間，不在踝關節。","腕關節是髁狀關節，由橈骨遠端與舟狀骨、月骨、三角骨構成；腕管內有屈肌肌腱和正中神經。"],"table":{"headers":["關節","類型","考試重點"],"rows":[["肩","球窩","活動最大、最不穩定，易脫臼"],["肘","屈戌","極穩定，只屈伸"],["髖","球窩","負重，韌帶強，臼唇加深"],["膝","屈戌（含旋轉）","最大最複雜；十字韌帶、半月軟骨"],["踝","屈戌","內外翻在跗骨間，不在踝"],["腕","髁狀","腕管有正中神經"]]}},{"title":"穩定度、活動度與臨床重點","points":["穩定度越高的關節，活動性通常越低；韌帶彈性、骨骼配合度和囊內結構都會影響動作範圍。","手指關節屬屈戌關節，只容許屈曲和伸展；拇指基部是鞍狀關節，其他手指的對應關節多為髁狀。","屈肌支持帶和伸肌支持帶把肌腱貼近骨骼，滑液鞘減少肌腱移動時的摩擦。","腕管由屈肌支持帶與腕骨圍成，正中神經受壓會影響拇指側的感覺和手部功能。"]}],"terms":[{"zh":"關節","en":"Joint","def":"兩塊或以上骨骼相接的地方，讓骨骼連接並產生活動。"},{"zh":"纖維關節","en":"Fibrous joint","def":"以堅韌纖維組織連接的關節，通常不可活動，例如頭骨骨縫。"},{"zh":"軟骨關節","en":"Cartilaginous joint","def":"以纖維軟骨墊分隔的關節，可輕微活動，例如椎間盤。"},{"zh":"滑液關節","en":"Synovial joint","def":"骨骼之間有充滿滑液的關節腔，可自由活動，例如肩和膝。"},{"zh":"關節軟骨","en":"Articular cartilage","def":"覆蓋骨骼相接處的透明軟骨，提供平滑表面並吸收壓力。"},{"zh":"滑囊韌帶","en":"Capsular ligament","def":"包圍關節的纖維袖狀物，連接骨骼並保護關節。"},{"zh":"滑液膜","en":"Synovial membrane","def":"內襯滑囊並分泌滑液的上皮樣膜，覆蓋部分囊內結構。"},{"zh":"滑液","en":"Synovial fluid","def":"關節腔內的黏稠液體，潤滑、滋養並維持關節穩定。"},{"zh":"黏液囊","en":"Bursa","def":"關節附近的軟墊，減少骨骼與肌腱、韌帶或皮膚的摩擦。"},{"zh":"球窩關節","en":"Ball and socket joint","def":"球狀頭進入杯狀窩的關節，活動範圍最大，例如肩和髖。"},{"zh":"屈戌關節","en":"Hinge joint","def":"像門鉸的關節，只容許屈曲和伸展，例如肘和膝。"},{"zh":"鞍狀關節","en":"Saddle joint","def":"像人坐在馬鞍上的關節，拇指基部可作對向動作。"}],"examTips":["纖維不可動、軟骨輕微、滑液自由；別把椎間盤當成滑液關節。","關節軟骨無血管，營養來自滑液；半月軟骨負重，所以不被滑液膜覆蓋。","手指關節是屈戌，拇指基部是鞍狀；其他手指基部多為髁狀。","膝關節最大最複雜，完全伸展時會鎖定；肩關節活動最大但最不穩定。","內翻和外翻發生在跗骨之間，不是踝關節。","腕管內有正中神經和屈肌肌腱，由屈肌支持帶圍成。"],"remedies":[{"name":"Bryonia（瀉根）","note":"課文指 Bryonia 對漿膜和滑液膜有親和力；關節痛因輕微動作而加重，病人常想保持不動。"},{"name":"Rhus toxicodendron（毒葛）","note":"課文列為對關節有親和力的療劑；僵硬疼痛在開始動作和寒冷潮濕時較差，持續動作和熱敷會較好。"},{"name":"Ruta（芸香）","note":"課文列為對關節有親和力的療劑，親和力偏向纖維組織、肌腱、腕和足踝；扭傷後僵硬疼痛與動作相關。"}],"atlas":[],"questions":[{"id":"q0501","ch":5,"level":1,"type":"single","style":"concept","q":"纖維關節、軟骨關節、滑液關節的活動度，正確的是？","options":["不可活動、可輕微活動、可自由活動","可自由活動、可輕微活動、不可活動","三者都可自由活動","可輕微活動、不可活動、可自由活動"],"answer":[0],"explain":"課文的分類就是按活動度：纖維關節不可活動（如頭骨縫），軟骨關節可輕微活動（如椎間盤），滑液關節可自由活動（如肩、膝、髖）。把次序倒轉、說三者都可自由活動、或把纖維和軟骨對調，都不符合課文。","source":"第五章 5.1.1 關節的三種類型","chId":"ch05"},{"id":"q0502","ch":5,"level":1,"type":"single","style":"concept","q":"膝關節屬於哪一種滑液關節？","options":["球窩關節","屈戌關節","鞍狀關節","車軸關節"],"answer":[1],"explain":"課文指膝關節是由股骨髁、脛骨髁和膝蓋骨後面構成的屈戌關節，可作屈曲、伸展和旋轉式動作；雖然有少量旋轉，分類仍屬屈戌。球窩是肩和髖，車軸是橈尺關節，鞍狀是拇指基部。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0503","ch":5,"level":1,"type":"single","style":"concept","q":"肩關節屬於哪一種滑液關節？","options":["滑動關節","鞍狀關節","球窩關節","屈戌關節"],"answer":[2],"explain":"肩關節由肩胛骨的關節盂腔和肱骨頭構成，是球窩關節，也是人體活動性最大、最不穩定的關節。盂唇和韌帶只是增加穩定，不改變球窩的分類；屈戌見於肘和膝，滑動見於腕骨間，鞍狀見於拇指基部。","source":"第五章 5.2.1 肩關節","chId":"ch05"},{"id":"q0504","ch":5,"level":1,"type":"single","style":"concept","q":"關節軟骨的營養主要來自哪裡？","options":["血液","骨髓","淋巴液","滑液"],"answer":[3],"explain":"課文指關節軟骨沒有血液供應，營養是從滑液中取得。正因為無血管，軟骨受損後的修復能力有限，這也是關節軟骨病變難處理的原因。血液、淋巴液和骨髓都不是關節軟骨的直接營養來源。","source":"第五章 5.1.4 關節軟骨","chId":"ch05"},{"id":"q0505","ch":5,"level":2,"type":"single","style":"concept","q":"下列哪一項不是滑液關節的共同特徵？","options":["骨縫","滑囊韌帶","滑液膜","關節軟骨"],"answer":[0],"explain":"滑液關節的共同特徵包括關節軟骨、包圍關節的滑囊韌帶、滑液膜和滑液。骨縫是頭骨之間的纖維關節，完全不可動，沒有關節腔也沒有滑液，與滑液關節的構造和活動度都不同；「有腔」是滑液關節的關鍵。","source":"第五章 5.1.4 滑液關節的特徵","chId":"ch05"},{"id":"q0506","ch":5,"level":2,"type":"single","style":"concept","q":"腳的內翻（inversion）和外翻（eversion）主要發生在哪裡？","options":["髖關節","跗骨之間","踝關節","膝關節"],"answer":[1],"explain":"課文明言內翻和外翻的動作發生在跗骨骨骼之間，而不是在踝關節；踝關節本身只做背屈和蹠屈。把內外翻當成踝關節動作，是這一章最常見的陷阱，也容易與足部肌肉的作用混淆。","source":"第五章 5.2.8 踝關節","chId":"ch05"},{"id":"q0507","ch":5,"level":2,"type":"multi","style":"concept","q":"滑液（synovial fluid）有下列哪些功能？","options":["含噬菌細胞，清除微生物和殘骸","提供營養給關節腔內結構","製造紅骨髓","分泌膽汁","潤滑關節"],"answer":[0,1,4],"explain":"課文列出的滑液功能包括潤滑、提供營養、含噬菌細胞清除微生物和細胞殘骸、維持關節穩定，以及防止骨骼末端分開。膽汁由肝臟製造，紅骨髓在骨骼內，兩者都與滑液無關；不要把滑液當成消化液或造血組織。","source":"第五章 5.1.4 滑液","chId":"ch05"},{"id":"q0508","ch":5,"level":2,"type":"single","style":"concept","q":"膝關節的半月軟骨為何不被滑液膜覆蓋？","options":["因為它們沒有血管","因為它們位於關節囊外","因為它們支撐體重","因為它們是纖維組織"],"answer":[2],"explain":"課文指不用支撐體重的囊內結構會被滑液膜覆蓋，但半月軟骨支撐體重，所以不被覆蓋；十字韌帶和脂肪墊則被滑液膜覆蓋。說半月軟骨沒有血管、位於囊外或是纖維組織，都不是課文給的理由。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0509","ch":5,"level":3,"type":"single","style":"case","q":"一名長時間打字的人出現手腕麻痛，醫生懷疑腕管內結構受壓。腕管內最可能受壓的神經是？","options":["尺神經","橈神經","坐骨神經","正中神經"],"answer":[3],"explain":"課文指腕管由屈肌支持帶與腕骨圍成，腕關節和手指的屈肌肌腱以及正中神經通過腕管。尺神經、橈神經不是課文列出的腕管內容；坐骨神經在下肢。這題考的是腕管限界的內容物。","source":"第五章 屈肌支持帶","chId":"ch05"},{"id":"q0510","ch":5,"level":3,"type":"multi","style":"concept","q":"關於膝關節，下列哪些敘述正確？","options":["它屬於球窩關節","半月軟骨完全被滑液膜覆蓋","完全伸展時關節會鎖定","它是人體最大、最複雜的關節","十字韌帶位於關節囊內"],"answer":[2,3,4],"explain":"課文指膝關節最大最複雜，十字韌帶互相交錯、位於囊內，完全伸展時關節會被鎖定。半月軟骨支撐體重，不被滑液膜覆蓋；膝是屈戌關節，不是球窩。把膝當成球窩、或說半月軟骨完全被滑液膜覆蓋，都是類型與結構的混淆。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0511","ch":5,"level":3,"type":"single","style":"remedy","q":"一名病人關節僵硬疼痛，早上起床和開始動作時最痛，活動一會兒及熱敷後減輕，寒冷潮濕時加重。最對應的療劑是？","options":["Rhus toxicodendron","Ruta","Calcarea fluorica","Bryonia"],"answer":[0],"explain":"Rhus toxicodendron 的特徵是開始動作、寒冷潮濕時較差，持續動作和熱敷後較好。Bryonia 相反，任何輕微動作都加重、想保持不動；Ruta 偏向扭傷後纖維和肌腱；Calcarea fluorica 偏向外生骨贅。","source":"第五章 5.3 對關節有親和力的療劑、補充筆記 Rhus tox","chId":"ch05"}]},{"id":"ch06","num":6,"title":"肌肉","en":"Muscular System","group":"運動","tagline":"三大肌肉類型、肌肉動作與收縮原理","intro":"肌肉章的主線是「結構決定控制方式」：心肌、平滑肌、骨骼肌位置與控制各不同，骨骼肌再靠肌腱拉動骨骼、以拮抗肌成對運作。考試最常考面部、頸部、軀幹與四肢肌肉的動作配對，以及收縮概念：全有全無律、等長與等張、疲勞與恢復；呼吸肌也常一起問。","memoryHook":"心肌自律、平滑不隨意、骨骼隨意；肌腱拉骨，拮抗成對。","sections":[{"title":"三種肌肉類型：位置決定控制方式","points":["心肌（cardiac muscle）位於心壁，屬不隨意肌，但能自行產生收縮，細胞融合成片同步運作。","平滑肌（smooth muscle）屬不隨意肌，遍佈內臟與消化道壁，負責維持器官系統的體內平衡，例如推動食物。","骨骼肌（skeletal muscle）是隨意肌，數量最多，經肌腱（tendon）附著骨骼，收縮時拉動骨骼產生動作。","三種肌肉都含可收縮的蛋白細絲，分別在結構、功能與位置上不同；平滑肌與心肌受自律神經控制，骨骼肌受中樞神經分支控制。","肌腱是容易破裂和發炎的纖維帶，也是運動受傷的常見部位；肌肉必須跨越至少一個關節才能帶動身體部分。"],"table":{"headers":["種類","位置","隨意控制","特點"],"rows":[["心肌","心壁","不隨意","可自行產生收縮、細胞成片"],["平滑肌","內臟、消化道壁","不隨意","維持體內平衡、推動管腔內容"],["骨骼肌","附於骨骼","隨意","經肌腱拉動骨骼、數量最多"]]}},{"title":"面部與頸部肌肉：表情、咀嚼與轉頭","points":["枕額肌（occipitofrontalis）前後兩部份由帽狀腱膜相連，收縮時向上提眉。","上瞼提肌提上眼瞼；眼輪匝肌圍繞眼睛，用力收縮時瞇眼；頰肌把頰壓向牙齒，又叫「小號手肌」。","口輪匝肌關閉嘴唇、可造吹口哨形；咬肌、顳肌、翼狀肌都能關閉下頜，翼狀肌還把下巴向前拉。","胸鎖乳突肌單側收縮把頭拉向同側肩膊、協助轉頭；兩側同時收縮屈曲頸椎，強迫呼吸時可上提胸骨與鎖骨。","斜方肌把頭往後拉、挺直肩膊，並在肩關節活動時控制肩胛骨。"],"table":{"headers":["肌肉","主要動作"],"rows":[["枕額肌","上提眉毛"],["上瞼提肌","上提眼瞼"],["眼輪匝肌","圍繞眼睛、用力時瞇眼"],["頰肌","壓迫頰部、迫使空氣排出"],["口輪匝肌","閉唇、吹口哨"],["咬肌／顳肌／翼狀肌","關閉下頜（翼狀肌另前拉下巴）"],["胸鎖乳突肌","轉頭、屈曲頸椎、強迫呼吸時上提胸骨鎖骨"],["斜方肌","後拉頭部、挺肩、控制肩胛骨"]]}},{"title":"軀幹與骨盆底：核心、腹壁弱點與支撐","points":["背部六對大肌肉包括斜方肌、背闊肌、大圓肌、腰大肌、腰方肌與骶脊肌；骶脊肌收縮使脊柱伸展。","背闊肌與大圓肌都能伸展、內收和內旋手臂；背闊肌起自髂骨脊後部及腰椎、下胸椎棘突。","腰方肌固定下方肋骨、伸展脊柱；單側收縮造成腰部側屈，是呼吸時的穩定肌。","腹壁五對肌肉由淺至深為腹直肌、外斜肌、內斜肌、腹橫肌與腰方肌；內外斜肌纖維成直角，腹橫肌與腹直肌成直角。","腹肌一齊收縮可壓縮腹部器官、屈曲腰椎；單側收縮使軀幹側彎，單側斜肌收縮使軀幹旋轉。白線由劍突延伸至恥骨聯合。","腹股溝管長 2.5–4 cm，男性含精索、女性含圓韌帶，是腹壁弱點；骨盆底由肛提肌與尾骨肌構成，支撐骨盆器官並維持大小便自控。"],"table":{"headers":["層次","肌肉","纖維方向／特點"],"rows":[["最表層","腹直肌","垂直走向，兩側由白線相連"],["第二層","外斜肌","向下向前斜行"],["第三層","內斜肌","與外斜肌纖維成直角"],["最深層","腹橫肌","橫行，與腹直肌纖維成直角"]]}},{"title":"上肢與下肢：動作與主力肌肉","points":["三角肌前部屈曲、中部外展、後部伸展及外旋肩關節；胸大肌屈曲和內收手臂。","二頭肌屈曲肘關節並旋後；肱肌是肘關節主要屈肌；三頭肌伸展肘關節並協助手臂內收。","旋前圓肌與旋前方肌使前臂旋前，旋後肌（常得二頭肌幫助）使前臂旋後。","橈側腕屈肌與橈側腕伸肌一同作用使腕外展；尺側腕屈肌與尺側腕伸肌一同作用使腕內收。","股四頭肌是膝關節強力伸肌，只有股直肌同時屈曲髖關節；膕繩肌屈曲膝關節。","腓腸肌與比目魚肌使踝蹠屈（踮腳），腓腸肌同時屈膝；脛骨前肌使足背屈；縫匠肌是人體最長的肌肉。"],"table":{"headers":["動作","主要肌肉"],"rows":[["肩外展","三角肌中部"],["肘屈曲","肱肌（主要）、二頭肌"],["肘伸展","三頭肌"],["前臂旋前","旋前圓肌、旋前方肌"],["膝伸展","股四頭肌"],["膝屈曲","膕繩肌"],["踝蹠屈","腓腸肌、比目魚肌"],["踝背屈","脛骨前肌"],["髖屈曲","腰大肌＋髂肌、股直肌"]]}},{"title":"收縮、張力、疲勞與呼吸肌","points":["全有全無律（all-or-none law）指單一肌纖維要麼完全收縮、要麼不收縮；整條肌肉的力量取決於同時收縮的纖維數目與刺激頻率。","肌肉張力是持續而部份的收縮，纖維組輪流工作以維持姿勢而不易疲勞；良好張力可保護關節。","持續用力超過氧氣與燃料供應時，厭氧代謝產生乳酸，加上 ATP／肝醣耗盡，便出現肌肉疲勞。","運動後需補充 ATP 與肝醣、修復纖維；氧氣負債期間身體把過多乳酸轉為丙酮酸。","等張收縮（isotonic）張力穩定而肌肉縮短；等長收縮（isometric）長度不變而張力上升，例如推不動的重物。","呼吸肌以橫膈膜與肋間肌為主；強迫吸氣時胸鎖乳突肌上提胸骨與鎖骨，腰方肌固定下肋骨，腹肌參與用力呼氣與咳嗽。"],"table":{"headers":["收縮類型","長度","張力","例子"],"rows":[["等張（isotonic）","縮短","保持穩定","提起茶杯"],["等長（isometric）","不變","上升","單手抬 80 kg 的人卻抬不動"]]}}],"terms":[{"zh":"心肌","en":"Cardiac muscle","def":"位於心壁的不隨意肌，能自行產生收縮，細胞融合成片同步運作。"},{"zh":"平滑肌","en":"Smooth muscle","def":"分佈於內臟與血管壁的不隨意肌，維持器官系統的體內平衡。"},{"zh":"骨骼肌","en":"Skeletal muscle","def":"受意識控制的隨意肌，經肌腱附著骨骼，收縮時拉動骨骼。"},{"zh":"肌腱","en":"Tendon","def":"連接肌肉與骨骼的纖維帶，容易破裂和發炎，是運動受傷常見部位。"},{"zh":"拮抗肌","en":"Antagonistic pair","def":"作用相反的一對肌肉，一方收縮時另一方放鬆，避免損傷。"},{"zh":"肌肉張力","en":"Muscle tone","def":"持續而部份的收縮，由纖維組輪流工作維持姿勢，不易疲勞。"},{"zh":"等長收縮","en":"Isometric contraction","def":"肌肉長度不變而張力上升，例如推不動的重物。"},{"zh":"等張收縮","en":"Isotonic contraction","def":"張力保持穩定而肌肉縮短的收縮，例如提起茶杯。"},{"zh":"白線","en":"Linea alba","def":"前腹壁中線的強韌腱索，由劍突延伸至恥骨聯合，連接兩側腹直肌。"},{"zh":"腹股溝管","en":"Inguinal canal","def":"長 2.5–4 cm 的斜行管道，男性含精索、女性含圓韌帶，是腹壁弱點。"}],"examTips":["心肌是「不隨意但有自律性」：不受意識控制，卻能自行起搏；不要因為不隨意就把它歸入平滑肌。","全有全無律講的是單一肌纖維，不是整條肌肉；整條肌肉的力量由收縮纖維數目與刺激頻率決定。","等長與等張只看長度有沒有變：推不動的 80 kg 是等長，提起茶杯是等張。","呼吸的主力是橫膈膜與肋間肌；腹肌與胸鎖乳突肌只在強迫呼吸、咳嗽時才明顯參與。","面部肌肉常考「關閉下頜」：咬肌、顳肌、翼狀肌三者都會，翼狀肌還把下巴向前拉。"],"remedies":[{"name":"毒葛（Rhus toxicodendron）","note":"補充筆記以它對應肌肉拉傷後加劇的背痛、僵硬而需活動，與本章肌腱和肌肉拉傷主題相應。"},{"name":"芸香（Ruta graveolens）","note":"補充筆記用於肌腱、扭傷及過度疲勞後的損傷，對應本章所說肌腱易破裂發炎的部位。"}],"atlas":[],"questions":[{"id":"q0601","ch":6,"level":1,"type":"single","style":"concept","q":"哪一種肌肉位於心壁、屬不隨意肌，卻能自行產生收縮？","options":["平滑肌","心肌","肌腱","骨骼肌"],"answer":[1],"explain":"心肌位於心壁，屬不隨意肌，卻能自行產生收縮，是唯一具自律性的肌肉類型。平滑肌也不隨意，但分佈在內臟與血管，並非心壁；骨骼肌屬隨意肌，需運動神經衝動才收縮；肌腱只是連接肌肉與骨骼的纖維帶，不是肌肉組織。","source":"第六章 6.1 肌肉組織的三種類型","chId":"ch06"},{"id":"q0602","ch":6,"level":1,"type":"single","style":"concept","q":"收縮時向上提眉的是哪一條肌肉？","options":["眼輪匝肌","頰肌","枕額肌","上瞼提肌"],"answer":[2],"explain":"枕額肌的額骨部份（frontalis）收縮時向上提眉。上瞼提肌只提上眼瞼；眼輪匝肌圍繞眼睛，用力收縮時瞇眼；頰肌壓迫頰部、協助排出空氣，三者都不負責提眉。本題的重點是把「提眉」與「提眼瞼」分開。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0603","ch":6,"level":1,"type":"single","style":"concept","q":"位於下頜角外側、咀嚼時把下頜骨向上拉並對食物施壓的是哪條肌肉？","options":["胸鎖乳突肌","口輪匝肌","頰肌","咬肌"],"answer":[3],"explain":"咬肌由顴弓延伸到下頜角，收縮時把下頜骨向上拉、關閉下巴，並對食物施加壓力。頰肌是把頰壓向牙齒；口輪匝肌關閉嘴唇；胸鎖乳突肌作用在頸部，與咀嚼無關。別把「閉唇」與「閉下頜」混為一談。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0604","ch":6,"level":1,"type":"single","style":"concept","q":"全有全無律（all-or-none law）是指什麼？","options":["單一肌纖維完全收縮或完全不收縮","肌肉收縮時一定會縮短","所有肌肉會同時收縮","整條肌肉只能全部收縮，不能局部收縮"],"answer":[0],"explain":"全有全無律指單一肌纖維要麼完全收縮、要麼完全不收縮；整條肌肉的力量取決於同時收縮的纖維數目與刺激頻率，所以「整條肌肉全收縮」是錯的。等長收縮時肌肉並不縮短，故「一定縮短」也錯；不同肌肉各有獨立控制，不會一起全收縮。","source":"第六章 6.2.1 A 肌肉張力","chId":"ch06"},{"id":"q0605","ch":6,"level":2,"type":"single","style":"concept","q":"呼吸時固定下方肋骨；若只有一側收縮，會使腰椎向該側屈曲。這是哪一條肌肉？","options":["背闊肌","腰方肌","腹直肌","骶脊肌"],"answer":[1],"explain":"腰方肌由髂骨脊走向第 12 肋骨，收縮時固定下方肋骨，單側收縮使腰椎側屈，雙側則協助脊柱伸展。骶脊肌主要做脊柱伸展；腹直肌屈曲腰椎；背闊肌作用在肩關節，不固定肋骨。","source":"第六章 6.1.2 A 背部肌肉","chId":"ch06"},{"id":"q0606","ch":6,"level":2,"type":"single","style":"case","q":"嘗試單手抬起一位 80 kg 的人但抬不動，手臂肌肉仍在用力收縮。這屬於哪種收縮？","options":["等張收縮","拮抗收縮","等長收縮","被動收縮"],"answer":[2],"explain":"等長收縮（iso＝相等，metric＝長度）是肌肉長度不變、張力上升：阻力太大，肌肉無法縮短，力量以張力形式產生。等張收縮則是張力穩定而肌肉縮短，例如提起茶杯。拮抗收縮與被動收縮都不是課文用來描述這種情況的術語。","source":"第六章 6.2.1 E 等長和等張收縮","chId":"ch06"},{"id":"q0607","ch":6,"level":2,"type":"multi","style":"concept","q":"關於肌肉疲勞，下列哪些正確？（選 2–3 項）","options":["疲勞是因為肌纖維數目即時減少","ATP 與肝醣儲存耗盡也可導致疲勞","乳酸堆積在運動中的肌肉會促成疲勞","疲勞時蛋白質會最先被分解供能","氧氣供應不足時改用厭氧代謝，產生乳酸"],"answer":[1,2,4],"explain":"氧氣不足時身體改用效能較差的厭氧代謝，乳酸堆積促成疲勞；ATP 與肝醣耗盡亦可致疲勞。肌纖維數目不會即時減少，疲勞是供應與代謝問題；蛋白質只在脂肪與碳水化合物供應耗盡後才可能被利用，不是最先分解。","source":"第六章 6.2.1 B 肌肉疲勞","chId":"ch06"},{"id":"q0608","ch":6,"level":2,"type":"multi","style":"concept","q":"下列哪些肌肉收縮時會關閉下頜（嘴巴）？","options":["顳肌","咬肌","口輪匝肌","頰肌","翼狀肌"],"answer":[0,1,4],"explain":"咬肌、顳肌、翼狀肌都能關閉下頜：咬肌上提下頜、顳肌關閉嘴巴並協助咀嚼、翼狀肌關閉嘴巴並把下巴向前拉。頰肌是把頰壓向牙齒、協助排出空氣；口輪匝肌關閉的是嘴唇，不是下頜。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0609","ch":6,"level":3,"type":"single","style":"case","q":"個案：男子跌倒後肩膀無力，手臂無法向側面抬起（外展）。最可能受傷的是哪條肌肉？","options":["胸大肌","背闊肌","肱二頭肌","三角肌"],"answer":[3],"explain":"三角肌中部（主要部分）負責肩關節外展，受傷時手臂難以向側抬起。胸大肌做屈曲與內收；背闊肌做伸展、內收與內旋；肱二頭肌主要屈肘與旋後，並協助穩定肩關節，三者都不主導外展。","source":"第六章 6.1.4 肩部和上肢的肌肉","chId":"ch06"},{"id":"q0610","ch":6,"level":3,"type":"multi","style":"concept","q":"下列哪些肌肉同時收縮時，可使手臂伸展、內收並向內旋轉？","options":["胸大肌","肱肌","三角肌前部","大圓肌","背闊肌"],"answer":[3,4],"explain":"背闊肌與大圓肌都能伸展、內收和內旋手臂，兩者都附著於肱骨，是把手向後、向內拉的代表。胸大肌是屈曲與內收；三角肌前部負責屈曲；肱肌是肘屈肌，三者都不做伸展。只選一條會漏掉另一個協同肌。","source":"第六章 6.1.2 A 背部肌肉","chId":"ch06"},{"id":"q0611","ch":6,"level":3,"type":"multi","style":"concept","q":"關於呼吸肌，下列哪些正確？（選 2–3 項）","options":["腰方肌收縮會使下方肋骨下降以協助吸氣","橫膈膜收縮時向下變平，增加胸腔體積","強迫吸氣時胸鎖乳突肌可上提胸骨與鎖骨","腹直肌是平靜吸氣的主要肌肉","肋間肌收縮把肋骨向上向外拉"],"answer":[1,2,4],"explain":"橫膈膜收縮向下變平、肋間肌收縮把肋骨向上向外拉，兩者同時增加胸腔容積；強迫吸氣時胸鎖乳突肌可上提胸骨與鎖骨。腹直肌屬腹壁肌，主要在用力呼氣與咳嗽時參與；腰方肌是固定下方肋骨，不是把它下降。","source":"第六章 6.1.2 C 胸廓的肌肉；第九章 9.3 呼吸機制","chId":"ch06"},{"id":"q0612","ch":6,"level":3,"type":"multi","style":"case","q":"馬拉松後肌肉需要恢復。下列哪些是課文所述的恢復過程？","options":["修復受損的肌肉纖維","以蛋白質取代所有碳水化合物儲存","在氧氣負債期間把過多乳酸轉為丙酮酸","補充 ATP 與肝醣儲存","即時增加肌纖維數目以抵銷損傷"],"answer":[0,2,3],"explain":"運動後肌肉要補充 ATP 與肝醣、修復受損纖維；氧氣負債期間身體把過多乳酸轉為丙酮酸並更新能量儲存。肌纖維數目不會因一次馬拉松而增加（肥大是纖維尺寸變大）；蛋白質也不是取代碳水化合物的儲存形式。","source":"第六章 6.2.1 C 肌肉恢復","chId":"ch06"}]},{"id":"ch07","num":7,"title":"神經系統導論","en":"Introduction to the Nervous System","group":"神經感官","tagline":"神經元、衝動傳遞、反射弧與自主神經","intro":"課文第七章從略，本單元按第十六章及標準入門內容整理。神經系統以神經元為單位，用電訊號和化學訊號連成反應網絡：中樞整合，感覺入、運動出，自主神經調節內臟。考試重點是神經元構造配對、突觸單向傳遞、反射弧五站，以及交感與副交感的相反效應。","memoryHook":"樹突收、軸突送、髓鞘加速；反射五站：受—感—中—運—效。","sections":[{"title":"神經系統的分工：中樞與周圍","points":["中樞神經系統（CNS）由腦和脊髓組成，是整合與指揮中心；脊髓同時是上行感覺和下行運動的通道，也可獨立完成脊髓反射。","周圍神經系統（PNS）由12對腦神經和31對脊髓神經組成，負責把訊息來回運送，是CNS與身體各部的接線。","感覺（傳入）神經把感受器的訊息送往CNS；運動（傳出）神經把指令送到骨骼肌，屬隨意控制。","自主神經系統（ANS）是運動神經中不隨意的一支，支配平滑肌、心肌和腺體，分交感與副交感，維持體內平衡。","分類要看「方向」而非「位置」：同一條周圍神經內可同時有感覺和運動纖維，稱為混合神經。"],"table":{"headers":["分部","組成","主要工作"],"rows":[["中樞（CNS）","腦、脊髓","整合、分析、發出指令；脊髓反射"],["周圍（PNS）","12對腦神經、31對脊髓神經","傳入感覺、傳出運動"],["感覺（傳入）","感受器→CNS","把溫度、痛、觸、位置等送入中樞"],["運動（傳出）","CNS→效應器","支配骨骼肌，屬隨意"],["自主（ANS）","交感、副交感","不隨意調節內臟、血管、腺體"]]}},{"title":"神經元的構造與類型","points":["神經元（neuron）是神經系統的結構與功能單位，負責接收、整合和傳遞衝動；神經膠質細胞提供支持、營養和髓鞘。","細胞體含細胞核和胞器，是代謝中心；樹突（dendrite）短而多分支，接收訊息並傳向細胞體。","軸突（axon）通常只有一條且較長，把衝動由細胞體傳出；末端分支成突觸終末（synaptic terminal），釋放神經傳導物質。","髓鞘（myelin sheath）是包在軸突外的脂質絕緣層，可加速傳導；髓鞘中斷處稱蘭氏結（node of Ranvier），衝動在此跳躍前進。","依功能分三類：感覺神經元（傳入）、運動神經元（傳出）和中間神經元（interneuron，多在CNS內作連接與整合）。"],"table":{"headers":["構造","功能"],"rows":[["細胞體","含細胞核，代謝與整合中心"],["樹突","接收訊息，傳向細胞體"],["軸突","把衝動由細胞體傳往末端"],["髓鞘","脂質絕緣，加快傳導速度"],["突觸終末","釋放神經傳導物質到突觸間隙"]]}},{"title":"神經衝動與突觸傳遞","points":["靜息時神經元膜內帶負電、膜外帶正電，稱為極化；刺激足夠強使膜電位達到閾值，便產生動作電位（衝動）。","動作電位是「全或無」：刺激達閾值就給出固定大小的衝動，更強的刺激只增加衝動頻率，不加大每個衝動。","衝動沿軸突以電訊號傳導；有髓鞘纖維在蘭氏結之間跳躍傳導，比無髓鞘纖維快，所以粗而有髓的纖維反應最快。","到達突觸終末後，訊號由電轉為化學：突觸小泡釋放神經傳導物質（neurotransmitter）到突觸間隙，與突觸後膜的感受器結合。","突觸傳遞是單向的，只能由突觸前傳向突觸後，並可被加強或抑制；這解釋了神經路徑的固定方向和藥物作用點。","常見傳導物質包括乙醯膽鹼（acetylcholine）和正腎上腺素（noradrenaline）；交感與副交感末梢用不同傳導物質。"]},{"title":"反射弧：五個組成部分","points":["反射（reflex）是不經意識、快速而固定的反應；完成反射的神經路徑稱反射弧（reflex arc），是最基本的神經迴路。","五個部分依次是：感受器→感覺神經元→整合中樞（脊髓或腦）→運動神經元→效應器（肌肉或腺體）。","感受器偵測刺激（如皮膚受熱、肌腱被拉長）並產生衝動；效應器執行反應，兩者都不是神經元，是最易漏答的一站。","多數反射弧在脊髓層面完成，大腦不必參與；大腦可在意識層面抑制或加強反射，例如排尿反射可暫時忍住。","膝反射是單突觸反射的例子：敲打髕韌帶→股四頭肌收縮；只用一個突觸，反應最快。","反射的意義是爭取時間：痛覺到達意識之前，身體已先縮手，避免進一步受傷。"],"table":{"headers":["組成","工作","例子"],"rows":[["感受器","偵測刺激、產生衝動","皮膚痛覺感受器"],["感覺神經元","把衝動傳入中樞","背根神經節"],["整合中樞","分析並決定反應","脊髓灰質"],["運動神經元","把指令傳出","前根"],["效應器","執行反應","骨骼肌、平滑肌、腺體"]]}},{"title":"交感與副交感：戰鬥或逃跑 vs 休息與消化","points":["自主神經系統由交感與副交感兩支組成，多數器官同時受兩者支配，效應相反，平時互相平衡以維持體內平衡。","交感神經在恐懼、尷尬、憤怒、運動和寒冷時被激活，動員能量，讓身體「戰鬥或逃跑」。","副交感神經在休息、進食和睡眠時為主，促進消化、吸收、排尿和生殖功能，是「休息與消化」。","典型對比：交感使心跳加快、瞳孔放大、氣道擴張、消化減慢、膀胱放鬆；副交感則心跳減慢、瞳孔縮小、氣道收窄、消化和排尿增加。","腎上腺髓質受交感神經刺激而分泌腎上腺素和正腎上腺素入血，把交感效應加強並延長，是神經與內分泌的交會點。","記憶時要成對記「同一器官的相反效應」，不要只背「交感興奮」這種空泛口號。"],"table":{"headers":["器官","交感（戰鬥或逃跑）","副交感（休息與消化）"],"rows":[["心臟","心跳加快、收縮力增強","心跳減慢、力量減弱"],["瞳孔","輻射肌收縮、瞳孔放大","環狀肌收縮、瞳孔縮小"],["氣道","平滑肌放鬆、細支氣管擴張","平滑肌收縮、氣道收窄"],["消化","蠕動和分泌減少、括約肌收緊","蠕動和分泌增加"],["膀胱","膀胱壁放鬆、內括約肌收緊","膀胱壁收縮、內括約肌放鬆（排尿）"]]}}],"terms":[{"zh":"神經元","en":"Neuron","def":"神經系統的結構與功能單位，由細胞體、樹突和軸突組成，負責接收、整合和傳遞衝動。"},{"zh":"樹突","en":"Dendrite","def":"神經元短而多分支的突起，接收來自其他神經元或感受器的訊息，傳向細胞體。"},{"zh":"軸突","en":"Axon","def":"由細胞體伸出的長纖維，把神經衝動傳往突觸終末，通常只有一條。"},{"zh":"髓鞘","en":"Myelin sheath","def":"包圍軸突的脂質絕緣層，使衝動在蘭氏結之間跳躍傳導，加快速度。"},{"zh":"突觸","en":"Synapse","def":"神經元與下一個細胞之間的接合處，訊號經神經傳導物質越過突觸間隙，傳遞是單向的。"},{"zh":"神經傳導物質","en":"Neurotransmitter","def":"突觸終末釋放的化學信差，如乙醯膽鹼、正腎上腺素，與突觸後膜感受器結合。"},{"zh":"反射弧","en":"Reflex arc","def":"完成反射的神經路徑，由感受器、感覺神經元、整合中樞、運動神經元和效應器五站組成。"},{"zh":"效應器","en":"Effector","def":"執行反應的構造，可以是骨骼肌、平滑肌、心肌或腺體，不是神經元。"},{"zh":"中樞神經系統","en":"Central nervous system (CNS)","def":"由腦和脊髓組成，負責整合訊息、作出決定和發出指令。"},{"zh":"周圍神經系統","en":"Peripheral nervous system (PNS)","def":"由12對腦神經和31對脊髓神經組成，連接中樞與身體各部。"},{"zh":"交感神經","en":"Sympathetic nervous system","def":"自主神經的一支，在壓力、恐懼和運動時動員身體，即「戰鬥或逃跑」。"},{"zh":"副交感神經","en":"Parasympathetic nervous system","def":"自主神經的一支，在休息和進食時促進消化、吸收和排尿，即「休息與消化」。"}],"examTips":["樹突與軸突方向最易倒轉：記「樹突入、軸突出」，衝動由樹突→細胞體→軸突→突觸終末，不能反過來。","有髓鞘＝快，不等於「有髓鞘才有衝動」；無髓鞘纖維一樣傳導，只是較慢，髓鞘也不會改變衝動大小。","突觸是單向的：選項常說「可雙向傳遞」或「直接電傳」；化學突觸要經傳導物質，所以有延遲。","反射弧五站中，感受器和效應器常被誤當神經元；效應器可以是肌肉或腺體，不一定是肌肉。","交感與副交感要成對記：交感放大瞳孔、副交感縮小；交感放鬆膀胱、副交感收縮膀胱排尿，方向不要對調。","ANS的「不隨意」不等於完全不受意識影響：排尿反射可被大腦暫時抑制。"],"remedies":[],"atlas":[],"questions":[{"id":"q0701","ch":7,"level":1,"type":"single","style":"concept","q":"神經元中哪個構造主要負責接收訊息，並把訊息傳向細胞體？","options":["樹突","突觸終末","髓鞘","軸突"],"answer":[0],"explain":"樹突短而多分支，表面積大，專門接收來自其他神經元或感受器的訊息，再傳向細胞體。軸突是把衝動由細胞體傳出的單一條長纖維，方向剛好相反，是最常見的倒轉陷阱；髓鞘只是包在軸突外的脂質絕緣層，負責加快傳導；突觸終末位於軸突末端，負責釋放傳導物質。記住「樹突入、軸突出」。","source":"第七章從略；標準入門：神經元構造（對應第十六章16.1興奮性與傳導性）","chId":"ch07"},{"id":"q0702","ch":7,"level":1,"type":"single","style":"concept","q":"反射弧中，實際執行反應的構造是哪一站？","options":["感覺神經元","效應器","整合中樞","感受器"],"answer":[1],"explain":"效應器是反射弧的終站，收到運動神經元的指令後執行反應，可以是骨骼肌、平滑肌、心肌或腺體。感受器是起點，負責偵測刺激；感覺神經元把衝動傳入；整合中樞（脊髓或腦）決定要不要反應。考生常把「效應器」與「感受器」對調，或以為效應器一定是肌肉，忽略了腺體也是效應器。","source":"第七章從略；標準入門：反射弧五個組成部分","chId":"ch07"},{"id":"q0703","ch":7,"level":1,"type":"single","style":"concept","q":"副交感神經興奮時，下列哪項是典型效應？","options":["心跳加快","瞳孔放大","心跳減慢","細支氣管擴張"],"answer":[2],"explain":"副交感神經主「休息與消化」，使心跳減慢、心肌收縮力減弱，並促進胃腸蠕動和排尿。瞳孔放大、心跳加快和細支氣管擴張都是交感神經在「戰鬥或逃跑」時的效應，方向剛好相反。這題的三個干擾項都屬交感效應，只要把兩支的功能成對記住，就不會被單一「興奮」字眼誤導。","source":"第七章從略；標準入門：自主神經系統（對應第十六章16.4.1）","chId":"ch07"},{"id":"q0704","ch":7,"level":2,"type":"single","style":"concept","q":"有髓鞘的軸突傳導衝動比無髓鞘者快，主要原因為何？","options":["傳導物質釋放較多","突觸數目較多","衝動的幅度較大","衝動在蘭氏結之間跳躍傳導"],"answer":[3],"explain":"髓鞘是脂質絕緣層，離子只能在髓鞘中斷處（蘭氏結）交換，所以衝動逐結跳躍前進，速度大增。衝動幅度由「全或無」定律決定，不因髓鞘而變大；突觸數目多反而增加傳遞延遲，不會加快同一條纖維的傳導；傳導物質多少影響突觸傳遞強弱，與軸突傳導速度無直接關係。","source":"第七章從略；標準入門：髓鞘與跳躍傳導","chId":"ch07"},{"id":"q0705","ch":7,"level":2,"type":"single","style":"concept","q":"刺激強度已達閾值後再繼續增強，神經衝動會如何改變？","options":["衝動的頻率增加","每個衝動的幅度增大","髓鞘增厚以加速","傳導方向反轉"],"answer":[0],"explain":"動作電位遵循「全或無」：一旦達到閾值，每個衝動的幅度就固定，刺激再強也不會令單一衝動變大，只會令衝動產生的頻率增加，中樞便以此判斷刺激強弱。方向由樹突→細胞體→軸突固定，不會反轉；髓鞘厚度是解剖結構，不會即時因刺激而改變。把「更強刺激＝更大衝動」當成正確，是最典型的誤解。","source":"第七章從略；標準入門：動作電位的全或無定律","chId":"ch07"},{"id":"q0706","ch":7,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於反射弧的組成部分？（選出2–3項）","options":["髓鞘","突觸小泡","運動神經元","效應器","感受器"],"answer":[2,3,4],"explain":"反射弧五站是感受器、感覺神經元、整合中樞、運動神經元和效應器，本題正確項為感受器、運動神經元和效應器。突觸小泡是突觸終末內儲存傳導物質的胞器，髓鞘是軸突外的絕緣層，兩者都是神經元內部的構造，不是反射弧的「站」。分辨方法是問「這是不是路徑上傳遞或執行訊息的一個環節」，而不是「是否與神經有關」。","source":"第七章從略；標準入門：反射弧五個組成部分","chId":"ch07"},{"id":"q0707","ch":7,"level":3,"type":"single","style":"case","q":"學生敲打髕韌帶測試膝反射，若該反射弧的感覺神經元被阻斷，最可能出現什麼結果？","options":["小腿仍會前踢，但病人沒有感覺","小腿完全不會前踢","小腿前踢幅度反而變大","只有對側小腿失去反應"],"answer":[1],"explain":"反射弧必須完整，任何一站斷開都無法完成。感覺神經元負責把肌腱被拉長的訊息傳入脊髓，斷了就沒有衝動傳到整合中樞，運動神經元不會被激活，所以不會前踢。「仍能踢但沒有感覺」是感覺上行路徑受阻、反射弧仍完整的情況，屬不同層次的陷阱；反射弧是單側同側進行的，不會只影響對側。","source":"第七章從略；標準入門：反射弧完整性（對應第十六章16.4脊髓反射）","chId":"ch07"},{"id":"q0708","ch":7,"level":3,"type":"multi","style":"case","q":"交感神經被強烈激活時，下列哪些效應會出現？（選出2–3項）","options":["瞳孔放大","細支氣管擴張","胃腸蠕動增加","心跳加快","膀胱內括約肌放鬆"],"answer":[0,1,3],"explain":"交感＝戰鬥或逃跑：虹膜輻射肌收縮令瞳孔放大、細支氣管平滑肌放鬆令氣道擴張、竇房結被加速令心跳加快。相反，胃腸蠕動和分泌被抑制而非增加；膀胱壁放鬆而內括約肌收緊，是抑制排尿而非放鬆括約肌。後兩項其實是副交感的效應，把它們當成交感是本章最常見的對調陷阱。","source":"第七章從略；標準入門：交感與副交感的對比（對應第十六章16.4.1）","chId":"ch07"},{"id":"q0709","ch":7,"level":3,"type":"single","style":"case","q":"考生進入試場前心跳加速、手心出汗、瞳孔放大，此時最主要由哪個系統主導？","options":["只由脊髓反射控制","軀體運動神經系統","交感神經系統","副交感神經系統"],"answer":[2],"explain":"恐懼和壓力激發交感神經，並刺激腎上腺髓質分泌腎上腺素和正腎上腺素，形成「戰鬥或逃跑」：心跳加快、出汗、瞳孔放大。副交感是休息與消化，效應方向相反；軀體運動神經只支配隨意骨骼肌，不能解釋瞳孔和出汗；這些反應由下丘腦協調，不是單靠脊髓反射。","source":"第七章從略；標準入門：交感神經與壓力反應（對應第十六章16.4.1）","chId":"ch07"}]},{"id":"ch08","num":8,"title":"肌肉—骨骼的營養","en":"Nutrition for Muscles and Bones","group":"運動","tagline":"維他命、礦物質、BMI 與肥胖併發症","intro":"營養章的主線是「缺什麼、補什麼、過多又怎樣」：脂溶性與水溶性維他命的來源、功能與缺乏症要能配對；鈣、鎂、維他命 D、K、C 等共同建構骨骼基質，單吃鈣片並不足夠；BMI 用來篩檢營養失調與肥胖，而肥胖會帶來膽石、心血管病、糖尿病與骨關節炎。","memoryHook":"A 眼、D 骨、E 抗氧、K 凝血；B 雜顧代謝，C 造膠原。","sections":[{"title":"營養失調與 BMI","points":["營養失調（malnutrition）可源於蛋白質—能量營養失調（PEM）、缺乏維他命，或兩者同時出現。","BMI＝體重（kg）÷身高²（m²），用來評估營養失調程度與肥胖；身高未換成米是最常見的計算錯誤。","PEM 是蛋白質、碳水化合物與脂肪攝取不足，長期飢餓或創傷、發燒、疾病增加需求時出現，嬰幼兒最易受累。","瓜西奧科兒症（kwashiorkor）以缺乏蛋白質為主：血漿蛋白下降致腹水與下肢水腫，水腫掩飾消瘦，肝臟嚴重受損。","消瘦（marasmus）是蛋白質與碳水化合物同時缺乏，分解肌肉與脂肪，致嚴重消瘦、皮膚皺縮、頭髮脫落。","表 8.3 以 BMI 分級營養失調：＞20 正常、18.5–20 邊緣、17–18.5 輕微、16–17 中度、＜16 重度。"],"table":{"headers":["BMI（WHO）","分類"],"rows":[["＜18.5","過輕"],["18.5–24.9","正常"],["25.0–29.9","過重／肥胖前期"],["30.0–39.9","肥胖"],["≥40.0","嚴重肥胖"]]}},{"title":"脂溶性維他命：A、D、E、K","points":["脂溶性維他命 A、D、E、K 隨脂肪吸收，需要膽汁；礦物油會阻礙它們的吸收。","維他命 A（視黃醇）維持上皮組織與角膜、形成視紫質；缺乏致夜盲症、乾眼病、角質化。","維他命 D（鈣化固醇）促進鈣與磷酸鹽吸收，維持骨骼牙齒；兒童缺乏致佝僂病，成人缺乏致軟骨病。","維他命 E（生育酚）是抗氧化劑並促進免疫功能；缺乏可致貧血、運動失調、視力障礙。","維他命 K（Phylloquinone）在肝臟形成凝血酵素原與凝血因子 VII、IX、X；缺乏致凝血緩慢、新生嬰兒出血。"],"table":{"headers":["維他命","主要來源","功能","缺乏"],"rows":[["A","奶、牛油、蛋黃、魚肝油、綠黃葉菜","上皮與角膜、視紫質","夜盲、乾眼、角質化"],["D","魚肝油、奶、蛋黃、日光照射皮膚","促進鈣磷吸收","佝僂病、軟骨病"],["E","蛋黃、奶、牛油、綠葉菜、堅果","抗氧化、免疫功能","貧血、運動失調"],["K","多葉蔬菜、魚、肝、水果","凝血酵素原與凝血因子","凝血緩慢、嬰兒出血"]]}},{"title":"水溶性維他命：B 雜與 C","points":["B1（硫胺素）參與碳水化合物代謝與神經細胞營養；缺乏致疲勞、肌肉張力下降，最終腳氣病（beriberi）。","B2（核黃素）參與碳水與蛋白質代謝、維持皮膚健康；缺乏致口角炎、皮膚炎。","B3（菸鹼酸）為細胞呼吸所需並抑制膽固醇產生；長期缺乏致糙皮病（pellagra）：皮膚炎、腹瀉、癡呆。","B12（鈷胺素）參與 DNA 合成；缺乏致巨胚紅血球性貧血與脊髓神經纖維退化。","葉酸參與 DNA 合成與懷孕早期胎兒脊髓發育；缺乏與巨胚紅血球性貧血相關。","C（抗壞血酸）形成膠原蛋白、使紅血球成熟、抗氧化；缺乏致出血、傷口癒合慢、貧血，嚴重者壞血病。"],"table":{"headers":["維他命","功能","缺乏"],"rows":[["B1","碳水代謝、神經細胞營養","疲勞、肌肉張力下降、腳氣病"],["B2","碳水與蛋白質代謝、皮膚健康","口角炎、皮膚炎"],["B3","細胞呼吸、抑制膽固醇","糙皮病（皮膚炎、腹瀉、癡呆）"],["B12","DNA 合成","巨胚紅血球性貧血、脊髓神經退化"],["葉酸","DNA 合成、胎兒脊髓發育","課文未列缺乏症"],["C","膠原蛋白、抗氧化、紅血球成熟","出血、癒合慢、壞血病"]]}},{"title":"骨骼基質：不是單靠鈣","points":["骨骼的主要結構成分是磷酸鈣（calcium phosphate），肌肉含蛋白質纖維，神經活動則依賴鈣、鈉、鉀。","骨骼基質不是單靠鈣：鎂、維他命 D、K、C、B6、鋅、銅、錳都參與建構，最後由磷酸鈣黏合。","單獨大量服用鈣補充品不能預防骨質疏鬆，反而可能令身體負荷無法溶解的鈣鹽。","評估病人飲食是否有廣泛優質食物；嚴重缺乏時轉介註冊營養治療師。","課文以生物組織鹽對應礦物：氟化鈣主彈性，磷酸鈣主骨骼牙齒，磷酸鎂為抗痙攣與神經鬆弛劑。"],"table":{"headers":["營養素","在骨骼健康中的角色（課文）"],"rows":[["鈣＋磷","形成磷酸鈣，骨骼主要結構成分"],["鎂、維他命 D、K、C、B6、鋅、銅、錳","建構骨骼基質所需"],["維他命 D","促進鈣與磷酸鹽吸收"],["單獨鈣補充","不足以預防骨質疏鬆"]]}},{"title":"肥胖與其併發症","points":["肥胖是身體脂肪過量積聚，能量攝取大於消耗；不活動而進食超過每日需求者最常見。","膽石多為膽固醇沉澱，肥胖、女性、多次懷孕、口服避孕藥與高膽固醇飲食都是易感因素。","肥胖傾向缺血性心臟病與高血壓：粥樣斑使冠狀動脈變窄致心絞痛，閉塞致心肌梗塞。","II 型糖尿病約佔糖尿病九成，肥胖與久坐是易感因素；胰島素抗性使葡萄糖難以進入細胞。","負重關節的骨關節炎與肥胖有關；腹內壓增加亦與疝氣、滾動性空隙疝及靜脈曲張有關。"],"table":{"headers":["併發症","課文重點"],"rows":[["膽石","膽固醇沉澱；可致膽絞痛、膽囊炎、阻塞性黃疸"],["缺血性心臟病","冠狀動脈粥樣斑變窄→心絞痛；閉塞→心肌梗塞"],["高血壓","原發性佔 95%，影響心、腦、腎、視網膜"],["II 型糖尿病","約佔九成，肥胖與久坐為易感因素"],["骨關節炎","軟骨變薄、骨刺，負重關節受累"],["疝氣／靜脈曲張","腹內壓或靜脈壓上升，瓣膜失效"]]}}],"terms":[{"zh":"身體質量指數","en":"Body mass index (BMI)","def":"體重（kg）除以身高平方（m²），用於評估營養失調與肥胖程度。"},{"zh":"蛋白質—能量營養失調","en":"Protein-energy malnutrition (PEM)","def":"蛋白質、碳水化合物與脂肪攝取不足，嬰幼兒與長期飢餓者最易受累。"},{"zh":"瓜西奧科兒症","en":"Kwashiorkor","def":"以蛋白質缺乏為主，血漿蛋白下降致腹水與下肢水腫，並有肝損害。"},{"zh":"消瘦","en":"Marasmus","def":"蛋白質與碳水化合物同時缺乏，分解肌肉與脂肪，致嚴重消瘦與皮膚皺縮。"},{"zh":"脂溶性維他命","en":"Fat-soluble vitamins","def":"維他命 A、D、E、K，隨脂肪吸收並需要膽汁，礦物油會阻礙吸收。"},{"zh":"水溶性維他命","en":"Water-soluble vitamins","def":"維他命 B 雜與 C，參與能量代謝、DNA 合成、膠原蛋白形成等。"},{"zh":"骨關節炎","en":"Osteoarthritis","def":"退化性非炎症關節病，軟骨變薄、關節面受損，可形成骨刺。"},{"zh":"膽石","en":"Gallstones","def":"膽汁成分沉澱，多為膽固醇；可致膽絞痛、膽囊炎或膽管阻塞。"},{"zh":"吸收不良","en":"Malabsorption","def":"營養素未被有效吸收，可針對單一營養素或一系列營養素。"},{"zh":"惡性貧血","en":"Pernicious anaemia","def":"缺乏維他命 B12 的貧血，自身抗體破壞內在因子與胃壁細胞。"}],"examTips":["BMI 公式是 kg ÷ m²，身高要先由 cm 換成 m；1.6 m 不是 160。","脂溶性維他命吸收靠膽汁，礦物油會阻礙吸收；脂肪吸收不良會連帶缺乏 A、D、E、K。","維他命 K 缺乏看凝血（凝血酵素原、因子 VII、IX、X），不是看貧血。","表 8.1 把維他命 K 的化學名寫成「葉酸（Phylloquinone）」，但葉酸其實屬 B 雜；答題以「K＝凝血」為準。","課文正文說 BMI 超過 31 才肥胖，表 8.4 卻是 WHO ≥30、亞洲 ≥25；計算題請用表 8.4。","表 8.3 與表 8.4 是兩套切點：8.3 用於營養失調分級（＜16 重度），8.4 用於過重與肥胖分類，別混用。"],"remedies":[{"name":"氟化鈣（Calc fluor）","note":"課文稱它為彈性礦物，是骨骼、牙齒、皮膚、肌肉與血管的結構成分；缺乏見於靜脈曲張、牙釉質差、脆甲。"},{"name":"磷酸鈣（Calc phos）","note":"骨骼、指甲與牙齒的主要礦物成分；缺乏時骨折修復不良、礦物質吸收差。"},{"name":"磷酸鎂（Mag phos）","note":"抗痙攣與神經鬆弛劑；缺乏見頭痛伴視力模糊、神經痛、絞痛，也用於書寫時手部痙攣。"}],"atlas":[],"questions":[{"id":"q0801","ch":8,"level":1,"type":"single","style":"concept","q":"身體質量指數（BMI）的計算方式是？","options":["身高²（m²）÷體重（kg）","體重（kg）÷身高（cm）","體重（kg）×身高²（m²）","體重（kg）÷身高²（m²）"],"answer":[3],"explain":"BMI＝體重（kg）÷身高²（m²），身高必須以米為單位。用 cm 直接代入會把數值放大多倍；把公式倒轉或相乘，都會得出錯誤分類，這是計算題最常見的失分位。記住分子是體重、分母是身高的平方。","source":"第八章 8.1 C 肥胖症（表 8.4）","chId":"ch08"},{"id":"q0802","ch":8,"level":1,"type":"single","style":"concept","q":"兒童缺乏維他命 D 會導致什麼疾病？","options":["佝僂病","夜盲症","壞血病","軟骨病"],"answer":[0],"explain":"維他命 D 促進鈣與磷酸鹽吸收，兒童缺乏造成佝僂病，成人缺乏則為軟骨病。夜盲症屬維他命 A 缺乏；壞血病屬維他命 C 缺乏；腳氣病屬維他命 B1 缺乏，與 D 無關。","source":"第八章 8.1 表 8.1 脂溶性維他命","chId":"ch08"},{"id":"q0803","ch":8,"level":1,"type":"single","style":"concept","q":"嚴重缺乏維他命 C 會引起什麼疾病？","options":["糙皮病","壞血病","腳氣病","惡性貧血"],"answer":[1],"explain":"維他命 C（抗壞血酸）參與膠原蛋白形成，嚴重缺乏引起壞血病，表現為多發性出血、傷口癒合緩慢與貧血。腳氣病是 B1 缺乏；糙皮病是 B3 缺乏；惡性貧血是 B12 缺乏。","source":"第八章 8.1 表 8.2 水溶性維他命","chId":"ch08"},{"id":"q0804","ch":8,"level":1,"type":"single","style":"concept","q":"下列哪一種是脂溶性維他命？","options":["維他命 B1","維他命 B12","維他命 A","維他命 C"],"answer":[2],"explain":"維他命 A 屬脂溶性，與 D、E、K 一同需要膽汁協助吸收，礦物油會阻礙吸收。B1、B12 與 C 都屬水溶性，不會與脂溶性維他命同組；把它們混在一起記，最容易在分類題失分。","source":"第八章 8.1 表 8.1 與表 8.2","chId":"ch08"},{"id":"q0805","ch":8,"level":2,"type":"single","style":"concept","q":"缺乏哪一種維他命會導致巨胚紅血球性貧血及脊髓神經纖維退化？","options":["維他命 B1","葉酸","維他命 C","維他命 B12"],"answer":[3],"explain":"維他命 B12（鈷胺素）參與 DNA 合成，缺乏造成巨胚紅血球性貧血，並可致脊髓神經纖維退化；惡性貧血正是 B12 缺乏最常見的形式。葉酸也參與 DNA 合成，但課文列出的脊髓退化對應 B12；B1 與 C 的缺乏症完全不同。","source":"第八章 8.1 表 8.2 水溶性維他命","chId":"ch08"},{"id":"q0806","ch":8,"level":2,"type":"single","style":"concept","q":"脂溶性維他命的吸收需要下列哪一種物質協助？","options":["膽汁","內在因子","胰島素","胃酸"],"answer":[0],"explain":"脂溶性維他命隨脂肪一起吸收，需要膽汁乳化；礦物油會阻礙它們的吸收。胃酸與胰島素都不是脂溶性維他命吸收的條件；內在因子是吸收維他命 B12 所需，而 B12 屬水溶性。","source":"第八章 8.1 表 8.1 脂溶性維他命","chId":"ch08"},{"id":"q0807","ch":8,"level":2,"type":"multi","style":"concept","q":"關於蛋白質—能量營養失調（PEM），下列哪些正確？（選 2–3 項）","options":["是蛋白質、碳水化合物與脂肪攝取不足的結果","創傷、發燒或疾病增加需求時可出現","嬰兒和小孩尤其易受影響","只涉及單一種維他命缺乏","只會發生在成年人身上"],"answer":[0,1,2],"explain":"PEM 是蛋白質、碳水化合物與脂肪攝取不足，長期飢餓或創傷、發燒、疾病令需求增加時出現，嬰幼兒因生長發育需求大而尤其易受影響。它不是單一維他命缺乏，也不是只發生在成人；缺乏維他命可與 PEM 同時出現，是合併而非替代。","source":"第八章 8.1 A 營養失調","chId":"ch08"},{"id":"q0808","ch":8,"level":2,"type":"multi","style":"concept","q":"課文指出肥胖使病人傾向下列哪些併發症？","options":["惡性貧血","骨關節炎","膽石","肺氣腫","II 型糖尿病"],"answer":[1,2,4],"explain":"肥胖傾向膽石、缺血性心臟病與高血壓、II 型糖尿病、骨關節炎，以及疝氣和靜脈曲張。惡性貧血是維他命 B12 吸收問題；肺氣腫屬呼吸系統疾病，課文沒有把它列為肥胖的併發症。","source":"第八章 8.1 C 肥胖症","chId":"ch08"},{"id":"q0809","ch":8,"level":3,"type":"single","style":"case","q":"個案：男子身高 1.6 m、體重 80 kg。按表 8.4 的標準，他的 BMI 分類是？","options":["嚴重肥胖","肥胖","過重","正常"],"answer":[1],"explain":"BMI＝80÷1.6²＝80÷2.56≈31.25。表 8.4 以 ≥30 為肥胖，30–39.9 屬肥胖 class I，故屬肥胖而非過重；過重是 25–29.9。若只記住正文「超過 31」也同樣落入肥胖，但計算與分類仍應以表 8.4 為準。","source":"第八章 8.1 C 肥胖症（表 8.4）","chId":"ch08"},{"id":"q0810","ch":8,"level":3,"type":"single","style":"case","q":"個案：幼童腹部脹大、下肢水腫、肝臟受損，皮膚與毛髮色素減退。最可能是下列哪一種營養問題？","options":["壞血病","佝僂病","瓜西奧科兒症（kwashiorkor）","消瘦（marasmus）"],"answer":[2],"explain":"瓜西奧科兒症以蛋白質缺乏為主：血漿蛋白下降導致腹水與下肢水腫，水腫掩飾了消瘦，肝臟嚴重受損，皮膚毛髮色素減退。消瘦是蛋白質與碳水化合物同時缺乏，以嚴重消瘦、皮膚皺縮、頭髮脫落為主，沒有典型水腫。","source":"第八章 8.1 A 營養失調（蛋白質能量營養失調）","chId":"ch08"},{"id":"q0811","ch":8,"level":3,"type":"single","style":"case","q":"個案：長者跌倒骨折後癒合緩慢，飲食中礦物質吸收欠佳。課文所述哪一種組織鹽與骨骼、牙齒的主要礦物成分相應？","options":["硫酸鈣（Calc sulph）","磷酸鎂（Mag phos）","氟化鈣（Calc fluor）","磷酸鈣（Calc phos）"],"answer":[3],"explain":"磷酸鈣（Calc phos）是骨骼、指甲與牙齒的主要礦物成分，缺乏時骨折修復不良、礦物質吸收差。氟化鈣主彈性，對應靜脈曲張、脆甲；磷酸鎂是抗痙攣與神經鬆弛劑；硫酸鈣則與肝臟及皮膚問題相關。","source":"第八章 8.2 健康的肌肉—骨骼系統","chId":"ch08"},{"id":"q0812","ch":8,"level":3,"type":"multi","style":"concept","q":"關於骨骼基質的建構，下列哪些正確？（選 2–3 項）","options":["鎂是建構骨骼基質所需的礦物質之一","維他命 K 參與骨骼基質的建構","單獨大量服用鈣片足以預防骨質疏鬆","維他命 B12 是骨骼的主要結構成分","維他命 D 促進鈣與磷酸鹽的吸收"],"answer":[0,1,4],"explain":"鎂、維他命 D、維他命 K 都參與建構骨骼基質，維他命 D 還促進鈣與磷酸鹽吸收。課文明言單獨大量補鈣不能預防骨質疏鬆，反而可能令身體負荷無法溶解的鈣鹽；維他命 B12 參與 DNA 合成，不是骨骼的主要結構成分。","source":"第八章 8.2 健康的肌肉—骨骼系統","chId":"ch08"}]},{"id":"ch09","num":9,"title":"呼吸系統","en":"Respiratory System","group":"循環呼吸","tagline":"氣道、肺泡換氣與呼吸機制","intro":"呼吸章的主線是「換氣→擴散→運送」：空氣經鼻、咽、喉、氣管到肺泡，被暖化、濕化與過濾；吸氣靠橫膈膜與肋間肌主動增加胸腔容積，呼氣靠肺的彈性回縮被動完成；氣體沿分壓差擴散，再由血液運送。考試重點是壓力變化、右支氣管特徵與肺泡換氣計算。","memoryHook":"吸氣主動降壓，呼氣被動回彈；右支氣管短闊直，異物最愛右肺。","sections":[{"title":"呼吸系統的組成：上與下呼吸道","points":["呼吸系統分上呼吸道（鼻、咽、喉）與下呼吸道（氣管、兩條支氣管、兩個肺臟）。","胸腔中央的縱隔（mediastinum）容納心臟、大血管、氣管、食道、淋巴結與神經。","氣道把吸入空氣暖化或冷卻至接近體溫、加濕，並以黏液黏住微粒，達到過濾淨化。","血液與肺臟之間的氣體交換稱體外呼吸，血液與細胞之間稱體內呼吸。","呼吸肌包括肋間肌與橫膈膜；胸廓由十二對肋骨保護，第一對肋骨固定位置。"],"table":{"headers":["部位","包括"],"rows":[["上呼吸道（URT）","鼻、咽、喉"],["下呼吸道（LRT）","氣管、左右主支氣管、肺臟"],["呼吸肌","肋間肌、橫膈膜"]]}},{"title":"鼻、咽、喉：暖化、過濾與保護","points":["鼻甲（conchae）增加表面面積並造成亂流，使暖化、濕化與過濾更有效；鼻黏膜血管豐富，故鼻出血量多。","鼻咽只有空氣通過，後壁有咽扁桃腺（腺樣增殖體）；口咽與喉咽是空氣與食物共用通道。","吞嚥時軟顎提高分隔鼻咽與口咽；會厭（epiglottis）覆蓋氣管，防止食物掉入呼吸道。","喉頭由甲狀軟骨、環狀軟骨、杓狀軟骨與會厭構成；聲帶外展時張開發低音，內收拉緊發高音。","鼻腔的嗅覺末梢位於鼻頂（篩狀板與上鼻甲），衝動由嗅神經送到腦部。"],"table":{"headers":["器官","主要功能"],"rows":[["鼻","暖化、濕化、過濾；嗅覺"],["咽","空氣與食物通道；共鳴；扁桃腺防禦"],["喉","發聲、保護下呼吸道、空氣通道"],["氣管","以 C 形軟骨維持開放；纖毛梯清除微粒"]]}},{"title":"氣管、支氣管與肺泡","points":["氣管長約 10–11 cm，由 16–20 個 C 形透明軟骨環支撐，後壁柔軟以便食道擴張。","隆突（carina）位於氣管分叉點，是最後一道防線，受刺激時引發咳嗽。","右支氣管較闊、較短、較垂直，異物易墮入右肺；右肺三葉，左肺兩葉（心臟佔位）。","小支氣管沒有軟骨，平滑肌較厚；副交感神經令其收縮，交感神經令其擴張。","肺泡約一億五千萬個，壁只有一層鱗狀上皮，與毛細血管壁合成呼吸膜。","間隔細胞分泌肺表面活性劑，降低表面張力，防止呼氣時肺泡塌陷；約胎兒 35 週開始分泌。"],"table":{"headers":["項目","右支氣管","左支氣管"],"rows":[["長度","約 2.5 cm","約 5 cm"],["形態","較闊、較短、較垂直","較窄、較長"],["肺內分支","三個分支，進入三葉","兩個分支，進入兩葉"],["異物吸入","較易墮入右肺","較少"]]}},{"title":"呼吸機制：吸氣與呼氣","points":["吸氣的主動部分：肋間肌收縮把肋骨向上向外拉，橫膈膜收縮向下變平，胸腔容積增加。","胸腔容積增加使胸腔內壓低於大氣壓，壁層肋膜拉動肺，肺泡內壓下降，空氣被吸入。","呼氣是被動的：肌肉放鬆、肋骨下移內收、肺彈性回縮，肺泡內壓高於大氣，空氣排出。","平靜吸氣約 2 秒、呼氣約 3 秒，之後有短暫間歇；平均呼吸速率每分鐘 12–15 次。","胸腔負壓有助靜脈回流，稱為呼吸泵（respiratory pump）。","彈性、可塑性與氣道阻力都會影響呼吸：可塑性低或氣道收窄時，需要更用力才能使肺充氣。"],"table":{"headers":["階段","肌肉","胸腔容積","壓力","主動／被動"],"rows":[["吸氣","肋間肌＋橫膈膜收縮","增加","胸腔壓低於大氣","主動"],["呼氣","肌肉放鬆","減少","肺泡內壓高於大氣","被動"]]}},{"title":"肺容量、氣體交換與呼吸調節","points":["解剖性無效腔約 150 ml；潮氣量約 500 ml；肺活量＝潮氣量＋吸氣儲備量＋呼氣儲備量。","肺泡換氣＝（潮氣量－無效腔）×呼吸速率＝（500－150）×15＝5.25 L/min。","氣體沿分壓差擴散：肺泡 PO₂ 13.3 kPa、PCO₂ 5.3 kPa；缺氧血 PO₂ 5.3、PCO₂ 5.8 kPa。","氧氣 98.5% 與血紅蛋白結合、1.5% 溶於血漿；二氧化碳 70% 以重碳酸鹽、23% 氨基甲醯血紅蛋白、7% 溶解運送。","呼吸中樞位於腦幹；咳嗽反射由迷走神經把衝動傳到腦幹呼吸中樞，再引發深吸氣、聲門關閉與爆發呼氣。","血液二氧化碳濃度改變可改變呼吸；打嗝是橫膈膜不隨意痙攣，增加二氧化碳可抑制。"],"table":{"headers":["容量","定義"],"rows":[["潮氣量（TV）","每次呼吸進出肺部，休息時約 500 ml"],["解剖性無效腔","不參與交換的氣道容積，約 150 ml"],["肺活量（VC）","TV＋IRV＋ERV"],["餘氣量（RV）","強迫呼氣後仍留在肺內，不能直接測量"],["肺泡換氣","（TV－150）×呼吸速率"]]}}],"terms":[{"zh":"換氣","en":"Ventilation","def":"確保空氣進出肺臟的生理過程，靠肋間肌與橫膈膜完成。"},{"zh":"體外呼吸","en":"External respiration","def":"肺泡與肺泡毛細血管血液之間，穿過呼吸膜的氣體交換。"},{"zh":"體內呼吸","en":"Internal respiration","def":"毛細血管血液與身體細胞之間，透過擴散進行的氣體交換。"},{"zh":"會厭","en":"Epiglottis","def":"附於甲狀軟骨的葉狀彈性纖維軟骨，吞嚥時覆蓋氣管防止嗆入。"},{"zh":"隆突","en":"Carina","def":"氣管分叉為左右支氣管處的高度敏感區，受刺激引發咳嗽。"},{"zh":"呼吸膜","en":"Respiratory membrane","def":"肺泡壁與毛細血管壁緊密貼合而成，氣體擴散在此發生。"},{"zh":"肺表面活性劑","en":"Surfactant","def":"間隔細胞分泌的磷脂液體，降低表面張力，防止肺泡塌陷。"},{"zh":"潮氣量","en":"Tidal volume (TV)","def":"每次呼吸週期進出肺部的空氣量，休息時約 500 ml。"},{"zh":"解剖性無效腔","en":"Anatomical dead space","def":"不會發生氣體交換的傳送氣道容積，約 150 ml。"},{"zh":"肺活量","en":"Vital capacity (VC)","def":"能移進和移出肺臟的最大空氣量，等於 TV＋IRV＋ERV。"}],"examTips":["右支氣管短、闊、垂直，是異物最常墮入的一側；左肺只有兩葉，別與右肺三葉混淆。","吸氣的主動力量來自橫膈膜下降與肋間肌上提肋骨；平靜呼氣則是被動的彈性回縮。","肺泡換氣要先減去 150 ml 無效腔再乘呼吸速率，直接把 500×15 會高估。","肺表面活性劑約 35 週才足量，早產嬰兒因此易有呼吸問題；它降低表面張力、防止肺泡塌陷。","呼吸中樞在腦幹；課文沒有把延髓、腦橋分開考，別自行加戲。"],"remedies":[{"name":"瀉根（Bryonia）","note":"課文用於肋膜炎：主要症狀是任何移動都會使情況惡化，與肋膜發炎時呼吸、活動加劇疼痛相應。"},{"name":"磷酸鎂組合（Mag phos，組合 I）","note":"課文提到以含磷酸鎂的組織鹽組合溶於熱水啜飲，用於橫膈膜不隨意痙攣引起的打嗝。"}],"atlas":[8],"questions":[{"id":"q0901","ch":9,"level":1,"type":"single","style":"concept","q":"氣體交換主要在哪裡進行？","options":["肺泡","支氣管","喉頭","氣管"],"answer":[0],"explain":"肺泡是支氣管反覆分支後形成的單層空氣囊，壁只有一層鱗狀上皮，外圍包著毛細血管，兩者合成呼吸膜，氣體在此擴散。氣管、支氣管與喉頭屬傳送空氣的通道，壁太厚，不能進行氣體交換。","source":"第九章 9.2 呼吸系統的構成部份","chId":"ch09"},{"id":"q0902","ch":9,"level":1,"type":"single","style":"concept","q":"下列哪一個器官屬於上呼吸道？","options":["肺臟","喉頭","主支氣管","氣管"],"answer":[1],"explain":"上呼吸道由鼻、咽部與喉頭構成；下呼吸道由氣管、兩條主支氣管與兩個肺臟組成。氣管與支氣管雖是通道，但屬下呼吸道；肺臟亦屬下呼吸道。判斷的關鍵是「喉頭以上」與「氣管以下」的分界。","source":"第九章 9.2 呼吸系統的構成部份","chId":"ch09"},{"id":"q0903","ch":9,"level":1,"type":"single","style":"concept","q":"吞嚥時覆蓋氣管、防止食物掉入呼吸道的結構是？","options":["隆突","聲帶","會厭","軟顎"],"answer":[2],"explain":"會厭是附著於甲狀軟骨的葉狀彈性纖維軟骨；吞嚥時喉頭上升、會厭覆蓋氣管，確保食物進入食道。聲帶負責發聲，軟顎負責分隔鼻咽與口咽，隆突是氣管分叉處的咳嗽觸發點，都不負責封閉氣管。","source":"第九章 9.2 呼吸系統的構成部份／9.2.3 喉頭","chId":"ch09"},{"id":"q0904","ch":9,"level":1,"type":"single","style":"concept","q":"右肺被分為幾個肺葉？","options":["四個","一個","兩個","三個"],"answer":[3],"explain":"右肺分上、中、下三葉；左肺因心臟佔去左側空間，只有上、下兩葉。右支氣管也因較短、較闊、較垂直，成為異物較易墮入的一側。把左右肺葉數目對調，是最常見的失分位；記住「左二右三」。","source":"第九章 9.2.5 肺臟","chId":"ch09"},{"id":"q0905","ch":9,"level":2,"type":"single","style":"concept","q":"吸氣時，胸腔與肺泡內的壓力如何變化？","options":["胸腔壓降至低於大氣壓，肺泡內壓下降，空氣入肺","胸腔壓不變，靠肺主動擴張吸入空氣","肺泡內壓上升，空氣被吸入","胸腔壓上升至高於大氣壓，空氣被推入肺"],"answer":[0],"explain":"吸氣時肋間肌與橫膈膜收縮使胸腔容積增加，胸腔內壓降至低於大氣壓，壁層肋膜拉動肺，肺泡內壓下降，空氣於是被拉入肺。壓力上升才把空氣推入的說法與事實相反；肺本身沒有主動擴張的能力，靠的是胸腔與肋膜的機械連結。","source":"第九章 9.3.1 呼吸週期 A 吸氣","chId":"ch09"},{"id":"q0906","ch":9,"level":2,"type":"single","style":"concept","q":"平靜呼氣為何被形容為被動過程？","options":["橫膈膜強力收縮把空氣推出","肋間肌與橫膈膜放鬆，肺靠彈性回縮","腹肌強力收縮把空氣壓出","聲門關閉後空氣被擠出"],"answer":[1],"explain":"平靜呼氣是被動的：肋間肌與橫膈膜放鬆，肋骨下移內收，肺靠自身彈性回縮，肺泡內壓高於大氣，空氣排出。腹肌收縮屬用力呼氣；橫膈膜在呼氣時是放鬆而非強力收縮；聲門關閉是咳嗽反射的一部分，不是平靜呼氣的機制。","source":"第九章 9.3.1 呼吸週期 B 呼氣","chId":"ch09"},{"id":"q0907","ch":9,"level":2,"type":"multi","style":"concept","q":"關於平靜吸氣，下列哪些正確？（選 2–3 項）","options":["聲門緊閉以增加胸腔負壓","橫膈膜收縮向下變平","外肋間肌收縮把肋骨向上向外拉","腹肌強力收縮協助吸氣","胸腔容積增加，空氣被拉入肺"],"answer":[1,2,4],"explain":"吸氣的主動力量來自橫膈膜收縮向下變平，以及外肋間肌收縮把肋骨向上向外拉，兩者令胸腔容積增加、壓力下降。腹肌收縮與聲門關閉屬用力呼氣與咳嗽的動作，不會在平靜吸氣時出現。","source":"第九章 9.3 呼吸機制","chId":"ch09"},{"id":"q0908","ch":9,"level":2,"type":"multi","style":"concept","q":"右支氣管具有下列哪些特徵？","options":["較短","較窄","較垂直","較闊","較長"],"answer":[0,2,3],"explain":"右支氣管較闊、較短、較垂直，因此異物較易墮入右肺；它約長 2.5 cm，入肺後分三個分支進入三葉。左支氣管較窄、較長（約 5 cm），並非右支氣管的特徵；兩者大小不同是為了在縱隔容納心臟。","source":"第九章 9.2.6 支氣管和小支氣管","chId":"ch09"},{"id":"q0909","ch":9,"level":3,"type":"single","style":"case","q":"個案：早產嬰兒出生後呼吸困難，肺泡不穩定地打開甚至塌陷。最可能缺乏什麼？","options":["氣管軟骨環","肋膜漿液","肺表面活性劑","會厭軟骨"],"answer":[2],"explain":"肺表面活性劑由間隔細胞分泌，降低表面張力，防止呼氣時肺泡塌陷；約胎兒 35 週才足量，早產嬰兒分泌不足，肺泡不穩定地打開，造成嚴重呼吸問題。會厭、肋膜與軟骨的問題不會以「肺泡塌陷」為主要表現。","source":"第九章 9.2.7 呼吸性小支氣管和肺泡","chId":"ch09"},{"id":"q0910","ch":9,"level":3,"type":"single","style":"case","q":"個案：一側胸腔被刺穿，空氣進入肋膜腔。該側肺最可能出現什麼變化？","options":["氣管立即完全閉合","表面活性劑消失而肺泡擴大","因壓力上升而過度膨脹","因彈性回縮而塌陷"],"answer":[3],"explain":"肋膜腔是潛在空間，兩層肋膜靠漿液與表面張力貼合；一旦被刺穿，空氣進入，貼合失效，肺因其彈性回縮而塌陷。肺不會過度膨脹；氣管不會立即閉合；表面活性劑仍在肺泡內，只是肺泡失去維持擴張的機械條件。","source":"第九章 9.2.5 B 肋膜和肋膜腔","chId":"ch09"},{"id":"q0911","ch":9,"level":3,"type":"single","style":"concept","q":"潮氣量 500 ml、解剖性無效腔 150 ml、呼吸速率 15 次／分，肺泡換氣是多少？","options":["5.25 L／分鐘","4.5 L／分鐘","7.5 L／分鐘","6.75 L／分鐘"],"answer":[0],"explain":"肺泡換氣＝（潮氣量－解剖性無效腔）×呼吸速率＝（500－150）×15＝350×15＝5250 ml，即 5.25 L/min。直接 500×15＝7.5 L/min 是沒有扣除無效腔的常見錯誤；其餘數值不對應任何正確組合。","source":"第九章 9.3.3 肺部各種容量及容積","chId":"ch09"},{"id":"q0912","ch":9,"level":3,"type":"multi","style":"concept","q":"關於呼吸的調節與防禦反射，下列哪些正確？（選 2–3 項）","options":["呼吸中樞位於小腦","血氧下降是調節呼吸的唯一因素","咳嗽衝動經迷走神經傳到腦幹呼吸中樞","血液二氧化碳濃度改變可改變呼吸","呼吸中樞位於腦幹"],"answer":[2,3,4],"explain":"呼吸中樞位於腦幹，咳嗽反射的衝動經迷走神經傳到腦幹呼吸中樞，再引發深吸氣、聲門關閉與爆發呼氣；血液二氧化碳濃度改變也可改變呼吸。呼吸中樞不在小腦；調節呼吸的因素不只血氧，二氧化碳與多種反射同樣重要。","source":"第九章 9.2.4 氣管（咳嗽反射）；9.3.4 氣體交換","chId":"ch09"}]},{"id":"ch10","num":10,"title":"心血管系統","en":"Cardiovascular System","group":"循環呼吸","tagline":"心臟四腔、瓣膜、傳導與兩套循環","intro":"心血管章的主線是「兩個泵、兩套循環」：右心送血到肺、左心送血到全身，瓣膜確保單向流動；冠狀動脈是主動脈第一個分支，供應心肌本身；竇房結起搏、房室結延遲 0.1 秒、蒲金氏纖維傳到心室尖；心搏週期分心房收縮、心室收縮與完全舒張。","memoryHook":"右心去肺、左心去全身；SA 起搏、AV 延遲、蒲金氏纖維傳到心室尖。","sections":[{"title":"位置與三層結構","points":["心臟位於胸腔縱隔，夾在兩肺之間，上靠大血管、下由橫膈膜支撐；因佔位使左肺只有兩葉。","心包（pericardium）是雙層漿液膜，外層纖維性，限制心臟過度擴張，只容許小量尺寸變化。","心肌（myocardium）是心臟主體，特化具自律性，細胞融合成片同步收縮。","心內膜（endocardium）光滑不黏，與大血管內皮連續，減少血流阻力。","心臟實際是兩個並排的泵，由中隔分開，防止含氧血與缺氧血混合。"],"table":{"headers":["層","特點","功能"],"rows":[["心包","雙層漿液膜、外層纖維","固定、限制過度擴張"],["心肌","特化、自律、細胞成片","產生收縮力"],["心內膜","光滑內襯","減少血流阻力"]]}},{"title":"四腔與瓣膜：確保單向血流","points":["心臟以垂直隔膜與水平分隔分為四腔：上為心房（血液流入），下為心室（血液泵出）。","右心房與右心室之間是三尖瓣，左心房與左心室之間是二尖瓣，都是單向房室瓣，防止倒流。","肺動脈與主動脈出口有半月瓣，防止血液倒流並維持血壓。","肺靜脈把帶氧血送入左心房；肺動脈把缺氧血由右心室送到肺；腔靜脈把全身血液送回右心房。","左心室壁遠比右心室厚，因需把血液泵至全身；右心只需泵到接近的肺。","胎兒左右心房之間的卵圓孔（foramen ovale）讓血液繞過肺；出生時閉合，未閉可致發紺或心雜音。"],"table":{"headers":["腔室","流入","流出","相關瓣膜"],"rows":[["右心房","上、下腔靜脈","右心室","三尖瓣"],["右心室","右心房","肺動脈","三尖瓣、肺動脈半月瓣"],["左心房","肺靜脈","左心室","二尖瓣"],["左心室","左心房","主動脈","二尖瓣、主動脈半月瓣"]]}},{"title":"肺循環、體循環與冠狀循環","points":["肺循環：右心室→肺動脈→肺→肺靜脈→左心房，目的在使血紅蛋白重新充氧。","體循環：左心室→主動脈→全身器官（肺除外）→腔靜脈→右心房。","動脈承受高壓、壁較厚有肌肉層；靜脈低壓、壁薄，腿部靜脈有瓣膜，靠小腿肌肉泵推送血液。","冠狀動脈是主動脈第一個分支，共四條，走在心臟表面，供應心肌本身。","冠狀動脈搭橋通常取腿部靜脈反向使用，正因靜脈內有瓣膜。","長時間站立或不活動時，靜脈泵失效，可致靜脈曲張，深層靜脈亦可能形成血栓。"],"table":{"headers":["循環","路徑","血液氣體變化"],"rows":[["肺循環","右心室→肺動脈→肺→肺靜脈→左心房","缺氧血變帶氧血"],["體循環","左心室→主動脈→全身→腔靜脈→右心房","帶氧血變缺氧血"],["冠狀循環","主動脈→冠狀動脈→心肌→心靜脈","供應心肌本身"]]}},{"title":"傳導系統：自律性與起搏","points":["心肌具自律性（autorhythmicity），不需外來刺激也能自發收縮，但仍受自主神經與荷爾蒙調節。","竇房結（SA node）位於右心房壁近上腔靜脈開口，是主起搏器，比其餘細胞更快啟動衝動，引起心房收縮。","房室結（AV node）延遲約 0.1 秒，讓心房先完成收縮；竇房結失效時可作次要起搏器，但固有速率較慢。","房室束（希斯氏束）越過纖維環，分左右支束，再成蒲金氏纖維，把衝動送到心室尖，使心室由下往上收縮。","迷走神經（副交感）供應竇房結、房室結與心房肌，降低速率與力量；交感神經供應全心肌，增加速率與力量。","影響心跳速率的因素包括性別、年齡、自主神經活性、腎上腺素與甲狀腺素、運動、溫度、壓力感受器反射與情緒。"],"table":{"headers":["構造","位置","功能"],"rows":[["竇房結","右心房壁近上腔靜脈開口","主起搏器，引發心房收縮"],["房室結","心房間隔近房室瓣","延遲 0.1 秒；次要起搏器"],["房室束","跨纖維環、心室間隔","把衝動傳向心室"],["蒲金氏纖維","心室心肌","傳至心室尖，引發心室收縮"]]}},{"title":"心搏週期與心電圖","points":["心搏週期分三階段：心房收縮、心室收縮、心房與心室完全舒張。","脈搏 74 次／分時，每個週期約 0.8 秒；脈搏代表左心室收縮把血液推入血管。","血壓 120/80：上值為心室收縮壓，下值為舒張壓。","ECG 的 P 波代表竇房結衝動傳遍心房；QRS 代表衝動經房室結、房室束、蒲金氏纖維引起心室去極化；T 波代表心室放鬆。","由竇房結發出的心律稱竇性心律，速率 60–100 次／分；過快為心跳過速，過慢為心跳過緩。","分析波形、週期之間的時間間距，可獲得心肌狀態與傳導系統的資訊。"],"table":{"headers":["波形","代表"],"rows":[["P 波","竇房結衝動傳遍心房"],["QRS 複合波","衝動經房室結、房室束、蒲金氏纖維至心室"],["T 波","心室放鬆（復極化）"]]}}],"terms":[{"zh":"縱隔","en":"Mediastinum","def":"胸腔中央空間，容納心臟、大血管、氣管、食道與淋巴結。"},{"zh":"心包","en":"Pericardium","def":"雙層漿液膜，外層纖維性，固定心臟並限制其過度擴張。"},{"zh":"三尖瓣","en":"Tricuspid valve","def":"右心房與右心室之間的單向房室瓣，防止血液倒流。"},{"zh":"二尖瓣","en":"Bicuspid (mitral) valve","def":"左心房與左心室之間的單向房室瓣，防止血液倒流。"},{"zh":"半月瓣","en":"Semilunar valve","def":"位於肺動脈與主動脈出口，防止倒流並維持血壓。"},{"zh":"竇房結","en":"Sinoatrial node (SA node)","def":"位於右心房壁的主起搏器，最快啟動衝動並引起心房收縮。"},{"zh":"房室結","en":"Atrioventricular node (AV node)","def":"延遲衝動約 0.1 秒，讓心房先收縮；亦是次要起搏器。"},{"zh":"蒲金氏纖維","en":"Purkinje fibres","def":"心室心肌內的細小傳導纖維，把衝動送到心室尖引發收縮。"},{"zh":"卵圓孔","en":"Foramen ovale","def":"胎兒左右心房之間的開口，讓血液繞過肺；出生後通常閉合。"},{"zh":"心搏週期","en":"Cardiac cycle","def":"心房收縮、心室收縮與完全舒張三個階段的循環。"},{"zh":"冠狀動脈","en":"Coronary artery","def":"主動脈第一個分支，共四條，供應心肌本身的血液。"}],"examTips":["右心是肺循環的泵、左心是體循環的泵；肺動脈例外地運送缺氧血，肺靜脈運送帶氧血。","三尖瓣在右、二尖瓣在左；半月瓣只在肺動脈與主動脈出口，別把房室瓣與半月瓣混淆。","房室結的 0.1 秒延遲是為了讓心房先收縮完，不是為了減慢心跳。","ECG 的 QRS 對應心室去極化，T 波才是心室放鬆；P 波代表衝動傳遍心房。","左心室壁最厚是因為要泵血至全身；右心室只泵到肺，所以壁薄得多。"],"remedies":[{"name":"瀉根（Bryonia）","note":"補充筆記列它對漿膜（包括心包膜）有親和力，並見心悸、心絞痛因費力而加劇，與本章心包及心搏負荷主題相應。"}],"atlas":[9],"questions":[{"id":"q1001","ch":10,"level":1,"type":"single","style":"concept","q":"心臟的主起搏器（pacemaker）是？","options":["蒲金氏纖維","竇房結","房室束","房室結"],"answer":[1],"explain":"竇房結位於右心房壁近上腔靜脈開口，是主起搏器，因為它比其餘特化細胞更快啟動衝動，引起心房收縮。房室結是次要起搏器並負責延遲；房室束與蒲金氏纖維只負責傳導，不會自行決定心跳節律。","source":"第十章 10.1.1 A 竇房結","chId":"ch10"},{"id":"q1002","ch":10,"level":1,"type":"single","style":"concept","q":"右心房與右心室之間的瓣膜是？","options":["肺動脈半月瓣","主動脈半月瓣","三尖瓣","二尖瓣"],"answer":[2],"explain":"右心房與右心室之間是三尖瓣，左心房與左心室之間是二尖瓣，兩者都是單向房室瓣，防止血液倒流。半月瓣位於肺動脈與主動脈出口，不是房室之間的瓣膜；主動脈半月瓣在左心室出口，位置與三尖瓣不同。","source":"第十章 10.1 心臟內部的基礎結構","chId":"ch10"},{"id":"q1003","ch":10,"level":1,"type":"single","style":"concept","q":"心臟哪一個腔室的肌肉壁最厚？","options":["左心房","右心房","右心室","左心室"],"answer":[3],"explain":"左心室要把血液經主動脈泵至全身，阻力最大，所以心肌壁最厚；右心室只把血液泵到鄰近的肺，壁薄得多。心房主要接收血液，壁更薄，並非以厚度見稱。腔壁厚度反映的是「泵血距離與阻力」，不是腔室大小。","source":"第十章 10.1 心臟內部的基礎結構","chId":"ch10"},{"id":"q1004","ch":10,"level":1,"type":"single","style":"concept","q":"心搏週期三個階段的先後次序是？","options":["心房收縮→心室收縮→心房與心室完全舒張","心室收縮→心房收縮→完全舒張","心房舒張→心室舒張→心房收縮","心房與心室同時收縮→舒張"],"answer":[0],"explain":"心搏週期依序為心房收縮、心室收縮、心房與心室完全舒張；房室結延遲 0.1 秒正是為了讓心房先收縮完成。其餘次序都把心室收縮放在心房收縮之前，或把舒張放在收縮之前，與課文不符。","source":"第十章 10.3 心搏週期","chId":"ch10"},{"id":"q1005","ch":10,"level":2,"type":"single","style":"concept","q":"房室結把衝動延遲約 0.1 秒，主要目的為何？","options":["降低整體心跳速率","讓心房在心室收縮前完成收縮","讓蒲金氏纖維先放電","防止血液由心室倒流至心房"],"answer":[1],"explain":"房室結的 0.1 秒延遲是為了讓心房在心室開始收縮前完成收縮，使血液充分流入心室。延遲不是為了減慢整體心跳（心跳速率主要由竇房結決定），也不是防止血液倒流（那是瓣膜的功能）。","source":"第十章 10.1.1 B 房室結","chId":"ch10"},{"id":"q1006","ch":10,"level":2,"type":"single","style":"concept","q":"肺循環的路徑是？","options":["左心室→主動脈→肺→腔靜脈→右心房","左心房→肺動脈→肺→肺靜脈→左心室","右心室→肺動脈→肺→肺靜脈→左心房","右心房→肺動脈→肺→肺靜脈→右心室"],"answer":[2],"explain":"肺循環由右心室把缺氧血送入肺動脈，經肺毛細血管換氣後，由肺靜脈把帶氧血送回左心房。體循環則由左心室經主動脈到全身，再經腔靜脈回右心房；把兩者的起點或終點對調，是最常見的錯誤。","source":"第十章 10.2 循環系統","chId":"ch10"},{"id":"q1007","ch":10,"level":2,"type":"multi","style":"concept","q":"關於冠狀動脈，下列哪些正確？（選 2–3 項）","options":["只有兩條，供應肺臟","共有四條，走在心臟表面","搭橋手術常取腿部靜脈反向使用","起源於肺動脈","是主動脈的第一個分支"],"answer":[1,2,4],"explain":"冠狀動脈是主動脈的第一個分支，走在心臟表面，共四條，供應心肌本身；搭橋手術常取腿部靜脈反向使用，正因為靜脈內有瓣膜。它不起源於肺動脈，也不只兩條，若只有兩條會令心肌得不到足夠血液。","source":"第十章 10.2 循環系統","chId":"ch10"},{"id":"q1008","ch":10,"level":2,"type":"multi","style":"concept","q":"關於心臟的自主神經供應，下列哪些正確？（選 2–3 項）","options":["副交感神經興奮降低脈衝速率與心跳力量","迷走神經供應竇房結、房室結及心房肌","交感神經興奮增加心跳速率與力量","副交感神經興奮會加快心跳","交感神經只供應心房肌，不供應心室"],"answer":[0,1,2],"explain":"迷走神經（副交感）供應竇房結、房室結與心房肌，興奮時降低脈衝速率與心跳力量；交感神經供應竇房結、房室結及心房與心室心肌，興奮時增加速率與力量。交感不是只供應心房，副交感也不會加快心跳。","source":"第十章 10.1.1 C 心臟的神經供應","chId":"ch10"},{"id":"q1009","ch":10,"level":3,"type":"single","style":"case","q":"按課文，新生嬰兒出生後持續發紺、聽診有心雜音，最可能與下列哪一項有關？","options":["冠狀動脈狹窄","心包積液","二尖瓣倒流","卵圓孔未閉合"],"answer":[3],"explain":"課文把新生兒發紺與心雜音連到卵圓孔未閉合或閉合不全：胎兒期卵圓孔讓血液繞過肺，出生時通常關閉；未閉合時課文說可致發紺，邊緣渦流則產生心雜音。二尖瓣倒流、心包積液與冠狀動脈狹窄都不是課文用來解釋這個組合的構造。","source":"第十章 10.1 卵圓孔與胎兒循環","chId":"ch10"},{"id":"q1010","ch":10,"level":3,"type":"single","style":"case","q":"個案：病人竇房結功能衰退，由房室結接手起搏，心跳反而比原來慢。原因為何？","options":["房室結的固有激活速率較慢","迷走神經被切斷","蒲金氏纖維完全沒有傳導能力","房室結的 0.1 秒延遲變長"],"answer":[0],"explain":"竇房結受損時房室結可接手，但其固有激活速率比竇房結慢，所以心跳反而較慢；0.1 秒延遲只是傳導特性，不是速率較慢的原因。蒲金氏纖維負責傳導；迷走神經被切斷會令心跳加快，兩者都不能解釋。","source":"第十章 10.1.1 B 房室結","chId":"ch10"},{"id":"q1011","ch":10,"level":3,"type":"multi","style":"concept","q":"關於心電圖波形，下列哪些正確？（選 2–3 項）","options":["T 波：心房收縮","QRS 複合波：衝動經房室結、房室束與蒲金氏纖維","P 波：竇房結衝動傳遍心房","T 波：心室放鬆","P 波：心室去極化"],"answer":[1,2,3],"explain":"P 波是竇房結衝動傳遍心房；QRS 複合波是衝動經房室結、房室束與蒲金氏纖維，引起心室去極化；T 波代表心室放鬆。把 P 波說成心室去極化、T 波說成心房收縮，是把三個波形的順序與意義對調。","source":"第十章 10.3.1 心臟內的電氣改變","chId":"ch10"},{"id":"q1012","ch":10,"level":3,"type":"multi","style":"case","q":"個案：長途飛行後小腿腫痛，被診斷為深層靜脈血栓。關於靜脈回流，下列哪些正確？","options":["長時間不活動可致血液積聚與血栓","靜脈沒有瓣膜，全靠心臟的吸力","小腿肌肉收縮可把血液向上推","靜脈血壓比動脈高，所以靜脈壁較厚","腿部靜脈有瓣膜，防止血液倒流"],"answer":[0,2,4],"explain":"腿部靜脈有瓣膜防止倒流，小腿肌肉收縮像泵一樣把血液向上推；長時間站立或不活動使這個泵失效，血液積聚，可致靜脈曲張，深層靜脈亦可能形成血栓。靜脈血壓遠低於動脈，所以靜脈壁較薄、肌肉層少，並非較厚。","source":"第十章 10.2 循環系統（靜脈回流）","chId":"ch10"}]},{"id":"ch11","num":11,"title":"血液","en":"Blood","group":"循環呼吸","tagline":"血漿蛋白、血細胞與止血凝血","intro":"血液既是結締組織，也是身體的運輸與防禦幹線。考試主線有三條：血漿蛋白怎樣決定滲透壓、三類血細胞各有什麼專職、止血由血管收縮到纖維蛋白溶解的四步次序。把「成分—功能—失衡後果」串成一條線，比死背數字有效。","memoryHook":"血漿五五、細胞四五；收縮、栓、凝、溶——止血四步。","sections":[{"title":"血液：一種結締組織","points":["血液屬結締組織：它能運輸物質、連接體內外環境，而且含有纖維（凝血時的纖維蛋白），符合結締組織的特徵。","血量約體重的 7%，70kg 男性約有 5.6L；女性比例較低，兒童較高，再逐步降至成人水平。","血漿約佔血容積 55%，各種細胞約佔 45%；血漿中水佔 90–92%，其餘是蛋白、無機鹽、營養素、廢物、荷爾蒙與氣體。","血液呈弱鹼性，pH 維持在 7.35–7.45，靠緩衝系統不斷修正。","驗血常是第一線檢查，因為血液分析可同時反映多個系統的狀況。"]},{"title":"血漿蛋白三兄弟","points":["血漿蛋白只佔血漿約 7%，但分子大、留在血管內，產生約 25 mmHg（3.3 kPa）的滲透壓，把水留在循環內。","蛋白下降（製造減少或由血管流失）會令滲透壓下降，液體走入組織與體腔，形成水腫。","白蛋白由肝製造、數量最多，主職維持滲透壓，兼任脂質與類固醇荷爾蒙的運輸分子。","球蛋白大多由肝、其餘由淋巴組織製造；抗體屬免疫球蛋白，由淋巴細胞產生，與抗原結合使其失效。","球蛋白亦運送甲狀腺素與鐵（運鐵蛋白），並可抑制某些蛋白水解酵素，例如 α2 巨球蛋白抑制胰蛋白酶。","纖維蛋白原由肝合成，是凝血必需物質；血清就是移除凝血因子後的血漿。"],"table":{"headers":["血漿蛋白","來源","主要功能"],"rows":[["白蛋白","肝臟","維持血漿滲透壓、運送脂質與類固醇荷爾蒙"],["球蛋白","肝臟、淋巴組織","抗體、運送甲狀腺素與鐵、抑制酵素"],["纖維蛋白原","肝臟","凝血原料，被凝血酵素轉為纖維蛋白"]]}},{"title":"紅血球：沒有核的運輸車","points":["紅血球是富彈性的雙凹圓盤，含血紅蛋白但沒有細胞器與細胞核，所以不能分裂，壽命約 120 天。","血紅蛋白含鐵、對氧有高親和力；與氧結合後成鮮紅的氧合血紅蛋白，所以動脈血較鮮紅。","紅骨髓製造：兒童靠長骨（如股骨），成人靠扁骨（胸骨、肋骨、頭骨）；維他命 B12 與葉酸是紅血球生成必需。","參考值：紅血球男 4.5–6.5×10⁶/mL、女 4.5–5.0×10⁶/mL；血紅蛋白男約 16、女約 14 g/dl，男低於 13、女低於 11.5 考慮貧血。","老化紅血球在脾、骨髓與肝分解，鐵會再循環，血紅素的含鐵部分成為膽鹽成分。","紅血球膜上的抗原決定 ABO 與 Rh 血型；身體不會對自身抗原產生抗體，否則會造成致命的輸血反應。"]},{"title":"白血球與血小板","points":["白血球約佔血容積 1%，體積較大、有細胞核，能繁殖；染色後分顆粒細胞（嗜酸粉紅、嗜鹼藍、嗜中紫）與非顆粒細胞（單核、淋巴）。","嗜中性白血球經趨化作用到感染區，以吞噬作用殺菌，顆粒即溶小體；膿液＝壞死組織＋死亡微生物＋耗盡的嗜中性白血球。","嗜酸性白血球負責清除寄生蟲（蟲體太大不能吞噬），並與過敏有關，可抑制嗜鹼性白血球釋出的組織胺。","嗜鹼性白血球顆粒含肝素（抗凝血）與組織胺（促發炎）；肝素是體內天然抗凝血劑之一。","單核白血球在血中吞噬，入組織後變成巨噬細胞並分泌 IL-1；固定的巨噬細胞包括庫氏細胞、小神經膠質細胞、蘭格罕氏細胞、肺泡巨噬細胞與蝕骨細胞。","淋巴細胞負責免疫：在骨髓活化的是 B 細胞，在胸腺成熟的 T 細胞；血小板則是無核的細胞碎片，含凝血物質。"],"table":{"headers":["白血球","類型與染色","主要功能"],"rows":[["嗜中性","顆粒細胞、紫色","趨化後吞噬微生物，死亡後構成膿液"],["嗜酸性","顆粒細胞、粉紅","對抗寄生蟲、調節過敏反應"],["嗜鹼性","顆粒細胞、藍色","釋出肝素與組織胺"],["單核","非顆粒細胞","入組織成巨噬細胞，分泌 IL-1"],["淋巴","非顆粒細胞","B 細胞與 T 細胞，負責特異性免疫"]]}},{"title":"止血四步與凝血","points":["第一步血管收縮：血小板黏附受損血管壁並釋出血清素，令血管收窄；受損血管本身亦釋出血栓素。","第二步血小板栓：黏性血小板互相黏附，並釋出 ADP 吸引更多血小板，形成正回饋，迅速封住傷口。","第三步凝血：凝血酵素原活化劑把凝血酵素原變成凝血酵素，後者把纖維蛋白原變成不可溶的纖維蛋白網，比血小板栓堅固得多。","外在途徑由受損組織釋出組織因子（凝血酶原酶）啟動，數秒內完成；內在途徑由內皮受損與血小板黏附啟動，需 3–6 分鐘；兩者通常同時進行。","凝血因子編號是發現順序，不是作用順序；第 8 因子缺乏見於血友病，所以他們出血風險特別高。","第四步纖維蛋白溶解：內皮釋放活化劑，把血纖維蛋白溶解酵素原變成血纖維蛋白溶解酵素，分解纖維蛋白，凝塊清除後血管壁才恢復完整。"],"table":{"headers":["止血步驟","主要事件","關鍵物質"],"rows":[["1 血管收縮","血小板黏附、血管收窄","血清素、血栓素"],["2 血小板栓","血小板互黏聚集","ADP（正回饋）"],["3 凝血","形成不可溶纖維蛋白網","凝血酵素、纖維蛋白原"],["4 纖維蛋白溶解","分解凝塊、展開修復","血纖維蛋白溶解酵素"]]}}],"terms":[{"zh":"血漿","en":"Plasma","def":"血液的液體部分，約佔血容積 55%，水佔 90–92%，其餘為蛋白、鹽類、營養素與廢物。"},{"zh":"血清","en":"Serum","def":"血漿移除凝血因子後剩下的清澈液體，與血漿不可混為一談。"},{"zh":"血紅蛋白","en":"Haemoglobin","def":"紅血球內含鐵的色素蛋白，對氧有高親和力，與氧結合後呈鮮紅色。"},{"zh":"氧合血紅蛋白","en":"Oxyhaemoglobin","def":"血紅蛋白與氧結合後的鮮紅色形態，是動脈血顏色的來源。"},{"zh":"紅血球生成","en":"Erythropoiesis","def":"紅骨髓製造紅血球的過程，需要維他命 B12 與葉酸參與。"},{"zh":"白蛋白","en":"Albumin","def":"由肝製造、數量最多的血漿蛋白，維持滲透壓並運送脂質與類固醇荷爾蒙。"},{"zh":"球蛋白","en":"Globulin","def":"血漿蛋白之一，包括抗體、運輸蛋白（如運鐵蛋白）與酵素抑制劑。"},{"zh":"纖維蛋白原","en":"Fibrinogen","def":"肝合成的凝血蛋白，被凝血酵素轉化為不溶的纖維蛋白。"},{"zh":"止血","en":"Haemostasis","def":"血管受損後停止出血的一連串反應：血管收縮、血小板栓、凝血與纖維蛋白溶解。"},{"zh":"血小板栓","en":"Platelet plug","def":"黏性血小板聚集形成的臨時封堵物，由 ADP 正回饋加速形成。"},{"zh":"凝血酵素","en":"Thrombin","def":"把纖維蛋白原轉化為纖維蛋白的酵素，由凝血酵素原轉變而來。"},{"zh":"纖維蛋白溶解","en":"Fibrinolysis","def":"以血纖維蛋白溶解酵素分解纖維蛋白凝塊的過程，屬止血第四步。"}],"examTips":["血清不等於血漿：血清是凝血因子被移除後的血漿，問「缺少什麼」時答案就是凝血因子。","止血次序必記：血管收縮→血小板栓→凝血→纖維蛋白溶解；把凝血排在血小板栓之前是最常見的錯。","凝血因子編號＝發現先後，不是作用次序；第 8 因子缺乏與血友病相關。","內在途徑慢（3–6 分鐘）、外在途徑快（數秒），兩者通常同時發生，勿倒轉。","血漿蛋白下降→滲透壓下降→水腫；不是血壓下降，也不是血量增加。","紅血球無核無細胞器，所以不能分裂、壽命約 120 天；成人造血靠扁骨而非長骨。"],"remedies":[{"name":"亞砷酸鐵（Ferr ars）","note":"課文把鐵鹽列為女性因月經或懷孕而血紅蛋白偏低時的溫和選擇，親和力在紅血球與血紅蛋白的生成。"},{"name":"鐵（Ferr met）","note":"課文點名的順勢療法鐵鹽之一，用於希望較溫和、較迅速改善血紅蛋白偏低的情況。"},{"name":"磷酸鐵（Ferr phos）","note":"與上述兩者並列為課文建議的鐵鹽，方向同樣是貧血傾向與血紅蛋白不足。"}],"atlas":[],"questions":[{"id":"q1101","ch":11,"level":1,"type":"single","style":"concept","q":"血液中，血漿約佔血容積的多少？","options":["約 90%","約 55%","約 7%","約 45%"],"answer":[1],"explain":"血漿約佔血容積 55%，各種細胞約佔 45%。7% 是血量佔體重的比例，不是血容積組成；90–92% 是血漿之中水份的比例。最常見的陷阱是把「血漿裡有九成水」直接當成「血漿佔九成血容積」，兩條百分比線要分清楚。","source":"第十一章 11.2 血液的組成成份","chId":"ch11"},{"id":"q1102","ch":11,"level":1,"type":"single","style":"concept","q":"下列哪種血漿蛋白數量最多，主要負責維持血漿滲透壓？","options":["纖維蛋白原","凝血酵素原","白蛋白","球蛋白"],"answer":[2],"explain":"白蛋白由肝製造、是數量最多的血漿蛋白，主職維持正常血漿滲透壓，並兼運脂質與類固醇荷爾蒙。球蛋白以抗體與運輸為主；纖維蛋白原是凝血原料；凝血酵素原是凝血系統的蛋白。陷阱是把「凝血因子」與「滲透壓」混為一談，其實兩者由不同蛋白負責。","source":"第十一章 11.2.1 血漿蛋白","chId":"ch11"},{"id":"q1103","ch":11,"level":1,"type":"single","style":"concept","q":"止血第一步中，令受損血管收縮的主要物質是？","options":["血小板釋出的 ADP","凝血酵素","嗜鹼性白血球釋出的肝素","血小板釋出的血清素"],"answer":[3],"explain":"血小板黏附受損血管壁後釋出血清素，令血管收縮；受損血管本身亦釋出血栓素。ADP 屬第二步，用來吸引更多血小板；凝血酵素在第三步凝血才出場；肝素是抗凝血劑，作用方向相反。陷阱是見到「血小板釋出」就選 ADP，忽略了題目問的是血管收縮。","source":"第十一章 11.3.2 止血：1. 血管收縮","chId":"ch11"},{"id":"q1104","ch":11,"level":1,"type":"single","style":"concept","q":"紅血球不能進行細胞分裂，最直接的原因是？","options":["沒有細胞核與細胞器","血紅蛋白佔滿整個細胞","壽命只有約 120 天","呈雙凹圓盤形"],"answer":[0],"explain":"紅血球沒有細胞核與細胞器，所以不能分裂、不能自行修補，壽命才只有約 120 天。雙凹形是增加表面積以利氣體交換；血紅蛋白是內容物，不是不能分裂的原因；120 天是結果而不是原因。陷阱正是把結果（壽命短）當成原因。","source":"第十一章 11.3 血液的細胞成份","chId":"ch11"},{"id":"q1105","ch":11,"level":2,"type":"multi","style":"concept","q":"關於血漿蛋白，下列哪些正確？（選 2–3 項）","options":["球蛋白包括由淋巴細胞產生的抗體","血漿蛋白可自由穿過毛細血管小孔進入組織","血漿蛋白下降會令血漿滲透壓上升","白蛋白可運送脂質與類固醇荷爾蒙","纖維蛋白原由肝合成，是凝血必需物質"],"answer":[0,3,4],"explain":"白蛋白既維持滲透壓亦運脂質與類固醇荷爾蒙；球蛋白包含抗體、運輸蛋白與酵素抑制劑；纖維蛋白原由肝合成，是凝血原料。血漿蛋白分子太大，正常不能穿過毛細血管小孔，所以才留在血管內形成滲透壓；蛋白下降時滲透壓是下降而非上升，液體反而走入組織。這兩個相反方向的敘述就是本題的陷阱。","source":"第十一章 11.2.1 血漿蛋白","chId":"ch11"},{"id":"q1106","ch":11,"level":2,"type":"single","style":"concept","q":"止血過程的正確次序是？","options":["凝血→血管收縮→血小板栓→纖維蛋白溶解","血管收縮→血小板栓→凝血→纖維蛋白溶解","血小板栓→血管收縮→凝血→纖維蛋白溶解","血管收縮→凝血→血小板栓→纖維蛋白溶解"],"answer":[1],"explain":"課文把止血分成四步：先血管收縮減少血流，再由血小板聚集形成臨時的血小板栓，然後凝血形成更強韌的纖維蛋白網，最後纖維蛋白溶解清除凝塊。把凝血放在血小板栓之前，等於跳過了立即封堵的步驟；把血小板栓放在血管收縮之前，則忽略了血清素令血管收窄這第一個反應。 陷阱是憑「先凝血才封口」的直覺排次序，忽略血小板栓才是即時封堵。","source":"第十一章 11.3.2 止血","chId":"ch11"},{"id":"q1107","ch":11,"level":2,"type":"multi","style":"concept","q":"比較凝血的外在途徑與內在途徑，下列哪些正確？（選 2–3 項）","options":["外在途徑由受損組織釋出組織因子啟動","內在途徑由血管內皮受損與血小板黏附啟動","外在途徑在數秒內發生","內在途徑比外在途徑快，數秒內完成","兩者不會同時發生，身體只會選其一"],"answer":[0,1,2],"explain":"外在途徑由循環以外的受損組織釋出組織因子（凝血酶原酶）啟動，數秒內完成；內在途徑局限於血循環內，由內皮受損與血小板黏附激發，需 3–6 分鐘。課文明言兩者通常一起發生，所以「只選其一」是錯的。最易失分是把快慢倒轉：慢的是內在，快的是外在。","source":"第十一章 11.3.2 血液凝結","chId":"ch11"},{"id":"q1108","ch":11,"level":2,"type":"single","style":"concept","q":"單核白血球離開血流進入組織後，會變成什麼細胞，並分泌哪種細胞激素？","options":["漿細胞；抗體","嗜中性白血球；溶小體","巨噬細胞；白細胞介素-1","巨噬細胞；組織胺"],"answer":[2],"explain":"單核白血球在血中擔任吞噬細胞，進入組織後變成巨噬細胞，並產生細胞激素白細胞介素-1（IL-1），參與炎症與免疫。漿細胞由 B 淋巴細胞分化，不是單核細胞；溶小體是嗜中性白血球的顆粒；組織胺主要由嗜鹼性白血球與肥大細胞釋出。陷阱是「巨噬細胞＋組織胺」這個似是而非的配對。","source":"第十一章 11.3 白血球","chId":"ch11"},{"id":"q1109","ch":11,"level":3,"type":"single","style":"case","q":"一名肝硬化病人血中白蛋白明顯下降，出現下肢水腫。最直接的解釋是？","options":["血小板不足，微血管持續滲血","血漿黏度上升，血流變慢","血紅蛋白不足，組織缺氧而積水","血漿滲透壓下降，液體由血管移入組織"],"answer":[3],"explain":"白蛋白是維持血漿滲透壓的主力；肝硬化令白蛋白製造減少，滲透壓下降，水便留不住而移入組織與體腔，形成水腫。血漿黏度雖受白蛋白影響，但黏度與水腫沒有直接因果；血紅蛋白負責運氧；血小板關乎止血。陷阱是見到「肝病」就想到凝血，忽略了蛋白與滲透壓這條線。","source":"第十一章 11.2.1 血漿蛋白與水腫","chId":"ch11"},{"id":"q1110","ch":11,"level":3,"type":"multi","style":"case","q":"一名第 8 因子缺乏的血友病患者拔牙後滲血不止。下列哪些正確？（選 2–3 項）","options":["第 8 因子是凝血所需，缺乏會令纖維蛋白網形成不足","初期形成的血小板栓比纖維蛋白凝塊弱，只能暫時封堵","凝血因子的編號等於它們參與凝血的先後次序","肝素由嗜中性白血球製造，可加速凝血","凝血酵素能促進自身製造，屬正回饋"],"answer":[0,1,4],"explain":"第 8 因子是凝血過程的一員，缺乏時纖維蛋白網不足，所以血友病患者危險；血小板栓只是臨時封印，強度遠不及纖維蛋白凝塊；課文亦指出凝血酵素對自身製造有強力促進作用，屬正回饋。編號代表被發現的順序而非作用次序；肝素由嗜鹼性白血球製造，而且是抗凝血，兩項都是典型干擾。","source":"第十一章 11.3 血小板與 11.3.2 凝血的控制","chId":"ch11"},{"id":"q1111","ch":11,"level":3,"type":"single","style":"remedy","q":"一名 30 歲女性因月經量多，血紅蛋白處於貧血邊緣。除硫酸鐵外，課文提到可考慮的順勢療法選項是？","options":["鐵鹽，例如磷酸鐵（Ferr phos）","球蛋白輸注","肝素（Heparin）","華法林（Warfarin）"],"answer":[0],"explain":"課文指出女性因月經或懷孕可令血紅蛋白天然偏低，硫酸鐵可矯正，若想要較溫和迅速的效果，可用順勢療法的鐵鹽：亞砷酸鐵、鐵與磷酸鐵。華法林是術後抗凝血藥物，肝素是天然抗凝血劑，兩者方向完全相反；球蛋白與免疫有關，不是補鐵。陷阱是見到「血液」就聯想到抗凝血藥。","source":"第十一章 11.3 紅血球與貧血","chId":"ch11"}]},{"id":"ch12","num":12,"title":"抵抗力與免疫力","en":"Resistance and Immunity","group":"免疫","tagline":"非特異性防禦、炎症、淋巴系統與免疫記憶","intro":"身體有兩道防線：非特異性防禦先擋，特異性免疫後追。考試主線是炎症五大徵象的成因、淋巴系統的引流與過濾分工，以及 B／T 細胞與主動、被動免疫的四格圖。把「誰製造抗體、誰記得住抗原」牢牢記住，個案題就會穩。","memoryHook":"紅熱痛腫失功能；主動有記憶，被動借抗體。","sections":[{"title":"第一線：非特異性防禦","points":["非特異性防禦不是「什麼都亂擋」，而是幾套固定機制：表面屏障、吞噬作用、天然抗菌物質、炎症與 NK 細胞。","皮膚與黏膜完整時是有效生理屏障；黏膜分泌黏液困住微生物，皮脂與汗液含抗菌、抗黴物質。","鼻毛像粗過濾器；呼吸道纖毛把黏液與吸入物推向喉嚨，再咳出或吞下；尿液由膀胱單向流出，減少微生物逆行。","吞噬細胞循化學趨向性移到炎症區，伸出偽足包住目標；吞噬作用對目標沒有選擇性。","天然抗菌物質包括胃液鹽酸、溶菌酶（lysozyme；課文寫「溶酶體」）、唾液、干擾素與補體；溶菌酶見於淚液及分泌物，但不在汗、尿或腦脊髓液。","補體是約 20 種蛋白，被免疫複合物或細菌壁糖類活化，可破壞細菌壁、促進吞噬，並吸引噬菌細胞。"],"table":{"headers":["防禦機制","例子","作用"],"rows":[["表面屏障","皮膚、黏膜、纖毛","阻擋與清除入侵物"],["吞噬作用","嗜中性白血球、巨噬細胞","吞食並消化微生物"],["天然抗菌物質","鹽酸、溶菌酶、補體","殺菌、促進吞噬"],["炎症","血管與白血球反應","升溫、清創、限制擴散"],["NK 細胞","一群淋巴細胞","殺死非自身、受病毒感染的細胞"]]}},{"title":"炎症：五大徵象與背後機制","points":["急性炎症五大徵象：紅、熱、痛、腫脹、喪失功能；目的是升高局部溫度殺菌、清除有害物質，本身是有利反應。","紅與熱來自微動脈及局部毛細血管擴張、血流增加，介質包括組織胺與血清素。","腫脹來自血管通透性增加與血管內壓上升，液體走入間質；血漿蛋白（抗體、纖維蛋白原）亦漏出，纖維蛋白在間質築牆限制感染。","白血球移動：血流變慢令白血球貼壁，嗜中性最先進入組織；約 24 小時後巨噬細胞成主要細胞。","發燒：巨噬細胞與顆粒細胞釋出 IL-1（內因致熱原），重設下視丘恆溫器；高溫抑制微生物，同時促進吞噬。","疼痛由腫脹壓迫神經末梢，加上緩激肽與前列腺素令末梢更敏感；化膿則是死亡細胞、殘骸、纖維蛋白與微生物的混合物。"],"table":{"headers":["徵象","主要成因"],"rows":[["紅","微血管擴張、血流增加"],["熱","血流增加、局部代謝上升"],["腫","通透性增加、液體入間質"],["痛","腫脹壓迫＋緩激肽、前列腺素"],["喪失功能","腫痛與組織損傷"]]}},{"title":"淋巴系統：沒有泵的回收網","points":["淋巴循環是開放路線、沒有泵：靠淋巴管平滑肌節律收縮、鄰近骨骼肌運動與動脈脈動推動淋巴。","組成包括淋巴液、淋巴管、淋巴結、淋巴器官（脾、胸腺）、瀰漫性淋巴組織（扁桃腺）與骨髓。","三大功能：組織引流（每日約 21L 液體離開血管，只有 3–4L 經淋巴回流）、小腸吸收脂肪與脂溶性維他命、免疫力。","淋巴液成分似血漿但不含血漿蛋白，所以等於間質液；小腸乳糜管吸收脂肪後呈乳狀，稱為乳糜。","毛細淋巴管是閉端小管、單層內皮、通透性高；幾乎所有組織都有，除了中樞神經系統、骨骼與大部份皮膚表層。","淋巴管有杯狀瓣膜，單向流向胸部，最後經胸導管與右淋巴導管排入鎖骨下靜脈。"],"table":{"headers":["導管","引流範圍","入口"],"rows":[["胸導管","雙腿、盆腔腹腔、左半胸、頭頸左側、左臂","左鎖骨下靜脈"],["右淋巴導管","右半胸、頭頸右側、右臂","右鎖骨下靜脈"]]}},{"title":"淋巴結、脾、胸腺與 MALT","points":["淋巴結呈豆形，有 4–5 條輸入淋巴管，但只有 1 條輸出；門位有 1 條動脈進入，1 條靜脈與 1 條輸出淋巴管離開。","淋巴結兩大功能：過濾吞噬（微生物、腫瘤細胞、殘骸）與增殖淋巴細胞；清除不全會發炎腫大，稱淋巴結病。","脾臟是最大淋巴器官，位於左季肋區、胃底與橫膈之間；紅髓充滿血液，白髓是淋巴組織；沒有傳入淋巴管。","脾功能：破壞老舊紅血球（膽紅素與鐵經脾靜脈、門靜脈送肝）、儲血約 350ml、免疫反應，以及胎兒造血。","胸腺位於胸骨後縱隔上部，青春期最重（30–40g）後退化；T 淋巴細胞在此成熟，能分辨自身與外來，受胸腺素刺激。","MALT（扁桃腺、派伊爾氏淋巴集結）沒有被膜、沒有傳入淋巴管，所以不過濾淋巴液，負責早期攔截入侵抗原。"],"table":{"headers":["器官","位置","特點"],"rows":[["淋巴結","沿淋巴管成群分佈","4–5 輸入、1 輸出；過濾與增殖淋巴細胞"],["脾臟","左季肋區","最大淋巴器官；無傳入淋巴管；儲血約 350ml"],["胸腺","胸骨後縱隔上部","T 細胞成熟；青春期後退化"],["MALT","消化道、呼吸道、泌尿生殖道","無被膜；扁桃腺與派伊爾氏淋巴集結"]]}},{"title":"特異性免疫與四類後天免疫","points":["抗原通常是膜上蛋白；每個淋巴細胞只對一種抗原反應，這正是免疫記憶的基礎。","T 細胞在胸腺成熟，負責細胞免疫；B 細胞在骨髓活化，負責抗體免疫，固定在脾與淋巴結等淋巴組織。","T 細胞四型：記憶（長壽、再遇即反應）、細胞毒素（黏附並毒殺受感染細胞與癌細胞）、輔助（分泌細胞因子、協助 B 細胞）、抑制（踩煞車）。","B 細胞受抗原刺激、在輔助 T 幫助下分裂成漿細胞與記憶 B；漿細胞活不過一天，只分泌一種抗體。","五類抗體：IgA 見於分泌、IgD 在 B 細胞表面、IgE 與過敏有關、IgG 最大且能過胎盤、IgM 在原發反應大量製造。","主動免疫（自然患病或接種疫苗）有記憶細胞、保護久；被動免疫（母體抗體或注射抗血清）沒有記憶、保護短。"],"table":{"headers":["類型","獲得方式","記憶細胞","例子"],"rows":[["主動天然","自然感染","有","得過麻疹後康復"],["主動人工","疫苗、類毒素","有","破傷風類毒素"],["被動天然","母體 IgG 過胎盤、IgA 經母乳","無","嬰兒的短期保護"],["被動人工","注射現成抗血清","無","抗蛇毒血清"]]}}],"terms":[{"zh":"非特異性防禦","en":"Non-specific defence","def":"對任何入侵者都有效的第一線機制，包括屏障、吞噬、炎症與 NK 細胞。"},{"zh":"吞噬作用","en":"Phagocytosis","def":"細胞以偽足包圍並消化外來顆粒或微生物，對目標沒有選擇性。"},{"zh":"化學趨向性","en":"Chemotaxis","def":"白血球被化學引誘劑吸引，移向炎症或感染部位的現象。"},{"zh":"補體","en":"Complement","def":"血液與組織中約 20 種蛋白，可破壞細菌壁、促進吞噬並吸引噬菌細胞。"},{"zh":"炎症","en":"Inflammation","def":"局部血流、血管通透性與白血球反應的組合，表現為紅、熱、痛、腫與喪失功能。"},{"zh":"淋巴液","en":"Lymph","def":"由組織液進入淋巴管形成的清澈液體，成分似間質液，不含血漿蛋白。"},{"zh":"淋巴結","en":"Lymph node","def":"沿淋巴管分佈的豆形器官，過濾淋巴液並增殖淋巴細胞。"},{"zh":"脾臟","en":"Spleen","def":"人體最大的淋巴器官，位於左季肋區，破壞老舊紅血球、儲血並參與免疫。"},{"zh":"胸腺","en":"Thymus","def":"胸骨後縱隔上部的淋巴器官，T 淋巴細胞在此成熟，青春期後退化。"},{"zh":"抗原呈現細胞","en":"Antigen-presenting cell","def":"消化抗原後把抗原碎片展示在細胞膜上，以活化 T 淋巴細胞，例如巨噬細胞。"},{"zh":"漿細胞","en":"Plasma cell","def":"由 B 淋巴細胞分化，分泌特定抗體，壽命不超過一天。"},{"zh":"記憶細胞","en":"Memory cell","def":"初次接觸抗原後長期存留的淋巴細胞，再遇同一抗原時可快速反應。"}],"examTips":["炎症五大徵象要把「喪失功能」一齊記，考題最愛在四項裡偷走這一項。","急性炎症先到的是嗜中性白血球，約 24 小時後巨噬細胞接手；慢性炎症則以淋巴細胞為主。","脾臟沒有傳入淋巴管；淋巴結有 4–5 條輸入、1 條輸出，這是分辨兩者的關鍵。","主動免疫才有記憶細胞；被動免疫（母體抗體、抗血清）保護短，因為抗體會被分解。","原發反應約 2 星期才驗到抗體；繼發反應靠記憶 B，快而強。","補體與溶菌酶別混淆：補體是約 20 種血漿蛋白，溶菌酶是分泌物中的抗菌蛋白，不在汗與尿。"],"remedies":[],"atlas":[],"questions":[{"id":"q1201","ch":12,"level":1,"type":"single","style":"concept","q":"以下哪項不屬於急性炎症的五大徵象？","options":["紅","黃疸","喪失功能","熱"],"answer":[1],"explain":"急性炎症五大徵象是紅、熱、痛、腫脹與喪失功能。黃疸是膽紅素過高令皮膚與鞏膜發黃，屬肝膽問題，不是炎症的局部徵象。這題的陷阱是「紅」與「黃」都屬於顏色變化，但炎症的紅來自血流增加，黃疸來自膽紅素沉積，兩者機制完全不同。","source":"第十二章 12.2 炎症反應","chId":"ch12"},{"id":"q1202","ch":12,"level":1,"type":"single","style":"concept","q":"急性炎症中，最先大量進入感染部位的吞噬細胞是？","options":["嗜鹼性白血球","漿細胞","嗜中性白血球","嗜酸性白血球"],"answer":[2],"explain":"課文明言在急性階段最重要的白血球是嗜中性白血球，牠們黏附血管內層、穿過內皮進入組織吞噬抗原，死亡後構成膿液的主要成分。嗜酸性主攻寄生蟲與過敏；嗜鹼性釋出組織胺與肝素；漿細胞負責分泌抗體而非吞噬。陷阱是以為「巨噬細胞」一定最先到，其實巨噬細胞約 24 小時後才成主力。","source":"第十二章 12.2.1 白血球的移動","chId":"ch12"},{"id":"q1203","ch":12,"level":1,"type":"single","style":"concept","q":"T 淋巴細胞在哪個器官成熟，並學會分辨自身與外來組織？","options":["脾臟","淋巴結","紅骨髓","胸腺"],"answer":[3],"explain":"淋巴細胞源自紅骨髓的多能幹細胞，進入胸腺後發展為成熟的 T 淋巴細胞，並能區分自身與外來組織。骨髓是 B 淋巴細胞被活化／加工的地方；脾臟與淋巴結是成熟淋巴細胞聚集與反應的場所，不是 T 細胞成熟之處。陷阱是把「製造」與「成熟」都放在骨髓。","source":"第十二章 12.3.3 胸腺","chId":"ch12"},{"id":"q1204","ch":12,"level":1,"type":"single","style":"concept","q":"人體最大的淋巴器官是？","options":["脾臟","扁桃腺","胸腺","淋巴結"],"answer":[0],"explain":"脾臟含網狀組織與淋巴組織，是最大的淋巴器官，位於腹腔左季肋區、胃底與橫膈之間。胸腺在青春期最重也只有 30–40g；扁桃腺屬黏膜相關淋巴組織；淋巴結最大的也不過杏仁大小。陷阱是胸腺名氣大，但論體積與淋巴組織量，脾臟才是最大。","source":"第十二章 12.3.3 脾臟","chId":"ch12"},{"id":"q1205","ch":12,"level":2,"type":"multi","style":"concept","q":"淋巴系統的功能包括下列哪些？（選 2–3 項）","options":["製造凝血因子","參與免疫力","把組織液引流回血液","在小腸吸收脂肪與脂溶性維他命","運送大部分氧氣到組織"],"answer":[1,2,3],"explain":"課文列出的淋巴功能有三：組織引流、小腸吸收脂肪與脂溶性物質、免疫力。氧氣主要由紅血球的血紅蛋白運送；凝血因子主要由肝臟合成。這兩項都屬血液與肝臟的工作，卻很容易因為「都是循環系統」而被誤選，是典型的概念混淆陷阱。","source":"第十二章 12.3 淋巴系統的功能","chId":"ch12"},{"id":"q1206","ch":12,"level":2,"type":"single","style":"concept","q":"炎症時的「腫脹」最直接由什麼造成？","options":["動脈收縮令血液滯留在局部","微血管通透性增加與血管內壓上升，液體走入間質","纖維蛋白溶解把凝塊分解","嗜中性白血球在局部大量繁殖"],"answer":[1],"explain":"腫脹（水腫）是液體離開局部血管進入間質空隙所致：炎症介質令毛細血管通透性增加，加上血流增加使血管內壓上升。動脈收縮會減少血流，與炎症的血管擴張相反；纖維蛋白溶解屬凝血後期；嗜中性白血球不會在組織大量繁殖。陷阱是把「紅熱」（血流增加）與「腫」（液體外移）混成同一機制。","source":"第十二章 12.2.1 增加組織液的形成","chId":"ch12"},{"id":"q1207","ch":12,"level":2,"type":"single","style":"concept","q":"比較淋巴結與脾臟，下列哪項正確？","options":["兩者的成熟都靠胸腺素刺激","脾臟有 4–5 條傳入淋巴管","脾臟沒有傳入淋巴管，主要過濾血液","淋巴結有多條輸出淋巴管"],"answer":[2],"explain":"脾臟沒有傳入淋巴管，主要過濾血液；淋巴結才是 4–5 條輸入、只有 1 條輸出。胸腺素由胸腺上皮細胞分泌，刺激胸腺及其他淋巴組織成熟，並非脾與淋巴結的分別。陷阱是把淋巴結的「多入一出」錯配到脾臟身上。","source":"第十二章 12.3.3 淋巴結與脾臟","chId":"ch12"},{"id":"q1208","ch":12,"level":2,"type":"multi","style":"concept","q":"關於五類抗體，下列哪些正確？（選 2–3 項）","options":["IgD 由漿細胞分泌進入血液","IgM 是強力的補體活化劑","IgG 能通過胎盤保護胎兒","IgA 見於母乳與唾液，防止抗原穿過上皮膜","IgE 在原發反應時大量製造"],"answer":[1,2,3],"explain":"IgA 出現在分泌中如母乳與唾液；IgG 是最大、最普遍的抗體，能過胎盤；IgM 在原發反應大量製造，亦是強力補體活化劑。原發反應大量製造的是 IgM 而不是 IgE；IgE 主要在過敏時大量出現。IgD 展示在 B 細胞表面讓抗原結合以活化 B 細胞，不是由漿細胞分泌入血。 陷阱是把「原發反應」與 IgE 的過敏角色混淆。","source":"第十二章 12.4.2 表 12.2 抗體的五種類型","chId":"ch12"},{"id":"q1209","ch":12,"level":3,"type":"single","style":"case","q":"一名六個月嬰兒全靠母乳、未接種疫苗，對母親得過的疾病仍有短期保護。這屬於哪類免疫？","options":["主動天然免疫，有記憶細胞","主動人工免疫，有記憶細胞","被動人工免疫，有記憶細胞","被動天然免疫，無記憶細胞、保護短暫"],"answer":[3],"explain":"母親的 IgG 經胎盤、IgA 經母乳進入嬰兒體內，嬰兒自己的淋巴細胞沒有被活化，所以沒有記憶細胞，抗體分解後保護即消失，屬被動天然免疫。主動免疫的定義是個體自己產生抗體並形成記憶細胞；被動人工則是注射現成抗血清。陷阱是見到「天然」就以為一定有記憶，其實關鍵在抗體是「借來的」。","source":"第十二章 12.6 被動天然後天免疫","chId":"ch12"},{"id":"q1210","ch":12,"level":3,"type":"single","style":"case","q":"HIV 主要破壞輔助 T 淋巴細胞。為何病人連抗體免疫也會受損？","options":["B 淋巴細胞需要輔助 T 細胞刺激，才能有效產生抗體","巨噬細胞停止吞噬抗原","補體無法被活化","抗原呈現細胞完全消失"],"answer":[0],"explain":"課文指出輔助 T 不但是細胞免疫所必需，抗體免疫同樣需要它：B 細胞雖負責製造抗體，但首先要經輔助 T 刺激。所以輔助 T 數量顯著下降，代表整個免疫系統受危害。補體活化只是抗體的功能之一；巨噬細胞與抗原呈現細胞不是 HIV 的主要攻擊目標。陷阱是以為「B 細胞自己做抗體」，忽略了 T 的授權。","source":"第十二章 12.4.1 輔助 T 淋巴細胞","chId":"ch12"},{"id":"q1211","ch":12,"level":3,"type":"multi","style":"case","q":"關於疫苗與免疫記憶，下列哪些正確？（選 2–3 項）","options":["被動免疫的抗體會被分解，保護較短暫","接種後數小時內即可驗到大量抗體","疫苗保留抗原特性，一般不造成疾病症狀","注射現成抗血清屬於主動免疫","主動人工免疫會產生記憶細胞，保護較持久"],"answer":[0,2,4],"explain":"疫苗用已死或減弱的微生物、或去活性毒素，保留抗原性以刺激淋巴細胞而不致病；主動人工免疫會產生記憶細胞，故保護較久；被動免疫的抗體終會被分解，所以短暫。注射現成抗血清屬被動人工免疫；接種後原發反應約需兩星期才驗到低水平抗體，數小時內大量抗體是錯的。 陷阱是把「打了針」一律當成主動免疫，忽略抗體是外來的。","source":"第十二章 12.5 記憶細胞與 12.6 後天免疫","chId":"ch12"},{"id":"q1212","ch":12,"level":3,"type":"single","style":"case","q":"肺結核在肺內形成肉芽腫，把微生物圍住。下列哪項最能描述這情況？","options":["只有血管收縮，沒有細胞浸潤","慢性炎症，以淋巴細胞與纖維化為主，把微生物圍住","急性炎症，以嗜中性白血球為主，數天內消退","補體耗盡造成的水腫"],"answer":[1],"explain":"慢性炎症與急性相似但持續較久，浸潤細胞由淋巴細胞取代嗜中性白血球，纖維組織母細胞被活化產生膠原與纖維化；身體若清不掉感染，會把它圍成肉芽腫，肺結核正是典型例子。嗜中性為主、數天消退是急性炎症；血管收縮屬止血第一步；補體耗盡不是肉芽腫的成因。 陷阱是見到「肉芽腫」仍用急性炎症的嗜中性細胞去解釋。","source":"第十二章 12.2.2 慢性炎症","chId":"ch12"}]},{"id":"ch13","num":13,"title":"排泄系統","en":"The Urinary System","group":"內臟","tagline":"腎元濾過、重吸收與排尿通道","intro":"排泄系統的重點不是「小便」本身，而是腎元如何把血液變成尿液：先濾過，再選擇性重吸收，最後分泌。考試主線是腎臟位置、腎元三段工作、ADH 與醛固酮對尿量的調控，以及輸尿管至尿道一路的防逆流與括約肌控制。","memoryHook":"先濾、後收、再分泌；內括不隨意，外括隨意。","sections":[{"title":"排泄與泌尿系統的構成","points":["排泄不同於排糞：排泄是把細胞代謝產生的廢物排出，泌尿系統、皮膚與肝臟都參與，排糞則在直腸與肛門發生。","尿液約含 96% 水、2% 尿素，其餘 2% 是尿酸、肌酸酐、氨、鈉、鉀、氯化物、磷酸鹽、硫酸鹽與草酸鹽。","氨、尿素與尿酸都是含氮廢物，用來排掉身體不需要的氮；排出的形式視水分供應而定。","魚類排氨、哺乳類排尿素、鳥類水分最少所以排半固體尿酸。","器官組成：2 個腎臟製造尿液、2 條輸尿管運送、1 個膀胱暫存、1 條尿道排出，受肋廓與骨盆帶保護。"],"table":{"headers":["器官","主要功能","關鍵特點"],"rows":[["腎臟","過濾血液、製造尿液","含百萬計腎元，調節血壓與電解質"],["輸尿管","把尿液送到膀胱","平滑肌蠕動，斜穿膀胱壁防逆流"],["膀胱","暫時儲存尿液","逼尿肌收縮排空，內有三角區"],["尿道","把尿液排出體外","內括約肌不隨意、外括約肌隨意"]]}},{"title":"腎臟的位置與鄰居","points":["腎臟位於後腹壁、脊柱兩側，在腹膜之後、橫膈之下，由第 12 胸椎延伸到第 3 腰椎。","右腎通常比左腎稍低，因為右上腹有相當大的空間被肝臟佔用。","腰豆形，約長 11cm、寬 6cm、高 3cm、重 150g；嵌入脂肪團中，並由腎筋膜包圍固定。","兩腎上方各接腎上腺；右腎前面是肝右葉、十二指腸與結腸肝曲；左腎前面是脾、胃、胰、空腸與結腸脾曲。","約 25% 血容積由心臟泵入腎臟；入球微動脈比出球微動脈寬，這個「瓶頸」設計有助過濾。"],"table":{"headers":["腎臟","上方","前面"],"rows":[["右腎","右腎上腺","肝右葉、十二指腸、結腸肝曲"],["左腎","左腎上腺","脾臟、胃、胰臟、空腸、結腸脾曲"]]}},{"title":"腎元：濾過、重吸收、分泌","points":["腎元是腎臟的機能性顯微單位，每腎有數以百萬計；負責排廢物、調節血容積與血壓、控制電解質與 pH。","工作流程：血液在腎小球濾過，濾液進入鮑氏囊，再在特化腎小管內選擇性重吸收，最後產物分泌入收集管。","健康成人腎小球每分鐘可濾過 125ml 血液；如果沒有重吸收，每天大約要喝 180L 水才補得回來。","血壓太高可令腎小球微動脈不可修復地損壞；血壓太低則濾過力量不足，有毒分子留在循環內。","腎元受內分泌調節，主要是 ADH、醛固酮與副甲狀腺素。"]},{"title":"選擇性重吸收與腎小管分泌","points":["近曲小管是重吸收主戰場，葡萄糖與氨基酸 100% 回收；亨利氏彎管調節水與鹽；遠曲小管與收集管受荷爾蒙微調。","主動運輸在載體部位消耗化學能，把物質逆濃度差搬回血液；水則靠滲透作用被動跟隨。","運送極限量（腎臟閾值）是腎臟重吸收某物質的最大能力；血糖超過約 9 mmol/L（160mg/dl）便會出現糖尿。","ADH 增加遠曲小管與收集管對水的通透性，水重吸收增加、尿量減少；醛固酮增加鈉重吸收並排出鉀。","ANP 在血容量過高時分泌，降低鈉與水的重吸收、增加尿量，並抑制 ADH 與醛固酮。","尿素與尿酸的重吸收非常有限；青黴素、阿斯匹靈等來不及被濾過，便由腎小管分泌清除，H⁺ 分泌則維持血液 pH。"],"table":{"headers":["荷爾蒙","發動時機","主要動作","尿量"],"rows":[["ADH","缺水、血液太濃","增加水重吸收","減少"],["醛固酮","血壓低、血鈉低","重吸收鈉、排出鉀","減少"],["ANP","血容量過高、血壓高","減少鈉與水重吸收","增加"]]}},{"title":"輸尿管、膀胱與尿道","points":["輸尿管長約 25–30cm、直徑約 3mm，由纖維外層、平滑肌層與移形上皮黏膜三層構成。","輸尿管靠平滑肌蠕動推進尿液，這是平滑肌的固有特性、不受自主神經控制；蠕動源自腎小盞的起搏器。","輸尿管斜穿膀胱後壁，膀胱漲滿時內壓升高會壓閉輸尿管開口，防止尿液逆流回腎。","膀胱呈梨形，充滿時變橢圓；約 300–400ml 開始有尿意，容積很少超過 600ml；逼尿肌收縮排空膀胱。","三角區由兩個輸尿管開口與下方尿道口圍成；尿道內括約肌是上段平滑肌增厚，不受意識控制。","女性尿道約 4cm；男性尿道較長並兼生殖功能；外尿道括約肌由骨骼肌構成，受意識控制，是憋尿的關鍵。"],"table":{"headers":["結構","組織／特點","功能"],"rows":[["輸尿管","平滑肌＋移形上皮","蠕動送尿、斜穿防逆流"],["膀胱逼尿肌","交錯平滑肌","收縮排空膀胱"],["尿道內括約肌","平滑肌，自主神經","平時保持閉合"],["尿道外括約肌","骨骼肌，隨意神經","可主動憋尿或排尿"]]}}],"terms":[{"zh":"排泄","en":"Excretion","def":"把細胞代謝產生的廢物排出體外，與排糞不同，由泌尿系統、皮膚與肝臟參與。"},{"zh":"腎元","en":"Nephron","def":"腎臟的機能性顯微單位，負責濾過、重吸收與分泌，每個腎有數以百萬計。"},{"zh":"腎小球","en":"Glomerulus","def":"腎元內進行濾過的一團微血管，血液中的水與小分子在此被濾出。"},{"zh":"選擇性重吸收","en":"Selective reabsorption","def":"腎小管把濾液中有用物質搬回血液的過程，維持水、電解質與酸鹼平衡。"},{"zh":"運送極限量","en":"Transport maximum","def":"腎臟重吸收某物質的最大能力，亦稱腎臟閾值；超過便會由尿排出。"},{"zh":"腎臟閾值","en":"Renal threshold","def":"血中某物質濃度高到載體飽和、開始出現在尿中的界線，例如血糖約 9 mmol/L。"},{"zh":"腎盂","en":"Renal pelvis","def":"漏斗狀的集尿結構，接收腎臟生成的尿液，並延續為輸尿管。"},{"zh":"逼尿肌","en":"Detrusor muscle","def":"膀胱壁中層交錯排列的平滑肌，收縮時把尿液排出。"},{"zh":"三角區","en":"Trigone","def":"膀胱底部的平滑三角形區域，由兩個輸尿管開口與尿道口圍成。"},{"zh":"輸尿管","en":"Ureter","def":"長約 25–30cm 的肌肉管道，靠蠕動把尿液由腎臟送到膀胱。"},{"zh":"抗利尿素","en":"Antidiuretic hormone (ADH)","def":"由腦下垂體後葉分泌，增加遠曲小管與收集管對水的通透性，令尿量減少。"},{"zh":"醛固酮","en":"Aldosterone","def":"由腎上腺皮層分泌，增加鈉重吸收與鉀排出，令尿量減少。"}],"examTips":["右腎比左腎低，因為肝臟佔用右上腹空間；考題常把左右倒轉。","腎元是機能單位；濾過在腎小球，重吸收在腎小管，兩者不要混淆。","葡萄糖平常 100% 重吸收，但血糖超過約 9 mmol/L 便會出現糖尿，原因是載體飽和。","ADH 保水（尿少）、醛固酮保鈉排鉀、ANP 排鈉排水（尿多），三者的方向要分清。","內括約肌不隨意、外括約肌隨意；女性尿道約 4cm，男性較長並兼生殖功能。","輸尿管蠕動是平滑肌固有特性，不受自主神經控制；斜穿膀胱壁是防逆流的關鍵。"],"remedies":[],"atlas":[],"questions":[{"id":"q1301","ch":13,"level":1,"type":"single","style":"concept","q":"腎臟的機能性顯微單位是？","options":["腎小盞","腎盂","腎元","腎小球"],"answer":[2],"explain":"腎元是腎臟的機能性顯微單位，每個腎有數以百萬計，負責濾過、重吸收與分泌。腎小球只是腎元內負責濾過的一團微血管；腎盂與腎小盞屬集尿與排尿通道，不是機能單位。陷阱是把「腎小球」當成整個單位，其實它只是腎元的第一站。","source":"第十三章 13.3.1 B. 腎元","chId":"ch13"},{"id":"q1302","ch":13,"level":1,"type":"single","style":"concept","q":"右腎通常比左腎位置稍低，主要原因是？","options":["右側腎上腺壓迫","右側橫膈膜較低","右腎體積較大","右上腹有肝臟佔用空間"],"answer":[3],"explain":"課文明言右腎通常比左腎稍低，因為有相當大空間被肝臟佔用。橫膈膜、腎臟體積與腎上腺都不是課文給出的原因；腎上腺在兩腎上方，位置對稱。陷阱是以為「右邊有肝」只影響消化，其實肝臟的體積直接改變了右腎的高度。","source":"第十三章 13.3.1 腎臟","chId":"ch13"},{"id":"q1303","ch":13,"level":1,"type":"single","style":"concept","q":"膀胱約含有多少尿液時，會開始感到不適、產生尿意？","options":["300–400ml","800–1000ml","600–700ml","100–200ml"],"answer":[0],"explain":"課文指膀胱含有大約 300–400ml 尿液時會開始感到不適，總容積很少超過約 600ml。100–200ml 仍屬舒適範圍；600ml 已是接近上限而非起始尿意；800ml 以上更超出膀胱一般容量。陷阱是把「開始有尿意」與「最大容量」兩個數字對調。","source":"第十三章 13.3.3 膀胱","chId":"ch13"},{"id":"q1304","ch":13,"level":1,"type":"single","style":"concept","q":"女性尿道的長度約為？","options":["2cm","4cm","25cm","10cm"],"answer":[1],"explain":"課文指女性尿道約 4cm，在恥骨聯合後方向下向前走，於陰道前方開口；男性尿道較長，且同時與生殖系統有關。25–30cm 是輸尿管的長度，不是尿道。陷阱是把尿道與輸尿管的數字混淆，兩者都在本章出現，但長度相差很遠。","source":"第十三章 13.3.4 尿道","chId":"ch13"},{"id":"q1305","ch":13,"level":2,"type":"multi","style":"concept","q":"腎元的功能包括下列哪些？（選 2–3 項）","options":["調節血容積與血壓","分泌膽汁幫助脂肪消化","以尿液形式排除廢物","控制電解質與代謝物水平、調節血液 pH","製造胰島素調節血糖"],"answer":[0,2,3],"explain":"課文列明腎元三方面功能：排廢物、調節血容積與血壓、控制電解質與代謝物並調節 pH，全部受內分泌系統調節。膽汁由肝細胞製造；胰島素由胰島 β 細胞分泌。這兩項都是「腹部器官」的相鄰概念，容易被誤選，但它們不屬腎元的工作。","source":"第十三章 13.3.1 B. 腎元","chId":"ch13"},{"id":"q1306","ch":13,"level":2,"type":"single","style":"concept","q":"尿液由腎元形成後，流經泌尿系統的正確次序是？","options":["腎小球囊→腎盂→腎小管→輸尿管→膀胱→尿道","腎小管→腎小球囊→收集管→腎盂→膀胱→輸尿管→尿道","腎小球囊→腎小管→收集管→腎盂→輸尿管→膀胱→尿道","腎小球囊→收集管→腎盂→腎小管→輸尿管→膀胱→尿道"],"answer":[2],"explain":"濾過在腎小球囊開始，濾出液依次經腎小管、收集管，再到腎盂，然後由輸尿管送入膀胱，最後經尿道排出。其餘選項把腎盂提前、把腎小管放在腎盂之後，或把輸尿管與膀胱的次序倒轉。陷阱是「腎盂」聽起來像腎臟的一部分就以為在最前，其實它只是集尿的漏斗。","source":"第十三章 13.3.2 至 13.3.4 尿液流經順序","chId":"ch13"},{"id":"q1307","ch":13,"level":2,"type":"multi","style":"concept","q":"關於調節腎小管重吸收的荷爾蒙，下列哪些正確？（選 2–3 項）","options":["ADH 會增加尿量以稀釋血液","醛固酮由腦下垂體後葉分泌","ANP 降低鈉與水的重吸收，令尿量增加","ADH 增加遠曲小管與收集管對水的通透性","醛固酮增加鈉重吸收並促進鉀排出"],"answer":[2,3,4],"explain":"ADH 令遠曲小管與收集管更透水，水被重吸收，尿量是減少而非增加；醛固酮由腎上腺皮層分泌，增加鈉重吸收、排出鉀；ANP 在血容量過高時降低鈉水重吸收，尿量增加。把 ADH 說成「利尿」是最常見的望文生義陷阱，它的名字是「抗利尿」。","source":"第十三章 13.3.1 C. 選擇性重吸收","chId":"ch13"},{"id":"q1308","ch":13,"level":2,"type":"single","style":"concept","q":"血糖超過約 9 mmol/L 後尿液出現葡萄糖，最直接的原因是？","options":["腎小球不再過濾葡萄糖","胰島素分泌過多把葡萄糖推入尿中","葡萄糖被腎小管分泌到濾液","腎小管載體部位被佔用，主動運輸負荷過重"],"answer":[3],"explain":"葡萄糖平時 100% 被重吸收，但載體數量有限；血糖超過運送極限量（約 9 mmol/L 或 160mg/dl）時，所有載體已被佔用、主動運輸負荷過重，多餘葡萄糖便留在管腔隨尿排出。腎小球仍然照樣濾過葡萄糖；胰島素是降血糖而非把糖推入尿；葡萄糖是「漏出」而非被分泌。 陷阱是以為糖尿一定是腎臟濾過出錯，其實問題在重吸收的載體。","source":"第十三章 13.3.1 C. 運送極限量","chId":"ch13"},{"id":"q1309","ch":13,"level":3,"type":"single","style":"case","q":"一名病人嚴重脫水，血漿滲透壓上升。預期他的尿量和尿液濃度如何變化？","options":["尿量減少，尿液濃縮","尿量不變，尿糖增加","尿量增加，尿液稀釋","尿量增加，尿鈉增加"],"answer":[0],"explain":"脫水時 ADH 分泌增加，遠曲小管與收集管對水通透性上升，水被大量重吸收，所以尿量減少、尿液濃縮，以保住水分。尿量增加且稀釋是 ADH 不足或 ANP 作用的方向；尿糖與尿鈉不是脫水的主要即時反應。陷阱是隻記住「多喝水多排尿」，沒有把 ADH 的保水方向連上。","source":"第十三章 13.3.1 C. ADH","chId":"ch13"},{"id":"q1310","ch":13,"level":3,"type":"single","style":"case","q":"一名 55 歲以上高血壓病人被處方利尿劑，服藥後尿量增加。其主要作用機理是？","options":["增加 ADH 的分泌","抑制腎元保留水分的能力","增加醛固酮的分泌","增加腎小球的濾過表面積"],"answer":[1],"explain":"課文指出利尿劑抑制腎元保留水分的能力，因此增加尿量、降低血壓。增加濾過表面積不是利尿劑的已知機理；ADH 與醛固酮都是保水保鈉的荷爾蒙，分泌增加反而會令尿量減少。陷阱是見到「降血壓」就以為一定與心臟或血管直接有關，忽略了腎臟的體積調節角色。","source":"第十三章 13.3.1 B. 腎元與利尿劑","chId":"ch13"},{"id":"q1311","ch":13,"level":3,"type":"multi","style":"case","q":"關於輸尿管與膀胱的防逆流及排尿控制，下列哪些正確？（選 2–3 項）","options":["尿道外括約肌由平滑肌構成，不受意識控制","輸尿管主要靠重力把尿液送入膀胱，沒有蠕動","尿道內括約肌不受意識控制","輸尿管斜穿膀胱後壁，膀胱漲滿時開口受壓而閉合","輸尿管蠕動是平滑肌固有特性，不受自主神經控制"],"answer":[2,3,4],"explain":"輸尿管斜穿膀胱後壁，膀胱內壓升高時會壓閉其開口以防逆流；蠕動源自腎小盞起搏器，是平滑肌固有特性、不受自主神經控制；內括約肌是上段平滑肌增厚，不受意識支配。外括約肌由骨骼肌構成，受意識控制；輸尿管靠蠕動而非重力送尿。兩個「括約肌」的組織與控制方式是本題最大陷阱。","source":"第十三章 13.3.2 輸尿管與 13.3.3 膀胱","chId":"ch13"}]},{"id":"ch14","num":14,"title":"肝臟","en":"The Liver","group":"內臟","tagline":"肝小葉、雙重血供與九大功能","intro":"肝臟是體內最大的腺體，也是代謝的總匯。考試主線有三條：肝小葉內血液與膽汁兩條相反方向的路徑、肝門靜脈與肝動脈的分工，以及九大功能中「代謝、解毒、儲存、分泌膽汁」的具體內容。膽囊只負責儲存與濃縮，不要與製造膽汁的肝細胞混淆。","memoryHook":"門靜脈七成血、肝動脈供氧；膽汁出肝、血入中央。","sections":[{"title":"位置、外形與肝葉","points":["肝臟是體內最大的腺體，重量可達約 2.5kg，位於右季肋部，可延伸到上腹部與右腰部。","上面前面是橫膈膜與前腹壁；下面有胃、膽管、十二指腸、結腸肝曲、右腎與腎上腺；後面有食道、下腔靜脈、主動脈、膽囊與脊柱。","肝臟分四葉：最大的右葉、楔形的左葉，以及位於後方表面的尾葉與方形葉。","肝臟被無彈性的薄膜包圍，腹膜不完全覆蓋；由韌帶固定於橫膈膜下方，部分靠腹腔器官的壓力托住。","它是最有能力再生的器官之一，也是可以接受移植的器官。"]},{"title":"肝小葉：血液與膽汁的兩條路","points":["肝小葉是六角形的機能單位，由立方的肝細胞以中央靜脈為中心、成對柱狀排列而成。","兩對細胞柱之間是竇狀隙，管壁不完整，容許門靜脈血與肝動脈血混合，並與肝細胞緊密接觸。","內襯竇狀隙的是庫氏細胞（星狀細胞），屬巨噬細胞，吞噬經過肝臟的破舊血細胞與外來微粒。","血流方向：竇狀隙→中央靜脈→較大靜脈→肝靜脈→下腔靜脈。","膽流方向：肝細胞柱另一側的膽小管→較大膽管→左右肝管→出肝，與血流方向相反。","每個肝小葉都含有淋巴組織與很多淋巴管，參與肝內免疫。"],"table":{"headers":["管道","內容物","流向"],"rows":[["竇狀隙","門靜脈血＋肝動脈血","流向中央靜脈"],["中央靜脈／肝靜脈","混合後的血液","出肝進入下腔靜脈"],["膽小管","膽汁","流向左右肝管出肝"]]}},{"title":"雙重血液供應：門靜脈與肝動脈","points":["肝門靜脈由腸臟延伸到肝臟，提供肝臟約 70% 的血液，但含氧量很低。","肝臟代謝活動旺盛、需氧量高，氧氣由肝動脈供應；肝動脈接近心臟，血液壓力非常高。","兩套血液在竇狀隙混合，既帶來營養，也帶來氧氣，並與肝細胞緊密接觸以便加工。","混合後的血液最後經肝靜脈離開肝臟，排空到下腔靜脈。"],"table":{"headers":["血管","供應比例","特點"],"rows":[["肝門靜脈","約 70%","含氧低、營養濃度高"],["肝動脈","其餘約 30%","供氧、壓力高"]]}},{"title":"肝臟九大功能","points":["代謝碳水化合物：餐後血糖上升，胰島素促使葡萄糖變成肝醣儲存；血糖回落時高血糖素令肝醣分解回葡萄糖。","代謝脂肪：把儲存的脂肪轉變為組織可以利用的能量形式。","蛋白質代謝：脫氨作用去掉含氮部分形成尿素；分解核酸形成尿酸；轉氨基作用把含氮部分移到碳水分子，造出非必需氨基酸。","合成血漿蛋白與大部份凝血因子；並由竇狀隙的庫氏細胞分解紅血球、抵抗微生物。","解毒：處理乙醇等藥物與微生物產生的毒素；並使胰島素、高血糖素、可體松、醛固酮、甲狀腺素與性荷爾蒙失去活性。","產熱：肝臟新陳代謝率高，是身體主要產熱器官；同時分泌膽汁（膽汁鹽、膽色素、膽固醇）並儲存肝醣、脂溶性維他命 A、D、E、K、鐵、銅與維他命 B12。"],"table":{"headers":["功能","具體內容"],"rows":[["1 碳水化合物代謝","胰島素促肝醣儲存；高血糖素促分解"],["2 脂肪代謝","把儲存的脂肪轉為組織可用的能量"],["3 蛋白質代謝","脫氨成尿素、轉氨基造非必需氨基酸"],["4 分解紅血球與防禦","竇狀隙的庫氏細胞吞噬"],["5 解毒","乙醇、藥物與微生物毒素"],["6 荷爾蒙滅活","胰島素、高血糖素、可體松、醛固酮、甲狀腺素、性荷爾蒙"],["7 產熱","高代謝率，身體主要產熱器官"],["8 分泌膽汁","膽汁鹽、膽色素、膽固醇"],["9 儲存","肝醣、維他命 A D E K、鐵、銅、B12"]]}},{"title":"膽囊與膽汁","points":["膽囊是梨形囊，附於肝臟後方表面，分底、體、頸，頸部與膽囊管相接。","膽囊動脈是肝動脈的分支；膽囊靜脈把血液引流入門靜脈。","膽囊功能：儲存膽汁、吸收水分把膽汁濃縮 10–15 倍、在需要時釋放膽汁。","進食後十二指腸分泌膽囊收縮素（CCK），加上脂肪與酸性乳糜出現，令膽囊收縮、奧迪氏括約肌放鬆。","膽汁每天約 500ml，含水、礦物鹽、黏液、膽色素（主要是膽紅素）、膽汁鹽與膽固醇；膽汁鹽在小腸乳化脂肪。","膽汁鹽在迴腸末端被再吸收，經門靜脈回肝，形成腸肝循環；膽紅素經腸菌轉為糞膽素排出，少量成為尿膽素原。"],"table":{"headers":["成份／結構","來源或作用"],"rows":[["膽汁鹽","肝細胞由膽固醇合成，乳化脂肪"],["膽紅素","紅血球溶血產物，與葡萄糖醛酸結合後排入膽汁"],["膽固醇","膽汁成份之一，亦是膽汁酸原料"],["CCK","十二指腸分泌，令膽囊收縮、括約肌放鬆"]]}}],"terms":[{"zh":"肝小葉","en":"Liver lobule","def":"肝臟的六角形機能單位，以中央靜脈為中心，肝細胞成對柱狀排列。"},{"zh":"肝細胞","en":"Hepatocyte","def":"肝小葉內立方形的主體細胞，負責代謝、解毒與製造膽汁。"},{"zh":"竇狀隙","en":"Sinusoid","def":"管壁不完整的肝內微血管，混合門靜脈血與肝動脈血，緊貼肝細胞。"},{"zh":"庫氏細胞","en":"Kupffer cell","def":"內襯竇狀隙的肝巨噬細胞，吞噬破舊血細胞與外來微粒。"},{"zh":"肝門靜脈","en":"Hepatic portal vein","def":"由腸臟通往肝臟的大靜脈，提供約 70% 肝血供，含氧低但營養高。"},{"zh":"肝動脈","en":"Hepatic artery","def":"供應肝臟氧氣的小動脈，壓力高，與門靜脈血在竇狀隙混合。"},{"zh":"膽小管","en":"Bile canaliculus","def":"肝細胞柱之間收集膽汁的微細管道，匯合後成左右肝管。"},{"zh":"膽囊","en":"Gall bladder","def":"附於肝臟後方的梨形囊，儲存膽汁並吸收水分濃縮 10–15 倍。"},{"zh":"膽紅素","en":"Bilirubin","def":"紅血球溶血產物，經肝細胞與葡萄糖醛酸結合後變水溶性，排入膽汁。"},{"zh":"膽汁鹽","en":"Bile salts","def":"由膽固醇合成的膽汁成份，在小腸乳化脂肪，並經腸肝循環回收。"},{"zh":"腸肝循環","en":"Enterohepatic circulation","def":"膽汁鹽在迴腸末端被再吸收，經門靜脈返回肝臟的再循環。"},{"zh":"脫氨作用","en":"Deamination","def":"從氨基酸移除含氮部分，形成尿素由尿排出。"}],"examTips":["肝門靜脈提供約 70% 血供但含氧低；氧氣靠肝動脈（壓力高），兩者最常被倒轉。","膽小管與竇狀隙位於肝細胞柱兩側，膽汁出肝、血液入中央靜脈，方向相反。","脫氨作用產生尿素；轉氨基作用製造非必需氨基酸，兩者勿混。","膽紅素要與葡萄糖醛酸結合才變水溶性；黃疸就是血膽紅素過高。","膽囊只儲存與濃縮膽汁，不製造膽汁；CCK 令膽囊收縮、奧迪氏括約肌放鬆。","庫氏細胞在竇狀隙，屬巨噬細胞；不要把牠當成肝細胞的一種。"],"remedies":[],"atlas":[],"questions":[{"id":"q1401","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟四個葉中，最大的是？","options":["左葉","方形葉","右葉","尾葉"],"answer":[2],"explain":"肝臟有四個葉，最明顯的是最大的右葉與較小、楔形的左葉；尾葉與方形葉位於肝臟後方表面。左葉雖然名字對稱，但體積比右葉小；尾葉與方形葉更只是後方的小葉。陷阱是看到「左、右」就以為兩葉相若，其實右葉明顯佔優。","source":"第十四章 14.1.1 肝葉","chId":"ch14"},{"id":"q1402","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟約 70% 的血液供應來自哪條血管？","options":["肝動脈","膽囊動脈","肝靜脈","肝門靜脈"],"answer":[3],"explain":"肝門靜脈由腸臟延伸到肝臟，提供約 70% 的血液，但含氧量很低；氧氣由肝動脈供應。肝靜脈是血液離開肝臟、排入下腔靜脈的通道；膽囊動脈只供應膽囊。陷阱是直覺認為「供應血液最多的一定是動脈」，其實肝臟以靜脈血為主。","source":"第十四章 14.2 肝門靜脈與肝動脈","chId":"ch14"},{"id":"q1403","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟的機能性顯微單位是？","options":["肝小葉","竇狀隙","庫氏細胞","肝細胞"],"answer":[0],"explain":"肝臟各葉由許多肝小葉組成，小葉是六角形的機能單位，肉眼也觀察得到。肝細胞是小葉內的建造材料；竇狀隙是小葉內的微血管；庫氏細胞是內襯竇狀隙的巨噬細胞。陷阱是把「最小的細胞」與「機能單位」混為一談，肝細胞雖是主體細胞，但不是單位。","source":"第十四章 14.1.2 結構","chId":"ch14"},{"id":"q1404","ch":14,"level":1,"type":"single","style":"concept","q":"膽囊的主要功能是？","options":["製造膽汁","儲存膽汁並吸收水分濃縮","分泌膽囊收縮素","把膽紅素變成膽汁鹽"],"answer":[1],"explain":"膽囊儲存膽汁、吸收水分把膽汁濃縮 10–15 倍，並在進食後釋放。膽汁由肝細胞製造，不是膽囊；膽囊收縮素由十二指腸分泌；膽紅素與膽汁鹽是兩種不同成份，膽汁鹽由膽固醇合成。陷阱是「膽囊」與「膽汁」名字相近，就把製造的功能錯配給膽囊。","source":"第十四章 14.2.2 膽囊的功能","chId":"ch14"},{"id":"q1405","ch":14,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於肝臟的功能？（選 2–3 項）","options":["對乙醇等藥物與微生物毒素進行解毒","分泌胰島素以降低血糖","合成血漿蛋白與大部份凝血因子","儲存肝醣與脂溶性維他命 A、D、E、K","分泌鹽酸以殺死胃內微生物"],"answer":[0,2,3],"explain":"肝臟儲存肝醣、脂溶性維他命、鐵、銅與 B12；負責解毒與荷爾蒙滅活；亦合成血漿蛋白與大部份凝血因子。胰島素由胰臟分泌，肝臟只是它的目標器官；鹽酸由胃黏膜分泌。這兩項都是「消化系統」的鄰近概念，容易誤植到肝臟身上。","source":"第十四章 14.2.1 肝臟的功能","chId":"ch14"},{"id":"q1406","ch":14,"level":2,"type":"single","style":"concept","q":"關於肝內血液與膽汁的流向，下列哪項正確？","options":["肝動脈→膽小管→中央靜脈；膽汁由中央靜脈出肝","中央靜脈→竇狀隙→肝門靜脈→下腔靜脈；膽小管→膽囊→肝靜脈","竇狀隙→中央靜脈→肝靜脈→下腔靜脈；膽小管→左右肝管","竇狀隙→膽小管→肝靜脈；膽汁經門靜脈出肝"],"answer":[2],"explain":"血液由竇狀隙流向中央靜脈，再匯成肝靜脈、排入下腔靜脈；膽汁則由肝細胞柱另一側的膽小管收集，匯成左右肝管出肝。其餘選項把兩條路徑混在一起，甚至讓膽汁經肝靜脈或門靜脈走。陷阱是忘記膽小管與竇狀隙位於肝細胞柱的兩側，方向剛好相反。","source":"第十四章 14.1.2 結構","chId":"ch14"},{"id":"q1407","ch":14,"level":2,"type":"multi","style":"concept","q":"關於膽汁與膽汁鹽，下列哪些正確？（選 2–3 項）","options":["大部分膽汁鹽在迴腸末端被再吸收，經門靜脈回肝","膽囊會製造膽固醇供膽汁使用","膽紅素是紅血球溶血的產物，是膽汁色素的主要成分","膽汁鹽在小腸內乳化脂肪，幫助消化","膽汁含大量蛋白水解酵素，直接分解蛋白質"],"answer":[0,2,3],"explain":"膽汁鹽在小腸乳化脂肪；大部分在迴腸末端再吸收，經門靜脈返回肝臟，形成腸肝循環；膽紅素是溶血產物，亦是膽汁色素的主要成分。膽固醇是膽汁成份、也是膽汁酸原料，但由肝細胞合成而非膽囊製造；膽汁不含蛋白水解酵素，蛋白質消化靠胃與胰的酵素。 陷阱是把膽汁當成含消化酵素的萬能消化液。","source":"第十四章 14.2.2 膽汁的成份與腸肝循環","chId":"ch14"},{"id":"q1408","ch":14,"level":2,"type":"single","style":"concept","q":"庫氏細胞（星狀細胞）位於何處，主要功能是什麼？","options":["肝小葉中央靜脈內皮，負責運送氧氣","膽小管壁上，負責分泌膽汁鹽","肝被膜上，負責固定肝臟位置","竇狀隙內，屬巨噬細胞，吞噬破舊血細胞與外來微粒"],"answer":[3],"explain":"庫氏細胞內襯竇狀隙，是肝內的巨噬細胞，吞噬並毀滅經過肝臟的破舊血細胞與外來微粒，亦參與分解紅血球。牠不在中央靜脈、膽小管或被膜上；分泌膽汁鹽的是肝細胞。陷阱是「星狀」聽起來像神經細胞，其實這裏指的是肝內的巨噬細胞。","source":"第十四章 14.1.2 竇狀隙與庫氏細胞","chId":"ch14"},{"id":"q1409","ch":14,"level":3,"type":"multi","style":"case","q":"一名肝硬化病人出現黃疸、下肢水腫與容易瘀青。下列解釋哪些正確？（選 2–3 項）","options":["肝臟停止製造膽汁鹽，脂肪吸收因此增加","肝合成白蛋白減少，血漿滲透壓下降而水腫","凝血因子合成減少，所以容易出血","庫氏細胞過度活躍令血紅蛋白上升","膽紅素無法在肝細胞內結合，積聚而出現黃疸"],"answer":[1,2,4],"explain":"這三個症狀正好對應肝臟三大功能：合成白蛋白（滲透壓）、處理膽紅素（黃疸）、合成凝血因子（出血）。膽汁鹽減少會令脂肪乳化與吸收變差，而不是增加；庫氏細胞活躍不會令血紅蛋白上升，反而參與破壞老舊紅血球。本題考跨章整合：血漿蛋白、膽紅素與凝血三條線都指向肝。 陷阱是只盯着黃疸，忽略水腫與出血同樣源自肝。","source":"第十四章 14.2.1 與 14.2.2 膽紅素","chId":"ch14"},{"id":"q1410","ch":14,"level":3,"type":"single","style":"case","q":"一名病人膽結石阻塞膽管，膽汁無法排入十二指腸。最可能出現的組合是？","options":["脂肪乳化受阻，同時膽紅素積聚引起黃疸","血糖立即下降，因為肝醣無法分解","蛋白質消化立即停頓，但膽紅素正常","尿量增加，因為 ADH 被抑制"],"answer":[0],"explain":"膽汁鹽負責在小腸乳化脂肪，膽管阻塞會令脂肪消化吸收變差；膽紅素無法隨膽汁排出，積聚血中便造成黃疸。蛋白質消化主要靠胃與胰的酵素，不是膽汁；血糖調節由肝醣與荷爾蒙控制，與膽管阻塞無直接關係；ADH 屬腎臟水分調節。陷阱是把膽汁當成萬能消化液。","source":"第十四章 14.2.2 膽汁成份與黃疸","chId":"ch14"},{"id":"q1411","ch":14,"level":3,"type":"single","style":"case","q":"病人切除膽囊後，進食含脂肪食物仍能消化。最合理的解釋是？","options":["膽汁鹽改由胰臟分泌以替代膽囊","肝細胞仍持續製造膽汁，經膽管流入十二指腸","脂肪改由胃的鹽酸乳化","膽囊切除後，肝臟會改為製造更多膽囊收縮素"],"answer":[1],"explain":"膽汁由肝細胞製造，膽囊只負責儲存與濃縮；切除膽囊後，肝臟仍持續分泌膽汁，經膽管流入十二指腸，只是沒有濃縮與大量儲備。膽囊收縮素由十二指腸分泌，不是肝；膽汁鹽由肝合成而非胰臟；鹽酸不能乳化脂肪。陷阱是以為「沒有膽囊就沒有膽汁」。","source":"第十四章 14.2.1 分泌膽汁與 14.2.2 膽囊","chId":"ch14"}]},{"id":"ch15","num":15,"title":"內分泌系統","en":"The Endocrine System","group":"內分泌","tagline":"荷爾蒙、腦下垂體、甲狀腺、腎上腺與血糖調節","intro":"內分泌系統以荷爾蒙作化學信差，經血流送到遠方目標細胞，作用較慢但精確。主線是三層軸線：下丘腦釋放荷爾蒙→腦下垂體前葉→目標腺體，再由目標荷爾蒙負回饋剎停。考試常考荷爾蒙配對、甲狀腺與鈣的調節、胰島素與高血糖素的拮抗，以及正／負回饋的辨認。","memoryHook":"下丘腦發令、前葉轉發、腺體執行；荷爾蒙一升高就回頭剎停——負回饋。","sections":[{"title":"內分泌系統總覽：無管腺與化學信差","points":["內分泌腺是無管腺（ductless gland），分泌細胞被豐富的微血管網包圍，荷爾蒙直接擴散入血，再運到目標組織和目標器官。","荷爾蒙只對有相應感受器的細胞起作用；肽荷爾蒙（如胰島素、腎上腺素）受體在細胞膜上，脂質荷爾蒙（如類固醇、甲狀腺素）受體在細胞內。","內分泌系統調節較慢、較精確而持久；自主神經系統則快而短，兩者共同維持體內平衡（homeostasis）。","荷爾蒙釋放通常受負回饋控制：目標荷爾蒙升高會抑制上游釋放，防止細胞被過度驅使。","少數情況是正回饋：反應擴大原刺激，直至過程完成，例如分娩時催產素引起的子宮收縮和血液凝固。","荷爾蒙可由下丘腦—腦下垂體軸間接控制（如甲狀腺素、皮質醇），或直接由血液中刺激物水平控制（如胰島素、高血糖素）。"],"table":{"headers":["比較","肽荷爾蒙","脂質（類固醇）荷爾蒙"],"rows":[["感受器位置","細胞膜上","細胞內"],["例子","胰島素、高血糖素、腎上腺素","糖皮質激素、鹽皮質激素、甲狀腺素"],["作用方式","較快，經訊息傳遞放大","較慢，調節基因表現和蛋白質合成"]]}},{"title":"下丘腦與腦下垂體前葉","points":["下丘腦屬腦部而非腺體，卻是內分泌的總指揮：製造釋放荷爾蒙和抑制荷爾蒙，經腦下垂體門系統送到前葉。","腦下垂體位於蝶鞍（sella turcica），如雞豆大小，分前葉（腺性垂體）與後葉（神經垂體）；前葉來自咽頭腺狀上皮，後葉是腦向下生長的部份。","前葉荷爾蒙有GH、TSH、ACTH、PRL、FSH、LH；每一種都受下丘腦相應的釋放荷爾蒙刺激，並多數受負回饋調節。","生長荷爾蒙（GH）刺激骨骼和骨骼肌生長、促進蛋白質合成和脂肪分解、升高血糖；夜間睡眠、低血糖、運動和焦慮時分泌增加，青春期達高峰。","TSH刺激甲狀腺生長及分泌T3、T4；ACTH刺激腎上腺皮質分泌皮質醇；PRL刺激乳汁製造；FSH和LH作用於卵巢和睪丸。","臨床上軸線失常多數源於下丘腦釋放荷爾蒙失調，而非腺體本身衰退，這是常見的推理陷阱。"],"table":{"headers":["下丘腦釋放荷爾蒙","前葉荷爾蒙","目標"],"rows":[["GHRH／GHRIH","GH","大部分組織（骨骼、肌肉）"],["TRH","TSH","甲狀腺"],["CRH","ACTH","腎上腺皮質"],["PRH／PIH（多巴胺）","PRL","乳房"],["GnRH（LHRH）","FSH、LH","卵巢、睪丸"]]}},{"title":"腦下垂體後葉：催產素與抗利尿素","points":["後葉只儲存和釋放兩種荷爾蒙：催產素（oxytocin）和抗利尿素（ADH，血管加壓素），兩者均由下丘腦製造，經神經纖維送到後葉。","催產素在分娩時刺激子宮平滑肌收縮，產後刺激乳房肌上皮細胞收縮以排出乳汁。","催產素的分泌是正回饋典型：子宮頸被拉展→衝動傳到下丘腦→更多催產素→更強收縮，直至嬰兒出生、拉展減少才停止。","ADH增加腎臟遠曲小管和收集管對水的通透性，促進水重吸收、減少尿量；分泌由下丘腦滲透壓感受器監測的血漿滲透壓調節。","脫水或出血時滲透壓上升→ADH增加→尿少而濃；大量飲水後滲透壓下降→ADH減少→尿多而稀。","ADH在高濃度（如嚴重失血）會收縮皮膚和腹部器官的血管，產生加壓效應，故又稱血管加壓素。"],"table":{"headers":["荷爾蒙","來源","主要作用","回饋"],"rows":[["催產素","下丘腦製造、後葉釋放","子宮收縮、排乳","正回饋"],["抗利尿素（ADH）","下丘腦製造、後葉釋放","水重吸收↑、尿量↓；高濃度收縮血管","負回饋（滲透壓）"]]}},{"title":"甲狀腺與副甲狀腺","points":["甲狀腺在喉頭和氣管前方，約第5至第7頸椎及第1胸椎水平，呈蝴蝶形，兩葉由峽連接，重約25g。","濾泡細胞分泌T3、T4，需要碘；甲狀腺球蛋白（thyroglobulin）是膠質主要成分，儲存荷爾蒙的前驅物。","T3、T4增加基礎代謝率和產熱，調節碳水化合物、蛋白質、脂肪代謝，是骨骼和神經系統正常生長發育所需。","TSH刺激甲狀腺生長和分泌；T3、T4升高時負回饋抑制TRH和TSH；碘不足則T3、T4低→TSH高→甲狀腺腫大。","濾泡旁細胞（C細胞）分泌降血鈣素（calcitonin），減少骨重吸收鈣並抑制腎小管重吸收鈣，使血鈣下降。","副甲狀腺素（PTH）作用相反：促進小腸和腎小管吸收鈣，必要時活化蝕骨細胞分解骨組織，使血鈣上升。"],"table":{"headers":["甲狀腺機能亢進","甲狀腺機能低下"],"rows":[["基礎代謝率上升、體重減輕但胃口好","代謝率下降、體重增加而無胃口"],["焦慮、坐立不安、心跳加快","抑鬱、精神遲鈍、心跳減慢"],["怕熱、溫暖汗濕的皮膚、腹瀉","怕冷、皮膚乾燥、便秘"]]}},{"title":"腎上腺、胰島與負回饋","points":["腎上腺位於腎臟頂部，分外部皮質與內部髓質；皮質以膽固醇製造糖皮質激素、鹽皮質激素和少量雄性激素。","皮質醇（cortisol）是主要糖皮質激素：促進糖質新生、脂肪分解和蛋白質分解，升高血糖，並有抗炎和免疫抑制作用；分泌高峰在早上4至8時。","醛固酮（aldosterone）是主要鹽皮質激素，促進腎小管重吸收鈉和水、排出鉀，維持水與電解質平衡。","腎上腺髓質由神經組織發育而來，受交感神經刺激分泌腎上腺素和正腎上腺素，加強「作戰或逃跑」；腎上腺素對心臟和代謝影響較大，正腎上腺素對血管影響較大。","胰島的α細胞分泌高血糖素、β細胞分泌胰島素、δ細胞分泌抑生長素；正常血糖約3.5至8 mmol/L。","胰島素降低血糖（促進葡萄糖入細胞、肝糖合成、脂肪和蛋白質合成）；高血糖素升高血糖（促進肝糖分解和糖質新生）；兩者由血糖水平直接負回饋控制。"],"table":{"headers":["胰島細胞","荷爾蒙","主要效應","刺激"],"rows":[["α細胞","高血糖素","肝糖分解、糖質新生→血糖↑","低血糖、運動"],["β細胞","胰島素","葡萄糖入細胞、肝糖合成→血糖↓","血糖↑、副交感"],["δ細胞","抑生長素","抑制GH、胰島素和高血糖素","課文未詳述"]]}}],"terms":[{"zh":"荷爾蒙","en":"Hormone","def":"內分泌腺分泌的化學信差，經血流運送到目標組織，調節細胞生長和代謝。"},{"zh":"負回饋","en":"Negative feedback","def":"效應器反應減低或抵銷原刺激，使荷爾蒙水平和內在環境維持在正常範圍。"},{"zh":"正回饋","en":"Positive feedback","def":"反應擴大原刺激，使荷爾蒙釋放愈來愈多，直至特定過程完成才停止，如分娩。"},{"zh":"腦下垂體前葉","en":"Anterior pituitary","def":"腺性垂體，受下丘腦釋放荷爾蒙經門系統刺激，分泌GH、TSH、ACTH、PRL、FSH、LH。"},{"zh":"腦下垂體後葉","en":"Posterior pituitary","def":"神經垂體，儲存並釋放下丘腦製造的催產素和抗利尿素。"},{"zh":"甲狀腺素","en":"Thyroxine (T4)","def":"甲狀腺濾泡細胞分泌的脂質荷爾蒙，需碘，增加基礎代謝率和產熱，受TSH調節。"},{"zh":"降血鈣素","en":"Calcitonin","def":"甲狀腺濾泡旁C細胞分泌，減少骨重吸收鈣並抑制腎小管重吸收鈣，使血鈣下降。"},{"zh":"副甲狀腺素","en":"Parathormone (PTH)","def":"副甲狀腺分泌，促進小腸和腎小管吸收鈣，必要時活化蝕骨細胞，使血鈣上升。"},{"zh":"皮質醇","en":"Cortisol","def":"腎上腺皮質主要的糖皮質激素，促進糖質新生、脂肪和蛋白質分解，升高血糖，抗炎及抑制免疫。"},{"zh":"醛固酮","en":"Aldosterone","def":"腎上腺皮質主要的鹽皮質激素，促進腎小管重吸收鈉和水、排出鉀，維持水與電解質平衡。"},{"zh":"胰島素","en":"Insulin","def":"胰島β細胞分泌的多胜肽荷爾蒙，促進葡萄糖入細胞和肝糖合成，降低血糖。"},{"zh":"高血糖素","en":"Glucagon","def":"胰島α細胞分泌，促進肝糖分解和糖質新生，升高血糖，與胰島素拮抗。"}],"examTips":["前葉與後葉要分清：後葉只釋放ADH和催產素，兩者其實由下丘腦製造；選項常把「後葉製造」當成正確。","甲狀腺素具脂溶性，受體在細胞內；胰島素（肽類）和腎上腺素（胺類）的受體在細胞膜上，不要憑「胺類」字眼中陷阱。","負回饋方向：目標荷爾蒙升高是抑制上游，不是刺激；TSH在T3、T4低時才升高。","正回饋只有少數例子：分娩子宮收縮、排乳、血液凝固；不要把月經週期或血糖調節誤判為正回饋。","鈣的兩個荷爾蒙方向要分明：降血鈣素（甲狀腺C細胞）降鈣，PTH（副甲狀腺）升鈣；令蝕骨細胞分解骨的是PTH。","腎上腺皮質與髓質要分開：皮質分泌類固醇（皮質醇、醛固酮），髓質分泌兒茶酚胺（腎上腺素、正腎上腺素）。"],"remedies":[],"atlas":[],"questions":[{"id":"q1501","ch":15,"level":1,"type":"single","style":"concept","q":"胰島中哪種細胞分泌胰島素（insulin）？","options":["δ細胞","濾泡旁細胞","β細胞","α細胞"],"answer":[2],"explain":"胰島β細胞分泌胰島素，作用是降低血糖；α細胞分泌高血糖素，作用相反；δ細胞分泌抑生長素，抑制GH、胰島素和高血糖素。濾泡旁細胞（C細胞）位於甲狀腺，分泌降血鈣素，與胰島完全無關，是把兩個腺體混在一起時的常見干擾項。記「β＝降血糖」便可與α細胞分開。","source":"第十五章 15.2 E 胰島","chId":"ch15"},{"id":"q1502","ch":15,"level":1,"type":"single","style":"concept","q":"下列哪個荷爾蒙由腦下垂體後葉釋放？","options":["促腎上腺皮質荷爾蒙（ACTH）","甲狀腺促素（TSH）","生長荷爾蒙（GH）","抗利尿素（ADH）"],"answer":[3],"explain":"後葉只釋放抗利尿素和催產素兩種荷爾蒙，而且兩者均由下丘腦製造，經神經纖維送到後葉儲存。TSH、ACTH和GH都是前葉荷爾蒙，分別作用於甲狀腺、腎上腺皮質和大部分組織。最常見的陷阱是把「後葉釋放」誤讀成「後葉製造」，或以為後葉也分泌TSH。","source":"第十五章 15.1 B 腦下垂體後葉","chId":"ch15"},{"id":"q1503","ch":15,"level":1,"type":"single","style":"concept","q":"降血鈣素（calcitonin）由下列哪種細胞分泌？","options":["甲狀腺濾泡旁細胞（C細胞）","副甲狀腺主細胞","甲狀腺濾泡細胞","腎上腺皮質細胞"],"answer":[0],"explain":"甲狀腺內的濾泡旁細胞（C細胞）分泌降血鈣素，作用於骨骼和腎臟以降低血鈣。濾泡細胞製造T3和T4，與鈣無關；副甲狀腺主細胞分泌PTH，作用方向剛好相反（升血鈣）；腎上腺皮質分泌類固醇。這題的陷阱是把「降血鈣素」誤配給副甲狀腺，實際上它來自甲狀腺。","source":"第十五章 15.2 A 甲狀腺（降血鈣素）","chId":"ch15"},{"id":"q1504","ch":15,"level":1,"type":"single","style":"concept","q":"哪個荷爾蒙主要增加腎臟遠曲小管和收集管對水的通透性，從而減少尿量？","options":["降血鈣素","抗利尿素","催產素","醛固酮"],"answer":[1],"explain":"抗利尿素（ADH）增加遠曲小管和收集管對水的通透性，促進水重吸收，使尿量減少、尿液濃縮，故稱「抗利尿」。醛固酮雖也促進鈉和水重吸收，但主要作用是保鈉排鉀，題目問「水的通透性」是ADH的專利；降血鈣素管鈣；催產素管子宮和乳房。把醛固酮與ADH混淆是常見失分位。","source":"第十五章 15.1 B 抗利尿素","chId":"ch15"},{"id":"q1505","ch":15,"level":2,"type":"single","style":"concept","q":"甲狀腺素（T3、T4）血中水平下降時，下列反應次序何者正確？","options":["TRH↓→TSH↓→T3/T4回升","T3/T4↑→TRH↑→TSH↑","TRH↑→TSH↑→T3/T4回升","TSH↑→TRH↑→T3/T4下降"],"answer":[2],"explain":"負回饋的方向是：T3、T4低→解除對下丘腦和腦下垂體的抑制→TRH增加→TSH增加→甲狀腺分泌增加→T3、T4回升。把整個方向倒轉（TRH↓、TSH↓）、把T3/T4高當成刺激TRH、或把TSH放在TRH之前，都是負回饋最常見的陷阱。","source":"第十五章 15.2 A 甲狀腺素及三碘甲狀腺原氨酸","chId":"ch15"},{"id":"q1506","ch":15,"level":2,"type":"multi","style":"concept","q":"下列哪些是腦下垂體前葉分泌、並以其他內分泌腺為目標的促內分泌腺激素？（選出2–3項）","options":["抗利尿素（ADH）","促腎上腺皮質荷爾蒙（ACTH）","生長荷爾蒙（GH）","黃體生成素（LH）","甲狀腺促素（TSH）"],"answer":[1,3,4],"explain":"TSH以甲狀腺為目標、ACTH以腎上腺皮質為目標、FSH和LH以性腺為目標，三者都屬促內分泌腺激素（trophic hormone）。GH雖然來自前葉，但作用於大部分組織（骨骼、肌肉、肝臟）而非另一個內分泌腺；ADH是後葉荷爾蒙，作用於腎臟。分辨關鍵是問「它的目標是不是另一個腺體」。","source":"第十五章 15.1 A 腦下垂體前葉；表15.2","chId":"ch15"},{"id":"q1507","ch":15,"level":2,"type":"single","style":"concept","q":"催產素在分娩時的分泌被形容為正回饋，下列哪項最能解釋？","options":["催產素由ADH的濃度直接控制","嬰兒出生後催產素才大量分泌","子宮收縮減弱子宮頸的拉展，使分泌減少","子宮頸被拉展→更多催產素→更強子宮收縮→更大拉展"],"answer":[3],"explain":"正回饋是反應擴大原刺激：子宮頸被拉展→衝動傳到下丘腦→後葉釋放更多催產素→子宮收縮更強→拉展更大，循環直至嬰兒出生、拉展大大減少才停止。把催產素說成由ADH直接控制、說出生後才大量分泌、或說子宮收縮會減少子宮頸拉展，都與正回饋方向相反。","source":"第十五章 15.1 B 催產素；圖15.9","chId":"ch15"},{"id":"q1508","ch":15,"level":2,"type":"single","style":"concept","q":"胰島素與高血糖素對肝糖的效應，下列何者正確？","options":["胰島素促進肝糖合成，高血糖素促進肝糖分解","胰島素促進肝糖分解，高血糖素促進合成","兩者都促進肝糖合成","兩者都促進肝糖分解"],"answer":[0],"explain":"胰島素降低血糖：促進葡萄糖進入肌肉和結締組織細胞、在肝臟和骨骼肌合成肝糖，並抑制肝糖分解。高血糖素升高血糖：促進肝糖分解為葡萄糖及糖質新生。兩者方向相反，是拮抗荷爾蒙的典型；把兩者對調，或說兩者都促進合成／分解，都忽略拮抗關係。","source":"第十五章 15.2 E 胰島素與高血糖素","chId":"ch15"},{"id":"q1509","ch":15,"level":3,"type":"single","style":"case","q":"一名長期服用高劑量潑尼松龍（prednisolone）的病人出現月亮臉、頸腹肥胖、高血糖和傷口癒合遲緩，最直接的解釋是？","options":["胰島素分泌過多","糖皮質激素作用過強","副甲狀腺素分泌過低","甲狀腺素分泌過多"],"answer":[1],"explain":"潑尼松龍屬糖皮質激素類藥物，長期高劑量造成醫源性庫欣氏症候群：糖質新生增加致高血糖、脂肪重新分佈成月亮臉和水牛背、蛋白質分解致皮膚變薄和傷口癒合遲緩。甲狀腺亢進會體重減輕、怕熱、心跳快，不會有月亮臉；胰島素過多造成低血糖；PTH過低造成低血鈣和抽搐，與此個案不符。","source":"第十五章 15.2 C 糖皮質激素（庫欣氏症候群）","chId":"ch15"},{"id":"q1510","ch":15,"level":3,"type":"single","style":"case","q":"行山大量出汗後沒有補充水分，尿量明顯減少且尿液濃縮。下列機制次序何者最合理？","options":["血漿滲透壓↑→醛固酮↓→鈉排出↑→尿少而濃","血漿滲透壓↑→ADH↓→水重吸收↑→尿少而濃","血漿滲透壓↑→下丘腦滲透壓感受器→ADH↑→水重吸收↑→尿少而濃","血漿滲透壓↓→ADH↑→水重吸收↓→尿少而濃"],"answer":[2],"explain":"脫水使血漿滲透壓上升，下丘腦滲透壓感受器偵測到，ADH分泌增加，遠曲小管和收集管對水通透性上升，水重吸收增加，尿量減少而濃。把ADH說成下降、把血漿滲透壓說成下降，或把ADH作用說成減少水重吸收，都是方向倒轉；醛固酮主要調節鈉鉀，不是這個情境的主線。","source":"第十五章 15.1 B 抗利尿素；圖15.10","chId":"ch15"},{"id":"q1511","ch":15,"level":3,"type":"multi","style":"concept","q":"關於血鈣的調節，下列哪些正確？（選出2–3項）","options":["降血鈣素減少從骨骼重吸收鈣","副甲狀腺素增加腎小管對鈣的重吸收","副甲狀腺素在需要時活化蝕骨細胞","血鈣上升會刺激副甲狀腺素分泌","降血鈣素由副甲狀腺分泌"],"answer":[0,1,2],"explain":"降血鈣素由甲狀腺C細胞分泌，抑制骨重吸收鈣和腎小管重吸收鈣，使血鈣下降；PTH由副甲狀腺分泌，促進小腸和腎小管吸收鈣，必要時活化蝕骨細胞，使血鈣上升。血鈣上升刺激的是降血鈣素而非PTH；把降血鈣素說成副甲狀腺分泌，是把來源對調。","source":"第十五章 15.2 A 降血鈣素；15.2 B 副甲狀腺","chId":"ch15"},{"id":"q1512","ch":15,"level":3,"type":"single","style":"case","q":"山區居民長期碘攝取不足，甲狀腺明顯腫大但沒有機能亢進徵象，最合理的解釋是？","options":["T3/T4偏高→TSH偏高→甲狀腺增生","降血鈣素過多刺激甲狀腺長大","TSH偏低→甲狀腺萎縮","T3/T4偏低→TSH偏高→甲狀腺細胞增生"],"answer":[3],"explain":"碘不足使T3、T4合成減少，負回饋減弱令TSH升高，TSH刺激甲狀腺生長和活動，腺體腫大，即單純甲狀腺腫；若額外組織能維持荷爾蒙水平，就沒有亢進或低下。T3、T4偏高會抑制而非刺激TSH；TSH偏低會令腺體萎縮；降血鈣素與甲狀腺大小無關。陷阱是把「腫大」直接當成機能亢進。","source":"第十五章 15.2 A 甲狀腺（單純甲狀腺腫）","chId":"ch15"}]},{"id":"ch16","num":16,"title":"腦部與神經系統","en":"The Brain and Nervous System","group":"神經感官","tagline":"腦區、腦膜與CSF、血腦屏障、脊髓與自主神經效應","intro":"腦與脊髓由三層腦膜、腦脊髓液和血腦屏障保護；大腦皮層、腦幹、基底核、丘腦、下丘腦各司其職，CSF分泌與吸收平衡，BBB只放行葡萄糖和脂溶性物質；脊髓31對神經負責上下行傳遞，自主神經調控內臟。考試愛考「受損構造→喪失功能」的推理。","memoryHook":"膜三層、液120、分泌720；腦幹三中樞，運動交叉在延髓。","sections":[{"title":"保護層：腦膜、腦室與腦脊髓液","points":["腦約佔體重2%，受顱骨和三層腦膜保護；由外至內是硬腦膜、蛛網膜、軟腦膜。","蛛網膜與軟腦膜之間的蛛網膜下空間含腦脊髓液（CSF），把腦和脊髓浸透其中，發揮緩衝和減震作用。","CSF由脈絡膜叢（choroid plexus）分泌到各腦室，經第四腦室小孔進入蛛網膜下空間，再由蛛網膜絨毛回到靜脈竇。","分泌約每分鐘0.5毫升（每天720毫升），但容積穩定維持約120毫升，說明吸收與分泌幾乎同速。","CSF壓力側臥時約10 cm H2O，坐起時約30 cm H2O；腦部腫脹時CSF量減少作代償，腦組織萎縮時CSF量增加。","CSF功能：支持保護、維持恆定壓力、緩衝減震、保持濕潤，並容許營養素與廢物交換。"],"table":{"headers":["腦膜／空間","特徵"],"rows":[["硬腦膜","最外層，堅韌；大腦鐮由它構成"],["蛛網膜","中間層；絨毛伸入靜脈竇回收CSF"],["軟腦膜","最內層，緊貼腦表面"],["蛛網膜下空間","含CSF，腰椎穿刺取液處"]]}},{"title":"大腦：皮層、腦葉與神經束","points":["大腦是腦部最大部份，由大腦縱裂分左右半球，深處以胼胝體（白質）連接。","表面灰質（神經細胞體）形成大腦皮層，滿佈腦回與腦溝，大大增加表面面積；深層為白質神經纖維。","每半球分四葉：額葉、頂葉、顳葉、枕葉，邊界是中央溝、外側溝和頂枕溝。","大腦皮層三大功能：精神活動（記憶、思考、推理、道德感）、感覺感知（視、聽、觸、味、嗅、痛、溫）、啟動和控制隨意骨骼肌。","三類神經束：聯絡束連接同側不同腦回；連合束連接兩半球對應區（最大為胼胝體）；突出束連接皮層與較低部位及脊髓。","內囊是重要的突出束，位於基底核與丘腦之間；其中運動纖維形成錐體束，在延髓交叉，故左半球控制右側身體。"],"table":{"headers":["神經束","連接","例子"],"rows":[["聯絡（弓形）束","同側半球不同腦回","皮層內長短聯絡纖維"],["連合束","兩半球對應區域","胼胝體"],["突出束","皮層↔腦下部、脊髓","內囊、錐體束"]]}},{"title":"腦幹、基底核、丘腦與下丘腦","points":["腦幹由上而下為中腦、橋腦、延髓，延髓下接脊髓；中腦圍繞大腦導水管，是上下行纖維的轉播站。","橋腦在延髓上方，含呼吸調節中樞和呼吸中樞，與延髓呼吸中樞協調呼吸；其灰質在深處、纖維在表面。","延髓長約2.5 cm，內有生命中樞：心血管中樞、呼吸中樞，以及嘔吐、咳嗽、打噴嚏、吞嚥的反射中樞。","延髓的錐體交叉使運動纖維左右交叉；感覺纖維有些在延髓交叉，有些在脊髓較低水平交叉。","基底核是半球深處的灰質，參與啟動和精細控制複雜動作；受損會使動作不平穩、笨拙、不協調。","丘腦是感覺訊息傳往皮層前的轉發站；下丘腦在丘腦下方，控制自主神經、體溫、食慾、口渴、情緒、性行為和晝夜節律，並經神經和血管控制腦下垂體。"],"table":{"headers":["構造","主要功能"],"rows":[["中腦","上下行纖維轉播；圍繞大腦導水管"],["橋腦","連接兩半球與脊髓；呼吸調節中樞"],["延髓","心血管、呼吸、嘔吐咳嗽等反射中樞；錐體交叉"],["基底核","啟動與精細協調複雜動作"],["丘腦","感覺訊息轉發站"],["下丘腦","自主神經、體溫、食慾、情緒、生物鐘；控制腦下垂體"]]}},{"title":"血腦屏障與脊髓","points":["腦只佔體重2%，卻在高負荷時得到約15%血液；氧氣中斷4至5分鐘或葡萄糖中斷10至15分鐘即可造成腦損害。","血腦屏障（BBB）由腦微血管內皮細胞以緊密連接「肩並肩」排列而成，沒有一般微血管的窗孔。","只有葡萄糖和脂溶性物質能輕易通過；其他物質須與膜蛋白攜帶分子結合，否則無論敵友都被拒絕。","臨床後果：多數化療藥不能入腦；脂溶性海洛英可通過而嗎啡不能；L-dopa靠攜帶蛋白進入。","脊髓成年男性約45 cm，由寰椎延伸到第一腰椎（L1），中心灰質、外圍白質；共31對脊髓神經。","脊髓是腦與身體的主要連結，上行感覺、下行運動，並可獨立完成脊髓反射；皮節是特定脊髓神經支配的皮膚區域，有助定位神經損傷。"],"table":{"headers":["比較","一般微血管","腦微血管（BBB）"],"rows":[["內皮連接","有窗孔、細胞間有小缺口","緊密連接，無窗孔"],["通透性","多數物質可通過","只放行葡萄糖、脂溶性物質"],["臨床意義","藥物較易到達組織","多數藥物難入腦，需鞘內給藥"]]}},{"title":"自主神經系統對器官的效應","points":["自主神經系統（ANS）掌管不隨意反應，維持體內平衡；資訊在器官與下丘腦之間轉送，反應在意識水平以下協調。","交感神經主要是刺激性系統，在恐懼、尷尬、憤怒、運動和寒冷時動員身體，即「作戰或逃跑」；副交感通常恢復平靜，即「休息與消化」。","心血管：交感加速竇房結、增強心跳、舒張冠狀動脈和骨骼肌血管、收縮皮膚和內臟血管以升血壓；副交感減慢心跳、收縮冠狀動脈，對其他血管影響很少。","呼吸與消化：交感擴張細支氣管、抑制胃腸蠕動和分泌、增加括約肌張力、促使肝臟分解肝糖；副交感收縮氣道、增加胃腸活動和分泌、促進肝糖合成和膽汁分泌。","泌尿與眼睛：交感放鬆膀胱壁、收緊尿道內括約肌（抑制排尿），使瞳孔放大、睫狀肌放鬆看遠；副交感收縮膀胱壁、放鬆內括約肌（排尿），使瞳孔縮小。","皮膚只有交感支配：增加汗液分泌、豎毛肌收縮（雞皮）、周邊血管收縮；腎上腺髓質受交感刺激分泌腎上腺素和正腎上腺素，加強並延長交感效應。"],"table":{"headers":["器官","交感","副交感"],"rows":[["心臟","心跳↑、收縮力↑、冠狀動脈舒張","心跳↓、冠狀動脈收縮"],["氣道","細支氣管擴張","細支氣管收縮"],["胃腸","蠕動和分泌↓、括約肌收緊","蠕動和分泌↑"],["肝臟","肝糖→葡萄糖","葡萄糖→肝糖、膽汁分泌↑"],["膀胱","膀胱壁放鬆、內括約肌收緊","膀胱壁收縮、內括約肌放鬆"],["瞳孔","輻射肌收縮、放大","環狀肌收縮、縮小"],["皮膚","汗液↑、豎毛、血管收縮","無副交感支配"]]}}],"terms":[{"zh":"腦膜","en":"Meninges","def":"覆蓋腦和脊髓的三層保護膜，由外至內為硬腦膜、蛛網膜、軟腦膜。"},{"zh":"腦脊髓液","en":"Cerebrospinal fluid (CSF)","def":"清澈弱鹼性液體，位於蛛網膜下空間，支持保護腦和脊髓、緩衝減震並容許物質交換。"},{"zh":"脈絡膜叢","en":"Choroid plexus","def":"由血管和室管膜細胞組成的區域，分泌CSF到各腦室。"},{"zh":"胼胝體","en":"Corpus callosum","def":"連接左右大腦半球的大型連合神經束，由白質構成。"},{"zh":"內囊","en":"Internal capsule","def":"位於基底核與丘腦之間的重要突出束，含錐體束，許多往返皮層的衝動經此傳遞。"},{"zh":"基底核","en":"Basal ganglia","def":"大腦半球深處的灰質團塊，參與啟動和精細控制複雜動作；受損使動作笨拙不協調。"},{"zh":"丘腦","en":"Thalamus","def":"位於第三腦室兩側的灰質，把皮膚、內臟和特殊感官的訊息轉發到大腦皮層。"},{"zh":"下丘腦","en":"Hypothalamus","def":"丘腦下方、腦下垂體上方的腦區，控制自主神經、體溫、食慾、情緒、生物鐘及腦下垂體。"},{"zh":"血腦屏障","en":"Blood-brain barrier (BBB)","def":"腦微血管內皮以緊密連接形成的屏障，只讓葡萄糖和脂溶性物質輕易通過。"},{"zh":"皮節","en":"Dermatome","def":"受特定某一對脊髓神經支配的皮膚區域，可用來定位神經受損範圍。"},{"zh":"交感神經","en":"Sympathetic nervous system","def":"自主神經的一支，動員身體應付壓力，即「作戰或逃跑」，使心跳加快、瞳孔放大、氣道擴張。"},{"zh":"副交感神經","en":"Parasympathetic nervous system","def":"自主神經的一支，促進休息、消化和排尿，使心跳減慢、瞳孔縮小、胃腸活動增加。"}],"examTips":["三層腦膜由外到內是硬、蛛、軟；CSF在蛛網膜下空間，不在硬腦膜外空間（硬膜外是脂肪和結締組織的軟墊）。","CSF數字要成組記：0.5 ml/min＝720 ml/day，容積120 ml；分泌等於吸收所以容積穩定，不是「不再分泌」。","延髓的兩個交叉最易混淆：錐體交叉是運動纖維，感覺交叉部分在延髓、部分在脊髓。","丘腦是「轉發站」，下丘腦是「控制中心」；問體溫、食慾、生物鐘一定選下丘腦。","BBB不是完全密封：葡萄糖和脂溶性物質可通過，L-dopa靠載體；把「所有物質都不能通過」當正確就中陷阱。","腰椎穿刺選L3/L4或L4/L5，因為脊髓已在L1終止，可避開脊髓；不是因為該處CSF特別多。"],"remedies":[{"name":"Mercurius（水銀）","note":"課文16.5指出水銀是對神經系統有親和力的金屬療劑之一；以非順勢療法層級使用時有毒。只記親和力，不記劑量。"},{"name":"Plumbum（鉛）","note":"課文16.5把鉛列為對神經系統有親和力的金屬療劑，並提醒它是環境污染物，可在神經系統累積。不寫劑量。"},{"name":"Aluminium（鋁）","note":"課文16.5把鋁與水銀、鉛、錫並列為神經系統親和力療劑；金屬在非順勢療法層級有毒，故只列親和力。"}],"atlas":[16],"questions":[{"id":"q1601","ch":16,"level":1,"type":"single","style":"concept","q":"腦脊髓液主要存在於哪個空間？","options":["蛛網膜下空間","硬腦膜外空間","中央溝","大腦縱裂"],"answer":[0],"explain":"腦脊髓液位於蛛網膜與軟腦膜之間的蛛網膜下空間，把腦和脊髓浸透其中。硬腦膜外空間是脊椎骨骨膜與硬腦膜之間的一層脂肪和結締組織，屬軟墊層，也是硬膜外給藥的位置，不是CSF所在。大腦縱裂是分開兩半球的裂隙；中央溝是分隔額葉和頂葉的腦溝。把硬腦膜外空間當成CSF所在是最常見的混淆。","source":"第十六章 16.1 腦膜與腦脊髓液","chId":"ch16"},{"id":"q1602","ch":16,"level":1,"type":"single","style":"concept","q":"腦脊髓液主要由下列哪個構造分泌？","options":["軟腦膜","脈絡膜叢","蛛網膜絨毛","胼胝體"],"answer":[1],"explain":"脈絡膜叢由血管和室管膜細胞組成，分泌CSF到各腦室；蛛網膜絨毛（蛛網顆粒）則是回收站，把CSF送回靜脈竇，兩者一分泌一吸收，方向相反，是典型對調陷阱。軟腦膜只是最內層的保護膜；胼胝體是連接兩半球的白質。記「脈絡叢製造、蛛網絨毛回收」便可分開。","source":"第十六章 16.1 腦脊髓液（脈絡膜叢）","chId":"ch16"},{"id":"q1603","ch":16,"level":1,"type":"single","style":"concept","q":"感覺訊息傳往大腦皮層前，主要在哪個構造被轉發？","options":["下丘腦","小腦","丘腦","基底核"],"answer":[2],"explain":"來自皮膚、內臟和特殊感官的訊息先傳到丘腦，再分送到大腦皮層，所以丘腦是「轉發站」。基底核負責動作的啟動和精細協調；下丘腦管體溫、食慾、口渴和生物鐘；小腦管平衡和動作協調。把丘腦與下丘腦混淆是最常見的失分位；兩者位置相近但功能完全不同。","source":"第十六章 16.2.3 丘腦","chId":"ch16"},{"id":"q1604","ch":16,"level":1,"type":"single","style":"concept","q":"延髓內哪個中樞負責控制心跳速率、收縮力和血壓？","options":["體溫調節中樞","嘔吐反射中樞","呼吸中樞","心血管中樞"],"answer":[3],"explain":"心血管中樞位於延髓，內含血管舒縮中樞，控制心跳速率和收縮力，並透過血管直徑調節血壓。呼吸中樞只管呼吸速率和深度；嘔吐中樞是延髓反射中樞之一，負責把刺激物排出；體溫調節中樞在下丘腦，不在延髓。這四個中樞常被放在一起考位置配對。","source":"第十六章 16.2.2 延髓（心血管中樞）","chId":"ch16"},{"id":"q1605","ch":16,"level":2,"type":"single","style":"concept","q":"CSF每天分泌約720毫升，但顱內CSF容積穩定維持約120毫升，最合理的結論是？","options":["分泌與吸收幾乎以同速進行","蛛網膜絨毛完全沒有吸收功能","分泌量遠少於吸收量","CSF在成人已停止流動"],"answer":[0],"explain":"每天分泌720毫升而容積只有120毫升，表示同一時間有等量CSF被吸收，分泌與吸收幾乎同速，容積才穩定；不是停止分泌，也不是吸收遠多於分泌（否則容積會持續減少）。這條數字題常把「720」和「120」硬記而不理解關係；只要問「為何容積不變」，答案就是吸收追上分泌。","source":"第十六章 16.1 腦脊髓液（分泌與吸收）","chId":"ch16"},{"id":"q1606","ch":16,"level":2,"type":"single","style":"concept","q":"延髓錐體交叉的結果，下列何者正確？","options":["左大腦半球控制身體左側","左大腦半球控制身體右側","小腦控制身體同側的隨意動作","感覺纖維全部在脊髓交叉"],"answer":[1],"explain":"錐體（皮質脊髓）束的運動纖維在延髓左右交叉，故左半球支配右側骨骼肌、右半球支配左側，中風後對側無力就是這條路徑。感覺纖維有些在延髓交叉、有些在脊髓較低水平，所以「全部在脊髓交叉」是錯的。小腦確與協調有關，但隨意動作的指令源自大腦皮層，不能說小腦控制同側隨意動作。","source":"第十六章 16.2.2 延髓（錐體交叉）","chId":"ch16"},{"id":"q1607","ch":16,"level":2,"type":"multi","style":"concept","q":"基底核受損時，最可能出現哪些表現？（選出2–3項）","options":["皮膚感覺喪失","協調動作變差","動作不平穩、笨拙","精細動作控制變差","瞳孔放大"],"answer":[1,2,3],"explain":"基底核參與啟動和精細控制複雜動作，並與大腦皮層和丘腦連接，受損會使動作不平穩、笨拙、不協調，學習協調活動也受影響。瞳孔由虹膜肌肉和自主神經控制，與基底核無關；皮膚感覺走丘腦和感覺皮層路徑，也不經基底核。分辨關鍵是問「這是動作協調還是感覺或瞳孔」；後兩者屬其他系統。","source":"第十六章 16.2.3 基底核","chId":"ch16"},{"id":"q1608","ch":16,"level":2,"type":"single","style":"concept","q":"腰椎穿刺通常選在第3、4腰椎或第4、5腰椎之間，主要理由為何？","options":["該處血腦屏障最薄弱","該處腦脊髓液量最多","脊髓已在第一腰椎終止，可避免刺傷脊髓","該處沒有硬腦膜覆蓋"],"answer":[2],"explain":"成人脊髓約終止於第一腰椎（L1），L3/L4或L4/L5已在脊髓末端以下，只有馬尾神經根浮在CSF中，刺針較安全；課文也指出第2腰椎以下進入脊髓區域才「安全」。CSF在整個蛛網膜下空間循環，不是該處特別多；硬腦膜仍然覆蓋；BBB位於腦微血管，與穿刺位置無關。","source":"第十六章 16.4 脊髓神經的結構（腰椎穿刺）","chId":"ch16"},{"id":"q1609","ch":16,"level":3,"type":"single","style":"case","q":"細菌性腦膜炎病人需要把抗生素直接送入蛛網膜下空間，而非只靠靜脈注射，主要原因為何？","options":["CSF內完全沒有白血球","腦膜沒有血液供應","抗生素口服後完全不被吸收","多數藥物難以通過血腦屏障，腦內濃度不足"],"answer":[3],"explain":"BBB的內皮細胞以緊密連接排列，只放行葡萄糖和脂溶性物質，多數抗生素難以由血液入腦，所以療效緩慢，需經腰椎穿刺直接注入CSF。口服不被吸收太絕對，且因藥物而異；CSF正常只有少數白血球，但腦膜炎時會有炎症細胞；腦膜血管豐富，並非沒有血液供應。陷阱是把「BBB屏障」誤解成「腦膜無血管」。","source":"第十六章 16.3 血腦屏障","chId":"ch16"},{"id":"q1610","ch":16,"level":3,"type":"multi","style":"case","q":"交感神經興奮時，下列哪些效應正確？（選出2–3項）","options":["皮膚小動脈收縮","胃腸蠕動增加","細支氣管擴張","心跳減慢","瞳孔放大"],"answer":[0,2,4],"explain":"交感使虹膜輻射肌收縮而瞳孔放大、細支氣管平滑肌放鬆而擴張、皮膚小動脈收縮以提升周邊阻力；同時心跳加快而非減慢，胃腸蠕動和分泌被抑制而非增加。後兩項是副交感的效應，把它們混入交感是本章最常見的對調陷阱。記憶時把同一器官的交感與副交感效應成對背，比單背「交感興奮」可靠。","source":"第十六章 16.4.1 自主神經刺激的效應","chId":"ch16"},{"id":"q1611","ch":16,"level":3,"type":"single","style":"case","q":"右側內囊（含錐體束）出血，最可能出現哪種運動障礙？","options":["左側上下肢無力","只有皮膚感覺喪失而沒有無力","右側上下肢無力","雙眼失明"],"answer":[0],"explain":"內囊的運動纖維形成錐體束，下行至延髓交叉後才到對側脊髓前角，所以右側內囊病灶造成左側肢體無力（對側偏癱）。同側無力是忽略交叉的典型錯誤；視覺障礙屬枕葉或視覺路徑受損；純感覺喪失是感覺束（如丘腦）受損的表現，與錐體束不同。把「右側病灶」直接配「右側無力」就會中計。","source":"第十六章 16.2.1 大腦內部（內囊與錐體束）","chId":"ch16"},{"id":"q1612","ch":16,"level":3,"type":"single","style":"case","q":"頭部外傷後腦組織腫脹、顱內壓上升。此時CSF的角色，下列何者最合理？","options":["血腦屏障會打開讓多餘液體排出","CSF量減少以作代償，緩衝壓力上升","脈絡膜叢立即停止所有分泌","CSF分泌增加以填補空間"],"answer":[1],"explain":"課文指出腦部因出血或腫瘤擴大時，會透過降低CSF量產生代償；相反，腦組織萎縮時CSF容積增加。所以腫脹時CSF減少而非增加。BBB不會因腫脹而打開排液；脈絡膜叢仍持續分泌（約每分鐘0.5毫升），只是吸收與調節改變，「立即停止所有分泌」太絕對。這題考代償方向，不是考數字。","source":"第十六章 16.1 腦脊髓液（代償）","chId":"ch16"}]},{"id":"ch17","num":17,"title":"男性生殖系統","en":"Male Reproductive System","group":"生殖","tagline":"睪丸、管道、附屬腺體與精子生成","intro":"男性生殖系統的主線是「製造、運送、加料」：睪丸製造精子，副睪讓精子成熟，輸精管負責運送，儲精囊與前列腺加入分泌物組成精液。荷爾蒙由 LHRH 啟動，FSH 管精子、LH 管睾酮；考試最常考管道次序、精液成分比例，以及陰囊溫度與生育力的關係。","memoryHook":"睪丸做、副睪熟、輸精管送、儲精囊加養分、前列腺加凝結酶。","sections":[{"title":"青春期：LHRH → FSH／LH → 睪丸","points":["男性約 10–15 歲進入青春期：下丘腦釋放 LHRH，刺激腦下垂體前葉分泌 FSH 與 LH。","FSH 作用於睪丸，刺激精子製造；LH 則刺激睪丸分泌睾酮。記法：「F 管精、L 管酮」。","睾酮令身高體重增加、喉部變大而聲音低沉，並在面部、腋下、胸口、腹部及恥骨長出毛髮。","睾酮亦令陰莖、陰囊和前列腺增大，使睪丸內輸精管成熟，隨後開始生產精子。","青春期皮脂、汗液和費洛蒙分泌增加，頭髮變得油膩；費洛蒙是分泌到體外、可被同種個體察覺的化學訊息。"]},{"title":"睪丸、副睪與精索","points":["陰囊是外掛於體壁的皮囊，分兩個隔間，支撐睪丸、副睪及一小段精索；左側睪丸通常懸得比右側低。","睪丸懸於體壁外，周圍溫度比體溫低約 3℃，是維持理想生育力所必需；緊身內褲因此被認為可能削弱生育力。","睪丸平均約 4.5 × 3 cm，由三層組織構成；小葉內有 1–4 個曲細精管，周圍有青春期後分泌睾酮的細胞。","曲細精管在睪丸頂部匯集成約 6 m 長、反覆摺疊的副睪；精子在副睪內成熟並暫時儲存。","精子頭部含細胞核及穿透卵子外層的酵素；體部充滿粒線體提供能量；尾部決定活動力，任何部分受損都可致不孕。","精索內有睾丸動脈、睾丸靜脈叢、淋巴管、輸精管及神經，整體經腹股溝道——此處是腹股溝疝氣的常見位置。"]},{"title":"管道與附屬腺體：精液怎樣組成","points":["輸精管向上經腹部、越過膀胱頂部再向下，最後在陰莖頂端穿出尿道，途中接受儲精囊及前列腺分泌物。","兩個儲精囊的管道匯合形成射精管，再穿過前列腺；射精時約 60% 精液來自儲精囊，含營養素供精子使用。","前列腺分泌稀薄乳狀液，最重要的是凝結酵素，令精液在子宮頸附近變稠、停留較久。","尿道球腺分泌物使精液呈鹼性，中和陰道酸性；正常精液 2–5 ml、每 ml 約 50–150 × 10⁶ 精子、pH 7.20–7.60。","精液含精液纖維蛋白分解酵素（seminal plasmin），能殺滅多種細菌；亦含免疫抑制成分。","不孕因素：容積低、活動力低、數目 < 20 × 10⁶/ml、液化需 > 2 小時、形態異常、pH 上升及缺乏果糖。"],"table":{"headers":["構造","主要功能／分泌物"],"rows":[["睪丸","曲細精管製造精子；青春期後分泌睾酮"],["副睪","約 6 m 長，精子在此成熟及暫時儲存"],["輸精管","運送精子，經精索進入盆腔"],["儲精囊","加入約 60% 精液，含營養素"],["前列腺","乳狀液及凝結酵素，令精液變稠"],["尿道球腺","鹼性分泌物，中和陰道酸性"],["陰莖","勃起組織充血，完成性交"]]}},{"title":"陰莖與勃起","points":["陰莖分根部（位於會陰）和體部（包圍尿道）；放鬆時 5–10 cm，勃起可達 15 cm 或以上。","三層勃起組織：兩層陰莖海綿體及一層尿道海綿體，尿道由尿道海綿體中間通過。","陰莖尖端擴大為陰莖頭，其上的皮膚形成可動的雙層包皮。","勃起靠海綿狀組織充血：微動脈擴張令血液進入，微靜脈收縮防止血液流走，兩者同時發生才維持勃起。","威而鋼抑制磷酸二酯酶（PDE），作用與勃起機制相同但會影響其他血管，過度使用可致低血壓。"]}],"terms":[{"zh":"睪丸","en":"Testis","def":"男性生殖腺，位於陰囊內；曲細精管製造精子，周圍細胞分泌睾酮。"},{"zh":"副睪","en":"Epididymis","def":"約 6 m 長、高度摺疊的管道，精子在此成熟並暫時儲存。"},{"zh":"曲細精管","en":"Seminiferous tubules","def":"睪丸小葉內 1–4 個迴旋管道，是精子生成的位置。"},{"zh":"輸精管","en":"Vas deferens","def":"由副睪延伸出來的管道，經精索把精子運送至射精管。"},{"zh":"儲精囊","en":"Seminal vesicle","def":"成對腺體，射精時加入約 60% 精液，富含營養素。"},{"zh":"前列腺","en":"Prostate gland","def":"分泌乳狀液及凝結酵素，令精液變稠並保護精子。"},{"zh":"射精管","en":"Ejaculatory duct","def":"由儲精囊管道與輸精管匯合而成，穿過前列腺。"},{"zh":"尿道球腺","en":"Bulbourethral gland","def":"成對小腺體，分泌物使精液呈鹼性，中和陰道酸性。"},{"zh":"精索","en":"Spermatic cord","def":"含睾丸動脈、靜脈叢、淋巴管、輸精管及神經，經腹股溝道。"},{"zh":"睾酮","en":"Testosterone","def":"由睪丸分泌的男性荷爾蒙，促進第二性徵及精子生成。"},{"zh":"精子","en":"Spermatozoon","def":"分頭、體、尾；頭含 DNA 及穿透卵子的酵素，尾部決定活動力。"},{"zh":"精液","en":"Semen","def":"精子與附屬腺體分泌物的混合物，正常 2–5 ml、呈弱鹼性。"}],"examTips":["FSH 刺激精子製造、LH 刺激睾酮分泌；LHRH 作用於腦下垂體而非睪丸，別把三者倒轉。","精子在睪丸製造、在副睪成熟；副睪不是製造精子的地方，這是常見失分位。","精液 60% 來自儲精囊、前列腺提供凝結酵素；兩者角色不可對調。","必記數字：陰囊低於體溫 3℃、副睪約 6 m、精液 2–5 ml、pH 7.20–7.60、不孕標準 < 20 × 10⁶/ml。","勃起是微動脈擴張＋微靜脈收縮；只寫「動脈擴張」不完整。","前列腺肥大會壓迫穿過它的尿道，造成排尿問題；前列腺癌亦是同一器官的重要疾病。"],"remedies":[],"atlas":[],"questions":[{"id":"q1701","ch":17,"level":1,"type":"single","style":"concept","q":"男性生殖系統中，負責製造精子的器官是哪一個？","options":["前列腺","副睪","睪丸","儲精囊"],"answer":[2],"explain":"睪丸的曲細精管是精子生成的位置，青春期後受 FSH 刺激而製造精子，亦分泌睾酮。副睪只負責精子成熟及暫時儲存；前列腺與儲精囊屬附屬腺體，加入精液分泌物，並不製造精子。","source":"第十七章 17.2 男性生殖系統各個部份","chId":"ch17"},{"id":"q1702","ch":17,"level":1,"type":"single","style":"concept","q":"精子離開睪丸後，主要在哪裡成熟並暫時儲存？","options":["儲精囊","射精管","輸精管","副睪"],"answer":[3],"explain":"曲細精管匯集成副睪，精子在副睪內成熟並暫存。輸精管是運送管道；儲精囊加入營養分泌物；射精管是儲精囊管道與輸精管匯合後的短管，都是「運送或加料」而非成熟場所，不能選。","source":"第十七章 17.2 睪丸與副睪","chId":"ch17"},{"id":"q1703","ch":17,"level":1,"type":"single","style":"concept","q":"射精時，約六成精液由哪個構造加入？","options":["儲精囊","前列腺","尿道球腺","副睪"],"answer":[0],"explain":"課文指儲精囊加入約 60% 精液，並提供精子沿途所需的營養素。前列腺雖重要，但主要提供乳狀液及凝結酵素，佔量較少；尿道球腺只加鹼性分泌物；副睪是精子成熟處，不分泌精液。","source":"第十七章 17.2 儲精囊與前列腺","chId":"ch17"},{"id":"q1704","ch":17,"level":1,"type":"single","style":"concept","q":"哪種荷爾蒙直接刺激睪丸分泌睾酮？","options":["FSH","LH","睾酮","LHRH"],"answer":[1],"explain":"LH 刺激睪丸分泌睾酮；FSH 則刺激精子製造。LHRH 由下丘腦釋放，作用於腦下垂體前葉，不是直接作用於睪丸。睾酮是 LH 作用後的產物，並非刺激者；把「產物」當成「刺激荷爾蒙」是典型陷阱。","source":"第十七章 17.1 青春發育期","chId":"ch17"},{"id":"q1705","ch":17,"level":2,"type":"single","style":"concept","q":"精子由生成至排出，下列次序何者正確？","options":["副睪 → 曲細精管 → 輸精管 → 尿道 → 射精管","副睪 → 輸精管 → 曲細精管 → 射精管 → 尿道","曲細精管 → 副睪 → 輸精管 → 射精管 → 尿道","曲細精管 → 輸精管 → 副睪 → 射精管 → 尿道"],"answer":[2],"explain":"精子在曲細精管生成，進入副睪成熟及暫存，再由輸精管經精索運送；儲精囊管道與輸精管匯合成射精管，穿過前列腺後經尿道排出。其他選項都把副睪與曲細精管的先後倒轉，或把射精管放到尿道之後。","source":"第十七章 17.2 男性生殖系統各個部份","chId":"ch17"},{"id":"q1706","ch":17,"level":2,"type":"multi","style":"concept","q":"精索（spermatic cord）內包含下列哪些結構？","options":["睾丸靜脈叢","輸精管","睾丸動脈","射精管","前列腺"],"answer":[0,1,2],"explain":"課文列精索內有 1 條睾丸動脈、1 個睾丸靜脈叢、淋巴管、1 條輸精管及神經。射精管由儲精囊管道與輸精管匯合而成，位置在盆腔內；前列腺則位於膀胱下方，兩者都不在精索之內。","source":"第十七章 17.2 精索","chId":"ch17"},{"id":"q1707","ch":17,"level":2,"type":"single","style":"concept","q":"前列腺分泌物中，對生育最關鍵的成分是什麼？","options":["果糖","乳酸","精液纖維蛋白分解酵素","凝結酵素"],"answer":[3],"explain":"前列腺液最重要的是凝結酵素，使精液在接近子宮頸處變稠、停留較久，讓精子有時間調整方向。果糖與營養素主要來自儲精囊；乳酸與陰道酸性有關；精液纖維蛋白分解酵素是精液中的抗菌成分，課文未歸為前列腺分泌物。","source":"第十七章 17.2 前列腺","chId":"ch17"},{"id":"q1708","ch":17,"level":2,"type":"single","style":"concept","q":"睪丸懸掛在體壁外，對生育最主要的好處是什麼？","options":["維持比體溫低約 3℃ 的溫度","避免精子被尿液沖走","令精索可以縮短","增加睪丸的血液供應"],"answer":[0],"explain":"課文明言陰囊位置令睪丸周圍溫度低於體溫約 3℃，這是維持理想生育力所必需，也是緊身內褲可能削弱生育力的理由。其餘選項在課文都沒有支持，屬於把「陰囊位置」與排尿、血流或精索長度混為一談。","source":"第十七章 17.2 陰囊與睪丸","chId":"ch17"},{"id":"q1709","ch":17,"level":3,"type":"multi","style":"case","q":"32 歲男子精液分析：量 1.2 ml、精子 12 × 10⁶/ml、液化需 3 小時、形態正常。根據課文，哪些項目屬不孕因素？","options":["精子數目 12 × 10⁶/ml","精液量 1.2 ml（低容積）","液化需 3 小時","精液含果糖","精子形態正常"],"answer":[0,1,2],"explain":"課文列不孕因素包括低容積、低活動力、數目 < 20 × 10⁶/ml、液化需 2 小時以上、形態異常、pH 上升及缺乏果糖。此個案三項都符合；含果糖與形態正常反而是正常表現，「缺乏果糖」才是不孕因素。","source":"第十七章 17.2 不孕的問題","chId":"ch17"},{"id":"q1710","ch":17,"level":3,"type":"single","style":"case","q":"30 歲男子接受兩側輸精管結紮。術後最可能出現哪種情況？","options":["副睪不再儲存精子，睪丸因而萎縮","精液仍含儲精囊與前列腺分泌物，但不含精子","前列腺停止分泌，精液量變為零","睪丸立即停止製造精子"],"answer":[1],"explain":"結紮只阻斷輸精管運送，睪丸仍受 FSH 與 LH 刺激製造精子及睾酮；儲精囊、前列腺和尿道球腺仍加入分泌物，所以精液量大致不變，只是沒有精子。睪丸不會立即停產，前列腺也不會停止分泌。","source":"第十七章 17.2 輸精管與附屬腺體","chId":"ch17"},{"id":"q1711","ch":17,"level":3,"type":"single","style":"case","q":"68 歲男子排尿困難、夜尿增多，直腸指診發現前列腺增大。最合理的解釋是？","options":["前列腺分泌過多凝結酵素阻塞射精管","增大的睪丸由下方壓迫膀胱","增大的前列腺壓迫穿過它的尿道","前列腺壓迫輸尿管造成腎積水"],"answer":[2],"explain":"課文指前列腺肥大會阻塞通過它的管道，包括來自膀胱的尿道，因此造成排尿問題。輸尿管在更上方接駁膀胱，並非穿過前列腺；凝結酵素作用於精液性狀，不會阻塞射精管；睪丸位於陰囊，不會由下方壓迫膀胱。","source":"第十七章 17.2 前列腺","chId":"ch17"},{"id":"q1712","ch":17,"level":3,"type":"single","style":"case","q":"58 歲有心臟病的男子自行服用威而鋼後頭暈、血壓偏低。最符合課文的解釋是？","options":["藥物令微靜脈擴張，血液滯留於陰莖","藥物直接抑制心臟收縮力","藥物刺激交感神經使心跳減慢","藥物抑制 PDE，令血管過度擴張致低血壓"],"answer":[3],"explain":"課文指威而鋼抑制磷酸二酯酶（PDE），作用如勃起機制但會影響其他血管，血管過度擴張造成低血壓，心臟病患者可因血壓過低而有危險。勃起是微動脈擴張加上微靜脈收縮；只說微靜脈擴張的選項，方向相反。","source":"第十七章 17.2 陰莖與威而鋼附註","chId":"ch17"}]},{"id":"ch18","num":18,"title":"女性生殖系統","en":"Female Reproductive System","group":"生殖","tagline":"卵巢、子宮、月經週期與受精著床","intro":"女性生殖系統圍繞「每月預備一次懷孕」運作：FSH 養卵、雌激素增厚子宮內膜、LH 觸發排卵、黃體酮穩定內膜。考試主線是四期月經週期的時序與兩種回饋——雌激素正回饋觸發 LH、黃體酮負回饋抑制 FSH；以及受精在輸卵管、著床在子宮內膜。","memoryHook":"FSH 養卵、雌激素鋪床、LH 排卵、黃體酮安床；無懷孕就拆床。","sections":[{"title":"青春期與荷爾蒙起點","points":["女性約 11–13 歲開始青春期；月經週期開始前體重達約 45 kg 被認為重要。","下丘腦刺激腦下垂體前葉分泌 FSH 與 LH，與男性青春期的啟動荷爾蒙相同。","青春期變化包括乳房發育、陰毛及腋毛生長、身高增加、骨盆變寬、脂肪囤積於臀及乳房。","子宮、輸卵管和卵巢成熟；初經（menarche）標誌月經週期與排卵開始。","男性精子差不多按需求製造；女性卵子出生前已存在，儲存於兩個卵巢內可達 50 年。"]},{"title":"外生殖器（外陰）與會陰","points":["外陰由大陰唇、小陰唇、陰蒂、處女膜及前庭腺（巴氏腺）等構成。","大陰唇是兩個大摺疊，含皮膚、纖維組織、脂肪及大量皮脂腺；青春期起長出陰毛。","小陰唇之間為前庭，陰道、尿道及前庭腺的大導管均開口於此。","陰蒂相當於男性陰莖，含感覺神經末梢及勃起組織，但沒有生殖意義。","處女膜是黏膜薄層，部分封閉陰道口，通常不完全封閉以便經血通過。","前庭腺位於陰道口兩側、約小豌豆大，分泌黏液以保持外陰濕潤。"]},{"title":"陰道與子宮：三層結構","points":["陰道是纖維肌肉管，內襯複層鱗狀上皮，以約 45° 向上向後，位於膀胱與直腸之間。","成年陰道前壁約 7.5 cm、後壁約 9 cm，差距源於子宮頸穿入前壁的角度。","陰道三層：外層網狀組織、中層平滑肌、內層複層鱗狀上皮形成皺摺；沒有分泌腺。","青春期至更年期，嗜酸性乳酸菌分泌乳酸，維持陰道 pH 3.5–4.9，抑制其他微生物。","子宮為中空梨形，約 7.5 × 5 cm、壁厚 2.5 cm、重 30–40 g；分子宮底、子宮體、子宮頸。","子宮壁三層：子宮外膜（腹膜）、子宮肌層（最厚，平滑肌）、子宮內膜（柱狀上皮及腺體）。"],"table":{"headers":["層","構造","功能／週期變化"],"rows":[["子宮外膜","腹膜，覆蓋子宮多個表面","前後形成膀胱子宮陷凹及直腸子宮陷凹"],["子宮肌層","子宮壁最厚的平滑肌層","分娩時強力而有節奏地收縮，推出嬰兒"],["子宮內膜","柱狀上皮及大量管狀腺體","機能層增厚後剝落；基底層保留並再生"]]}},{"title":"輸卵管與卵巢","points":["輸卵管約 10 cm，從子宮體與子宮底之間伸出，位於闊韌帶上方游離緣。","末端指狀凸出為繖部，最長的是卵巢繖，與卵巢距離很近。","輸卵管三層：外層腹膜、中層平滑肌、內層纖毛上皮；靠蠕動與纖毛把卵子送向子宮。","受精通常發生在輸卵管，受精卵再被推入子宮內膜著床，兩者地點不同。","卵巢約 2.5–3.5 × 2 × 1 cm，分髓質（中央，纖維組織、血管、神經）與皮質（各階段卵泡）。","每約 28 天一個囊狀卵泡成熟、破裂排卵；排卵後卵泡內層細胞在 LH 影響下形成黃體。未受精時黃體退化為白體，受精後胚胎分泌 hCG 維持黃體。"]},{"title":"月經週期四期與荷爾蒙回饋","points":["週期約 28 天（課文亦提 26–30 天），分激增期、排卵期、分泌期、月經期。","激增期約 10 天：FSH 刺激多個卵泡，第 6 天起一個優勢卵泡分泌雌激素，修復子宮內膜至第 14 天。","排卵期：第 12–13 天雌激素達閾值，觸發 LH 大量釋放，約第 14 天排卵；卵子活力僅 24–36 小時。","分泌期約 14 天：黃體分泌黃體酮，令內膜血管及營養增加；高黃體酮負回饋抑制 FSH。","月經期約 4 天：未受精則黃體退化、黃體酮驟降，內膜血管破裂脫落，出血為新週期第 1 天。","懷孕時胚胎分泌 hCG 維持黃體；胎盤在懷孕約 40 週期間分泌高水平黃體酮，防止子宮收縮。"],"table":{"headers":["時期","大約時間","主要事件","主導荷爾蒙"],"rows":[["激增期","約 10 天（第 2 天起）","FSH 刺激卵泡，雌激素修復並增厚子宮內膜","FSH、雌激素"],["排卵期","約第 14 天","雌激素達閾值觸發 LH 湧現，卵泡破裂釋出卵子","LH、雌激素"],["分泌期","約 14 天","黃體分泌黃體酮，內膜血管及分泌物增加，準備著床","黃體酮、雌激素"],["月經期","約 4 天","黃體退化、黃體酮驟降，內膜脫落出血","黃體酮下降"]]}}],"terms":[{"zh":"卵巢","en":"Ovary","def":"女性生殖腺，皮質含各階段卵泡，每約 28 天排卵一次。"},{"zh":"輸卵管","en":"Fallopian tube","def":"約 10 cm，靠蠕動及纖毛運送卵子，通常是受精地點。"},{"zh":"子宮","en":"Uterus","def":"中空梨形肌肉器官，供受精卵著床及胎兒發育。"},{"zh":"子宮內膜","en":"Endometrium","def":"柱狀上皮及腺體層，機能層隨週期增厚、剝落。"},{"zh":"子宮肌層","en":"Myometrium","def":"子宮壁最厚的平滑肌層，分娩時收縮推出嬰兒。"},{"zh":"子宮頸","en":"Cervix","def":"子宮下端，穿過陰道前壁，以外口開口於陰道。"},{"zh":"陰道","en":"Vagina","def":"纖維肌肉管，性交及分娩通道，靠乳酸菌維持酸性。"},{"zh":"外陰","en":"Vulva","def":"女性外生殖器總稱，包括大、小陰唇、陰蒂、處女膜及前庭腺。"},{"zh":"前庭腺","en":"Vestibular gland","def":"陰道口兩側的小腺體，分泌黏液保持外陰濕潤。"},{"zh":"黃體","en":"Corpus luteum","def":"排卵後卵泡內層細胞形成，分泌黃體酮及雌激素。"},{"zh":"排卵","en":"Ovulation","def":"成熟卵泡破裂釋出卵子，約在週期第 14 天。"},{"zh":"月經週期","en":"Menstrual cycle","def":"約 28 天的荷爾蒙週期，分激增、排卵、分泌、月經四期。"}],"examTips":["四期長度：激增期約 10 天、排卵期在第 14 天左右、分泌期約 14 天、月經期約 4 天；卵子只活 24–36 小時。","雌激素在排卵前是正回饋（觸發 LH）；黃體酮在分泌期是負回饋（抑制 FSH），方向不要倒轉。","受精在輸卵管、著床在子宮內膜；「受精在子宮」是常見錯誤。","月經只脫落機能層，基底層保留並再生；記住「基底不走」。","陰道沒有分泌腺，濕潤靠子宮頸分泌物；酸性靠乳酸菌，pH 3.5–4.9。","黃體未受精→白體；受精→hCG 維持黃體，三個月後由胎盤接手。"],"remedies":[{"name":"Lachesis（響尾蛇毒）","note":"課文列為女性生殖系統三大比較療劑之一，要求掌握它與 SEPIA、PULSATILLA 在女性生殖系統作用的異同。"},{"name":"Sepia（墨魚）","note":"課文列為三大比較療劑之一；與月經失調、不孕、纖維瘤、卵巢囊腫及更年期等女性個案的溫和治療相關。"},{"name":"Pulsatilla（白頭翁）","note":"課文列為三大比較療劑之一；由初經延遲到更年期的女性個案都可能用到，本章只提示親和力，不涉劑量。"}],"atlas":[],"questions":[{"id":"q1801","ch":18,"level":1,"type":"single","style":"concept","q":"卵子受精通常發生在哪個位置？","options":["輸卵管","卵巢","子宮頸","子宮腔"],"answer":[0],"explain":"課文明言受精通常發生在輸卵管，受精卵再被推入子宮著床。卵巢是排卵處，子宮是著床及發育處，子宮頸是產道的一部分；把「受精」與「著床」都放在子宮，是最常見的混淆；記住「受精在管、著床在宮」。","source":"第十八章 18.2 輸卵管的功能","chId":"ch18"},{"id":"q1802","ch":18,"level":1,"type":"single","style":"concept","q":"子宮壁三層中，最厚的是哪一層？","options":["子宮內膜","子宮肌層","子宮外膜","基底層"],"answer":[1],"explain":"子宮肌層是子宮壁最厚的一層，由平滑肌與網狀組織、血管、神經交錯而成，分娩時強力收縮推出嬰兒。子宮外膜是腹膜，子宮內膜是柱狀上皮及腺體層；基底層只是內膜的一小部分，不是獨立全層。","source":"第十八章 18.2 子宮的結構","chId":"ch18"},{"id":"q1803","ch":18,"level":1,"type":"single","style":"concept","q":"月經期間，子宮內膜哪一層會剝落？","options":["基底層","子宮肌層","機能層","子宮外膜"],"answer":[2],"explain":"機能層是內膜較上層，週期前半段增厚、血管豐富；卵子未受精及植入時，機能層在月經期間剝落。基底層貼近子宮肌層，月經期間不會流失，並在每次週期再生新的機能層；肌層與外膜不受月經影響。","source":"第十八章 18.2 子宮內膜","chId":"ch18"},{"id":"q1804","ch":18,"level":1,"type":"single","style":"concept","q":"排卵前大量湧現、直接觸發卵泡破裂的荷爾蒙是？","options":["FSH","黃體酮","雌激素","LH"],"answer":[3],"explain":"排卵前數小時 LH 大量湧現，促使卵泡破裂並釋放卵子。FSH 負責刺激卵泡發育；雌激素在排卵前達到閾值，是觸發 LH 的訊號而非直接令卵泡破裂；黃體酮在排卵後由黃體分泌，主要穩定內膜。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"},{"id":"q1805","ch":18,"level":2,"type":"multi","style":"concept","q":"根據課文，月經週期各時期的配對，下列哪些正確？（選 2–3 項）","options":["排卵期持續約 14 天","激增期由週期第 14 天才開始","分泌期約 14 天","月經期約 4 天","激增期約 10 天"],"answer":[2,3,4],"explain":"課文列激增期約 10 天、分泌期約 14 天、月經期約 4 天。排卵期只是卵子在數小時內被釋放，並非持續 14 天；激增期由週期第 2 天開始，第 14 天完成子宮內膜修復，所以「第 14 天才開始」是把完成日誤當起始日。","source":"第十八章 18.3 月經週期","chId":"ch18"},{"id":"q1806","ch":18,"level":2,"type":"single","style":"concept","q":"陰道保持酸性環境，主要依靠什麼？","options":["嗜酸性乳酸菌分泌乳酸","子宮頸分泌鹽酸","陰道壁的分泌腺直接分泌乳酸","前庭腺分泌黏液"],"answer":[0],"explain":"青春期至更年期，陰道內正常的嗜酸性乳酸菌分泌乳酸，維持 pH 3.5–4.9，抑制其他微生物。陰道本身沒有分泌腺，濕潤靠子宮頸分泌物；前庭腺只保持外陰濕潤；子宮頸不會分泌鹽酸。","source":"第十八章 18.2 陰道的結構","chId":"ch18"},{"id":"q1807","ch":18,"level":2,"type":"single","style":"concept","q":"陰道口兩側、分泌黏液以保持外陰濕潤的腺體是？","options":["大陰唇的皮脂腺","前庭腺（巴氏腺）","陰道壁的分泌腺","子宮頸腺體"],"answer":[1],"explain":"前庭腺位於陰道口兩邊、約小豌豆大，導管開口於前庭，分泌黏液保持外陰濕潤。大陰唇皮脂腺屬皮膚附屬器，作用是潤滑皮膚；子宮頸分泌物才是陰道濕潤的主要來源；陰道本身沒有分泌腺，所以不是由陰道壁分泌乳酸。","source":"第十八章 18.2 前庭腺","chId":"ch18"},{"id":"q1808","ch":18,"level":2,"type":"single","style":"concept","q":"排卵後，卵泡內層細胞在何種荷爾蒙影響下形成黃體？","options":["催產素","hCG","LH","FSH"],"answer":[2],"explain":"課文明言排卵後在 LH 影響下，卵泡內層細胞發展成黃體，分泌黃體酮及少量雌激素。FSH 刺激卵泡成熟；hCG 在懷孕後才由胚胎分泌以維持黃體；催產素作用於子宮肌，與黃體形成無關。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"},{"id":"q1809","ch":18,"level":3,"type":"single","style":"case","q":"28 歲女性週期規律，今個月沒有懷孕，週期末黃體酮水平驟降。最直接的原因是？","options":["雌激素正回饋","FSH 分泌增加","子宮肌層收縮","黃體退化"],"answer":[3],"explain":"未受精就沒有 hCG 維持黃體，黃體退化令黃體酮驟降，子宮內膜失去支持而脫落。FSH 增加是黃體酮抑制解除後的結果，不是黃體酮下降的原因；雌激素正回饋發生在排卵前，子宮肌層收縮與月經來潮不是啟動因素。","source":"第十八章 18.2 卵巢的功能；18.3 分泌期","chId":"ch18"},{"id":"q1810","ch":18,"level":3,"type":"multi","style":"case","q":"24 歲女性開始服用組合式口服避孕丸（含雌激素及黃體酮）。其主要作用機制包括哪三項？","options":["促進黃體形成以穩定內膜","負回饋抑制 FSH 與 LH，抑制排卵","直接殺死已排出的卵子","使子宮內膜變薄，不利著床","使子宮頸黏液變厚，阻擋精子"],"answer":[1,3,4],"explain":"課文列組合式避孕丸透過負回饋令大腦以為荷爾蒙足夠，抑制 FSH 與 LH 而停止排卵；同時令子宮頸黏液變厚、子宮內膜變薄。它不殺死卵子，也不會促進黃體形成；「抑制排卵」與「殺卵」是兩種不同機制。","source":"第十八章 18.3 口服避孕丸附註","chId":"ch18"},{"id":"q1811","ch":18,"level":3,"type":"single","style":"case","q":"29 歲女性雙側輸卵管因盆腔炎阻塞，但排卵及月經週期正常。最可能的不孕原因是？","options":["精子與卵子無法在輸卵管相遇受精","子宮內膜不能增厚","卵巢不能排卵","黃體不能分泌黃體酮"],"answer":[0],"explain":"受精通常發生在輸卵管，卵子由繖部拾取後在管內與精子相遇；雙側阻塞使精卵無法會合。個案已說明排卵及週期正常，所以卵巢、內膜及黃體功能都不是主因；這是「管道阻塞」而非「荷爾蒙失效」。","source":"第十八章 18.2 輸卵管的功能","chId":"ch18"},{"id":"q1812","ch":18,"level":3,"type":"single","style":"case","q":"懷孕 6 週，超聲波見子宮內胚胎。此時維持黃體繼續分泌黃體酮的主要訊號是？","options":["子宮內膜分泌的雌激素","胚胎分泌的 hCG","腦下垂體前葉的 FSH","胎盤分泌的 hCG"],"answer":[1],"explain":"受精卵著床後，發育中的胚胎分泌 hCG，刺激黃體在懷孕頭 3 個月繼續分泌黃體酮及雌激素；之後才由胎盤接手。懷孕 6 週時胎盤尚未接管，FSH 與內膜雌激素都不是維持黃體的主要訊號。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"}]},{"id":"ch19","num":19,"title":"特殊感官","en":"The Special Senses","group":"神經感官","tagline":"耳、眼、鼻與味覺","intro":"特殊感官把外界刺激轉成神經衝動：耳蝸毛細胞負責聽覺，半規管與前庭負責平衡；視網膜視桿、視錐細胞感光，經視神經、視交叉、視束傳到枕葉；鼻與舌則靠溶解於黏液或唾液的化學物質刺激感受器。考試重點是傳導路徑、眼球三層與房水循環。","memoryHook":"錘砧鐙推卵形窗，耳蝸毛細胞發聲；鼻側交叉、顳側直行。","sections":[{"title":"外耳與中耳：收集與放大聲音","points":["外耳由耳廓與外耳道構成；耳廓為纖維彈性軟骨，最突出外脊是耳輪，耳垂含纖維與脂肪。","外耳道略呈 S 形、約 2.5 cm，外側 1/3 為軟骨；耵聹腺分泌耳垢，與毛髮、彎曲共同阻擋異物。","鼓膜分隔外耳道與中耳，由三層構成：外層無毛皮膚、中層纖維組織、內層黏膜延續至中耳。","中耳是顳骨內含氣空腔，內壁有卵形窗（被鐙骨足板堵塞）與圓形窗（薄纖維封閉）。","耳咽管約 4 cm，連接鼻咽與中耳，維持鼓膜兩邊氣壓相等；吞嚥或打呵欠可打開。","聽小骨由外至內為錘骨、砧骨、鐙骨，三者互相形成關節，在卵形窗放大聲音。"],"table":{"headers":["部分","主要構造","功能"],"rows":[["外耳","耳廓、外耳道（約 2.5 cm）、鼓膜","收集聲波、保護鼓膜"],["中耳","鼓室、聽小骨、耳咽管","傳遞並放大震動、平衡氣壓"],["內耳","前庭、耳蝸、3 條半規管","聽覺（耳蝸）與平衡（前庭、半規管）"]]}},{"title":"內耳：耳蝸、聽覺傳導與平衡","points":["內耳又稱迷路，分骨質與膜質迷路；骨質迷路由前庭、耳蝸及 3 條半規管構成。前庭內有橢圓囊與球囊，膜質迷路含內淋巴，與骨質迷路之間為外淋巴。","耳蝸橫切有三個隔間：前庭階、中階（耳蝸管）、鼓階；前庭階起於卵形窗，鼓階止於圓形窗。","基底膜上有支持細胞及耳蝸毛細胞，組成螺旋器（柯蒂氏器），是震動的感覺器官。","傳導：聲波→鼓膜→聽小骨→卵形窗→外淋巴→基底膜→毛細胞→第 8 腦神經→延髓聽覺核→顳葉。","音高由頻率（Hz）決定，不同頻率刺激基底膜不同位置；音量由強度（dB）決定，過強會損害毛細胞。","半規管探測頭部位置，與聽覺無關；衝動經前庭神經核到小腦，與視覺及本體感受協調。"]},{"title":"眼：三層結構與屈光媒體","points":["鞏膜是眼球後及側面最外層，維持形狀並供眼外肌附著；前方延續為透明角膜。","脈絡膜內襯鞏膜後方 5/6，血管豐富、深棕色，吸收穿過視網膜的光線。","視網膜是最內層，含視桿與視錐細胞；黃斑中央的中央凹只有視錐細胞，視盤則沒有光敏細胞。","睫狀體由睫狀肌及分泌性上皮構成，經懸韌帶連接晶狀體並分泌房水；晶狀體是雙凸、有彈性的透明體，也是眼內唯一可改變折射力的結構。","虹膜由色素細胞及環形、放射狀平滑肌構成，中央為瞳孔；副交感令瞳孔收縮，交感令擴大。","房水由睫狀體分泌入後房，經瞳孔到前房，再經鞏膜靜脈竇回流；玻璃體在晶狀體後方支撐視網膜。"],"table":{"headers":["層","主要構造","功能"],"rows":[["外層","鞏膜、角膜","維持眼球形狀；角膜折射光線"],["中層","脈絡膜、睫狀體、虹膜","供血、吸收光線、分泌房水、調節瞳孔"],["內層","視網膜（視桿、視錐細胞）","感光並產生神經衝動"]]}},{"title":"視覺生理與視路","points":["清晰視覺靠光線折射、瞳孔大小及晶狀體調節三個過程協調；光線依次穿過結膜、角膜、房水、晶狀體、玻璃體到達視網膜，只有晶狀體可改變折射力。","看 6 m 以內物件需調節：瞳孔收縮、眼球會聚、晶狀體變厚；看 6 m 以上則毋須調節。","視桿細胞對弱光敏感，含視紫質，強光下褪色，靠維他命 A 恢復；視錐細胞對亮光及顏色敏感。","視神經在黃斑鼻側約 0.5 cm 處形成，經視神經交叉：鼻側纖維交叉，顳側纖維不交叉。","視束由同側顳纖維與對側鼻纖維組成，向後到外側膝狀體，再經視輻射到枕葉視覺區。","青光眼是房水經許氏管回流缺損致眼內壓升高，壓迫視神經軸突及血供；慢性開角型先失周邊視野。"]},{"title":"鼻與味覺","points":["有氣味物質以揮發性分子隨空氣進入鼻腔，溶於黏液後刺激嗅覺化學感受器。","鼻腔頂部形成旋渦，增加受刺激感受器數目；鼻黏膜發炎可阻止氣味分子到達嗅覺區，造成嗅覺喪失（anosmia），常見於感冒。","連續接觸同一氣味會產生適應，幾分鐘內對該氣味感覺減弱，只影響該氣味。","味蕾分布於舌乳突、軟腭、咽及會厭上皮，由第 7、9、10 腦神經的感覺末梢構成。","甜、鹹在舌尖，酸在舌兩側，苦在舌後；訊號經延髓、丘腦到頂葉味覺區。","口乾時味覺受損，因為物質必須溶解才能被品嚐；味覺亦觸發唾液及胃液分泌。"]}],"terms":[{"zh":"耳廓","en":"Auricle","def":"耳部外突的纖維彈性軟骨，收集並導引聲波入外耳道。"},{"zh":"鼓膜","en":"Tympanic membrane","def":"分隔外耳道與中耳的三層薄膜，接收聲波震動。"},{"zh":"聽小骨","en":"Ossicles","def":"錘骨、砧骨、鐙骨，把鼓膜震動傳到卵形窗並放大。"},{"zh":"耳咽管","en":"Eustachian tube","def":"約 4 cm，連接鼻咽與中耳，維持鼓膜兩側氣壓相等。"},{"zh":"耳蝸","en":"Cochlea","def":"內耳螺旋形構造，內有基底膜及螺旋器，負責聽覺。"},{"zh":"螺旋器","en":"Organ of Corti","def":"基底膜上的聽覺感受器，含毛細胞，受震動後產生神經衝動。"},{"zh":"半規管","en":"Semicircular canals","def":"三條互相垂直的管道，探測頭部位置，與平衡有關。"},{"zh":"鞏膜","en":"Sclera","def":"眼球外層的纖維膜，維持形狀並供眼外肌附著。"},{"zh":"角膜","en":"Cornea","def":"眼球前方透明的上皮膜，折射光線並聚焦於視網膜。"},{"zh":"視網膜","en":"Retina","def":"眼球最內層，含視桿及視錐細胞，將光轉為神經衝動。"},{"zh":"視神經交叉","en":"Optic chiasma","def":"兩眼視神經相會處，鼻側纖維交叉、顳側纖維不交叉。"},{"zh":"房水","en":"Aqueous humour","def":"睫狀體分泌的清澈液體，供應眼前段營養並維持眼內壓。"}],"examTips":["聽小骨次序：錘骨→砧骨→鐙骨；鐙骨足板踏在卵形窗，圓形窗只由纖維封閉。","耳蝸三階：前庭階起於卵形窗、鼓階止於圓形窗，中階即耳蝸管，螺旋器在基底膜上。","視交叉只交叉鼻側纖維；視束由同側顳纖維＋對側鼻纖維組成。","房水由睫狀體分泌、經許氏管回流；眼內壓 10–20 mmHg，持續升高會壓迫視神經。","看近物：睫狀肌收縮→懸韌帶放鬆→晶狀體變厚；看遠物相反，別把因果倒轉。","味覺腦神經 7、9、10；甜鹹舌尖、酸兩側、苦舌後；視紫質只在視桿細胞。"],"remedies":[{"name":"Chamomilla（洋甘菊）","note":"課文指它是育嬰房不可或缺的療劑，用於嬰兒被出牙痛楚煎熬時；親和力在口腔與出牙不適。"},{"name":"Hekla lava（赫克拉熔岩）","note":"課文用於神經痛，以及與頜骨和牙齦相關的骨痛；親和力在頜骨與牙齦。"},{"name":"Spongia（海綿）","note":"課文療劑彙集例子：耳部發疹、水皰蔓延至對耳屏時用 Spongia；親和力在耳部。"}],"atlas":[],"questions":[{"id":"q1901","ch":19,"level":1,"type":"single","style":"concept","q":"聲波由鼓膜傳到內耳，下列次序何者正確？","options":["鼓膜 → 砧骨 → 錘骨 → 鐙骨 → 圓形窗","鼓膜 → 鐙骨 → 砧骨 → 錘骨 → 卵形窗","鼓膜 → 錘骨 → 砧骨 → 鐙骨 → 卵形窗","鼓膜 → 錘骨 → 鐙骨 → 砧骨 → 圓形窗"],"answer":[2],"explain":"聽小骨由外至內為錘骨、砧骨、鐙骨；鐙骨足板固定於卵形窗，把震動送入前庭階的外淋巴。圓形窗只由薄纖維封閉，是液體波最終耗盡之處，並非聽小骨接駁點；其餘選項把骨序或窗的位置調亂。","source":"第十九章 19.1 聽覺小骨","chId":"ch19"},{"id":"q1902","ch":19,"level":1,"type":"single","style":"concept","q":"聽覺的感受器位於何處？","options":["鼓膜","耳咽管","半規管的壺腹","耳蝸基底膜上的螺旋器"],"answer":[3],"explain":"耳蝸基底膜上有支持細胞及耳蝸毛細胞，組成螺旋器（柯蒂氏器），受震動後產生神經衝動。半規管壺腹的毛細胞屬平衡感受器；鼓膜只負責接收及傳遞震動；耳咽管的作用是平衡中耳與外界的氣壓。","source":"第十九章 19.1 耳蝸","chId":"ch19"},{"id":"q1903","ch":19,"level":1,"type":"single","style":"concept","q":"眼球中層哪個構造富含血管、呈深棕色並吸收光線？","options":["脈絡膜","視網膜","角膜","鞏膜"],"answer":[0],"explain":"脈絡膜內襯鞏膜後方 5/6，血管非常豐富、呈深巧克力棕色，吸收穿過視網膜的光線。鞏膜是外層纖維膜，角膜透明以折射光線，視網膜是內層感光構造；三者都屬眼球壁，但位置與功能不同。","source":"第十九章 19.4 眼睛結構","chId":"ch19"},{"id":"q1904","ch":19,"level":1,"type":"single","style":"concept","q":"哪個構造負責探測頭部在空間中的位置，與聽覺無關？","options":["鼓膜","半規管","耳咽管","耳蝸"],"answer":[1],"explain":"課文明言半規管沒有聽覺功能，只提供頭部在空間中位置的信息，致力維持姿勢和平衡。耳蝸是聽覺器官；鼓膜與耳咽管屬中耳的傳音及氣壓平衡構造，都不負責頭部位置感，所以不選。","source":"第十九章 19.3 半規管以及前庭","chId":"ch19"},{"id":"q1905","ch":19,"level":2,"type":"single","style":"concept","q":"房水（水狀液）最終經哪個構造回流靜脈循環？","options":["中央凹","玻璃體","鞏膜靜脈竇（許氏管）","視盤"],"answer":[2],"explain":"房水由睫狀體分泌入後房，經瞳孔到前房，再經虹膜與角膜之間角落的鞏膜靜脈竇（許氏管）回流。視盤是視神經離開眼球處，即盲點；中央凹在黃斑中央；玻璃體是晶狀體後方的啫喱狀物，三者都不引流房水。","source":"第十九章 19.4 眼睛內部","chId":"ch19"},{"id":"q1906","ch":19,"level":2,"type":"single","style":"concept","q":"關於近視與遠視的矯正，哪一項正確？","options":["近視用雙凸透鏡，遠視用雙凹透鏡","兩者都用平面鏡","兩者都用雙凸透鏡","近視用雙凹透鏡，遠視用雙凸透鏡"],"answer":[3],"explain":"課文以圖 19.34 展示遠視與近視的矯正透鏡，並指眼內折射異常可用雙凸或雙凹透鏡矯正。記法：近視用凹透鏡分散光線，遠視用凸透鏡增加會聚。最常見陷阱是把兩種透鏡對調，或以為平面鏡可矯正屈光。","source":"第十九章 19.5 光線的折射","chId":"ch19"},{"id":"q1907","ch":19,"level":2,"type":"multi","style":"concept","q":"關於視網膜，下列哪些正確？（選 2–3 項）","options":["視桿細胞對弱光較敏感","視網膜周邊以視錐細胞為主","視紫質存在於視錐細胞","視盤沒有光敏細胞，是盲點","中央凹只由視錐細胞構成"],"answer":[0,3,4],"explain":"課文指視桿細胞比視錐細胞敏感得多、中央凹只有視錐細胞、視盤是視神經離開處且沒有光敏細胞。視紫質只出現在視桿細胞；視網膜周邊有大量視桿細胞，視錐細胞反而較少，所以最後兩項都錯。","source":"第十九章 19.4 視網膜；19.5 視網膜的功能","chId":"ch19"},{"id":"q1908","ch":19,"level":2,"type":"multi","style":"concept","q":"關於嗅覺與味覺，下列哪些正確？（選 2–3 項）","options":["嗅覺感受器位於舌乳突","氣味分子需溶於黏液才能刺激嗅覺感受器","苦味主要在舌尖感受","連續接觸同一氣味會產生適應，數分鐘內感覺減弱","味蕾由第 7、9、10 腦神經的感覺末梢構成"],"answer":[1,3,4],"explain":"揮發性分子溶於鼻腔黏液後刺激嗅覺感受器；味蕾由舌咽、顏面及迷走神經（7、9、10）的末梢構成；嗅覺適應只影響該氣味。苦味在舌後，甜鹹才在舌尖；舌乳突是味蕾所在，不是嗅覺感受器。","source":"第十九章 19.6 嗅覺生理學與味覺","chId":"ch19"},{"id":"q1909","ch":19,"level":3,"type":"single","style":"case","q":"55 歲男子兩眼周邊視野逐漸收窄，眼壓 28 mmHg，視盤萎縮。最可能的情況是？","options":["慢性開角型青光眼","黃斑退化","白內障","急性閉角型青光眼"],"answer":[0],"explain":"房水經許氏管回流缺損令眼內壓升高，壓迫視神經軸突及血供；慢性開角型眼壓漸升、周邊視野先失，可發展成管狀視力甚至不可逆失明。急性閉角型會突發劇痛、畏光、流淚；白內障與黃斑退化不是眼壓問題。","source":"第十九章 19.4 青光眼附註","chId":"ch19"},{"id":"q1910","ch":19,"level":3,"type":"single","style":"case","q":"腦下垂體腫瘤向上壓迫視神經交叉，最直接受影響的是哪類纖維？","options":["兩眼視網膜顳側纖維","兩眼視網膜鼻側的交叉纖維","只影響左眼視神經","視輻射"],"answer":[1],"explain":"視交叉內來自每眼視網膜鼻側的纖維交叉到對側，顳側纖維不交叉而繼續同側向後走。腫瘤位於腦下垂體上方，正好壓迫交叉處，故兩眼鼻側纖維首當其衝；視輻射在交叉更後方，不會最先受壓。","source":"第十九章 19.4 視神經交叉","chId":"ch19"},{"id":"q1911","ch":19,"level":3,"type":"single","style":"case","q":"在噪音工廠工作 20 年的工人出現不可逆聽力下降，最可能受損的構造是？","options":["鼓膜","半規管","耳蝸螺旋器的毛細胞","聽小骨"],"answer":[2],"explain":"課文指巨大聲響長期發生會損害螺旋器中敏感的毛細胞，造成不可修補的耳聾，常見於嘈雜環境工作或樂團演奏者。鼓膜與聽小骨屬傳音結構，受損通常可處理；半規管負責平衡，與聽力下降無直接關係。","source":"第十九章 19.2 聽覺生理學","chId":"ch19"},{"id":"q1912","ch":19,"level":3,"type":"multi","style":"case","q":"看 6 米以內的近物時，眼睛會作哪些調整？","options":["瞳孔放大","睫狀肌收縮使晶狀體變厚","睫狀肌放鬆使晶狀體變薄","瞳孔收縮","雙眼會聚"],"answer":[1,3,4],"explain":"課文列近距視覺三項調整：瞳孔收縮減少光束寬度、眼球會聚使影像落在雙眼視網膜對應區域、睫狀肌收縮釋放懸韌帶張力令晶狀體變厚。瞳孔放大屬暗處反應；睫狀肌放鬆、晶狀體變薄是看 6 米以外遠物時的狀態。","source":"第十九章 19.5 調節","chId":"ch19"}]}];
window.QUESTIONS = [{"id":"q0101","ch":1,"level":1,"type":"single","style":"concept","q":"細胞質膜的雙層磷脂中，親水頭部和疏水尾部怎樣排列？","options":["親水頭向外、疏水尾向內","親水頭向內、疏水尾向外","頭尾隨機分布，沒有方向性","親水頭與疏水尾都朝外"],"answer":[0],"explain":"磷脂頭部帶電、親水，所以朝向膜兩側的水性環境；尾部不帶電、疏水，藏在雙層中間形成排水層。把親水頭與疏水尾方向倒轉，是最常見的錯誤；其他選項忽略了磷脂兩端性質完全不同。","source":"第一章 細胞質膜的功能","chId":"ch01"},{"id":"q0102","ch":1,"level":1,"type":"single","style":"concept","q":"下列哪一項不是課文列出的細胞器（organelle）？","options":["溶酶體","杯狀細胞","線粒體","核糖小體"],"answer":[1],"explain":"杯狀細胞是黏膜上皮中分泌黏液的細胞，屬於細胞類型，不是細胞內的胞器。線粒體、核糖小體和溶酶體都在課文列出的胞器名單內。題目考的是「胞器」與「特化細胞」的分類，不要見到顯微構造就當成胞器。","source":"第一章 細胞結構和功能","chId":"ch01"},{"id":"q0103","ch":1,"level":1,"type":"single","style":"concept","q":"哪一種膜內襯可活動的關節腔，並分泌滑液？","options":["黏膜","皮膚膜","滑膜","漿膜"],"answer":[2],"explain":"滑膜內襯可動關節腔並包圍腱，分泌清澈黏滑的滑液，作用是潤滑和滋養關節。黏膜見於消化道、呼吸道和泌尿生殖道；漿膜見於胸膜、心包膜和腹膜；皮膚膜是身體外表面的保護層。","source":"第一章 1.3 滑膜","chId":"ch01"},{"id":"q0104","ch":1,"level":1,"type":"single","style":"concept","q":"杯狀細胞（goblet cell）的主要分泌物是什麼？","options":["滑液","膽汁","漿液","黏液"],"answer":[3],"explain":"杯狀細胞在黏膜上皮中製造黏液；黏液積聚時細胞脹大，外形像高腳杯。漿液由漿膜分泌，滑液由滑膜分泌，膽汁由肝臟製造，三者都不是杯狀細胞的產物，不要把它們混成同一種分泌。","source":"第一章 1.3 黏膜","chId":"ch01"},{"id":"q0105","ch":1,"level":2,"type":"single","style":"concept","q":"下列哪一項不屬於漿膜（serous membrane）？","options":["滑膜","胸膜","心包膜","腹膜"],"answer":[0],"explain":"課文明確指出漿膜只見於三處：胸膜、心包膜和腹膜。滑膜雖然也分泌液體，但它內襯關節腔，而且不是上皮膜，由細隙狀結締組織和彈性纖維構成，因此不能混入漿膜；「會分泌液體」不是漿膜的判準。","source":"第一章 1.3 漿液膜、滑膜","chId":"ch01"},{"id":"q0106","ch":1,"level":2,"type":"single","style":"concept","q":"主動運輸與被動運輸最關鍵的分別是甚麼？","options":["主動運輸由高濃度往低濃度，被動相反","主動運輸逆濃度梯度並需要能量","主動運輸不需要膜蛋白，被動需要","主動運輸只運送水，被動只運送氣體"],"answer":[1],"explain":"課文定義主動運輸是物質由低濃度往高濃度、逆濃度梯度移動，需要能量；被動運輸則順濃度梯度，不需能量。把主動與被動的方向說反，是常見錯誤；也有選項把運輸方式與物質種類錯誤配對，或忽略膜蛋白參與多種運輸。","source":"第一章 細胞質膜的功能","chId":"ch01"},{"id":"q0107","ch":1,"level":2,"type":"multi","style":"concept","q":"根據課文，膜蛋白質可以有以下哪些功能？","options":["製造黏液","作為酵素","參與物質穿越細胞膜的運輸","合成磷脂","作為荷爾蒙和化學信差的特異性受體"],"answer":[1,2,4],"explain":"課文列出膜蛋白可作特異性感受器、酵素，以及參與跨膜運輸；附在膜蛋白外部的碳水化合物則給細胞免疫學身份。黏液由杯狀細胞製造，磷脂是膜的成分而非膜蛋白的產物，所以「製造黏液」和「合成磷脂」都是把其他構造的功能借用過來。","source":"第一章 膜蛋白質的一些功能","chId":"ch01"},{"id":"q0108","ch":1,"level":2,"type":"single","style":"concept","q":"下列哪一項不是課文列出的腸漏綜合症誘因？","options":["病毒或細菌感染","寄生蟲侵擾","長期高纖飲食","過量攝取乙醇"],"answer":[2],"explain":"課文列出的誘因包括寄生蟲、病毒和細菌感染、過量乙醇，以及非類固醇抗發炎藥；高纖飲食不在其列。腸漏的關鍵是腸壁屏障失效，讓本應被阻擋的物質通過，而不是由纖維攝取量直接造成。","source":"第一章 1.4 維持健康的膜","chId":"ch01"},{"id":"q0109","ch":1,"level":3,"type":"single","style":"case","q":"一名長期吸煙者的呼吸道上皮杯狀細胞分泌黏液的功能受損。最直接受影響的防禦是甚麼？","options":["腎臟的鈉鉀泵失去能量","關節滑液的黏度下降","肺泡的氣體交換面積增加","吸入的外來微粒較難被黏住並排出"],"answer":[3],"explain":"課文指呼吸道黏膜的黏液能阻止吸入的外來微粒，防止它們進入肺泡；杯狀細胞分泌不足，最直接就是黏附與清除微粒的能力下降。腎臟鈉鉀泵、關節滑液和肺泡氣體交換面積都不是杯狀細胞黏液的直接防禦，與呼吸道黏膜無直接關係。","source":"第一章 1.3 黏膜","chId":"ch01"},{"id":"q0110","ch":1,"level":3,"type":"multi","style":"concept","q":"關於體內三種膜，下列哪些敘述正確？","options":["滑膜是一種上皮膜","滑液有潤滑和滋養關節的作用","黏膜見於消化道、呼吸道和泌尿生殖道","漿膜由單層鱗狀上皮和疏鬆結締組織構成"],"answer":[1,2,3],"explain":"正確項包括：滑液潤滑並滋養關節、黏膜見於消化道／呼吸道／泌尿生殖道、漿膜由單層鱗狀上皮和疏鬆結締組織構成。滑膜不是上皮膜，而是由細隙狀結締組織層和彈性纖維構成，所以「滑膜是一種上皮膜」是陷阱。","source":"第一章 1.3 上皮膜、滑膜","chId":"ch01"},{"id":"q0111","ch":1,"level":3,"type":"single","style":"case","q":"一名病人長期服用非類固醇抗發炎藥並每日飲酒，出現腹痛和腹瀉。按課文，最可能受損的是哪一層？","options":["消化道黏膜","胸膜","關節滑膜","心包膜"],"answer":[0],"explain":"課文把 NSAIDs 和過量乙醇列為腸漏綜合症的誘因，而腸漏是腸壁黏膜屏障失效，讓本應被阻擋的物質通過。心包膜和胸膜屬漿膜，與口服藥物和酒精的直接接觸無關；滑膜在關節，也不是消化道的第一線。","source":"第一章 1.4 維持健康的膜","chId":"ch01"},{"id":"q0201","ch":2,"level":1,"type":"single","style":"concept","q":"成年人皮膚的表面積大約是多少？","options":["0.5–1 平方米","1.5–2 平方米","5–6 平方米","3–4 平方米"],"answer":[1],"explain":"課文指成年人皮膚表面積平均約 20,000 cm²，即大約 1.5–2 平方米。這個數字要與「2 英鎊硬幣大小的皮膚有超過 300 萬個細胞」分開記：前者是全身面積，後者是一小片皮膚的細胞數。","source":"第二章 2.1 皮膚的結構","chId":"ch02"},{"id":"q0202","ch":2,"level":1,"type":"single","style":"concept","q":"表皮最厚的位置在哪裡？","options":["背部","腹部","手掌和腳底","面部"],"answer":[2],"explain":"課文指表皮在身體不同部位有不同厚度，手掌和腳底最厚，這是經常受壓和摩擦的部位。背部、腹部和面部的表皮都較薄；題目常用「經常受壓」作提示，手掌和腳底正符合，不要只看面積大小。","source":"第二章 2.1.1 表皮","chId":"ch02"},{"id":"q0203","ch":2,"level":1,"type":"single","style":"concept","q":"下列哪一項不是表皮的特徵？","options":["由複層角質鱗狀上皮構成","靠真皮間質液取得營養","最外層是角質層","含豐富血管"],"answer":[3],"explain":"表皮沒有血管，營養和氧氣來自由真皮乳突滲出的間質液；它由複層角質鱗狀上皮構成，最表面是角質層。把真皮的特徵套到表皮，是最常見的混淆；表皮也無神經末梢，感覺由真皮接受器負責。","source":"第二章 2.1.1 表皮","chId":"ch02"},{"id":"q0204","ch":2,"level":1,"type":"single","style":"concept","q":"麥氏小體（Meissner's corpuscle）主要感受哪種刺激？","options":["輕壓","溫度","重壓","疼痛"],"answer":[0],"explain":"課文的感覺接受器表列明：麥氏小體感受輕壓，巴氏小體感受重壓，自由神經末梢感受疼痛。重壓是巴氏小體的功能，疼痛是自由神經末梢，兩者最易與麥氏小體混淆；溫度由另一類接受器負責，不是本表三項。","source":"第二章 表 2.1 皮膚中的感覺接受器","chId":"ch02"},{"id":"q0205","ch":2,"level":2,"type":"single","style":"concept","q":"兩個膚色不同的人，黑色素細胞數量與膚色的關係，哪項正確？","options":["黑色素由角質層製造","黑色素細胞數量相近，膚色差異主要來自黑色素分泌量","膚色較深者的黑色素細胞數目一定較多","日曬會減少黑色素合成"],"answer":[1],"explain":"課文指黑色素細胞的數量相當固定，膚色差別取決於黑色素被分泌的數量；接觸陽光會促進黑色素合成。把「細胞數目」和「分泌量」混淆、說黑色素由角質層製造、或說日曬會減少合成，都與課文相反。","source":"第二章 2.1.1 皮膚顏色","chId":"ch02"},{"id":"q0206","ch":2,"level":2,"type":"single","style":"concept","q":"汗腺主要受哪種神經刺激？","options":["沒有神經支配","副交感神經","交感神經","體感神經"],"answer":[2],"explain":"課文明言汗腺受交感神經刺激，並對體溫升高和恐懼有反應；下視丘的溫度調節中樞再透過自主神經調控。副交感神經主要與消化分泌和蠕動有關，不要把所有腺體都歸給副交感；「汗腺由交感支配」是本章必記點。","source":"第二章 2.1.2 汗腺","chId":"ch02"},{"id":"q0207","ch":2,"level":2,"type":"multi","style":"concept","q":"真皮內含有下列哪些結構？","options":["汗腺及管道","骨髓","角質層","血管","感覺神經末梢"],"answer":[0,3,4],"explain":"真皮內有血管、淋巴管、汗腺及管道、感覺神經末梢、毛髮、豎毛肌和皮脂腺。角質層屬表皮最表面，骨髓在骨骼的骨髓腔，兩者都不在真皮；這題考的是分層，不是把所有皮膚構造混在一起。","source":"第二章 2.1.2 真皮","chId":"ch02"},{"id":"q0208","ch":2,"level":2,"type":"single","style":"concept","q":"一級與二級癒合的比較，哪項正確？","options":["一級癒合的疤痕較多","一級癒合靠肉芽組織從底部長起","二級癒合所需時間較短","二級癒合收縮較大、疤痕較多"],"answer":[3],"explain":"課文比較表列明：二級癒合收縮較大以縮小傷口、疤痕較多、需時較長；一級癒合則疤痕較少、時間較短。把一級說成疤痕較多或靠肉芽由底部長起，或把二級說成時間較短，都是把兩者特徵倒轉。","source":"第二章 2.4 傷口癒合","chId":"ch02"},{"id":"q0209","ch":2,"level":3,"type":"single","style":"case","q":"一名病人小腿有靜脈曲張性潰瘍，傷口開放、邊緣無法對合。最可能採用的癒合方式及其特徵是？","options":["二級癒合，肉芽組織由底部生長並收縮","一級癒合，疤痕較多且收縮較大","二級癒合，主要靠上皮細胞增殖且沒有收縮","一級癒合，上皮細胞直接跨越傷口"],"answer":[0],"explain":"課文把靜脈曲張性潰瘍和褥瘡列為二級癒合的例子：傷口開放，肉芽組織由凹洞底部生長，纖維組織造成較大的收縮以縮小傷口。把二級癒合說成主要靠上皮增殖而沒有收縮，或把一級癒合說成上皮直接跨越傷口，都不符合課文。","source":"第二章 2.4 二級癒合","chId":"ch02"},{"id":"q0210","ch":2,"level":3,"type":"multi","style":"concept","q":"下列哪些會延緩傷口癒合？","options":["傷口感染","局部血液供應不足","糖尿病","營養狀態良好","年輕"],"answer":[0,1,2],"explain":"課文把感染、免疫力受損、血液供應和全身狀態不良（例如糖尿病和癌症）列為降低癒合速度的因素；局部血供良好才有利修復。營養良好和年輕並非延緩因素，反而是較有利的條件。","source":"第二章 2.4.1 傷口癒合需具備的條件","chId":"ch02"},{"id":"q0211","ch":2,"level":3,"type":"single","style":"case","q":"工人在酷熱環境大量流汗，只補充清水。按課文，最可能出現哪種電解質問題？","options":["血鉀過高","血鈉過低","血鈣過高","血糖過低"],"answer":[1],"explain":"課文在排泄作用一節指出，汗液含氯化鈉，過度流汗而只補清水會稀釋體液，可能導致血鈉水準異常低；要適度增加水分和鹽的攝取。血鉀過高、血鈣過高和血糖過低都不是課文與流汗直接連結的電解質變化。","source":"第二章 排泄作用","chId":"ch02"},{"id":"q0301","ch":3,"level":1,"type":"single","style":"concept","q":"消化道壁由內到外的四層次序是？","options":["漿膜→肌肉層→黏膜下層→黏膜","黏膜→肌肉層→黏膜下層→漿膜","黏膜→黏膜下層→肌肉層→漿膜","黏膜下層→黏膜→肌肉層→漿膜"],"answer":[2],"explain":"課文由內到外描述四層：黏膜→黏膜下層→肌肉層→漿膜（或動脈外膜）。把黏膜下層和肌肉層倒轉、由外到內排列、或把黏膜下層放到最內，都是常見的次序錯配。","source":"第三章 3.1.1 消化道的基礎結構","chId":"ch03"},{"id":"q0302","ch":3,"level":1,"type":"single","style":"concept","q":"右髂骨窩主要對應哪組器官？","options":["肝臟和膽囊","脾臟","胃和胰臟","盲腸和闌尾"],"answer":[3],"explain":"課文的腹部器官位置表列明：右髂骨窩是盲腸和闌尾，右季肋部是肝臟和膽囊，左季肋部是脾臟，上腹部是胃和胰臟。這題考九區定位，左右以人體為準，不要以觀察者方向混淆；右下腹不等於右上腹。","source":"第三章 3.2 腹部內各器官的位置","chId":"ch03"},{"id":"q0303","ch":3,"level":1,"type":"single","style":"concept","q":"膽汁由哪個器官製造？","options":["肝臟","胰臟","膽囊","胃"],"answer":[0],"explain":"膽汁由肝臟製造，每天約 500 mL，儲存在膽囊，進食時經膽管釋放入十二指腸。膽囊只是儲存和釋放，不是製造；胰臟分泌胰液，胃分泌胃液，三者的產物不要混淆，尤其膽囊與肝臟的分工最常考。","source":"第三章 3.3.1 肝臟和膽囊","chId":"ch03"},{"id":"q0304","ch":3,"level":1,"type":"single","style":"concept","q":"胃蛋白酶（pepsin）把蛋白質分解成甚麼？","options":["單醣","多勝肽","脂肪酸和甘油","氨基酸"],"answer":[1],"explain":"課文指胃蛋白酶把蛋白質轉化為多勝肽；氨基酸要再靠胰蛋白酶、胰凝乳蛋白酶和腸細胞的胜肽酶逐步分解。脂肪酸和甘油是脂肪分解產物，單醣是碳水化合物分解產物；把「多勝肽」誤當成最終產物氨基酸，是常見陷阱。","source":"第三章 胃部的功能","chId":"ch03"},{"id":"q0305","ch":3,"level":2,"type":"single","style":"concept","q":"歐氏神經叢（Auerbach's plexus）位於何處？","options":["黏膜上皮之下","黏膜下層","肌肉層的內環肌與外縱肌之間","漿膜之外"],"answer":[2],"explain":"課文指腸肌叢（歐氏神經叢）位於肌肉層的內環肌和外縱肌之間，供應鄰近平滑肌和血管；黏膜下層的神經叢則是麥氏神經叢。把歐氏叢放在黏膜上皮之下、黏膜下層或漿膜之外，都不符合課文。","source":"第三章 3.1.1 肌肉層、黏膜下層","chId":"ch03"},{"id":"q0306","ch":3,"level":2,"type":"single","style":"concept","q":"副交感神經受刺激時，消化道會出現甚麼反應？","options":["蠕動減少、分泌減少","只增加分泌，蠕動不變","括約肌全部放鬆且沒有蠕動","蠕動增加、腺體分泌增加"],"answer":[3],"explain":"課文指副交感神經透過活躍腸肌神經叢增加肌肉活動（尤其蠕動），並透過活躍黏膜下神經叢增加腺體分泌，所以蠕動和分泌會同時增加。說蠕動減少、只增加分泌、或括約肌全部放鬆而沒有蠕動，都是把交感效應或兩個神經叢的作用錯誤拆開。","source":"第三章 3.1.1 神經分佈","chId":"ch03"},{"id":"q0307","ch":3,"level":2,"type":"multi","style":"concept","q":"胃的功能包括下列哪些？","options":["分泌內在因子","製造膽汁","吸收大部分水分","暫時儲存食物","分泌鹽酸作非特異防禦"],"answer":[0,3,4],"explain":"課文列出的胃功能包括暫時儲存食物、分泌內在因子供 B12 吸收、以鹽酸作非特異防禦，以及分泌胃蛋白酶和胃泌素等。製造膽汁的是肝臟，大部分水分在小腸吸收，所以這兩項不屬於胃。","source":"第三章 胃部的功能","chId":"ch03"},{"id":"q0308","ch":3,"level":2,"type":"single","style":"concept","q":"膽汁在脂肪消化中的主要作用是甚麼？","options":["乳化脂肪","中和胃酸","把脂肪分解為脂肪酸和甘油","把蛋白質分解為多勝肽"],"answer":[0],"explain":"膽鹽把脂肪乳化成薄層，增加脂肪酶作用的表面積，但膽汁本身不含分解脂肪的酵素；真正把脂肪切成脂肪酸和甘油的是胰脂肪酶。中和胃酸、分解蛋白質或直接分解脂肪都不是膽汁的主要作用。","source":"第三章 3.3.1 肝臟和膽囊、表 3.2","chId":"ch03"},{"id":"q0309","ch":3,"level":3,"type":"single","style":"case","q":"一名病人胃部切除後出現維生素 B12 吸收不良。最可能缺少甚麼？","options":["胃蛋白酶","內在因子","胰澱粉酶","膽鹽"],"answer":[1],"explain":"課文指胃分泌內在因子，而內在因子是迴腸末端吸收維生素 B12 所必需；胃部切除最直接就是失去這個來源。膽鹽與脂肪乳化有關，胰澱粉酶分解澱粉，胃蛋白酶分解蛋白質，都不直接負責 B12 吸收。","source":"第三章 胃部的功能、表 3.2","chId":"ch03"},{"id":"q0310","ch":3,"level":3,"type":"multi","style":"concept","q":"小腸適合吸收的結構特徵包括哪些？","options":["絨毛內毛細血管壁只有一個細胞厚","絨毛壁只有一個細胞厚","絨毛增加表面積","有大量破骨細胞","表面由多層角質鱗狀上皮覆蓋"],"answer":[0,1,2],"explain":"課文指小腸表面有絨毛，絨毛壁只有一個細胞厚，與它接觸的毛細血管壁也只有一個細胞厚，以促進營養物質通過。破骨細胞屬骨骼；多層角質鱗狀上皮是皮膚表皮的特徵，不是小腸吸收面。","source":"第三章 3.3.1 小腸","chId":"ch03"},{"id":"q0311","ch":3,"level":3,"type":"single","style":"case","q":"膽結石阻塞膽管後，脂肪消化最先受影響的是哪一步？","options":["蛋白質分解為多勝肽","維生素 B12 吸收","脂肪乳化不足","澱粉分解為雙醣"],"answer":[2],"explain":"膽汁經膽管進入十二指腸，膽鹽負責乳化脂肪；膽管阻塞會令膽汁不能到達小腸，脂肪無法散成薄層，脂肪酶效率下降。蛋白質和澱粉的消化主要靠胃蛋白酶和胰澱粉酶，B12 吸收則靠內在因子和迴腸末端。","source":"第三章 3.3.1 肝臟和膽囊","chId":"ch03"},{"id":"q0401","ch":4,"level":1,"type":"single","style":"concept","q":"成年人體內共有多少塊骨？","options":["106 塊","156 塊","306 塊","206 塊"],"answer":[3],"explain":"課文明確指人體內有 206 塊不同的骨骼。這個數字要與脊柱的 24 塊可動脊椎骨分開：24 只是脊柱的一部分，加上薦骨、尾骨和四肢、頭骨等才是全身 206 塊。","source":"第四章 4.2 骨骼","chId":"ch04"},{"id":"q0402","ch":4,"level":1,"type":"single","style":"concept","q":"人體最大的骨與最細小的骨，正確配對是？","options":["股骨與鐙骨","脛骨與腕骨","髖骨與趾骨","肱骨與指骨"],"answer":[0],"explain":"課文指人體內最大的骨骼是股骨，最細小的是耳內小骨之一的鐙骨。肱骨、脛骨和髖骨都比股骨小；指骨、腕骨和趾骨也不是最細小的骨。兩個極端都在課文點名，其他選項只是隨意配對。","source":"第四章 4.2 骨骼","chId":"ch04"},{"id":"q0403","ch":4,"level":1,"type":"single","style":"concept","q":"造骨細胞（osteoblast）的主要功能是甚麼？","options":["成熟後監控骨骼組織","形成新骨並分泌膠原","製造軟骨","再吸收骨骼"],"answer":[1],"explain":"課文指造骨細胞負責形成骨骼，分泌膠原和骨骼組織其他成分；它們成熟後被困於新骨內，成為骨細胞。再吸收是蝕骨細胞的工作，製造軟骨的是軟骨細胞，兩者不要與造骨細胞混淆。","source":"第四章 4.3.2 骨骼細胞","chId":"ch04"},{"id":"q0404","ch":4,"level":1,"type":"single","style":"concept","q":"長骨的骨髓腔內主要含哪種骨髓？","options":["紅骨髓","骨膜","黃骨髓","透明軟骨"],"answer":[2],"explain":"課文指長骨骨幹由緻密質骨和中央骨髓腔構成，骨髓腔內含多脂肪的黃骨髓；紅骨髓主要見於短骨、不規則骨、扁骨和種子骨的疏鬆質骨內。骨膜和透明軟骨是骨骼的其他構造，不是骨髓腔的內容物。","source":"第四章 4.3.1 長骨的一般結構","chId":"ch04"},{"id":"q0405","ch":4,"level":2,"type":"single","style":"concept","q":"脊柱的頸椎、胸椎和腰椎數目，正確的是？","options":["7、5、12","12、7、5","5、12、7","7、12、5"],"answer":[3],"explain":"課文列明 7 塊頸椎、12 塊胸椎、5 塊腰椎，另有 1 塊薦骨（5 塊融合）和 1 塊尾骨（4 塊融合）。把頸和腰倒轉、腰和胸倒轉、或頸和胸倒轉，都是常見的數字錯配。","source":"第四章 4.2.2 脊柱","chId":"ch04"},{"id":"q0406","ch":4,"level":2,"type":"single","style":"concept","q":"降鈣素（calcitonin）對骨骼與血鈣的作用是甚麼？","options":["增加鈣進入骨骼","促進蝕骨細胞再吸收","減少鈣進入骨骼","抑制造骨細胞形成骨"],"answer":[0],"explain":"課文指降鈣素增加鈣攝入骨骼，副甲狀腺素則促進骨釋放鈣、減少鈣進入骨骼，提升血鈣。促進蝕骨細胞再吸收、減少鈣進入骨骼或抑制造骨細胞，方向都與降鈣素相反。","source":"第四章 4.4.1 骨骼生長的荷爾蒙調節","chId":"ch04"},{"id":"q0407","ch":4,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於中軸骨骼（axial skeleton）？","options":["肋骨","脊柱","頭骨","肩胛骨","鎖骨"],"answer":[0,1,2],"explain":"課文指中軸骨架由頭骨、脊柱、胸骨和肋骨構成；鎖骨和肩胛骨屬肩帶，是附肢骨骼的一部分。這題的陷阱是把「位於軀幹附近」的肩帶骨誤當成中軸骨，位置接近不等於同一分區。","source":"第四章 4.2.2 中軸骨骼、4.2.3 附肢骨架","chId":"ch04"},{"id":"q0408","ch":4,"level":2,"type":"single","style":"concept","q":"骨折癒合的階段次序，正確的是？","options":["骨痂→血腫→炎症／肉芽→成熟→重建","血腫→炎症／肉芽→骨痂→成熟→重建","血腫→骨痂→炎症／肉芽→重建→成熟","炎症／肉芽→血腫→骨痂→重建→成熟"],"answer":[1],"explain":"課文列明五階段：血腫→炎症／肉芽→骨痂→成熟→重建。把血腫放到骨痂之後、把炎症與血腫倒轉、或把成熟與重建倒轉，都會打亂次序。","source":"第四章 4.5.1 骨骼的癒合","chId":"ch04"},{"id":"q0409","ch":4,"level":3,"type":"single","style":"case","q":"一名長者股骨頸骨折，骨折部位血液供應不足。最可能出現哪種後果？","options":["骨痂形成過多，骨骼特別堅硬","骨折在數天內完全癒合","軟骨性接合，修復部位較軟弱","骨折只形成血腫，沒有炎症期"],"answer":[2],"explain":"課文指血液供應不足會減少造骨細胞、增加軟骨細胞，可能導致骨折的軟骨性接合，修復部位較軟弱；股骨頸正是課文列出的高危部位。說骨痂過多、數天內完全癒合、或沒有炎症期，都與血供不足的結果相反。","source":"第四章 4.5.2 延緩骨折癒合的因素","chId":"ch04"},{"id":"q0410","ch":4,"level":3,"type":"multi","style":"concept","q":"下列哪些是課文列出的延緩骨折癒合因素？","options":["血液供應不足","年輕","骨端持續移動","骨端排列良好","死骨碎片或軟組織碎片"],"answer":[0,2,4],"explain":"課文列出的因素包括死骨和軟組織碎片、血供不足、骨端排列不當、骨端持續移動，以及感染、全身疾病、營養不良、類固醇和老化。骨端排列良好有利癒合；年輕也不是延緩因素。","source":"第四章 4.5.2 延緩骨折癒合的因素","chId":"ch04"},{"id":"q0411","ch":4,"level":3,"type":"single","style":"remedy","q":"一名病人跌倒後脛骨骨膜壓痛，骨折已接合但局部仍有刺痛，觸摸和動作時加重。課文中最對應的療劑是？","options":["Calcarea phosphorica","Calcarea fluorica","Bryonia","Symphytum"],"answer":[3],"explain":"Symphytum 的親和力在軟骨、骨膜和扁平骨，課文用於骨折、骨膜損傷、鈍器傷後疼痛和骨不連合；傷口癒合後仍留骨膜痛正是其重點。Calcarea fluorica 偏向外生骨贅和骨刺，Calcarea phosphorica 偏向成長痛和癒合不良，Bryonia 偏向滑液膜和漿膜。","source":"第四章 表八、紫草（Symphytum）","chId":"ch04"},{"id":"q0501","ch":5,"level":1,"type":"single","style":"concept","q":"纖維關節、軟骨關節、滑液關節的活動度，正確的是？","options":["不可活動、可輕微活動、可自由活動","可自由活動、可輕微活動、不可活動","三者都可自由活動","可輕微活動、不可活動、可自由活動"],"answer":[0],"explain":"課文的分類就是按活動度：纖維關節不可活動（如頭骨縫），軟骨關節可輕微活動（如椎間盤），滑液關節可自由活動（如肩、膝、髖）。把次序倒轉、說三者都可自由活動、或把纖維和軟骨對調，都不符合課文。","source":"第五章 5.1.1 關節的三種類型","chId":"ch05"},{"id":"q0502","ch":5,"level":1,"type":"single","style":"concept","q":"膝關節屬於哪一種滑液關節？","options":["球窩關節","屈戌關節","鞍狀關節","車軸關節"],"answer":[1],"explain":"課文指膝關節是由股骨髁、脛骨髁和膝蓋骨後面構成的屈戌關節，可作屈曲、伸展和旋轉式動作；雖然有少量旋轉，分類仍屬屈戌。球窩是肩和髖，車軸是橈尺關節，鞍狀是拇指基部。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0503","ch":5,"level":1,"type":"single","style":"concept","q":"肩關節屬於哪一種滑液關節？","options":["滑動關節","鞍狀關節","球窩關節","屈戌關節"],"answer":[2],"explain":"肩關節由肩胛骨的關節盂腔和肱骨頭構成，是球窩關節，也是人體活動性最大、最不穩定的關節。盂唇和韌帶只是增加穩定，不改變球窩的分類；屈戌見於肘和膝，滑動見於腕骨間，鞍狀見於拇指基部。","source":"第五章 5.2.1 肩關節","chId":"ch05"},{"id":"q0504","ch":5,"level":1,"type":"single","style":"concept","q":"關節軟骨的營養主要來自哪裡？","options":["血液","骨髓","淋巴液","滑液"],"answer":[3],"explain":"課文指關節軟骨沒有血液供應，營養是從滑液中取得。正因為無血管，軟骨受損後的修復能力有限，這也是關節軟骨病變難處理的原因。血液、淋巴液和骨髓都不是關節軟骨的直接營養來源。","source":"第五章 5.1.4 關節軟骨","chId":"ch05"},{"id":"q0505","ch":5,"level":2,"type":"single","style":"concept","q":"下列哪一項不是滑液關節的共同特徵？","options":["骨縫","滑囊韌帶","滑液膜","關節軟骨"],"answer":[0],"explain":"滑液關節的共同特徵包括關節軟骨、包圍關節的滑囊韌帶、滑液膜和滑液。骨縫是頭骨之間的纖維關節，完全不可動，沒有關節腔也沒有滑液，與滑液關節的構造和活動度都不同；「有腔」是滑液關節的關鍵。","source":"第五章 5.1.4 滑液關節的特徵","chId":"ch05"},{"id":"q0506","ch":5,"level":2,"type":"single","style":"concept","q":"腳的內翻（inversion）和外翻（eversion）主要發生在哪裡？","options":["髖關節","跗骨之間","踝關節","膝關節"],"answer":[1],"explain":"課文明言內翻和外翻的動作發生在跗骨骨骼之間，而不是在踝關節；踝關節本身只做背屈和蹠屈。把內外翻當成踝關節動作，是這一章最常見的陷阱，也容易與足部肌肉的作用混淆。","source":"第五章 5.2.8 踝關節","chId":"ch05"},{"id":"q0507","ch":5,"level":2,"type":"multi","style":"concept","q":"滑液（synovial fluid）有下列哪些功能？","options":["含噬菌細胞，清除微生物和殘骸","提供營養給關節腔內結構","製造紅骨髓","分泌膽汁","潤滑關節"],"answer":[0,1,4],"explain":"課文列出的滑液功能包括潤滑、提供營養、含噬菌細胞清除微生物和細胞殘骸、維持關節穩定，以及防止骨骼末端分開。膽汁由肝臟製造，紅骨髓在骨骼內，兩者都與滑液無關；不要把滑液當成消化液或造血組織。","source":"第五章 5.1.4 滑液","chId":"ch05"},{"id":"q0508","ch":5,"level":2,"type":"single","style":"concept","q":"膝關節的半月軟骨為何不被滑液膜覆蓋？","options":["因為它們沒有血管","因為它們位於關節囊外","因為它們支撐體重","因為它們是纖維組織"],"answer":[2],"explain":"課文指不用支撐體重的囊內結構會被滑液膜覆蓋，但半月軟骨支撐體重，所以不被覆蓋；十字韌帶和脂肪墊則被滑液膜覆蓋。說半月軟骨沒有血管、位於囊外或是纖維組織，都不是課文給的理由。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0509","ch":5,"level":3,"type":"single","style":"case","q":"一名長時間打字的人出現手腕麻痛，醫生懷疑腕管內結構受壓。腕管內最可能受壓的神經是？","options":["尺神經","橈神經","坐骨神經","正中神經"],"answer":[3],"explain":"課文指腕管由屈肌支持帶與腕骨圍成，腕關節和手指的屈肌肌腱以及正中神經通過腕管。尺神經、橈神經不是課文列出的腕管內容；坐骨神經在下肢。這題考的是腕管限界的內容物。","source":"第五章 屈肌支持帶","chId":"ch05"},{"id":"q0510","ch":5,"level":3,"type":"multi","style":"concept","q":"關於膝關節，下列哪些敘述正確？","options":["它屬於球窩關節","半月軟骨完全被滑液膜覆蓋","完全伸展時關節會鎖定","它是人體最大、最複雜的關節","十字韌帶位於關節囊內"],"answer":[2,3,4],"explain":"課文指膝關節最大最複雜，十字韌帶互相交錯、位於囊內，完全伸展時關節會被鎖定。半月軟骨支撐體重，不被滑液膜覆蓋；膝是屈戌關節，不是球窩。把膝當成球窩、或說半月軟骨完全被滑液膜覆蓋，都是類型與結構的混淆。","source":"第五章 5.2.7 膝關節","chId":"ch05"},{"id":"q0511","ch":5,"level":3,"type":"single","style":"remedy","q":"一名病人關節僵硬疼痛，早上起床和開始動作時最痛，活動一會兒及熱敷後減輕，寒冷潮濕時加重。最對應的療劑是？","options":["Rhus toxicodendron","Ruta","Calcarea fluorica","Bryonia"],"answer":[0],"explain":"Rhus toxicodendron 的特徵是開始動作、寒冷潮濕時較差，持續動作和熱敷後較好。Bryonia 相反，任何輕微動作都加重、想保持不動；Ruta 偏向扭傷後纖維和肌腱；Calcarea fluorica 偏向外生骨贅。","source":"第五章 5.3 對關節有親和力的療劑、補充筆記 Rhus tox","chId":"ch05"},{"id":"q0601","ch":6,"level":1,"type":"single","style":"concept","q":"哪一種肌肉位於心壁、屬不隨意肌，卻能自行產生收縮？","options":["平滑肌","心肌","肌腱","骨骼肌"],"answer":[1],"explain":"心肌位於心壁，屬不隨意肌，卻能自行產生收縮，是唯一具自律性的肌肉類型。平滑肌也不隨意，但分佈在內臟與血管，並非心壁；骨骼肌屬隨意肌，需運動神經衝動才收縮；肌腱只是連接肌肉與骨骼的纖維帶，不是肌肉組織。","source":"第六章 6.1 肌肉組織的三種類型","chId":"ch06"},{"id":"q0602","ch":6,"level":1,"type":"single","style":"concept","q":"收縮時向上提眉的是哪一條肌肉？","options":["眼輪匝肌","頰肌","枕額肌","上瞼提肌"],"answer":[2],"explain":"枕額肌的額骨部份（frontalis）收縮時向上提眉。上瞼提肌只提上眼瞼；眼輪匝肌圍繞眼睛，用力收縮時瞇眼；頰肌壓迫頰部、協助排出空氣，三者都不負責提眉。本題的重點是把「提眉」與「提眼瞼」分開。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0603","ch":6,"level":1,"type":"single","style":"concept","q":"位於下頜角外側、咀嚼時把下頜骨向上拉並對食物施壓的是哪條肌肉？","options":["胸鎖乳突肌","口輪匝肌","頰肌","咬肌"],"answer":[3],"explain":"咬肌由顴弓延伸到下頜角，收縮時把下頜骨向上拉、關閉下巴，並對食物施加壓力。頰肌是把頰壓向牙齒；口輪匝肌關閉嘴唇；胸鎖乳突肌作用在頸部，與咀嚼無關。別把「閉唇」與「閉下頜」混為一談。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0604","ch":6,"level":1,"type":"single","style":"concept","q":"全有全無律（all-or-none law）是指什麼？","options":["單一肌纖維完全收縮或完全不收縮","肌肉收縮時一定會縮短","所有肌肉會同時收縮","整條肌肉只能全部收縮，不能局部收縮"],"answer":[0],"explain":"全有全無律指單一肌纖維要麼完全收縮、要麼完全不收縮；整條肌肉的力量取決於同時收縮的纖維數目與刺激頻率，所以「整條肌肉全收縮」是錯的。等長收縮時肌肉並不縮短，故「一定縮短」也錯；不同肌肉各有獨立控制，不會一起全收縮。","source":"第六章 6.2.1 A 肌肉張力","chId":"ch06"},{"id":"q0605","ch":6,"level":2,"type":"single","style":"concept","q":"呼吸時固定下方肋骨；若只有一側收縮，會使腰椎向該側屈曲。這是哪一條肌肉？","options":["背闊肌","腰方肌","腹直肌","骶脊肌"],"answer":[1],"explain":"腰方肌由髂骨脊走向第 12 肋骨，收縮時固定下方肋骨，單側收縮使腰椎側屈，雙側則協助脊柱伸展。骶脊肌主要做脊柱伸展；腹直肌屈曲腰椎；背闊肌作用在肩關節，不固定肋骨。","source":"第六章 6.1.2 A 背部肌肉","chId":"ch06"},{"id":"q0606","ch":6,"level":2,"type":"single","style":"case","q":"嘗試單手抬起一位 80 kg 的人但抬不動，手臂肌肉仍在用力收縮。這屬於哪種收縮？","options":["等張收縮","拮抗收縮","等長收縮","被動收縮"],"answer":[2],"explain":"等長收縮（iso＝相等，metric＝長度）是肌肉長度不變、張力上升：阻力太大，肌肉無法縮短，力量以張力形式產生。等張收縮則是張力穩定而肌肉縮短，例如提起茶杯。拮抗收縮與被動收縮都不是課文用來描述這種情況的術語。","source":"第六章 6.2.1 E 等長和等張收縮","chId":"ch06"},{"id":"q0607","ch":6,"level":2,"type":"multi","style":"concept","q":"關於肌肉疲勞，下列哪些正確？（選 2–3 項）","options":["疲勞是因為肌纖維數目即時減少","ATP 與肝醣儲存耗盡也可導致疲勞","乳酸堆積在運動中的肌肉會促成疲勞","疲勞時蛋白質會最先被分解供能","氧氣供應不足時改用厭氧代謝，產生乳酸"],"answer":[1,2,4],"explain":"氧氣不足時身體改用效能較差的厭氧代謝，乳酸堆積促成疲勞；ATP 與肝醣耗盡亦可致疲勞。肌纖維數目不會即時減少，疲勞是供應與代謝問題；蛋白質只在脂肪與碳水化合物供應耗盡後才可能被利用，不是最先分解。","source":"第六章 6.2.1 B 肌肉疲勞","chId":"ch06"},{"id":"q0608","ch":6,"level":2,"type":"multi","style":"concept","q":"下列哪些肌肉收縮時會關閉下頜（嘴巴）？","options":["顳肌","咬肌","口輪匝肌","頰肌","翼狀肌"],"answer":[0,1,4],"explain":"咬肌、顳肌、翼狀肌都能關閉下頜：咬肌上提下頜、顳肌關閉嘴巴並協助咀嚼、翼狀肌關閉嘴巴並把下巴向前拉。頰肌是把頰壓向牙齒、協助排出空氣；口輪匝肌關閉的是嘴唇，不是下頜。","source":"第六章 6.1.1 A 面部肌肉","chId":"ch06"},{"id":"q0609","ch":6,"level":3,"type":"single","style":"case","q":"個案：男子跌倒後肩膀無力，手臂無法向側面抬起（外展）。最可能受傷的是哪條肌肉？","options":["胸大肌","背闊肌","肱二頭肌","三角肌"],"answer":[3],"explain":"三角肌中部（主要部分）負責肩關節外展，受傷時手臂難以向側抬起。胸大肌做屈曲與內收；背闊肌做伸展、內收與內旋；肱二頭肌主要屈肘與旋後，並協助穩定肩關節，三者都不主導外展。","source":"第六章 6.1.4 肩部和上肢的肌肉","chId":"ch06"},{"id":"q0610","ch":6,"level":3,"type":"multi","style":"concept","q":"下列哪些肌肉同時收縮時，可使手臂伸展、內收並向內旋轉？","options":["胸大肌","肱肌","三角肌前部","大圓肌","背闊肌"],"answer":[3,4],"explain":"背闊肌與大圓肌都能伸展、內收和內旋手臂，兩者都附著於肱骨，是把手向後、向內拉的代表。胸大肌是屈曲與內收；三角肌前部負責屈曲；肱肌是肘屈肌，三者都不做伸展。只選一條會漏掉另一個協同肌。","source":"第六章 6.1.2 A 背部肌肉","chId":"ch06"},{"id":"q0611","ch":6,"level":3,"type":"multi","style":"concept","q":"關於呼吸肌，下列哪些正確？（選 2–3 項）","options":["腰方肌收縮會使下方肋骨下降以協助吸氣","橫膈膜收縮時向下變平，增加胸腔體積","強迫吸氣時胸鎖乳突肌可上提胸骨與鎖骨","腹直肌是平靜吸氣的主要肌肉","肋間肌收縮把肋骨向上向外拉"],"answer":[1,2,4],"explain":"橫膈膜收縮向下變平、肋間肌收縮把肋骨向上向外拉，兩者同時增加胸腔容積；強迫吸氣時胸鎖乳突肌可上提胸骨與鎖骨。腹直肌屬腹壁肌，主要在用力呼氣與咳嗽時參與；腰方肌是固定下方肋骨，不是把它下降。","source":"第六章 6.1.2 C 胸廓的肌肉；第九章 9.3 呼吸機制","chId":"ch06"},{"id":"q0612","ch":6,"level":3,"type":"multi","style":"case","q":"馬拉松後肌肉需要恢復。下列哪些是課文所述的恢復過程？","options":["修復受損的肌肉纖維","以蛋白質取代所有碳水化合物儲存","在氧氣負債期間把過多乳酸轉為丙酮酸","補充 ATP 與肝醣儲存","即時增加肌纖維數目以抵銷損傷"],"answer":[0,2,3],"explain":"運動後肌肉要補充 ATP 與肝醣、修復受損纖維；氧氣負債期間身體把過多乳酸轉為丙酮酸並更新能量儲存。肌纖維數目不會因一次馬拉松而增加（肥大是纖維尺寸變大）；蛋白質也不是取代碳水化合物的儲存形式。","source":"第六章 6.2.1 C 肌肉恢復","chId":"ch06"},{"id":"q0701","ch":7,"level":1,"type":"single","style":"concept","q":"神經元中哪個構造主要負責接收訊息，並把訊息傳向細胞體？","options":["樹突","突觸終末","髓鞘","軸突"],"answer":[0],"explain":"樹突短而多分支，表面積大，專門接收來自其他神經元或感受器的訊息，再傳向細胞體。軸突是把衝動由細胞體傳出的單一條長纖維，方向剛好相反，是最常見的倒轉陷阱；髓鞘只是包在軸突外的脂質絕緣層，負責加快傳導；突觸終末位於軸突末端，負責釋放傳導物質。記住「樹突入、軸突出」。","source":"第七章從略；標準入門：神經元構造（對應第十六章16.1興奮性與傳導性）","chId":"ch07"},{"id":"q0702","ch":7,"level":1,"type":"single","style":"concept","q":"反射弧中，實際執行反應的構造是哪一站？","options":["感覺神經元","效應器","整合中樞","感受器"],"answer":[1],"explain":"效應器是反射弧的終站，收到運動神經元的指令後執行反應，可以是骨骼肌、平滑肌、心肌或腺體。感受器是起點，負責偵測刺激；感覺神經元把衝動傳入；整合中樞（脊髓或腦）決定要不要反應。考生常把「效應器」與「感受器」對調，或以為效應器一定是肌肉，忽略了腺體也是效應器。","source":"第七章從略；標準入門：反射弧五個組成部分","chId":"ch07"},{"id":"q0703","ch":7,"level":1,"type":"single","style":"concept","q":"副交感神經興奮時，下列哪項是典型效應？","options":["心跳加快","瞳孔放大","心跳減慢","細支氣管擴張"],"answer":[2],"explain":"副交感神經主「休息與消化」，使心跳減慢、心肌收縮力減弱，並促進胃腸蠕動和排尿。瞳孔放大、心跳加快和細支氣管擴張都是交感神經在「戰鬥或逃跑」時的效應，方向剛好相反。這題的三個干擾項都屬交感效應，只要把兩支的功能成對記住，就不會被單一「興奮」字眼誤導。","source":"第七章從略；標準入門：自主神經系統（對應第十六章16.4.1）","chId":"ch07"},{"id":"q0704","ch":7,"level":2,"type":"single","style":"concept","q":"有髓鞘的軸突傳導衝動比無髓鞘者快，主要原因為何？","options":["傳導物質釋放較多","突觸數目較多","衝動的幅度較大","衝動在蘭氏結之間跳躍傳導"],"answer":[3],"explain":"髓鞘是脂質絕緣層，離子只能在髓鞘中斷處（蘭氏結）交換，所以衝動逐結跳躍前進，速度大增。衝動幅度由「全或無」定律決定，不因髓鞘而變大；突觸數目多反而增加傳遞延遲，不會加快同一條纖維的傳導；傳導物質多少影響突觸傳遞強弱，與軸突傳導速度無直接關係。","source":"第七章從略；標準入門：髓鞘與跳躍傳導","chId":"ch07"},{"id":"q0705","ch":7,"level":2,"type":"single","style":"concept","q":"刺激強度已達閾值後再繼續增強，神經衝動會如何改變？","options":["衝動的頻率增加","每個衝動的幅度增大","髓鞘增厚以加速","傳導方向反轉"],"answer":[0],"explain":"動作電位遵循「全或無」：一旦達到閾值，每個衝動的幅度就固定，刺激再強也不會令單一衝動變大，只會令衝動產生的頻率增加，中樞便以此判斷刺激強弱。方向由樹突→細胞體→軸突固定，不會反轉；髓鞘厚度是解剖結構，不會即時因刺激而改變。把「更強刺激＝更大衝動」當成正確，是最典型的誤解。","source":"第七章從略；標準入門：動作電位的全或無定律","chId":"ch07"},{"id":"q0706","ch":7,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於反射弧的組成部分？（選出2–3項）","options":["髓鞘","突觸小泡","運動神經元","效應器","感受器"],"answer":[2,3,4],"explain":"反射弧五站是感受器、感覺神經元、整合中樞、運動神經元和效應器，本題正確項為感受器、運動神經元和效應器。突觸小泡是突觸終末內儲存傳導物質的胞器，髓鞘是軸突外的絕緣層，兩者都是神經元內部的構造，不是反射弧的「站」。分辨方法是問「這是不是路徑上傳遞或執行訊息的一個環節」，而不是「是否與神經有關」。","source":"第七章從略；標準入門：反射弧五個組成部分","chId":"ch07"},{"id":"q0707","ch":7,"level":3,"type":"single","style":"case","q":"學生敲打髕韌帶測試膝反射，若該反射弧的感覺神經元被阻斷，最可能出現什麼結果？","options":["小腿仍會前踢，但病人沒有感覺","小腿完全不會前踢","小腿前踢幅度反而變大","只有對側小腿失去反應"],"answer":[1],"explain":"反射弧必須完整，任何一站斷開都無法完成。感覺神經元負責把肌腱被拉長的訊息傳入脊髓，斷了就沒有衝動傳到整合中樞，運動神經元不會被激活，所以不會前踢。「仍能踢但沒有感覺」是感覺上行路徑受阻、反射弧仍完整的情況，屬不同層次的陷阱；反射弧是單側同側進行的，不會只影響對側。","source":"第七章從略；標準入門：反射弧完整性（對應第十六章16.4脊髓反射）","chId":"ch07"},{"id":"q0708","ch":7,"level":3,"type":"multi","style":"case","q":"交感神經被強烈激活時，下列哪些效應會出現？（選出2–3項）","options":["瞳孔放大","細支氣管擴張","胃腸蠕動增加","心跳加快","膀胱內括約肌放鬆"],"answer":[0,1,3],"explain":"交感＝戰鬥或逃跑：虹膜輻射肌收縮令瞳孔放大、細支氣管平滑肌放鬆令氣道擴張、竇房結被加速令心跳加快。相反，胃腸蠕動和分泌被抑制而非增加；膀胱壁放鬆而內括約肌收緊，是抑制排尿而非放鬆括約肌。後兩項其實是副交感的效應，把它們當成交感是本章最常見的對調陷阱。","source":"第七章從略；標準入門：交感與副交感的對比（對應第十六章16.4.1）","chId":"ch07"},{"id":"q0709","ch":7,"level":3,"type":"single","style":"case","q":"考生進入試場前心跳加速、手心出汗、瞳孔放大，此時最主要由哪個系統主導？","options":["只由脊髓反射控制","軀體運動神經系統","交感神經系統","副交感神經系統"],"answer":[2],"explain":"恐懼和壓力激發交感神經，並刺激腎上腺髓質分泌腎上腺素和正腎上腺素，形成「戰鬥或逃跑」：心跳加快、出汗、瞳孔放大。副交感是休息與消化，效應方向相反；軀體運動神經只支配隨意骨骼肌，不能解釋瞳孔和出汗；這些反應由下丘腦協調，不是單靠脊髓反射。","source":"第七章從略；標準入門：交感神經與壓力反應（對應第十六章16.4.1）","chId":"ch07"},{"id":"q0801","ch":8,"level":1,"type":"single","style":"concept","q":"身體質量指數（BMI）的計算方式是？","options":["身高²（m²）÷體重（kg）","體重（kg）÷身高（cm）","體重（kg）×身高²（m²）","體重（kg）÷身高²（m²）"],"answer":[3],"explain":"BMI＝體重（kg）÷身高²（m²），身高必須以米為單位。用 cm 直接代入會把數值放大多倍；把公式倒轉或相乘，都會得出錯誤分類，這是計算題最常見的失分位。記住分子是體重、分母是身高的平方。","source":"第八章 8.1 C 肥胖症（表 8.4）","chId":"ch08"},{"id":"q0802","ch":8,"level":1,"type":"single","style":"concept","q":"兒童缺乏維他命 D 會導致什麼疾病？","options":["佝僂病","夜盲症","壞血病","軟骨病"],"answer":[0],"explain":"維他命 D 促進鈣與磷酸鹽吸收，兒童缺乏造成佝僂病，成人缺乏則為軟骨病。夜盲症屬維他命 A 缺乏；壞血病屬維他命 C 缺乏；腳氣病屬維他命 B1 缺乏，與 D 無關。","source":"第八章 8.1 表 8.1 脂溶性維他命","chId":"ch08"},{"id":"q0803","ch":8,"level":1,"type":"single","style":"concept","q":"嚴重缺乏維他命 C 會引起什麼疾病？","options":["糙皮病","壞血病","腳氣病","惡性貧血"],"answer":[1],"explain":"維他命 C（抗壞血酸）參與膠原蛋白形成，嚴重缺乏引起壞血病，表現為多發性出血、傷口癒合緩慢與貧血。腳氣病是 B1 缺乏；糙皮病是 B3 缺乏；惡性貧血是 B12 缺乏。","source":"第八章 8.1 表 8.2 水溶性維他命","chId":"ch08"},{"id":"q0804","ch":8,"level":1,"type":"single","style":"concept","q":"下列哪一種是脂溶性維他命？","options":["維他命 B1","維他命 B12","維他命 A","維他命 C"],"answer":[2],"explain":"維他命 A 屬脂溶性，與 D、E、K 一同需要膽汁協助吸收，礦物油會阻礙吸收。B1、B12 與 C 都屬水溶性，不會與脂溶性維他命同組；把它們混在一起記，最容易在分類題失分。","source":"第八章 8.1 表 8.1 與表 8.2","chId":"ch08"},{"id":"q0805","ch":8,"level":2,"type":"single","style":"concept","q":"缺乏哪一種維他命會導致巨胚紅血球性貧血及脊髓神經纖維退化？","options":["維他命 B1","葉酸","維他命 C","維他命 B12"],"answer":[3],"explain":"維他命 B12（鈷胺素）參與 DNA 合成，缺乏造成巨胚紅血球性貧血，並可致脊髓神經纖維退化；惡性貧血正是 B12 缺乏最常見的形式。葉酸也參與 DNA 合成，但課文列出的脊髓退化對應 B12；B1 與 C 的缺乏症完全不同。","source":"第八章 8.1 表 8.2 水溶性維他命","chId":"ch08"},{"id":"q0806","ch":8,"level":2,"type":"single","style":"concept","q":"脂溶性維他命的吸收需要下列哪一種物質協助？","options":["膽汁","內在因子","胰島素","胃酸"],"answer":[0],"explain":"脂溶性維他命隨脂肪一起吸收，需要膽汁乳化；礦物油會阻礙它們的吸收。胃酸與胰島素都不是脂溶性維他命吸收的條件；內在因子是吸收維他命 B12 所需，而 B12 屬水溶性。","source":"第八章 8.1 表 8.1 脂溶性維他命","chId":"ch08"},{"id":"q0807","ch":8,"level":2,"type":"multi","style":"concept","q":"關於蛋白質—能量營養失調（PEM），下列哪些正確？（選 2–3 項）","options":["是蛋白質、碳水化合物與脂肪攝取不足的結果","創傷、發燒或疾病增加需求時可出現","嬰兒和小孩尤其易受影響","只涉及單一種維他命缺乏","只會發生在成年人身上"],"answer":[0,1,2],"explain":"PEM 是蛋白質、碳水化合物與脂肪攝取不足，長期飢餓或創傷、發燒、疾病令需求增加時出現，嬰幼兒因生長發育需求大而尤其易受影響。它不是單一維他命缺乏，也不是只發生在成人；缺乏維他命可與 PEM 同時出現，是合併而非替代。","source":"第八章 8.1 A 營養失調","chId":"ch08"},{"id":"q0808","ch":8,"level":2,"type":"multi","style":"concept","q":"課文指出肥胖使病人傾向下列哪些併發症？","options":["惡性貧血","骨關節炎","膽石","肺氣腫","II 型糖尿病"],"answer":[1,2,4],"explain":"肥胖傾向膽石、缺血性心臟病與高血壓、II 型糖尿病、骨關節炎，以及疝氣和靜脈曲張。惡性貧血是維他命 B12 吸收問題；肺氣腫屬呼吸系統疾病，課文沒有把它列為肥胖的併發症。","source":"第八章 8.1 C 肥胖症","chId":"ch08"},{"id":"q0809","ch":8,"level":3,"type":"single","style":"case","q":"個案：男子身高 1.6 m、體重 80 kg。按表 8.4 的標準，他的 BMI 分類是？","options":["嚴重肥胖","肥胖","過重","正常"],"answer":[1],"explain":"BMI＝80÷1.6²＝80÷2.56≈31.25。表 8.4 以 ≥30 為肥胖，30–39.9 屬肥胖 class I，故屬肥胖而非過重；過重是 25–29.9。若只記住正文「超過 31」也同樣落入肥胖，但計算與分類仍應以表 8.4 為準。","source":"第八章 8.1 C 肥胖症（表 8.4）","chId":"ch08"},{"id":"q0810","ch":8,"level":3,"type":"single","style":"case","q":"個案：幼童腹部脹大、下肢水腫、肝臟受損，皮膚與毛髮色素減退。最可能是下列哪一種營養問題？","options":["壞血病","佝僂病","瓜西奧科兒症（kwashiorkor）","消瘦（marasmus）"],"answer":[2],"explain":"瓜西奧科兒症以蛋白質缺乏為主：血漿蛋白下降導致腹水與下肢水腫，水腫掩飾了消瘦，肝臟嚴重受損，皮膚毛髮色素減退。消瘦是蛋白質與碳水化合物同時缺乏，以嚴重消瘦、皮膚皺縮、頭髮脫落為主，沒有典型水腫。","source":"第八章 8.1 A 營養失調（蛋白質能量營養失調）","chId":"ch08"},{"id":"q0811","ch":8,"level":3,"type":"single","style":"case","q":"個案：長者跌倒骨折後癒合緩慢，飲食中礦物質吸收欠佳。課文所述哪一種組織鹽與骨骼、牙齒的主要礦物成分相應？","options":["硫酸鈣（Calc sulph）","磷酸鎂（Mag phos）","氟化鈣（Calc fluor）","磷酸鈣（Calc phos）"],"answer":[3],"explain":"磷酸鈣（Calc phos）是骨骼、指甲與牙齒的主要礦物成分，缺乏時骨折修復不良、礦物質吸收差。氟化鈣主彈性，對應靜脈曲張、脆甲；磷酸鎂是抗痙攣與神經鬆弛劑；硫酸鈣則與肝臟及皮膚問題相關。","source":"第八章 8.2 健康的肌肉—骨骼系統","chId":"ch08"},{"id":"q0812","ch":8,"level":3,"type":"multi","style":"concept","q":"關於骨骼基質的建構，下列哪些正確？（選 2–3 項）","options":["鎂是建構骨骼基質所需的礦物質之一","維他命 K 參與骨骼基質的建構","單獨大量服用鈣片足以預防骨質疏鬆","維他命 B12 是骨骼的主要結構成分","維他命 D 促進鈣與磷酸鹽的吸收"],"answer":[0,1,4],"explain":"鎂、維他命 D、維他命 K 都參與建構骨骼基質，維他命 D 還促進鈣與磷酸鹽吸收。課文明言單獨大量補鈣不能預防骨質疏鬆，反而可能令身體負荷無法溶解的鈣鹽；維他命 B12 參與 DNA 合成，不是骨骼的主要結構成分。","source":"第八章 8.2 健康的肌肉—骨骼系統","chId":"ch08"},{"id":"q0901","ch":9,"level":1,"type":"single","style":"concept","q":"氣體交換主要在哪裡進行？","options":["肺泡","支氣管","喉頭","氣管"],"answer":[0],"explain":"肺泡是支氣管反覆分支後形成的單層空氣囊，壁只有一層鱗狀上皮，外圍包著毛細血管，兩者合成呼吸膜，氣體在此擴散。氣管、支氣管與喉頭屬傳送空氣的通道，壁太厚，不能進行氣體交換。","source":"第九章 9.2 呼吸系統的構成部份","chId":"ch09"},{"id":"q0902","ch":9,"level":1,"type":"single","style":"concept","q":"下列哪一個器官屬於上呼吸道？","options":["肺臟","喉頭","主支氣管","氣管"],"answer":[1],"explain":"上呼吸道由鼻、咽部與喉頭構成；下呼吸道由氣管、兩條主支氣管與兩個肺臟組成。氣管與支氣管雖是通道，但屬下呼吸道；肺臟亦屬下呼吸道。判斷的關鍵是「喉頭以上」與「氣管以下」的分界。","source":"第九章 9.2 呼吸系統的構成部份","chId":"ch09"},{"id":"q0903","ch":9,"level":1,"type":"single","style":"concept","q":"吞嚥時覆蓋氣管、防止食物掉入呼吸道的結構是？","options":["隆突","聲帶","會厭","軟顎"],"answer":[2],"explain":"會厭是附著於甲狀軟骨的葉狀彈性纖維軟骨；吞嚥時喉頭上升、會厭覆蓋氣管，確保食物進入食道。聲帶負責發聲，軟顎負責分隔鼻咽與口咽，隆突是氣管分叉處的咳嗽觸發點，都不負責封閉氣管。","source":"第九章 9.2 呼吸系統的構成部份／9.2.3 喉頭","chId":"ch09"},{"id":"q0904","ch":9,"level":1,"type":"single","style":"concept","q":"右肺被分為幾個肺葉？","options":["四個","一個","兩個","三個"],"answer":[3],"explain":"右肺分上、中、下三葉；左肺因心臟佔去左側空間，只有上、下兩葉。右支氣管也因較短、較闊、較垂直，成為異物較易墮入的一側。把左右肺葉數目對調，是最常見的失分位；記住「左二右三」。","source":"第九章 9.2.5 肺臟","chId":"ch09"},{"id":"q0905","ch":9,"level":2,"type":"single","style":"concept","q":"吸氣時，胸腔與肺泡內的壓力如何變化？","options":["胸腔壓降至低於大氣壓，肺泡內壓下降，空氣入肺","胸腔壓不變，靠肺主動擴張吸入空氣","肺泡內壓上升，空氣被吸入","胸腔壓上升至高於大氣壓，空氣被推入肺"],"answer":[0],"explain":"吸氣時肋間肌與橫膈膜收縮使胸腔容積增加，胸腔內壓降至低於大氣壓，壁層肋膜拉動肺，肺泡內壓下降，空氣於是被拉入肺。壓力上升才把空氣推入的說法與事實相反；肺本身沒有主動擴張的能力，靠的是胸腔與肋膜的機械連結。","source":"第九章 9.3.1 呼吸週期 A 吸氣","chId":"ch09"},{"id":"q0906","ch":9,"level":2,"type":"single","style":"concept","q":"平靜呼氣為何被形容為被動過程？","options":["橫膈膜強力收縮把空氣推出","肋間肌與橫膈膜放鬆，肺靠彈性回縮","腹肌強力收縮把空氣壓出","聲門關閉後空氣被擠出"],"answer":[1],"explain":"平靜呼氣是被動的：肋間肌與橫膈膜放鬆，肋骨下移內收，肺靠自身彈性回縮，肺泡內壓高於大氣，空氣排出。腹肌收縮屬用力呼氣；橫膈膜在呼氣時是放鬆而非強力收縮；聲門關閉是咳嗽反射的一部分，不是平靜呼氣的機制。","source":"第九章 9.3.1 呼吸週期 B 呼氣","chId":"ch09"},{"id":"q0907","ch":9,"level":2,"type":"multi","style":"concept","q":"關於平靜吸氣，下列哪些正確？（選 2–3 項）","options":["聲門緊閉以增加胸腔負壓","橫膈膜收縮向下變平","外肋間肌收縮把肋骨向上向外拉","腹肌強力收縮協助吸氣","胸腔容積增加，空氣被拉入肺"],"answer":[1,2,4],"explain":"吸氣的主動力量來自橫膈膜收縮向下變平，以及外肋間肌收縮把肋骨向上向外拉，兩者令胸腔容積增加、壓力下降。腹肌收縮與聲門關閉屬用力呼氣與咳嗽的動作，不會在平靜吸氣時出現。","source":"第九章 9.3 呼吸機制","chId":"ch09"},{"id":"q0908","ch":9,"level":2,"type":"multi","style":"concept","q":"右支氣管具有下列哪些特徵？","options":["較短","較窄","較垂直","較闊","較長"],"answer":[0,2,3],"explain":"右支氣管較闊、較短、較垂直，因此異物較易墮入右肺；它約長 2.5 cm，入肺後分三個分支進入三葉。左支氣管較窄、較長（約 5 cm），並非右支氣管的特徵；兩者大小不同是為了在縱隔容納心臟。","source":"第九章 9.2.6 支氣管和小支氣管","chId":"ch09"},{"id":"q0909","ch":9,"level":3,"type":"single","style":"case","q":"個案：早產嬰兒出生後呼吸困難，肺泡不穩定地打開甚至塌陷。最可能缺乏什麼？","options":["氣管軟骨環","肋膜漿液","肺表面活性劑","會厭軟骨"],"answer":[2],"explain":"肺表面活性劑由間隔細胞分泌，降低表面張力，防止呼氣時肺泡塌陷；約胎兒 35 週才足量，早產嬰兒分泌不足，肺泡不穩定地打開，造成嚴重呼吸問題。會厭、肋膜與軟骨的問題不會以「肺泡塌陷」為主要表現。","source":"第九章 9.2.7 呼吸性小支氣管和肺泡","chId":"ch09"},{"id":"q0910","ch":9,"level":3,"type":"single","style":"case","q":"個案：一側胸腔被刺穿，空氣進入肋膜腔。該側肺最可能出現什麼變化？","options":["氣管立即完全閉合","表面活性劑消失而肺泡擴大","因壓力上升而過度膨脹","因彈性回縮而塌陷"],"answer":[3],"explain":"肋膜腔是潛在空間，兩層肋膜靠漿液與表面張力貼合；一旦被刺穿，空氣進入，貼合失效，肺因其彈性回縮而塌陷。肺不會過度膨脹；氣管不會立即閉合；表面活性劑仍在肺泡內，只是肺泡失去維持擴張的機械條件。","source":"第九章 9.2.5 B 肋膜和肋膜腔","chId":"ch09"},{"id":"q0911","ch":9,"level":3,"type":"single","style":"concept","q":"潮氣量 500 ml、解剖性無效腔 150 ml、呼吸速率 15 次／分，肺泡換氣是多少？","options":["5.25 L／分鐘","4.5 L／分鐘","7.5 L／分鐘","6.75 L／分鐘"],"answer":[0],"explain":"肺泡換氣＝（潮氣量－解剖性無效腔）×呼吸速率＝（500－150）×15＝350×15＝5250 ml，即 5.25 L/min。直接 500×15＝7.5 L/min 是沒有扣除無效腔的常見錯誤；其餘數值不對應任何正確組合。","source":"第九章 9.3.3 肺部各種容量及容積","chId":"ch09"},{"id":"q0912","ch":9,"level":3,"type":"multi","style":"concept","q":"關於呼吸的調節與防禦反射，下列哪些正確？（選 2–3 項）","options":["呼吸中樞位於小腦","血氧下降是調節呼吸的唯一因素","咳嗽衝動經迷走神經傳到腦幹呼吸中樞","血液二氧化碳濃度改變可改變呼吸","呼吸中樞位於腦幹"],"answer":[2,3,4],"explain":"呼吸中樞位於腦幹，咳嗽反射的衝動經迷走神經傳到腦幹呼吸中樞，再引發深吸氣、聲門關閉與爆發呼氣；血液二氧化碳濃度改變也可改變呼吸。呼吸中樞不在小腦；調節呼吸的因素不只血氧，二氧化碳與多種反射同樣重要。","source":"第九章 9.2.4 氣管（咳嗽反射）；9.3.4 氣體交換","chId":"ch09"},{"id":"q1001","ch":10,"level":1,"type":"single","style":"concept","q":"心臟的主起搏器（pacemaker）是？","options":["蒲金氏纖維","竇房結","房室束","房室結"],"answer":[1],"explain":"竇房結位於右心房壁近上腔靜脈開口，是主起搏器，因為它比其餘特化細胞更快啟動衝動，引起心房收縮。房室結是次要起搏器並負責延遲；房室束與蒲金氏纖維只負責傳導，不會自行決定心跳節律。","source":"第十章 10.1.1 A 竇房結","chId":"ch10"},{"id":"q1002","ch":10,"level":1,"type":"single","style":"concept","q":"右心房與右心室之間的瓣膜是？","options":["肺動脈半月瓣","主動脈半月瓣","三尖瓣","二尖瓣"],"answer":[2],"explain":"右心房與右心室之間是三尖瓣，左心房與左心室之間是二尖瓣，兩者都是單向房室瓣，防止血液倒流。半月瓣位於肺動脈與主動脈出口，不是房室之間的瓣膜；主動脈半月瓣在左心室出口，位置與三尖瓣不同。","source":"第十章 10.1 心臟內部的基礎結構","chId":"ch10"},{"id":"q1003","ch":10,"level":1,"type":"single","style":"concept","q":"心臟哪一個腔室的肌肉壁最厚？","options":["左心房","右心房","右心室","左心室"],"answer":[3],"explain":"左心室要把血液經主動脈泵至全身，阻力最大，所以心肌壁最厚；右心室只把血液泵到鄰近的肺，壁薄得多。心房主要接收血液，壁更薄，並非以厚度見稱。腔壁厚度反映的是「泵血距離與阻力」，不是腔室大小。","source":"第十章 10.1 心臟內部的基礎結構","chId":"ch10"},{"id":"q1004","ch":10,"level":1,"type":"single","style":"concept","q":"心搏週期三個階段的先後次序是？","options":["心房收縮→心室收縮→心房與心室完全舒張","心室收縮→心房收縮→完全舒張","心房舒張→心室舒張→心房收縮","心房與心室同時收縮→舒張"],"answer":[0],"explain":"心搏週期依序為心房收縮、心室收縮、心房與心室完全舒張；房室結延遲 0.1 秒正是為了讓心房先收縮完成。其餘次序都把心室收縮放在心房收縮之前，或把舒張放在收縮之前，與課文不符。","source":"第十章 10.3 心搏週期","chId":"ch10"},{"id":"q1005","ch":10,"level":2,"type":"single","style":"concept","q":"房室結把衝動延遲約 0.1 秒，主要目的為何？","options":["降低整體心跳速率","讓心房在心室收縮前完成收縮","讓蒲金氏纖維先放電","防止血液由心室倒流至心房"],"answer":[1],"explain":"房室結的 0.1 秒延遲是為了讓心房在心室開始收縮前完成收縮，使血液充分流入心室。延遲不是為了減慢整體心跳（心跳速率主要由竇房結決定），也不是防止血液倒流（那是瓣膜的功能）。","source":"第十章 10.1.1 B 房室結","chId":"ch10"},{"id":"q1006","ch":10,"level":2,"type":"single","style":"concept","q":"肺循環的路徑是？","options":["左心室→主動脈→肺→腔靜脈→右心房","左心房→肺動脈→肺→肺靜脈→左心室","右心室→肺動脈→肺→肺靜脈→左心房","右心房→肺動脈→肺→肺靜脈→右心室"],"answer":[2],"explain":"肺循環由右心室把缺氧血送入肺動脈，經肺毛細血管換氣後，由肺靜脈把帶氧血送回左心房。體循環則由左心室經主動脈到全身，再經腔靜脈回右心房；把兩者的起點或終點對調，是最常見的錯誤。","source":"第十章 10.2 循環系統","chId":"ch10"},{"id":"q1007","ch":10,"level":2,"type":"multi","style":"concept","q":"關於冠狀動脈，下列哪些正確？（選 2–3 項）","options":["只有兩條，供應肺臟","共有四條，走在心臟表面","搭橋手術常取腿部靜脈反向使用","起源於肺動脈","是主動脈的第一個分支"],"answer":[1,2,4],"explain":"冠狀動脈是主動脈的第一個分支，走在心臟表面，共四條，供應心肌本身；搭橋手術常取腿部靜脈反向使用，正因為靜脈內有瓣膜。它不起源於肺動脈，也不只兩條，若只有兩條會令心肌得不到足夠血液。","source":"第十章 10.2 循環系統","chId":"ch10"},{"id":"q1008","ch":10,"level":2,"type":"multi","style":"concept","q":"關於心臟的自主神經供應，下列哪些正確？（選 2–3 項）","options":["副交感神經興奮降低脈衝速率與心跳力量","迷走神經供應竇房結、房室結及心房肌","交感神經興奮增加心跳速率與力量","副交感神經興奮會加快心跳","交感神經只供應心房肌，不供應心室"],"answer":[0,1,2],"explain":"迷走神經（副交感）供應竇房結、房室結與心房肌，興奮時降低脈衝速率與心跳力量；交感神經供應竇房結、房室結及心房與心室心肌，興奮時增加速率與力量。交感不是只供應心房，副交感也不會加快心跳。","source":"第十章 10.1.1 C 心臟的神經供應","chId":"ch10"},{"id":"q1009","ch":10,"level":3,"type":"single","style":"case","q":"按課文，新生嬰兒出生後持續發紺、聽診有心雜音，最可能與下列哪一項有關？","options":["冠狀動脈狹窄","心包積液","二尖瓣倒流","卵圓孔未閉合"],"answer":[3],"explain":"課文把新生兒發紺與心雜音連到卵圓孔未閉合或閉合不全：胎兒期卵圓孔讓血液繞過肺，出生時通常關閉；未閉合時課文說可致發紺，邊緣渦流則產生心雜音。二尖瓣倒流、心包積液與冠狀動脈狹窄都不是課文用來解釋這個組合的構造。","source":"第十章 10.1 卵圓孔與胎兒循環","chId":"ch10"},{"id":"q1010","ch":10,"level":3,"type":"single","style":"case","q":"個案：病人竇房結功能衰退，由房室結接手起搏，心跳反而比原來慢。原因為何？","options":["房室結的固有激活速率較慢","迷走神經被切斷","蒲金氏纖維完全沒有傳導能力","房室結的 0.1 秒延遲變長"],"answer":[0],"explain":"竇房結受損時房室結可接手，但其固有激活速率比竇房結慢，所以心跳反而較慢；0.1 秒延遲只是傳導特性，不是速率較慢的原因。蒲金氏纖維負責傳導；迷走神經被切斷會令心跳加快，兩者都不能解釋。","source":"第十章 10.1.1 B 房室結","chId":"ch10"},{"id":"q1011","ch":10,"level":3,"type":"multi","style":"concept","q":"關於心電圖波形，下列哪些正確？（選 2–3 項）","options":["T 波：心房收縮","QRS 複合波：衝動經房室結、房室束與蒲金氏纖維","P 波：竇房結衝動傳遍心房","T 波：心室放鬆","P 波：心室去極化"],"answer":[1,2,3],"explain":"P 波是竇房結衝動傳遍心房；QRS 複合波是衝動經房室結、房室束與蒲金氏纖維，引起心室去極化；T 波代表心室放鬆。把 P 波說成心室去極化、T 波說成心房收縮，是把三個波形的順序與意義對調。","source":"第十章 10.3.1 心臟內的電氣改變","chId":"ch10"},{"id":"q1012","ch":10,"level":3,"type":"multi","style":"case","q":"個案：長途飛行後小腿腫痛，被診斷為深層靜脈血栓。關於靜脈回流，下列哪些正確？","options":["長時間不活動可致血液積聚與血栓","靜脈沒有瓣膜，全靠心臟的吸力","小腿肌肉收縮可把血液向上推","靜脈血壓比動脈高，所以靜脈壁較厚","腿部靜脈有瓣膜，防止血液倒流"],"answer":[0,2,4],"explain":"腿部靜脈有瓣膜防止倒流，小腿肌肉收縮像泵一樣把血液向上推；長時間站立或不活動使這個泵失效，血液積聚，可致靜脈曲張，深層靜脈亦可能形成血栓。靜脈血壓遠低於動脈，所以靜脈壁較薄、肌肉層少，並非較厚。","source":"第十章 10.2 循環系統（靜脈回流）","chId":"ch10"},{"id":"q1101","ch":11,"level":1,"type":"single","style":"concept","q":"血液中，血漿約佔血容積的多少？","options":["約 90%","約 55%","約 7%","約 45%"],"answer":[1],"explain":"血漿約佔血容積 55%，各種細胞約佔 45%。7% 是血量佔體重的比例，不是血容積組成；90–92% 是血漿之中水份的比例。最常見的陷阱是把「血漿裡有九成水」直接當成「血漿佔九成血容積」，兩條百分比線要分清楚。","source":"第十一章 11.2 血液的組成成份","chId":"ch11"},{"id":"q1102","ch":11,"level":1,"type":"single","style":"concept","q":"下列哪種血漿蛋白數量最多，主要負責維持血漿滲透壓？","options":["纖維蛋白原","凝血酵素原","白蛋白","球蛋白"],"answer":[2],"explain":"白蛋白由肝製造、是數量最多的血漿蛋白，主職維持正常血漿滲透壓，並兼運脂質與類固醇荷爾蒙。球蛋白以抗體與運輸為主；纖維蛋白原是凝血原料；凝血酵素原是凝血系統的蛋白。陷阱是把「凝血因子」與「滲透壓」混為一談，其實兩者由不同蛋白負責。","source":"第十一章 11.2.1 血漿蛋白","chId":"ch11"},{"id":"q1103","ch":11,"level":1,"type":"single","style":"concept","q":"止血第一步中，令受損血管收縮的主要物質是？","options":["血小板釋出的 ADP","凝血酵素","嗜鹼性白血球釋出的肝素","血小板釋出的血清素"],"answer":[3],"explain":"血小板黏附受損血管壁後釋出血清素，令血管收縮；受損血管本身亦釋出血栓素。ADP 屬第二步，用來吸引更多血小板；凝血酵素在第三步凝血才出場；肝素是抗凝血劑，作用方向相反。陷阱是見到「血小板釋出」就選 ADP，忽略了題目問的是血管收縮。","source":"第十一章 11.3.2 止血：1. 血管收縮","chId":"ch11"},{"id":"q1104","ch":11,"level":1,"type":"single","style":"concept","q":"紅血球不能進行細胞分裂，最直接的原因是？","options":["沒有細胞核與細胞器","血紅蛋白佔滿整個細胞","壽命只有約 120 天","呈雙凹圓盤形"],"answer":[0],"explain":"紅血球沒有細胞核與細胞器，所以不能分裂、不能自行修補，壽命才只有約 120 天。雙凹形是增加表面積以利氣體交換；血紅蛋白是內容物，不是不能分裂的原因；120 天是結果而不是原因。陷阱正是把結果（壽命短）當成原因。","source":"第十一章 11.3 血液的細胞成份","chId":"ch11"},{"id":"q1105","ch":11,"level":2,"type":"multi","style":"concept","q":"關於血漿蛋白，下列哪些正確？（選 2–3 項）","options":["球蛋白包括由淋巴細胞產生的抗體","血漿蛋白可自由穿過毛細血管小孔進入組織","血漿蛋白下降會令血漿滲透壓上升","白蛋白可運送脂質與類固醇荷爾蒙","纖維蛋白原由肝合成，是凝血必需物質"],"answer":[0,3,4],"explain":"白蛋白既維持滲透壓亦運脂質與類固醇荷爾蒙；球蛋白包含抗體、運輸蛋白與酵素抑制劑；纖維蛋白原由肝合成，是凝血原料。血漿蛋白分子太大，正常不能穿過毛細血管小孔，所以才留在血管內形成滲透壓；蛋白下降時滲透壓是下降而非上升，液體反而走入組織。這兩個相反方向的敘述就是本題的陷阱。","source":"第十一章 11.2.1 血漿蛋白","chId":"ch11"},{"id":"q1106","ch":11,"level":2,"type":"single","style":"concept","q":"止血過程的正確次序是？","options":["凝血→血管收縮→血小板栓→纖維蛋白溶解","血管收縮→血小板栓→凝血→纖維蛋白溶解","血小板栓→血管收縮→凝血→纖維蛋白溶解","血管收縮→凝血→血小板栓→纖維蛋白溶解"],"answer":[1],"explain":"課文把止血分成四步：先血管收縮減少血流，再由血小板聚集形成臨時的血小板栓，然後凝血形成更強韌的纖維蛋白網，最後纖維蛋白溶解清除凝塊。把凝血放在血小板栓之前，等於跳過了立即封堵的步驟；把血小板栓放在血管收縮之前，則忽略了血清素令血管收窄這第一個反應。 陷阱是憑「先凝血才封口」的直覺排次序，忽略血小板栓才是即時封堵。","source":"第十一章 11.3.2 止血","chId":"ch11"},{"id":"q1107","ch":11,"level":2,"type":"multi","style":"concept","q":"比較凝血的外在途徑與內在途徑，下列哪些正確？（選 2–3 項）","options":["外在途徑由受損組織釋出組織因子啟動","內在途徑由血管內皮受損與血小板黏附啟動","外在途徑在數秒內發生","內在途徑比外在途徑快，數秒內完成","兩者不會同時發生，身體只會選其一"],"answer":[0,1,2],"explain":"外在途徑由循環以外的受損組織釋出組織因子（凝血酶原酶）啟動，數秒內完成；內在途徑局限於血循環內，由內皮受損與血小板黏附激發，需 3–6 分鐘。課文明言兩者通常一起發生，所以「只選其一」是錯的。最易失分是把快慢倒轉：慢的是內在，快的是外在。","source":"第十一章 11.3.2 血液凝結","chId":"ch11"},{"id":"q1108","ch":11,"level":2,"type":"single","style":"concept","q":"單核白血球離開血流進入組織後，會變成什麼細胞，並分泌哪種細胞激素？","options":["漿細胞；抗體","嗜中性白血球；溶小體","巨噬細胞；白細胞介素-1","巨噬細胞；組織胺"],"answer":[2],"explain":"單核白血球在血中擔任吞噬細胞，進入組織後變成巨噬細胞，並產生細胞激素白細胞介素-1（IL-1），參與炎症與免疫。漿細胞由 B 淋巴細胞分化，不是單核細胞；溶小體是嗜中性白血球的顆粒；組織胺主要由嗜鹼性白血球與肥大細胞釋出。陷阱是「巨噬細胞＋組織胺」這個似是而非的配對。","source":"第十一章 11.3 白血球","chId":"ch11"},{"id":"q1109","ch":11,"level":3,"type":"single","style":"case","q":"一名肝硬化病人血中白蛋白明顯下降，出現下肢水腫。最直接的解釋是？","options":["血小板不足，微血管持續滲血","血漿黏度上升，血流變慢","血紅蛋白不足，組織缺氧而積水","血漿滲透壓下降，液體由血管移入組織"],"answer":[3],"explain":"白蛋白是維持血漿滲透壓的主力；肝硬化令白蛋白製造減少，滲透壓下降，水便留不住而移入組織與體腔，形成水腫。血漿黏度雖受白蛋白影響，但黏度與水腫沒有直接因果；血紅蛋白負責運氧；血小板關乎止血。陷阱是見到「肝病」就想到凝血，忽略了蛋白與滲透壓這條線。","source":"第十一章 11.2.1 血漿蛋白與水腫","chId":"ch11"},{"id":"q1110","ch":11,"level":3,"type":"multi","style":"case","q":"一名第 8 因子缺乏的血友病患者拔牙後滲血不止。下列哪些正確？（選 2–3 項）","options":["第 8 因子是凝血所需，缺乏會令纖維蛋白網形成不足","初期形成的血小板栓比纖維蛋白凝塊弱，只能暫時封堵","凝血因子的編號等於它們參與凝血的先後次序","肝素由嗜中性白血球製造，可加速凝血","凝血酵素能促進自身製造，屬正回饋"],"answer":[0,1,4],"explain":"第 8 因子是凝血過程的一員，缺乏時纖維蛋白網不足，所以血友病患者危險；血小板栓只是臨時封印，強度遠不及纖維蛋白凝塊；課文亦指出凝血酵素對自身製造有強力促進作用，屬正回饋。編號代表被發現的順序而非作用次序；肝素由嗜鹼性白血球製造，而且是抗凝血，兩項都是典型干擾。","source":"第十一章 11.3 血小板與 11.3.2 凝血的控制","chId":"ch11"},{"id":"q1111","ch":11,"level":3,"type":"single","style":"remedy","q":"一名 30 歲女性因月經量多，血紅蛋白處於貧血邊緣。除硫酸鐵外，課文提到可考慮的順勢療法選項是？","options":["鐵鹽，例如磷酸鐵（Ferr phos）","球蛋白輸注","肝素（Heparin）","華法林（Warfarin）"],"answer":[0],"explain":"課文指出女性因月經或懷孕可令血紅蛋白天然偏低，硫酸鐵可矯正，若想要較溫和迅速的效果，可用順勢療法的鐵鹽：亞砷酸鐵、鐵與磷酸鐵。華法林是術後抗凝血藥物，肝素是天然抗凝血劑，兩者方向完全相反；球蛋白與免疫有關，不是補鐵。陷阱是見到「血液」就聯想到抗凝血藥。","source":"第十一章 11.3 紅血球與貧血","chId":"ch11"},{"id":"q1201","ch":12,"level":1,"type":"single","style":"concept","q":"以下哪項不屬於急性炎症的五大徵象？","options":["紅","黃疸","喪失功能","熱"],"answer":[1],"explain":"急性炎症五大徵象是紅、熱、痛、腫脹與喪失功能。黃疸是膽紅素過高令皮膚與鞏膜發黃，屬肝膽問題，不是炎症的局部徵象。這題的陷阱是「紅」與「黃」都屬於顏色變化，但炎症的紅來自血流增加，黃疸來自膽紅素沉積，兩者機制完全不同。","source":"第十二章 12.2 炎症反應","chId":"ch12"},{"id":"q1202","ch":12,"level":1,"type":"single","style":"concept","q":"急性炎症中，最先大量進入感染部位的吞噬細胞是？","options":["嗜鹼性白血球","漿細胞","嗜中性白血球","嗜酸性白血球"],"answer":[2],"explain":"課文明言在急性階段最重要的白血球是嗜中性白血球，牠們黏附血管內層、穿過內皮進入組織吞噬抗原，死亡後構成膿液的主要成分。嗜酸性主攻寄生蟲與過敏；嗜鹼性釋出組織胺與肝素；漿細胞負責分泌抗體而非吞噬。陷阱是以為「巨噬細胞」一定最先到，其實巨噬細胞約 24 小時後才成主力。","source":"第十二章 12.2.1 白血球的移動","chId":"ch12"},{"id":"q1203","ch":12,"level":1,"type":"single","style":"concept","q":"T 淋巴細胞在哪個器官成熟，並學會分辨自身與外來組織？","options":["脾臟","淋巴結","紅骨髓","胸腺"],"answer":[3],"explain":"淋巴細胞源自紅骨髓的多能幹細胞，進入胸腺後發展為成熟的 T 淋巴細胞，並能區分自身與外來組織。骨髓是 B 淋巴細胞被活化／加工的地方；脾臟與淋巴結是成熟淋巴細胞聚集與反應的場所，不是 T 細胞成熟之處。陷阱是把「製造」與「成熟」都放在骨髓。","source":"第十二章 12.3.3 胸腺","chId":"ch12"},{"id":"q1204","ch":12,"level":1,"type":"single","style":"concept","q":"人體最大的淋巴器官是？","options":["脾臟","扁桃腺","胸腺","淋巴結"],"answer":[0],"explain":"脾臟含網狀組織與淋巴組織，是最大的淋巴器官，位於腹腔左季肋區、胃底與橫膈之間。胸腺在青春期最重也只有 30–40g；扁桃腺屬黏膜相關淋巴組織；淋巴結最大的也不過杏仁大小。陷阱是胸腺名氣大，但論體積與淋巴組織量，脾臟才是最大。","source":"第十二章 12.3.3 脾臟","chId":"ch12"},{"id":"q1205","ch":12,"level":2,"type":"multi","style":"concept","q":"淋巴系統的功能包括下列哪些？（選 2–3 項）","options":["製造凝血因子","參與免疫力","把組織液引流回血液","在小腸吸收脂肪與脂溶性維他命","運送大部分氧氣到組織"],"answer":[1,2,3],"explain":"課文列出的淋巴功能有三：組織引流、小腸吸收脂肪與脂溶性物質、免疫力。氧氣主要由紅血球的血紅蛋白運送；凝血因子主要由肝臟合成。這兩項都屬血液與肝臟的工作，卻很容易因為「都是循環系統」而被誤選，是典型的概念混淆陷阱。","source":"第十二章 12.3 淋巴系統的功能","chId":"ch12"},{"id":"q1206","ch":12,"level":2,"type":"single","style":"concept","q":"炎症時的「腫脹」最直接由什麼造成？","options":["動脈收縮令血液滯留在局部","微血管通透性增加與血管內壓上升，液體走入間質","纖維蛋白溶解把凝塊分解","嗜中性白血球在局部大量繁殖"],"answer":[1],"explain":"腫脹（水腫）是液體離開局部血管進入間質空隙所致：炎症介質令毛細血管通透性增加，加上血流增加使血管內壓上升。動脈收縮會減少血流，與炎症的血管擴張相反；纖維蛋白溶解屬凝血後期；嗜中性白血球不會在組織大量繁殖。陷阱是把「紅熱」（血流增加）與「腫」（液體外移）混成同一機制。","source":"第十二章 12.2.1 增加組織液的形成","chId":"ch12"},{"id":"q1207","ch":12,"level":2,"type":"single","style":"concept","q":"比較淋巴結與脾臟，下列哪項正確？","options":["兩者的成熟都靠胸腺素刺激","脾臟有 4–5 條傳入淋巴管","脾臟沒有傳入淋巴管，主要過濾血液","淋巴結有多條輸出淋巴管"],"answer":[2],"explain":"脾臟沒有傳入淋巴管，主要過濾血液；淋巴結才是 4–5 條輸入、只有 1 條輸出。胸腺素由胸腺上皮細胞分泌，刺激胸腺及其他淋巴組織成熟，並非脾與淋巴結的分別。陷阱是把淋巴結的「多入一出」錯配到脾臟身上。","source":"第十二章 12.3.3 淋巴結與脾臟","chId":"ch12"},{"id":"q1208","ch":12,"level":2,"type":"multi","style":"concept","q":"關於五類抗體，下列哪些正確？（選 2–3 項）","options":["IgD 由漿細胞分泌進入血液","IgM 是強力的補體活化劑","IgG 能通過胎盤保護胎兒","IgA 見於母乳與唾液，防止抗原穿過上皮膜","IgE 在原發反應時大量製造"],"answer":[1,2,3],"explain":"IgA 出現在分泌中如母乳與唾液；IgG 是最大、最普遍的抗體，能過胎盤；IgM 在原發反應大量製造，亦是強力補體活化劑。原發反應大量製造的是 IgM 而不是 IgE；IgE 主要在過敏時大量出現。IgD 展示在 B 細胞表面讓抗原結合以活化 B 細胞，不是由漿細胞分泌入血。 陷阱是把「原發反應」與 IgE 的過敏角色混淆。","source":"第十二章 12.4.2 表 12.2 抗體的五種類型","chId":"ch12"},{"id":"q1209","ch":12,"level":3,"type":"single","style":"case","q":"一名六個月嬰兒全靠母乳、未接種疫苗，對母親得過的疾病仍有短期保護。這屬於哪類免疫？","options":["主動天然免疫，有記憶細胞","主動人工免疫，有記憶細胞","被動人工免疫，有記憶細胞","被動天然免疫，無記憶細胞、保護短暫"],"answer":[3],"explain":"母親的 IgG 經胎盤、IgA 經母乳進入嬰兒體內，嬰兒自己的淋巴細胞沒有被活化，所以沒有記憶細胞，抗體分解後保護即消失，屬被動天然免疫。主動免疫的定義是個體自己產生抗體並形成記憶細胞；被動人工則是注射現成抗血清。陷阱是見到「天然」就以為一定有記憶，其實關鍵在抗體是「借來的」。","source":"第十二章 12.6 被動天然後天免疫","chId":"ch12"},{"id":"q1210","ch":12,"level":3,"type":"single","style":"case","q":"HIV 主要破壞輔助 T 淋巴細胞。為何病人連抗體免疫也會受損？","options":["B 淋巴細胞需要輔助 T 細胞刺激，才能有效產生抗體","巨噬細胞停止吞噬抗原","補體無法被活化","抗原呈現細胞完全消失"],"answer":[0],"explain":"課文指出輔助 T 不但是細胞免疫所必需，抗體免疫同樣需要它：B 細胞雖負責製造抗體，但首先要經輔助 T 刺激。所以輔助 T 數量顯著下降，代表整個免疫系統受危害。補體活化只是抗體的功能之一；巨噬細胞與抗原呈現細胞不是 HIV 的主要攻擊目標。陷阱是以為「B 細胞自己做抗體」，忽略了 T 的授權。","source":"第十二章 12.4.1 輔助 T 淋巴細胞","chId":"ch12"},{"id":"q1211","ch":12,"level":3,"type":"multi","style":"case","q":"關於疫苗與免疫記憶，下列哪些正確？（選 2–3 項）","options":["被動免疫的抗體會被分解，保護較短暫","接種後數小時內即可驗到大量抗體","疫苗保留抗原特性，一般不造成疾病症狀","注射現成抗血清屬於主動免疫","主動人工免疫會產生記憶細胞，保護較持久"],"answer":[0,2,4],"explain":"疫苗用已死或減弱的微生物、或去活性毒素，保留抗原性以刺激淋巴細胞而不致病；主動人工免疫會產生記憶細胞，故保護較久；被動免疫的抗體終會被分解，所以短暫。注射現成抗血清屬被動人工免疫；接種後原發反應約需兩星期才驗到低水平抗體，數小時內大量抗體是錯的。 陷阱是把「打了針」一律當成主動免疫，忽略抗體是外來的。","source":"第十二章 12.5 記憶細胞與 12.6 後天免疫","chId":"ch12"},{"id":"q1212","ch":12,"level":3,"type":"single","style":"case","q":"肺結核在肺內形成肉芽腫，把微生物圍住。下列哪項最能描述這情況？","options":["只有血管收縮，沒有細胞浸潤","慢性炎症，以淋巴細胞與纖維化為主，把微生物圍住","急性炎症，以嗜中性白血球為主，數天內消退","補體耗盡造成的水腫"],"answer":[1],"explain":"慢性炎症與急性相似但持續較久，浸潤細胞由淋巴細胞取代嗜中性白血球，纖維組織母細胞被活化產生膠原與纖維化；身體若清不掉感染，會把它圍成肉芽腫，肺結核正是典型例子。嗜中性為主、數天消退是急性炎症；血管收縮屬止血第一步；補體耗盡不是肉芽腫的成因。 陷阱是見到「肉芽腫」仍用急性炎症的嗜中性細胞去解釋。","source":"第十二章 12.2.2 慢性炎症","chId":"ch12"},{"id":"q1301","ch":13,"level":1,"type":"single","style":"concept","q":"腎臟的機能性顯微單位是？","options":["腎小盞","腎盂","腎元","腎小球"],"answer":[2],"explain":"腎元是腎臟的機能性顯微單位，每個腎有數以百萬計，負責濾過、重吸收與分泌。腎小球只是腎元內負責濾過的一團微血管；腎盂與腎小盞屬集尿與排尿通道，不是機能單位。陷阱是把「腎小球」當成整個單位，其實它只是腎元的第一站。","source":"第十三章 13.3.1 B. 腎元","chId":"ch13"},{"id":"q1302","ch":13,"level":1,"type":"single","style":"concept","q":"右腎通常比左腎位置稍低，主要原因是？","options":["右側腎上腺壓迫","右側橫膈膜較低","右腎體積較大","右上腹有肝臟佔用空間"],"answer":[3],"explain":"課文明言右腎通常比左腎稍低，因為有相當大空間被肝臟佔用。橫膈膜、腎臟體積與腎上腺都不是課文給出的原因；腎上腺在兩腎上方，位置對稱。陷阱是以為「右邊有肝」只影響消化，其實肝臟的體積直接改變了右腎的高度。","source":"第十三章 13.3.1 腎臟","chId":"ch13"},{"id":"q1303","ch":13,"level":1,"type":"single","style":"concept","q":"膀胱約含有多少尿液時，會開始感到不適、產生尿意？","options":["300–400ml","800–1000ml","600–700ml","100–200ml"],"answer":[0],"explain":"課文指膀胱含有大約 300–400ml 尿液時會開始感到不適，總容積很少超過約 600ml。100–200ml 仍屬舒適範圍；600ml 已是接近上限而非起始尿意；800ml 以上更超出膀胱一般容量。陷阱是把「開始有尿意」與「最大容量」兩個數字對調。","source":"第十三章 13.3.3 膀胱","chId":"ch13"},{"id":"q1304","ch":13,"level":1,"type":"single","style":"concept","q":"女性尿道的長度約為？","options":["2cm","4cm","25cm","10cm"],"answer":[1],"explain":"課文指女性尿道約 4cm，在恥骨聯合後方向下向前走，於陰道前方開口；男性尿道較長，且同時與生殖系統有關。25–30cm 是輸尿管的長度，不是尿道。陷阱是把尿道與輸尿管的數字混淆，兩者都在本章出現，但長度相差很遠。","source":"第十三章 13.3.4 尿道","chId":"ch13"},{"id":"q1305","ch":13,"level":2,"type":"multi","style":"concept","q":"腎元的功能包括下列哪些？（選 2–3 項）","options":["調節血容積與血壓","分泌膽汁幫助脂肪消化","以尿液形式排除廢物","控制電解質與代謝物水平、調節血液 pH","製造胰島素調節血糖"],"answer":[0,2,3],"explain":"課文列明腎元三方面功能：排廢物、調節血容積與血壓、控制電解質與代謝物並調節 pH，全部受內分泌系統調節。膽汁由肝細胞製造；胰島素由胰島 β 細胞分泌。這兩項都是「腹部器官」的相鄰概念，容易被誤選，但它們不屬腎元的工作。","source":"第十三章 13.3.1 B. 腎元","chId":"ch13"},{"id":"q1306","ch":13,"level":2,"type":"single","style":"concept","q":"尿液由腎元形成後，流經泌尿系統的正確次序是？","options":["腎小球囊→腎盂→腎小管→輸尿管→膀胱→尿道","腎小管→腎小球囊→收集管→腎盂→膀胱→輸尿管→尿道","腎小球囊→腎小管→收集管→腎盂→輸尿管→膀胱→尿道","腎小球囊→收集管→腎盂→腎小管→輸尿管→膀胱→尿道"],"answer":[2],"explain":"濾過在腎小球囊開始，濾出液依次經腎小管、收集管，再到腎盂，然後由輸尿管送入膀胱，最後經尿道排出。其餘選項把腎盂提前、把腎小管放在腎盂之後，或把輸尿管與膀胱的次序倒轉。陷阱是「腎盂」聽起來像腎臟的一部分就以為在最前，其實它只是集尿的漏斗。","source":"第十三章 13.3.2 至 13.3.4 尿液流經順序","chId":"ch13"},{"id":"q1307","ch":13,"level":2,"type":"multi","style":"concept","q":"關於調節腎小管重吸收的荷爾蒙，下列哪些正確？（選 2–3 項）","options":["ADH 會增加尿量以稀釋血液","醛固酮由腦下垂體後葉分泌","ANP 降低鈉與水的重吸收，令尿量增加","ADH 增加遠曲小管與收集管對水的通透性","醛固酮增加鈉重吸收並促進鉀排出"],"answer":[2,3,4],"explain":"ADH 令遠曲小管與收集管更透水，水被重吸收，尿量是減少而非增加；醛固酮由腎上腺皮層分泌，增加鈉重吸收、排出鉀；ANP 在血容量過高時降低鈉水重吸收，尿量增加。把 ADH 說成「利尿」是最常見的望文生義陷阱，它的名字是「抗利尿」。","source":"第十三章 13.3.1 C. 選擇性重吸收","chId":"ch13"},{"id":"q1308","ch":13,"level":2,"type":"single","style":"concept","q":"血糖超過約 9 mmol/L 後尿液出現葡萄糖，最直接的原因是？","options":["腎小球不再過濾葡萄糖","胰島素分泌過多把葡萄糖推入尿中","葡萄糖被腎小管分泌到濾液","腎小管載體部位被佔用，主動運輸負荷過重"],"answer":[3],"explain":"葡萄糖平時 100% 被重吸收，但載體數量有限；血糖超過運送極限量（約 9 mmol/L 或 160mg/dl）時，所有載體已被佔用、主動運輸負荷過重，多餘葡萄糖便留在管腔隨尿排出。腎小球仍然照樣濾過葡萄糖；胰島素是降血糖而非把糖推入尿；葡萄糖是「漏出」而非被分泌。 陷阱是以為糖尿一定是腎臟濾過出錯，其實問題在重吸收的載體。","source":"第十三章 13.3.1 C. 運送極限量","chId":"ch13"},{"id":"q1309","ch":13,"level":3,"type":"single","style":"case","q":"一名病人嚴重脫水，血漿滲透壓上升。預期他的尿量和尿液濃度如何變化？","options":["尿量減少，尿液濃縮","尿量不變，尿糖增加","尿量增加，尿液稀釋","尿量增加，尿鈉增加"],"answer":[0],"explain":"脫水時 ADH 分泌增加，遠曲小管與收集管對水通透性上升，水被大量重吸收，所以尿量減少、尿液濃縮，以保住水分。尿量增加且稀釋是 ADH 不足或 ANP 作用的方向；尿糖與尿鈉不是脫水的主要即時反應。陷阱是隻記住「多喝水多排尿」，沒有把 ADH 的保水方向連上。","source":"第十三章 13.3.1 C. ADH","chId":"ch13"},{"id":"q1310","ch":13,"level":3,"type":"single","style":"case","q":"一名 55 歲以上高血壓病人被處方利尿劑，服藥後尿量增加。其主要作用機理是？","options":["增加 ADH 的分泌","抑制腎元保留水分的能力","增加醛固酮的分泌","增加腎小球的濾過表面積"],"answer":[1],"explain":"課文指出利尿劑抑制腎元保留水分的能力，因此增加尿量、降低血壓。增加濾過表面積不是利尿劑的已知機理；ADH 與醛固酮都是保水保鈉的荷爾蒙，分泌增加反而會令尿量減少。陷阱是見到「降血壓」就以為一定與心臟或血管直接有關，忽略了腎臟的體積調節角色。","source":"第十三章 13.3.1 B. 腎元與利尿劑","chId":"ch13"},{"id":"q1311","ch":13,"level":3,"type":"multi","style":"case","q":"關於輸尿管與膀胱的防逆流及排尿控制，下列哪些正確？（選 2–3 項）","options":["尿道外括約肌由平滑肌構成，不受意識控制","輸尿管主要靠重力把尿液送入膀胱，沒有蠕動","尿道內括約肌不受意識控制","輸尿管斜穿膀胱後壁，膀胱漲滿時開口受壓而閉合","輸尿管蠕動是平滑肌固有特性，不受自主神經控制"],"answer":[2,3,4],"explain":"輸尿管斜穿膀胱後壁，膀胱內壓升高時會壓閉其開口以防逆流；蠕動源自腎小盞起搏器，是平滑肌固有特性、不受自主神經控制；內括約肌是上段平滑肌增厚，不受意識支配。外括約肌由骨骼肌構成，受意識控制；輸尿管靠蠕動而非重力送尿。兩個「括約肌」的組織與控制方式是本題最大陷阱。","source":"第十三章 13.3.2 輸尿管與 13.3.3 膀胱","chId":"ch13"},{"id":"q1401","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟四個葉中，最大的是？","options":["左葉","方形葉","右葉","尾葉"],"answer":[2],"explain":"肝臟有四個葉，最明顯的是最大的右葉與較小、楔形的左葉；尾葉與方形葉位於肝臟後方表面。左葉雖然名字對稱，但體積比右葉小；尾葉與方形葉更只是後方的小葉。陷阱是看到「左、右」就以為兩葉相若，其實右葉明顯佔優。","source":"第十四章 14.1.1 肝葉","chId":"ch14"},{"id":"q1402","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟約 70% 的血液供應來自哪條血管？","options":["肝動脈","膽囊動脈","肝靜脈","肝門靜脈"],"answer":[3],"explain":"肝門靜脈由腸臟延伸到肝臟，提供約 70% 的血液，但含氧量很低；氧氣由肝動脈供應。肝靜脈是血液離開肝臟、排入下腔靜脈的通道；膽囊動脈只供應膽囊。陷阱是直覺認為「供應血液最多的一定是動脈」，其實肝臟以靜脈血為主。","source":"第十四章 14.2 肝門靜脈與肝動脈","chId":"ch14"},{"id":"q1403","ch":14,"level":1,"type":"single","style":"concept","q":"肝臟的機能性顯微單位是？","options":["肝小葉","竇狀隙","庫氏細胞","肝細胞"],"answer":[0],"explain":"肝臟各葉由許多肝小葉組成，小葉是六角形的機能單位，肉眼也觀察得到。肝細胞是小葉內的建造材料；竇狀隙是小葉內的微血管；庫氏細胞是內襯竇狀隙的巨噬細胞。陷阱是把「最小的細胞」與「機能單位」混為一談，肝細胞雖是主體細胞，但不是單位。","source":"第十四章 14.1.2 結構","chId":"ch14"},{"id":"q1404","ch":14,"level":1,"type":"single","style":"concept","q":"膽囊的主要功能是？","options":["製造膽汁","儲存膽汁並吸收水分濃縮","分泌膽囊收縮素","把膽紅素變成膽汁鹽"],"answer":[1],"explain":"膽囊儲存膽汁、吸收水分把膽汁濃縮 10–15 倍，並在進食後釋放。膽汁由肝細胞製造，不是膽囊；膽囊收縮素由十二指腸分泌；膽紅素與膽汁鹽是兩種不同成份，膽汁鹽由膽固醇合成。陷阱是「膽囊」與「膽汁」名字相近，就把製造的功能錯配給膽囊。","source":"第十四章 14.2.2 膽囊的功能","chId":"ch14"},{"id":"q1405","ch":14,"level":2,"type":"multi","style":"concept","q":"下列哪些屬於肝臟的功能？（選 2–3 項）","options":["對乙醇等藥物與微生物毒素進行解毒","分泌胰島素以降低血糖","合成血漿蛋白與大部份凝血因子","儲存肝醣與脂溶性維他命 A、D、E、K","分泌鹽酸以殺死胃內微生物"],"answer":[0,2,3],"explain":"肝臟儲存肝醣、脂溶性維他命、鐵、銅與 B12；負責解毒與荷爾蒙滅活；亦合成血漿蛋白與大部份凝血因子。胰島素由胰臟分泌，肝臟只是它的目標器官；鹽酸由胃黏膜分泌。這兩項都是「消化系統」的鄰近概念，容易誤植到肝臟身上。","source":"第十四章 14.2.1 肝臟的功能","chId":"ch14"},{"id":"q1406","ch":14,"level":2,"type":"single","style":"concept","q":"關於肝內血液與膽汁的流向，下列哪項正確？","options":["肝動脈→膽小管→中央靜脈；膽汁由中央靜脈出肝","中央靜脈→竇狀隙→肝門靜脈→下腔靜脈；膽小管→膽囊→肝靜脈","竇狀隙→中央靜脈→肝靜脈→下腔靜脈；膽小管→左右肝管","竇狀隙→膽小管→肝靜脈；膽汁經門靜脈出肝"],"answer":[2],"explain":"血液由竇狀隙流向中央靜脈，再匯成肝靜脈、排入下腔靜脈；膽汁則由肝細胞柱另一側的膽小管收集，匯成左右肝管出肝。其餘選項把兩條路徑混在一起，甚至讓膽汁經肝靜脈或門靜脈走。陷阱是忘記膽小管與竇狀隙位於肝細胞柱的兩側，方向剛好相反。","source":"第十四章 14.1.2 結構","chId":"ch14"},{"id":"q1407","ch":14,"level":2,"type":"multi","style":"concept","q":"關於膽汁與膽汁鹽，下列哪些正確？（選 2–3 項）","options":["大部分膽汁鹽在迴腸末端被再吸收，經門靜脈回肝","膽囊會製造膽固醇供膽汁使用","膽紅素是紅血球溶血的產物，是膽汁色素的主要成分","膽汁鹽在小腸內乳化脂肪，幫助消化","膽汁含大量蛋白水解酵素，直接分解蛋白質"],"answer":[0,2,3],"explain":"膽汁鹽在小腸乳化脂肪；大部分在迴腸末端再吸收，經門靜脈返回肝臟，形成腸肝循環；膽紅素是溶血產物，亦是膽汁色素的主要成分。膽固醇是膽汁成份、也是膽汁酸原料，但由肝細胞合成而非膽囊製造；膽汁不含蛋白水解酵素，蛋白質消化靠胃與胰的酵素。 陷阱是把膽汁當成含消化酵素的萬能消化液。","source":"第十四章 14.2.2 膽汁的成份與腸肝循環","chId":"ch14"},{"id":"q1408","ch":14,"level":2,"type":"single","style":"concept","q":"庫氏細胞（星狀細胞）位於何處，主要功能是什麼？","options":["肝小葉中央靜脈內皮，負責運送氧氣","膽小管壁上，負責分泌膽汁鹽","肝被膜上，負責固定肝臟位置","竇狀隙內，屬巨噬細胞，吞噬破舊血細胞與外來微粒"],"answer":[3],"explain":"庫氏細胞內襯竇狀隙，是肝內的巨噬細胞，吞噬並毀滅經過肝臟的破舊血細胞與外來微粒，亦參與分解紅血球。牠不在中央靜脈、膽小管或被膜上；分泌膽汁鹽的是肝細胞。陷阱是「星狀」聽起來像神經細胞，其實這裏指的是肝內的巨噬細胞。","source":"第十四章 14.1.2 竇狀隙與庫氏細胞","chId":"ch14"},{"id":"q1409","ch":14,"level":3,"type":"multi","style":"case","q":"一名肝硬化病人出現黃疸、下肢水腫與容易瘀青。下列解釋哪些正確？（選 2–3 項）","options":["肝臟停止製造膽汁鹽，脂肪吸收因此增加","肝合成白蛋白減少，血漿滲透壓下降而水腫","凝血因子合成減少，所以容易出血","庫氏細胞過度活躍令血紅蛋白上升","膽紅素無法在肝細胞內結合，積聚而出現黃疸"],"answer":[1,2,4],"explain":"這三個症狀正好對應肝臟三大功能：合成白蛋白（滲透壓）、處理膽紅素（黃疸）、合成凝血因子（出血）。膽汁鹽減少會令脂肪乳化與吸收變差，而不是增加；庫氏細胞活躍不會令血紅蛋白上升，反而參與破壞老舊紅血球。本題考跨章整合：血漿蛋白、膽紅素與凝血三條線都指向肝。 陷阱是只盯着黃疸，忽略水腫與出血同樣源自肝。","source":"第十四章 14.2.1 與 14.2.2 膽紅素","chId":"ch14"},{"id":"q1410","ch":14,"level":3,"type":"single","style":"case","q":"一名病人膽結石阻塞膽管，膽汁無法排入十二指腸。最可能出現的組合是？","options":["脂肪乳化受阻，同時膽紅素積聚引起黃疸","血糖立即下降，因為肝醣無法分解","蛋白質消化立即停頓，但膽紅素正常","尿量增加，因為 ADH 被抑制"],"answer":[0],"explain":"膽汁鹽負責在小腸乳化脂肪，膽管阻塞會令脂肪消化吸收變差；膽紅素無法隨膽汁排出，積聚血中便造成黃疸。蛋白質消化主要靠胃與胰的酵素，不是膽汁；血糖調節由肝醣與荷爾蒙控制，與膽管阻塞無直接關係；ADH 屬腎臟水分調節。陷阱是把膽汁當成萬能消化液。","source":"第十四章 14.2.2 膽汁成份與黃疸","chId":"ch14"},{"id":"q1411","ch":14,"level":3,"type":"single","style":"case","q":"病人切除膽囊後，進食含脂肪食物仍能消化。最合理的解釋是？","options":["膽汁鹽改由胰臟分泌以替代膽囊","肝細胞仍持續製造膽汁，經膽管流入十二指腸","脂肪改由胃的鹽酸乳化","膽囊切除後，肝臟會改為製造更多膽囊收縮素"],"answer":[1],"explain":"膽汁由肝細胞製造，膽囊只負責儲存與濃縮；切除膽囊後，肝臟仍持續分泌膽汁，經膽管流入十二指腸，只是沒有濃縮與大量儲備。膽囊收縮素由十二指腸分泌，不是肝；膽汁鹽由肝合成而非胰臟；鹽酸不能乳化脂肪。陷阱是以為「沒有膽囊就沒有膽汁」。","source":"第十四章 14.2.1 分泌膽汁與 14.2.2 膽囊","chId":"ch14"},{"id":"q1501","ch":15,"level":1,"type":"single","style":"concept","q":"胰島中哪種細胞分泌胰島素（insulin）？","options":["δ細胞","濾泡旁細胞","β細胞","α細胞"],"answer":[2],"explain":"胰島β細胞分泌胰島素，作用是降低血糖；α細胞分泌高血糖素，作用相反；δ細胞分泌抑生長素，抑制GH、胰島素和高血糖素。濾泡旁細胞（C細胞）位於甲狀腺，分泌降血鈣素，與胰島完全無關，是把兩個腺體混在一起時的常見干擾項。記「β＝降血糖」便可與α細胞分開。","source":"第十五章 15.2 E 胰島","chId":"ch15"},{"id":"q1502","ch":15,"level":1,"type":"single","style":"concept","q":"下列哪個荷爾蒙由腦下垂體後葉釋放？","options":["促腎上腺皮質荷爾蒙（ACTH）","甲狀腺促素（TSH）","生長荷爾蒙（GH）","抗利尿素（ADH）"],"answer":[3],"explain":"後葉只釋放抗利尿素和催產素兩種荷爾蒙，而且兩者均由下丘腦製造，經神經纖維送到後葉儲存。TSH、ACTH和GH都是前葉荷爾蒙，分別作用於甲狀腺、腎上腺皮質和大部分組織。最常見的陷阱是把「後葉釋放」誤讀成「後葉製造」，或以為後葉也分泌TSH。","source":"第十五章 15.1 B 腦下垂體後葉","chId":"ch15"},{"id":"q1503","ch":15,"level":1,"type":"single","style":"concept","q":"降血鈣素（calcitonin）由下列哪種細胞分泌？","options":["甲狀腺濾泡旁細胞（C細胞）","副甲狀腺主細胞","甲狀腺濾泡細胞","腎上腺皮質細胞"],"answer":[0],"explain":"甲狀腺內的濾泡旁細胞（C細胞）分泌降血鈣素，作用於骨骼和腎臟以降低血鈣。濾泡細胞製造T3和T4，與鈣無關；副甲狀腺主細胞分泌PTH，作用方向剛好相反（升血鈣）；腎上腺皮質分泌類固醇。這題的陷阱是把「降血鈣素」誤配給副甲狀腺，實際上它來自甲狀腺。","source":"第十五章 15.2 A 甲狀腺（降血鈣素）","chId":"ch15"},{"id":"q1504","ch":15,"level":1,"type":"single","style":"concept","q":"哪個荷爾蒙主要增加腎臟遠曲小管和收集管對水的通透性，從而減少尿量？","options":["降血鈣素","抗利尿素","催產素","醛固酮"],"answer":[1],"explain":"抗利尿素（ADH）增加遠曲小管和收集管對水的通透性，促進水重吸收，使尿量減少、尿液濃縮，故稱「抗利尿」。醛固酮雖也促進鈉和水重吸收，但主要作用是保鈉排鉀，題目問「水的通透性」是ADH的專利；降血鈣素管鈣；催產素管子宮和乳房。把醛固酮與ADH混淆是常見失分位。","source":"第十五章 15.1 B 抗利尿素","chId":"ch15"},{"id":"q1505","ch":15,"level":2,"type":"single","style":"concept","q":"甲狀腺素（T3、T4）血中水平下降時，下列反應次序何者正確？","options":["TRH↓→TSH↓→T3/T4回升","T3/T4↑→TRH↑→TSH↑","TRH↑→TSH↑→T3/T4回升","TSH↑→TRH↑→T3/T4下降"],"answer":[2],"explain":"負回饋的方向是：T3、T4低→解除對下丘腦和腦下垂體的抑制→TRH增加→TSH增加→甲狀腺分泌增加→T3、T4回升。把整個方向倒轉（TRH↓、TSH↓）、把T3/T4高當成刺激TRH、或把TSH放在TRH之前，都是負回饋最常見的陷阱。","source":"第十五章 15.2 A 甲狀腺素及三碘甲狀腺原氨酸","chId":"ch15"},{"id":"q1506","ch":15,"level":2,"type":"multi","style":"concept","q":"下列哪些是腦下垂體前葉分泌、並以其他內分泌腺為目標的促內分泌腺激素？（選出2–3項）","options":["抗利尿素（ADH）","促腎上腺皮質荷爾蒙（ACTH）","生長荷爾蒙（GH）","黃體生成素（LH）","甲狀腺促素（TSH）"],"answer":[1,3,4],"explain":"TSH以甲狀腺為目標、ACTH以腎上腺皮質為目標、FSH和LH以性腺為目標，三者都屬促內分泌腺激素（trophic hormone）。GH雖然來自前葉，但作用於大部分組織（骨骼、肌肉、肝臟）而非另一個內分泌腺；ADH是後葉荷爾蒙，作用於腎臟。分辨關鍵是問「它的目標是不是另一個腺體」。","source":"第十五章 15.1 A 腦下垂體前葉；表15.2","chId":"ch15"},{"id":"q1507","ch":15,"level":2,"type":"single","style":"concept","q":"催產素在分娩時的分泌被形容為正回饋，下列哪項最能解釋？","options":["催產素由ADH的濃度直接控制","嬰兒出生後催產素才大量分泌","子宮收縮減弱子宮頸的拉展，使分泌減少","子宮頸被拉展→更多催產素→更強子宮收縮→更大拉展"],"answer":[3],"explain":"正回饋是反應擴大原刺激：子宮頸被拉展→衝動傳到下丘腦→後葉釋放更多催產素→子宮收縮更強→拉展更大，循環直至嬰兒出生、拉展大大減少才停止。把催產素說成由ADH直接控制、說出生後才大量分泌、或說子宮收縮會減少子宮頸拉展，都與正回饋方向相反。","source":"第十五章 15.1 B 催產素；圖15.9","chId":"ch15"},{"id":"q1508","ch":15,"level":2,"type":"single","style":"concept","q":"胰島素與高血糖素對肝糖的效應，下列何者正確？","options":["胰島素促進肝糖合成，高血糖素促進肝糖分解","胰島素促進肝糖分解，高血糖素促進合成","兩者都促進肝糖合成","兩者都促進肝糖分解"],"answer":[0],"explain":"胰島素降低血糖：促進葡萄糖進入肌肉和結締組織細胞、在肝臟和骨骼肌合成肝糖，並抑制肝糖分解。高血糖素升高血糖：促進肝糖分解為葡萄糖及糖質新生。兩者方向相反，是拮抗荷爾蒙的典型；把兩者對調，或說兩者都促進合成／分解，都忽略拮抗關係。","source":"第十五章 15.2 E 胰島素與高血糖素","chId":"ch15"},{"id":"q1509","ch":15,"level":3,"type":"single","style":"case","q":"一名長期服用高劑量潑尼松龍（prednisolone）的病人出現月亮臉、頸腹肥胖、高血糖和傷口癒合遲緩，最直接的解釋是？","options":["胰島素分泌過多","糖皮質激素作用過強","副甲狀腺素分泌過低","甲狀腺素分泌過多"],"answer":[1],"explain":"潑尼松龍屬糖皮質激素類藥物，長期高劑量造成醫源性庫欣氏症候群：糖質新生增加致高血糖、脂肪重新分佈成月亮臉和水牛背、蛋白質分解致皮膚變薄和傷口癒合遲緩。甲狀腺亢進會體重減輕、怕熱、心跳快，不會有月亮臉；胰島素過多造成低血糖；PTH過低造成低血鈣和抽搐，與此個案不符。","source":"第十五章 15.2 C 糖皮質激素（庫欣氏症候群）","chId":"ch15"},{"id":"q1510","ch":15,"level":3,"type":"single","style":"case","q":"行山大量出汗後沒有補充水分，尿量明顯減少且尿液濃縮。下列機制次序何者最合理？","options":["血漿滲透壓↑→醛固酮↓→鈉排出↑→尿少而濃","血漿滲透壓↑→ADH↓→水重吸收↑→尿少而濃","血漿滲透壓↑→下丘腦滲透壓感受器→ADH↑→水重吸收↑→尿少而濃","血漿滲透壓↓→ADH↑→水重吸收↓→尿少而濃"],"answer":[2],"explain":"脫水使血漿滲透壓上升，下丘腦滲透壓感受器偵測到，ADH分泌增加，遠曲小管和收集管對水通透性上升，水重吸收增加，尿量減少而濃。把ADH說成下降、把血漿滲透壓說成下降，或把ADH作用說成減少水重吸收，都是方向倒轉；醛固酮主要調節鈉鉀，不是這個情境的主線。","source":"第十五章 15.1 B 抗利尿素；圖15.10","chId":"ch15"},{"id":"q1511","ch":15,"level":3,"type":"multi","style":"concept","q":"關於血鈣的調節，下列哪些正確？（選出2–3項）","options":["降血鈣素減少從骨骼重吸收鈣","副甲狀腺素增加腎小管對鈣的重吸收","副甲狀腺素在需要時活化蝕骨細胞","血鈣上升會刺激副甲狀腺素分泌","降血鈣素由副甲狀腺分泌"],"answer":[0,1,2],"explain":"降血鈣素由甲狀腺C細胞分泌，抑制骨重吸收鈣和腎小管重吸收鈣，使血鈣下降；PTH由副甲狀腺分泌，促進小腸和腎小管吸收鈣，必要時活化蝕骨細胞，使血鈣上升。血鈣上升刺激的是降血鈣素而非PTH；把降血鈣素說成副甲狀腺分泌，是把來源對調。","source":"第十五章 15.2 A 降血鈣素；15.2 B 副甲狀腺","chId":"ch15"},{"id":"q1512","ch":15,"level":3,"type":"single","style":"case","q":"山區居民長期碘攝取不足，甲狀腺明顯腫大但沒有機能亢進徵象，最合理的解釋是？","options":["T3/T4偏高→TSH偏高→甲狀腺增生","降血鈣素過多刺激甲狀腺長大","TSH偏低→甲狀腺萎縮","T3/T4偏低→TSH偏高→甲狀腺細胞增生"],"answer":[3],"explain":"碘不足使T3、T4合成減少，負回饋減弱令TSH升高，TSH刺激甲狀腺生長和活動，腺體腫大，即單純甲狀腺腫；若額外組織能維持荷爾蒙水平，就沒有亢進或低下。T3、T4偏高會抑制而非刺激TSH；TSH偏低會令腺體萎縮；降血鈣素與甲狀腺大小無關。陷阱是把「腫大」直接當成機能亢進。","source":"第十五章 15.2 A 甲狀腺（單純甲狀腺腫）","chId":"ch15"},{"id":"q1601","ch":16,"level":1,"type":"single","style":"concept","q":"腦脊髓液主要存在於哪個空間？","options":["蛛網膜下空間","硬腦膜外空間","中央溝","大腦縱裂"],"answer":[0],"explain":"腦脊髓液位於蛛網膜與軟腦膜之間的蛛網膜下空間，把腦和脊髓浸透其中。硬腦膜外空間是脊椎骨骨膜與硬腦膜之間的一層脂肪和結締組織，屬軟墊層，也是硬膜外給藥的位置，不是CSF所在。大腦縱裂是分開兩半球的裂隙；中央溝是分隔額葉和頂葉的腦溝。把硬腦膜外空間當成CSF所在是最常見的混淆。","source":"第十六章 16.1 腦膜與腦脊髓液","chId":"ch16"},{"id":"q1602","ch":16,"level":1,"type":"single","style":"concept","q":"腦脊髓液主要由下列哪個構造分泌？","options":["軟腦膜","脈絡膜叢","蛛網膜絨毛","胼胝體"],"answer":[1],"explain":"脈絡膜叢由血管和室管膜細胞組成，分泌CSF到各腦室；蛛網膜絨毛（蛛網顆粒）則是回收站，把CSF送回靜脈竇，兩者一分泌一吸收，方向相反，是典型對調陷阱。軟腦膜只是最內層的保護膜；胼胝體是連接兩半球的白質。記「脈絡叢製造、蛛網絨毛回收」便可分開。","source":"第十六章 16.1 腦脊髓液（脈絡膜叢）","chId":"ch16"},{"id":"q1603","ch":16,"level":1,"type":"single","style":"concept","q":"感覺訊息傳往大腦皮層前，主要在哪個構造被轉發？","options":["下丘腦","小腦","丘腦","基底核"],"answer":[2],"explain":"來自皮膚、內臟和特殊感官的訊息先傳到丘腦，再分送到大腦皮層，所以丘腦是「轉發站」。基底核負責動作的啟動和精細協調；下丘腦管體溫、食慾、口渴和生物鐘；小腦管平衡和動作協調。把丘腦與下丘腦混淆是最常見的失分位；兩者位置相近但功能完全不同。","source":"第十六章 16.2.3 丘腦","chId":"ch16"},{"id":"q1604","ch":16,"level":1,"type":"single","style":"concept","q":"延髓內哪個中樞負責控制心跳速率、收縮力和血壓？","options":["體溫調節中樞","嘔吐反射中樞","呼吸中樞","心血管中樞"],"answer":[3],"explain":"心血管中樞位於延髓，內含血管舒縮中樞，控制心跳速率和收縮力，並透過血管直徑調節血壓。呼吸中樞只管呼吸速率和深度；嘔吐中樞是延髓反射中樞之一，負責把刺激物排出；體溫調節中樞在下丘腦，不在延髓。這四個中樞常被放在一起考位置配對。","source":"第十六章 16.2.2 延髓（心血管中樞）","chId":"ch16"},{"id":"q1605","ch":16,"level":2,"type":"single","style":"concept","q":"CSF每天分泌約720毫升，但顱內CSF容積穩定維持約120毫升，最合理的結論是？","options":["分泌與吸收幾乎以同速進行","蛛網膜絨毛完全沒有吸收功能","分泌量遠少於吸收量","CSF在成人已停止流動"],"answer":[0],"explain":"每天分泌720毫升而容積只有120毫升，表示同一時間有等量CSF被吸收，分泌與吸收幾乎同速，容積才穩定；不是停止分泌，也不是吸收遠多於分泌（否則容積會持續減少）。這條數字題常把「720」和「120」硬記而不理解關係；只要問「為何容積不變」，答案就是吸收追上分泌。","source":"第十六章 16.1 腦脊髓液（分泌與吸收）","chId":"ch16"},{"id":"q1606","ch":16,"level":2,"type":"single","style":"concept","q":"延髓錐體交叉的結果，下列何者正確？","options":["左大腦半球控制身體左側","左大腦半球控制身體右側","小腦控制身體同側的隨意動作","感覺纖維全部在脊髓交叉"],"answer":[1],"explain":"錐體（皮質脊髓）束的運動纖維在延髓左右交叉，故左半球支配右側骨骼肌、右半球支配左側，中風後對側無力就是這條路徑。感覺纖維有些在延髓交叉、有些在脊髓較低水平，所以「全部在脊髓交叉」是錯的。小腦確與協調有關，但隨意動作的指令源自大腦皮層，不能說小腦控制同側隨意動作。","source":"第十六章 16.2.2 延髓（錐體交叉）","chId":"ch16"},{"id":"q1607","ch":16,"level":2,"type":"multi","style":"concept","q":"基底核受損時，最可能出現哪些表現？（選出2–3項）","options":["皮膚感覺喪失","協調動作變差","動作不平穩、笨拙","精細動作控制變差","瞳孔放大"],"answer":[1,2,3],"explain":"基底核參與啟動和精細控制複雜動作，並與大腦皮層和丘腦連接，受損會使動作不平穩、笨拙、不協調，學習協調活動也受影響。瞳孔由虹膜肌肉和自主神經控制，與基底核無關；皮膚感覺走丘腦和感覺皮層路徑，也不經基底核。分辨關鍵是問「這是動作協調還是感覺或瞳孔」；後兩者屬其他系統。","source":"第十六章 16.2.3 基底核","chId":"ch16"},{"id":"q1608","ch":16,"level":2,"type":"single","style":"concept","q":"腰椎穿刺通常選在第3、4腰椎或第4、5腰椎之間，主要理由為何？","options":["該處血腦屏障最薄弱","該處腦脊髓液量最多","脊髓已在第一腰椎終止，可避免刺傷脊髓","該處沒有硬腦膜覆蓋"],"answer":[2],"explain":"成人脊髓約終止於第一腰椎（L1），L3/L4或L4/L5已在脊髓末端以下，只有馬尾神經根浮在CSF中，刺針較安全；課文也指出第2腰椎以下進入脊髓區域才「安全」。CSF在整個蛛網膜下空間循環，不是該處特別多；硬腦膜仍然覆蓋；BBB位於腦微血管，與穿刺位置無關。","source":"第十六章 16.4 脊髓神經的結構（腰椎穿刺）","chId":"ch16"},{"id":"q1609","ch":16,"level":3,"type":"single","style":"case","q":"細菌性腦膜炎病人需要把抗生素直接送入蛛網膜下空間，而非只靠靜脈注射，主要原因為何？","options":["CSF內完全沒有白血球","腦膜沒有血液供應","抗生素口服後完全不被吸收","多數藥物難以通過血腦屏障，腦內濃度不足"],"answer":[3],"explain":"BBB的內皮細胞以緊密連接排列，只放行葡萄糖和脂溶性物質，多數抗生素難以由血液入腦，所以療效緩慢，需經腰椎穿刺直接注入CSF。口服不被吸收太絕對，且因藥物而異；CSF正常只有少數白血球，但腦膜炎時會有炎症細胞；腦膜血管豐富，並非沒有血液供應。陷阱是把「BBB屏障」誤解成「腦膜無血管」。","source":"第十六章 16.3 血腦屏障","chId":"ch16"},{"id":"q1610","ch":16,"level":3,"type":"multi","style":"case","q":"交感神經興奮時，下列哪些效應正確？（選出2–3項）","options":["皮膚小動脈收縮","胃腸蠕動增加","細支氣管擴張","心跳減慢","瞳孔放大"],"answer":[0,2,4],"explain":"交感使虹膜輻射肌收縮而瞳孔放大、細支氣管平滑肌放鬆而擴張、皮膚小動脈收縮以提升周邊阻力；同時心跳加快而非減慢，胃腸蠕動和分泌被抑制而非增加。後兩項是副交感的效應，把它們混入交感是本章最常見的對調陷阱。記憶時把同一器官的交感與副交感效應成對背，比單背「交感興奮」可靠。","source":"第十六章 16.4.1 自主神經刺激的效應","chId":"ch16"},{"id":"q1611","ch":16,"level":3,"type":"single","style":"case","q":"右側內囊（含錐體束）出血，最可能出現哪種運動障礙？","options":["左側上下肢無力","只有皮膚感覺喪失而沒有無力","右側上下肢無力","雙眼失明"],"answer":[0],"explain":"內囊的運動纖維形成錐體束，下行至延髓交叉後才到對側脊髓前角，所以右側內囊病灶造成左側肢體無力（對側偏癱）。同側無力是忽略交叉的典型錯誤；視覺障礙屬枕葉或視覺路徑受損；純感覺喪失是感覺束（如丘腦）受損的表現，與錐體束不同。把「右側病灶」直接配「右側無力」就會中計。","source":"第十六章 16.2.1 大腦內部（內囊與錐體束）","chId":"ch16"},{"id":"q1612","ch":16,"level":3,"type":"single","style":"case","q":"頭部外傷後腦組織腫脹、顱內壓上升。此時CSF的角色，下列何者最合理？","options":["血腦屏障會打開讓多餘液體排出","CSF量減少以作代償，緩衝壓力上升","脈絡膜叢立即停止所有分泌","CSF分泌增加以填補空間"],"answer":[1],"explain":"課文指出腦部因出血或腫瘤擴大時，會透過降低CSF量產生代償；相反，腦組織萎縮時CSF容積增加。所以腫脹時CSF減少而非增加。BBB不會因腫脹而打開排液；脈絡膜叢仍持續分泌（約每分鐘0.5毫升），只是吸收與調節改變，「立即停止所有分泌」太絕對。這題考代償方向，不是考數字。","source":"第十六章 16.1 腦脊髓液（代償）","chId":"ch16"},{"id":"q1701","ch":17,"level":1,"type":"single","style":"concept","q":"男性生殖系統中，負責製造精子的器官是哪一個？","options":["前列腺","副睪","睪丸","儲精囊"],"answer":[2],"explain":"睪丸的曲細精管是精子生成的位置，青春期後受 FSH 刺激而製造精子，亦分泌睾酮。副睪只負責精子成熟及暫時儲存；前列腺與儲精囊屬附屬腺體，加入精液分泌物，並不製造精子。","source":"第十七章 17.2 男性生殖系統各個部份","chId":"ch17"},{"id":"q1702","ch":17,"level":1,"type":"single","style":"concept","q":"精子離開睪丸後，主要在哪裡成熟並暫時儲存？","options":["儲精囊","射精管","輸精管","副睪"],"answer":[3],"explain":"曲細精管匯集成副睪，精子在副睪內成熟並暫存。輸精管是運送管道；儲精囊加入營養分泌物；射精管是儲精囊管道與輸精管匯合後的短管，都是「運送或加料」而非成熟場所，不能選。","source":"第十七章 17.2 睪丸與副睪","chId":"ch17"},{"id":"q1703","ch":17,"level":1,"type":"single","style":"concept","q":"射精時，約六成精液由哪個構造加入？","options":["儲精囊","前列腺","尿道球腺","副睪"],"answer":[0],"explain":"課文指儲精囊加入約 60% 精液，並提供精子沿途所需的營養素。前列腺雖重要，但主要提供乳狀液及凝結酵素，佔量較少；尿道球腺只加鹼性分泌物；副睪是精子成熟處，不分泌精液。","source":"第十七章 17.2 儲精囊與前列腺","chId":"ch17"},{"id":"q1704","ch":17,"level":1,"type":"single","style":"concept","q":"哪種荷爾蒙直接刺激睪丸分泌睾酮？","options":["FSH","LH","睾酮","LHRH"],"answer":[1],"explain":"LH 刺激睪丸分泌睾酮；FSH 則刺激精子製造。LHRH 由下丘腦釋放，作用於腦下垂體前葉，不是直接作用於睪丸。睾酮是 LH 作用後的產物，並非刺激者；把「產物」當成「刺激荷爾蒙」是典型陷阱。","source":"第十七章 17.1 青春發育期","chId":"ch17"},{"id":"q1705","ch":17,"level":2,"type":"single","style":"concept","q":"精子由生成至排出，下列次序何者正確？","options":["副睪 → 曲細精管 → 輸精管 → 尿道 → 射精管","副睪 → 輸精管 → 曲細精管 → 射精管 → 尿道","曲細精管 → 副睪 → 輸精管 → 射精管 → 尿道","曲細精管 → 輸精管 → 副睪 → 射精管 → 尿道"],"answer":[2],"explain":"精子在曲細精管生成，進入副睪成熟及暫存，再由輸精管經精索運送；儲精囊管道與輸精管匯合成射精管，穿過前列腺後經尿道排出。其他選項都把副睪與曲細精管的先後倒轉，或把射精管放到尿道之後。","source":"第十七章 17.2 男性生殖系統各個部份","chId":"ch17"},{"id":"q1706","ch":17,"level":2,"type":"multi","style":"concept","q":"精索（spermatic cord）內包含下列哪些結構？","options":["睾丸靜脈叢","輸精管","睾丸動脈","射精管","前列腺"],"answer":[0,1,2],"explain":"課文列精索內有 1 條睾丸動脈、1 個睾丸靜脈叢、淋巴管、1 條輸精管及神經。射精管由儲精囊管道與輸精管匯合而成，位置在盆腔內；前列腺則位於膀胱下方，兩者都不在精索之內。","source":"第十七章 17.2 精索","chId":"ch17"},{"id":"q1707","ch":17,"level":2,"type":"single","style":"concept","q":"前列腺分泌物中，對生育最關鍵的成分是什麼？","options":["果糖","乳酸","精液纖維蛋白分解酵素","凝結酵素"],"answer":[3],"explain":"前列腺液最重要的是凝結酵素，使精液在接近子宮頸處變稠、停留較久，讓精子有時間調整方向。果糖與營養素主要來自儲精囊；乳酸與陰道酸性有關；精液纖維蛋白分解酵素是精液中的抗菌成分，課文未歸為前列腺分泌物。","source":"第十七章 17.2 前列腺","chId":"ch17"},{"id":"q1708","ch":17,"level":2,"type":"single","style":"concept","q":"睪丸懸掛在體壁外，對生育最主要的好處是什麼？","options":["維持比體溫低約 3℃ 的溫度","避免精子被尿液沖走","令精索可以縮短","增加睪丸的血液供應"],"answer":[0],"explain":"課文明言陰囊位置令睪丸周圍溫度低於體溫約 3℃，這是維持理想生育力所必需，也是緊身內褲可能削弱生育力的理由。其餘選項在課文都沒有支持，屬於把「陰囊位置」與排尿、血流或精索長度混為一談。","source":"第十七章 17.2 陰囊與睪丸","chId":"ch17"},{"id":"q1709","ch":17,"level":3,"type":"multi","style":"case","q":"32 歲男子精液分析：量 1.2 ml、精子 12 × 10⁶/ml、液化需 3 小時、形態正常。根據課文，哪些項目屬不孕因素？","options":["精子數目 12 × 10⁶/ml","精液量 1.2 ml（低容積）","液化需 3 小時","精液含果糖","精子形態正常"],"answer":[0,1,2],"explain":"課文列不孕因素包括低容積、低活動力、數目 < 20 × 10⁶/ml、液化需 2 小時以上、形態異常、pH 上升及缺乏果糖。此個案三項都符合；含果糖與形態正常反而是正常表現，「缺乏果糖」才是不孕因素。","source":"第十七章 17.2 不孕的問題","chId":"ch17"},{"id":"q1710","ch":17,"level":3,"type":"single","style":"case","q":"30 歲男子接受兩側輸精管結紮。術後最可能出現哪種情況？","options":["副睪不再儲存精子，睪丸因而萎縮","精液仍含儲精囊與前列腺分泌物，但不含精子","前列腺停止分泌，精液量變為零","睪丸立即停止製造精子"],"answer":[1],"explain":"結紮只阻斷輸精管運送，睪丸仍受 FSH 與 LH 刺激製造精子及睾酮；儲精囊、前列腺和尿道球腺仍加入分泌物，所以精液量大致不變，只是沒有精子。睪丸不會立即停產，前列腺也不會停止分泌。","source":"第十七章 17.2 輸精管與附屬腺體","chId":"ch17"},{"id":"q1711","ch":17,"level":3,"type":"single","style":"case","q":"68 歲男子排尿困難、夜尿增多，直腸指診發現前列腺增大。最合理的解釋是？","options":["前列腺分泌過多凝結酵素阻塞射精管","增大的睪丸由下方壓迫膀胱","增大的前列腺壓迫穿過它的尿道","前列腺壓迫輸尿管造成腎積水"],"answer":[2],"explain":"課文指前列腺肥大會阻塞通過它的管道，包括來自膀胱的尿道，因此造成排尿問題。輸尿管在更上方接駁膀胱，並非穿過前列腺；凝結酵素作用於精液性狀，不會阻塞射精管；睪丸位於陰囊，不會由下方壓迫膀胱。","source":"第十七章 17.2 前列腺","chId":"ch17"},{"id":"q1712","ch":17,"level":3,"type":"single","style":"case","q":"58 歲有心臟病的男子自行服用威而鋼後頭暈、血壓偏低。最符合課文的解釋是？","options":["藥物令微靜脈擴張，血液滯留於陰莖","藥物直接抑制心臟收縮力","藥物刺激交感神經使心跳減慢","藥物抑制 PDE，令血管過度擴張致低血壓"],"answer":[3],"explain":"課文指威而鋼抑制磷酸二酯酶（PDE），作用如勃起機制但會影響其他血管，血管過度擴張造成低血壓，心臟病患者可因血壓過低而有危險。勃起是微動脈擴張加上微靜脈收縮；只說微靜脈擴張的選項，方向相反。","source":"第十七章 17.2 陰莖與威而鋼附註","chId":"ch17"},{"id":"q1801","ch":18,"level":1,"type":"single","style":"concept","q":"卵子受精通常發生在哪個位置？","options":["輸卵管","卵巢","子宮頸","子宮腔"],"answer":[0],"explain":"課文明言受精通常發生在輸卵管，受精卵再被推入子宮著床。卵巢是排卵處，子宮是著床及發育處，子宮頸是產道的一部分；把「受精」與「著床」都放在子宮，是最常見的混淆；記住「受精在管、著床在宮」。","source":"第十八章 18.2 輸卵管的功能","chId":"ch18"},{"id":"q1802","ch":18,"level":1,"type":"single","style":"concept","q":"子宮壁三層中，最厚的是哪一層？","options":["子宮內膜","子宮肌層","子宮外膜","基底層"],"answer":[1],"explain":"子宮肌層是子宮壁最厚的一層，由平滑肌與網狀組織、血管、神經交錯而成，分娩時強力收縮推出嬰兒。子宮外膜是腹膜，子宮內膜是柱狀上皮及腺體層；基底層只是內膜的一小部分，不是獨立全層。","source":"第十八章 18.2 子宮的結構","chId":"ch18"},{"id":"q1803","ch":18,"level":1,"type":"single","style":"concept","q":"月經期間，子宮內膜哪一層會剝落？","options":["基底層","子宮肌層","機能層","子宮外膜"],"answer":[2],"explain":"機能層是內膜較上層，週期前半段增厚、血管豐富；卵子未受精及植入時，機能層在月經期間剝落。基底層貼近子宮肌層，月經期間不會流失，並在每次週期再生新的機能層；肌層與外膜不受月經影響。","source":"第十八章 18.2 子宮內膜","chId":"ch18"},{"id":"q1804","ch":18,"level":1,"type":"single","style":"concept","q":"排卵前大量湧現、直接觸發卵泡破裂的荷爾蒙是？","options":["FSH","黃體酮","雌激素","LH"],"answer":[3],"explain":"排卵前數小時 LH 大量湧現，促使卵泡破裂並釋放卵子。FSH 負責刺激卵泡發育；雌激素在排卵前達到閾值，是觸發 LH 的訊號而非直接令卵泡破裂；黃體酮在排卵後由黃體分泌，主要穩定內膜。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"},{"id":"q1805","ch":18,"level":2,"type":"multi","style":"concept","q":"根據課文，月經週期各時期的配對，下列哪些正確？（選 2–3 項）","options":["排卵期持續約 14 天","激增期由週期第 14 天才開始","分泌期約 14 天","月經期約 4 天","激增期約 10 天"],"answer":[2,3,4],"explain":"課文列激增期約 10 天、分泌期約 14 天、月經期約 4 天。排卵期只是卵子在數小時內被釋放，並非持續 14 天；激增期由週期第 2 天開始，第 14 天完成子宮內膜修復，所以「第 14 天才開始」是把完成日誤當起始日。","source":"第十八章 18.3 月經週期","chId":"ch18"},{"id":"q1806","ch":18,"level":2,"type":"single","style":"concept","q":"陰道保持酸性環境，主要依靠什麼？","options":["嗜酸性乳酸菌分泌乳酸","子宮頸分泌鹽酸","陰道壁的分泌腺直接分泌乳酸","前庭腺分泌黏液"],"answer":[0],"explain":"青春期至更年期，陰道內正常的嗜酸性乳酸菌分泌乳酸，維持 pH 3.5–4.9，抑制其他微生物。陰道本身沒有分泌腺，濕潤靠子宮頸分泌物；前庭腺只保持外陰濕潤；子宮頸不會分泌鹽酸。","source":"第十八章 18.2 陰道的結構","chId":"ch18"},{"id":"q1807","ch":18,"level":2,"type":"single","style":"concept","q":"陰道口兩側、分泌黏液以保持外陰濕潤的腺體是？","options":["大陰唇的皮脂腺","前庭腺（巴氏腺）","陰道壁的分泌腺","子宮頸腺體"],"answer":[1],"explain":"前庭腺位於陰道口兩邊、約小豌豆大，導管開口於前庭，分泌黏液保持外陰濕潤。大陰唇皮脂腺屬皮膚附屬器，作用是潤滑皮膚；子宮頸分泌物才是陰道濕潤的主要來源；陰道本身沒有分泌腺，所以不是由陰道壁分泌乳酸。","source":"第十八章 18.2 前庭腺","chId":"ch18"},{"id":"q1808","ch":18,"level":2,"type":"single","style":"concept","q":"排卵後，卵泡內層細胞在何種荷爾蒙影響下形成黃體？","options":["催產素","hCG","LH","FSH"],"answer":[2],"explain":"課文明言排卵後在 LH 影響下，卵泡內層細胞發展成黃體，分泌黃體酮及少量雌激素。FSH 刺激卵泡成熟；hCG 在懷孕後才由胚胎分泌以維持黃體；催產素作用於子宮肌，與黃體形成無關。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"},{"id":"q1809","ch":18,"level":3,"type":"single","style":"case","q":"28 歲女性週期規律，今個月沒有懷孕，週期末黃體酮水平驟降。最直接的原因是？","options":["雌激素正回饋","FSH 分泌增加","子宮肌層收縮","黃體退化"],"answer":[3],"explain":"未受精就沒有 hCG 維持黃體，黃體退化令黃體酮驟降，子宮內膜失去支持而脫落。FSH 增加是黃體酮抑制解除後的結果，不是黃體酮下降的原因；雌激素正回饋發生在排卵前，子宮肌層收縮與月經來潮不是啟動因素。","source":"第十八章 18.2 卵巢的功能；18.3 分泌期","chId":"ch18"},{"id":"q1810","ch":18,"level":3,"type":"multi","style":"case","q":"24 歲女性開始服用組合式口服避孕丸（含雌激素及黃體酮）。其主要作用機制包括哪三項？","options":["促進黃體形成以穩定內膜","負回饋抑制 FSH 與 LH，抑制排卵","直接殺死已排出的卵子","使子宮內膜變薄，不利著床","使子宮頸黏液變厚，阻擋精子"],"answer":[1,3,4],"explain":"課文列組合式避孕丸透過負回饋令大腦以為荷爾蒙足夠，抑制 FSH 與 LH 而停止排卵；同時令子宮頸黏液變厚、子宮內膜變薄。它不殺死卵子，也不會促進黃體形成；「抑制排卵」與「殺卵」是兩種不同機制。","source":"第十八章 18.3 口服避孕丸附註","chId":"ch18"},{"id":"q1811","ch":18,"level":3,"type":"single","style":"case","q":"29 歲女性雙側輸卵管因盆腔炎阻塞，但排卵及月經週期正常。最可能的不孕原因是？","options":["精子與卵子無法在輸卵管相遇受精","子宮內膜不能增厚","卵巢不能排卵","黃體不能分泌黃體酮"],"answer":[0],"explain":"受精通常發生在輸卵管，卵子由繖部拾取後在管內與精子相遇；雙側阻塞使精卵無法會合。個案已說明排卵及週期正常，所以卵巢、內膜及黃體功能都不是主因；這是「管道阻塞」而非「荷爾蒙失效」。","source":"第十八章 18.2 輸卵管的功能","chId":"ch18"},{"id":"q1812","ch":18,"level":3,"type":"single","style":"case","q":"懷孕 6 週，超聲波見子宮內胚胎。此時維持黃體繼續分泌黃體酮的主要訊號是？","options":["子宮內膜分泌的雌激素","胚胎分泌的 hCG","腦下垂體前葉的 FSH","胎盤分泌的 hCG"],"answer":[1],"explain":"受精卵著床後，發育中的胚胎分泌 hCG，刺激黃體在懷孕頭 3 個月繼續分泌黃體酮及雌激素；之後才由胎盤接手。懷孕 6 週時胎盤尚未接管，FSH 與內膜雌激素都不是維持黃體的主要訊號。","source":"第十八章 18.2 卵巢的功能","chId":"ch18"},{"id":"q1901","ch":19,"level":1,"type":"single","style":"concept","q":"聲波由鼓膜傳到內耳，下列次序何者正確？","options":["鼓膜 → 砧骨 → 錘骨 → 鐙骨 → 圓形窗","鼓膜 → 鐙骨 → 砧骨 → 錘骨 → 卵形窗","鼓膜 → 錘骨 → 砧骨 → 鐙骨 → 卵形窗","鼓膜 → 錘骨 → 鐙骨 → 砧骨 → 圓形窗"],"answer":[2],"explain":"聽小骨由外至內為錘骨、砧骨、鐙骨；鐙骨足板固定於卵形窗，把震動送入前庭階的外淋巴。圓形窗只由薄纖維封閉，是液體波最終耗盡之處，並非聽小骨接駁點；其餘選項把骨序或窗的位置調亂。","source":"第十九章 19.1 聽覺小骨","chId":"ch19"},{"id":"q1902","ch":19,"level":1,"type":"single","style":"concept","q":"聽覺的感受器位於何處？","options":["鼓膜","耳咽管","半規管的壺腹","耳蝸基底膜上的螺旋器"],"answer":[3],"explain":"耳蝸基底膜上有支持細胞及耳蝸毛細胞，組成螺旋器（柯蒂氏器），受震動後產生神經衝動。半規管壺腹的毛細胞屬平衡感受器；鼓膜只負責接收及傳遞震動；耳咽管的作用是平衡中耳與外界的氣壓。","source":"第十九章 19.1 耳蝸","chId":"ch19"},{"id":"q1903","ch":19,"level":1,"type":"single","style":"concept","q":"眼球中層哪個構造富含血管、呈深棕色並吸收光線？","options":["脈絡膜","視網膜","角膜","鞏膜"],"answer":[0],"explain":"脈絡膜內襯鞏膜後方 5/6，血管非常豐富、呈深巧克力棕色，吸收穿過視網膜的光線。鞏膜是外層纖維膜，角膜透明以折射光線，視網膜是內層感光構造；三者都屬眼球壁，但位置與功能不同。","source":"第十九章 19.4 眼睛結構","chId":"ch19"},{"id":"q1904","ch":19,"level":1,"type":"single","style":"concept","q":"哪個構造負責探測頭部在空間中的位置，與聽覺無關？","options":["鼓膜","半規管","耳咽管","耳蝸"],"answer":[1],"explain":"課文明言半規管沒有聽覺功能，只提供頭部在空間中位置的信息，致力維持姿勢和平衡。耳蝸是聽覺器官；鼓膜與耳咽管屬中耳的傳音及氣壓平衡構造，都不負責頭部位置感，所以不選。","source":"第十九章 19.3 半規管以及前庭","chId":"ch19"},{"id":"q1905","ch":19,"level":2,"type":"single","style":"concept","q":"房水（水狀液）最終經哪個構造回流靜脈循環？","options":["中央凹","玻璃體","鞏膜靜脈竇（許氏管）","視盤"],"answer":[2],"explain":"房水由睫狀體分泌入後房，經瞳孔到前房，再經虹膜與角膜之間角落的鞏膜靜脈竇（許氏管）回流。視盤是視神經離開眼球處，即盲點；中央凹在黃斑中央；玻璃體是晶狀體後方的啫喱狀物，三者都不引流房水。","source":"第十九章 19.4 眼睛內部","chId":"ch19"},{"id":"q1906","ch":19,"level":2,"type":"single","style":"concept","q":"關於近視與遠視的矯正，哪一項正確？","options":["近視用雙凸透鏡，遠視用雙凹透鏡","兩者都用平面鏡","兩者都用雙凸透鏡","近視用雙凹透鏡，遠視用雙凸透鏡"],"answer":[3],"explain":"課文以圖 19.34 展示遠視與近視的矯正透鏡，並指眼內折射異常可用雙凸或雙凹透鏡矯正。記法：近視用凹透鏡分散光線，遠視用凸透鏡增加會聚。最常見陷阱是把兩種透鏡對調，或以為平面鏡可矯正屈光。","source":"第十九章 19.5 光線的折射","chId":"ch19"},{"id":"q1907","ch":19,"level":2,"type":"multi","style":"concept","q":"關於視網膜，下列哪些正確？（選 2–3 項）","options":["視桿細胞對弱光較敏感","視網膜周邊以視錐細胞為主","視紫質存在於視錐細胞","視盤沒有光敏細胞，是盲點","中央凹只由視錐細胞構成"],"answer":[0,3,4],"explain":"課文指視桿細胞比視錐細胞敏感得多、中央凹只有視錐細胞、視盤是視神經離開處且沒有光敏細胞。視紫質只出現在視桿細胞；視網膜周邊有大量視桿細胞，視錐細胞反而較少，所以最後兩項都錯。","source":"第十九章 19.4 視網膜；19.5 視網膜的功能","chId":"ch19"},{"id":"q1908","ch":19,"level":2,"type":"multi","style":"concept","q":"關於嗅覺與味覺，下列哪些正確？（選 2–3 項）","options":["嗅覺感受器位於舌乳突","氣味分子需溶於黏液才能刺激嗅覺感受器","苦味主要在舌尖感受","連續接觸同一氣味會產生適應，數分鐘內感覺減弱","味蕾由第 7、9、10 腦神經的感覺末梢構成"],"answer":[1,3,4],"explain":"揮發性分子溶於鼻腔黏液後刺激嗅覺感受器；味蕾由舌咽、顏面及迷走神經（7、9、10）的末梢構成；嗅覺適應只影響該氣味。苦味在舌後，甜鹹才在舌尖；舌乳突是味蕾所在，不是嗅覺感受器。","source":"第十九章 19.6 嗅覺生理學與味覺","chId":"ch19"},{"id":"q1909","ch":19,"level":3,"type":"single","style":"case","q":"55 歲男子兩眼周邊視野逐漸收窄，眼壓 28 mmHg，視盤萎縮。最可能的情況是？","options":["慢性開角型青光眼","黃斑退化","白內障","急性閉角型青光眼"],"answer":[0],"explain":"房水經許氏管回流缺損令眼內壓升高，壓迫視神經軸突及血供；慢性開角型眼壓漸升、周邊視野先失，可發展成管狀視力甚至不可逆失明。急性閉角型會突發劇痛、畏光、流淚；白內障與黃斑退化不是眼壓問題。","source":"第十九章 19.4 青光眼附註","chId":"ch19"},{"id":"q1910","ch":19,"level":3,"type":"single","style":"case","q":"腦下垂體腫瘤向上壓迫視神經交叉，最直接受影響的是哪類纖維？","options":["兩眼視網膜顳側纖維","兩眼視網膜鼻側的交叉纖維","只影響左眼視神經","視輻射"],"answer":[1],"explain":"視交叉內來自每眼視網膜鼻側的纖維交叉到對側，顳側纖維不交叉而繼續同側向後走。腫瘤位於腦下垂體上方，正好壓迫交叉處，故兩眼鼻側纖維首當其衝；視輻射在交叉更後方，不會最先受壓。","source":"第十九章 19.4 視神經交叉","chId":"ch19"},{"id":"q1911","ch":19,"level":3,"type":"single","style":"case","q":"在噪音工廠工作 20 年的工人出現不可逆聽力下降，最可能受損的構造是？","options":["鼓膜","半規管","耳蝸螺旋器的毛細胞","聽小骨"],"answer":[2],"explain":"課文指巨大聲響長期發生會損害螺旋器中敏感的毛細胞，造成不可修補的耳聾，常見於嘈雜環境工作或樂團演奏者。鼓膜與聽小骨屬傳音結構，受損通常可處理；半規管負責平衡，與聽力下降無直接關係。","source":"第十九章 19.2 聽覺生理學","chId":"ch19"},{"id":"q1912","ch":19,"level":3,"type":"multi","style":"case","q":"看 6 米以內的近物時，眼睛會作哪些調整？","options":["瞳孔放大","睫狀肌收縮使晶狀體變厚","睫狀肌放鬆使晶狀體變薄","瞳孔收縮","雙眼會聚"],"answer":[1,3,4],"explain":"課文列近距視覺三項調整：瞳孔收縮減少光束寬度、眼球會聚使影像落在雙眼視網膜對應區域、睫狀肌收縮釋放懸韌帶張力令晶狀體變厚。瞳孔放大屬暗處反應；睫狀肌放鬆、晶狀體變薄是看 6 米以外遠物時的狀態。","source":"第十九章 19.5 調節","chId":"ch19"}];
